// Render the exact calibrated multi-stop diagonal rose-blush-to-pearl gradient pill
// with top-left organic rose bloom, delicate specular top sheen, and fine capsule rim
// matching the reference video (media_1795849251859_81880744.mp4 / media_1795857200639_b1fac465.mp4).
// When translucentGlass == NO -> silky matte 「柔性粉雾」;
// When translucentGlass == YES -> real translucent 「粉雾玻璃」 layered over live UIGlassEffect refraction.
static UIImage *FQXVideoSelectedPillImageForSize(CGSize size, BOOL translucentGlass) {
    CGFloat w = ceil(size.width);
    CGFloat h = ceil(size.height);
    if (w < 8.0 || h < 8.0 || w > 600.0 || h > 240.0) return nil;
    static NSCache<NSString *, UIImage *> *cache = nil;
    static dispatch_once_t once;
    dispatch_once(&once, ^{
        cache = [[NSCache alloc] init];
        cache.countLimit = 64;
    });
    NSString *key = [NSString stringWithFormat:@"%s_%.0fx%.0f", translucentGlass ? "g" : "m", w, h];
    UIImage *cached = [cache objectForKey:key];
    if (cached) return cached;

    UIGraphicsImageRendererFormat *fmt = [UIGraphicsImageRendererFormat defaultFormat];
    fmt.opaque = NO;
    fmt.scale = UIScreen.mainScreen.scale;
    UIGraphicsImageRenderer *renderer = [[UIGraphicsImageRenderer alloc] initWithSize:CGSizeMake(w, h) format:fmt];
    UIImage *img = [renderer imageWithActions:^(UIGraphicsImageRendererContext *rctx) {
        CGContextRef ctx = rctx.CGContext;
        CGRect rect = CGRectMake(0.0, 0.0, w, h);
        CGFloat radius = MIN(w, h) * 0.5;
        UIBezierPath *capsule = [UIBezierPath bezierPathWithRoundedRect:rect cornerRadius:radius];

        CGContextSaveGState(ctx);
        [capsule addClip];

        CGColorSpaceRef cs = CGColorSpaceCreateDeviceRGB();
        // 1. Exact 5-stop diagonal sakura-rose -> warm rose -> misty rose-pearl -> cool pearl-silver gradient
        const CGFloat a0 = translucentGlass ? 0.68 : 0.98;
        const CGFloat a1 = translucentGlass ? 0.58 : 0.98;
        const CGFloat a2 = translucentGlass ? 0.44 : 0.97;
        const CGFloat a3 = translucentGlass ? 0.34 : 0.96;
        const CGFloat a4 = translucentGlass ? 0.30 : 0.96;
        const CGFloat comps[] = {
            224.0 / 255.0, 166.0 / 255.0, 182.0 / 255.0, a0, // #E0A6B6 top-left sakura rose
            223.0 / 255.0, 182.0 / 255.0, 193.0 / 255.0, a1, // #DFB6C1 warm rose blend
            226.0 / 255.0, 211.0 / 255.0, 216.0 / 255.0, a2, // #E2D3D8 misty rose-pearl
            226.0 / 255.0, 225.0 / 255.0, 228.0 / 255.0, a3, // #E2E1E4 cool neutral pearl
            223.0 / 255.0, 222.0 / 255.0, 226.0 / 255.0, a4  // #DFDEE2 soft silver-gray bottom
        };
        const CGFloat locs[] = {0.0, 0.26, 0.54, 0.78, 1.0};
        CGGradientRef linGrad = CGGradientCreateWithColorComponents(cs, comps, locs, 5);
        if (linGrad) {
            CGContextDrawLinearGradient(ctx, linGrad,
                                        CGPointMake(w * 0.12, 0.0),
                                        CGPointMake(w * 0.74, h * 0.92),
                                        kCGGradientDrawsBeforeStartLocation | kCGGradientDrawsAfterEndLocation);
            CGGradientRelease(linGrad);
        }

        // 2. Organic top-left sakura rose bloom concentrated along the upper-left curve
        const CGFloat radComps[] = {
            222.0 / 255.0, 152.0 / 255.0, 174.0 / 255.0, translucentGlass ? 0.34 : 0.28,
            222.0 / 255.0, 168.0 / 255.0, 186.0 / 255.0, translucentGlass ? 0.14 : 0.10,
            224.0 / 255.0, 212.0 / 255.0, 218.0 / 255.0, 0.0
        };
        const CGFloat radLocs[] = {0.0, 0.48, 1.0};
        CGGradientRef radGrad = CGGradientCreateWithColorComponents(cs, radComps, radLocs, 3);
        if (radGrad) {
            CGPoint bloomCenter = CGPointMake(w * 0.22, h * 0.16);
            CGFloat bloomRadius = MAX(w * 0.56, h * 0.85);
            CGContextDrawRadialGradient(ctx, radGrad, bloomCenter, 0.0, bloomCenter, bloomRadius, 0);
            CGGradientRelease(radGrad);
        }

        // 3. Upper inner specular glass highlight (plus subtle bottom refraction lift in glass mode)
        const CGFloat sheenComps[] = {
            1.0, translucentGlass ? (248.0 / 255.0) : (245.0 / 255.0),
            translucentGlass ? (251.0 / 255.0) : (248.0 / 255.0),
            translucentGlass ? 0.46 : 0.34,
            1.0, 245.0 / 255.0, 248.0 / 255.0, 0.0
        };
        const CGFloat sheenLocs[] = {0.0, 1.0};
        CGGradientRef sheenGrad = CGGradientCreateWithColorComponents(cs, sheenComps, sheenLocs, 2);
        if (sheenGrad) {
            CGContextDrawLinearGradient(ctx, sheenGrad,
                                        CGPointMake(w * 0.5, 0.0),
                                        CGPointMake(w * 0.5, MIN(h * (translucentGlass ? 0.32 : 0.28), 11.0)),
                                        0);
            CGGradientRelease(sheenGrad);
        }
        if (translucentGlass) {
            const CGFloat liftComps[] = {
                1.0, 1.0, 1.0, 0.0,
                1.0, 250.0 / 255.0, 252.0 / 255.0, 0.18
            };
            const CGFloat liftLocs[] = {0.0, 1.0};
            CGGradientRef liftGrad = CGGradientCreateWithColorComponents(cs, liftComps, liftLocs, 2);
            if (liftGrad) {
                CGContextDrawLinearGradient(ctx, liftGrad,
                                            CGPointMake(w * 0.5, MAX(0.0, h * 0.80)),
                                            CGPointMake(w * 0.5, h),
                                            0);
                CGGradientRelease(liftGrad);
            }
        }
        CGContextRestoreGState(ctx);

        // 4. Crisp 0.75pt hairline rim transitioning from rose top-left to cool silver/glass-white bottom-right
        CGContextSaveGState(ctx);
        CGRect strokeRect = CGRectInset(rect, 0.375, 0.375);
        UIBezierPath *strokePath = [UIBezierPath bezierPathWithRoundedRect:strokeRect
                                                              cornerRadius:MAX(0.0, radius - 0.375)];
        CGContextSetLineWidth(ctx, 0.75);
        CGContextAddPath(ctx, strokePath.CGPath);
        CGContextReplacePathWithStrokedPath(ctx);
        CGContextClip(ctx);
        const CGFloat borderComps[] = {
            translucentGlass ? (216.0 / 255.0) : (197.0 / 255.0),
            translucentGlass ? (158.0 / 255.0) : (156.0 / 255.0),
            translucentGlass ? (176.0 / 255.0) : (169.0 / 255.0),
            translucentGlass ? 0.72 : 0.82,
            translucentGlass ? 1.0 : (199.0 / 255.0),
            translucentGlass ? 1.0 : (198.0 / 255.0),
            translucentGlass ? 1.0 : (202.0 / 255.0),
            translucentGlass ? 0.46 : 0.72
        };
        const CGFloat borderLocs[] = {0.0, 1.0};
        CGGradientRef borderGrad = CGGradientCreateWithColorComponents(cs, borderComps, borderLocs, 2);
        if (borderGrad) {
            CGContextDrawLinearGradient(ctx, borderGrad,
                                        CGPointMake(w * 0.10, 0.0),
                                        CGPointMake(w * 0.85, h),
                                        kCGGradientDrawsBeforeStartLocation | kCGGradientDrawsAfterEndLocation);
            CGGradientRelease(borderGrad);
        }
        CGContextRestoreGState(ctx);
        CGColorSpaceRelease(cs);
    }];
    if (img) [cache setObject:img forKey:key];
    return img;
}

@interface FQXVideoSelectedPillView : UIImageView {
@public
    CGSize _renderedSize;
    BOOL _translucentGlass;
}
- (void)setTranslucentGlass:(BOOL)translucentGlass;
@end

@implementation FQXVideoSelectedPillView
- (instancetype)initWithFrame:(CGRect)frame {
    self = [super initWithFrame:frame];
    if (self) {
        self.userInteractionEnabled = NO;
        self.isAccessibilityElement = NO;
        self.accessibilityElementsHidden = YES;
        self.backgroundColor = UIColor.clearColor;
        self.contentMode = UIViewContentModeScaleToFill;
        self.autoresizingMask = UIViewAutoresizingFlexibleWidth | UIViewAutoresizingFlexibleHeight;
        _renderedSize = CGSizeZero;
        _translucentGlass = NO;
    }
    return self;
}
- (void)setTranslucentGlass:(BOOL)translucentGlass {
    if (_translucentGlass == translucentGlass && self.image) return;
    _translucentGlass = translucentGlass;
    _renderedSize = CGSizeZero;
    self.image = nil;
    [self setNeedsLayout];
    [self layoutIfNeeded];
}
- (void)layoutSubviews {
    [super layoutSubviews];
    CGSize sz = self.bounds.size;
    if (sz.width < 8.0 || sz.height < 8.0) return;
    if (!self.image || fabs(_renderedSize.width - sz.width) >= 0.5 || fabs(_renderedSize.height - sz.height) >= 0.5) {
        UIImage *img = FQXVideoSelectedPillImageForSize(sz, _translucentGlass);
        if (img) {
            self.image = img;
            _renderedSize = sz;
        }
    }
}
@end

static const char FQXK_FQXVideoSelectedPillOverlayKey = 0;
#define FQXVideoSelectedPillOverlayKey ((const void *)&FQXK_FQXVideoSelectedPillOverlayKey)
static const char FQXK_FQXPlatterVideoBaseViewKey = 0;
#define FQXPlatterVideoBaseViewKey ((const void *)&FQXK_FQXPlatterVideoBaseViewKey)

static void FQXSyncVideoSelectedPillOverlayInView(UIView *host, NSInteger selectionTintStyle) {
    if (![host isKindOfClass:UIView.class]) return;
    UIView *container = [host isKindOfClass:UIVisualEffectView.class]
        ? ((UIVisualEffectView *)host).contentView : host;
    FQXVideoSelectedPillView *overlay = objc_getAssociatedObject(host, FQXVideoSelectedPillOverlayKey);
    if (selectionTintStyle == FQXSelectionTintStyleDefault) {
        if (overlay) {
            [overlay removeFromSuperview];
            objc_setAssociatedObject(host, FQXVideoSelectedPillOverlayKey, nil, OBJC_ASSOCIATION_RETAIN_NONATOMIC);
        }
        return;
    }
    BOOL translucentGlass = (selectionTintStyle == FQXSelectionTintStyleRoseMistGlass);
    if (!overlay) {
        overlay = [[FQXVideoSelectedPillView alloc] initWithFrame:container.bounds];
        objc_setAssociatedObject(overlay, FQXOwnedGlassElementKey, @YES, OBJC_ASSOCIATION_RETAIN_NONATOMIC);
        objc_setAssociatedObject(host, FQXVideoSelectedPillOverlayKey, overlay, OBJC_ASSOCIATION_RETAIN_NONATOMIC);
    }
    if (overlay.superview != container) {
        [container insertSubview:overlay atIndex:0];
    }
    if (!CGRectEqualToRect(overlay.frame, container.bounds)) {
        overlay.frame = container.bounds;
    }
    [overlay setTranslucentGlass:translucentGlass];
}

static void FQXSyncNativeTabSelectionVideoPill(UIView *root, NSInteger selectionTintStyle, NSInteger depth) {
    if (!root || depth > 6) return;
    NSString *clsName = NSStringFromClass(root.class) ?: @"";
    if ([clsName containsString:@"TabSelectionView"] || [clsName containsString:@"SelectionPlatter"]) {
        FQXSyncVideoSelectedPillOverlayInView(root, selectionTintStyle);
        if (selectionTintStyle != FQXSelectionTintStyleDefault) {
            FQXVideoSelectedPillView *overlay = objc_getAssociatedObject(root, FQXVideoSelectedPillOverlayKey);
            UIView *container = [root isKindOfClass:UIVisualEffectView.class]
                ? ((UIVisualEffectView *)root).contentView : root;
            if (overlay && overlay.superview == container) {
                [container bringSubviewToFront:overlay];
            }
        }
        return;
    }
    for (UIView *sub in root.subviews) {
        FQXSyncNativeTabSelectionVideoPill(sub, selectionTintStyle, depth + 1);
    }
}

// surfaceStyle: 0 = none, 1 = matte VideoBase (#EEEDF0), 2 = translucent RoseMistGlass rim only
static void FQXSyncPlatterSurfaceBacking(UIView *platter, NSInteger surfaceStyle) {
    if (!platter) return;
    UIView *backing = objc_getAssociatedObject(platter, FQXPlatterVideoBaseViewKey);
    if (surfaceStyle == 0) {
        if (backing) {
            [backing removeFromSuperview];
            objc_setAssociatedObject(platter, FQXPlatterVideoBaseViewKey, nil, OBJC_ASSOCIATION_RETAIN_NONATOMIC);
        }
        return;
    }
    UIView *container = [platter isKindOfClass:UIVisualEffectView.class]
        ? ((UIVisualEffectView *)platter).contentView : platter;
    if (!backing) {
        backing = [[UIView alloc] initWithFrame:container.bounds];
        backing.autoresizingMask = UIViewAutoresizingFlexibleWidth | UIViewAutoresizingFlexibleHeight;
        backing.userInteractionEnabled = NO;
        backing.accessibilityElementsHidden = YES;
        backing.isAccessibilityElement = NO;
        backing.layer.cornerCurve = kCACornerCurveContinuous;
        backing.clipsToBounds = YES;
        objc_setAssociatedObject(backing, FQXOwnedGlassElementKey, @YES, OBJC_ASSOCIATION_RETAIN_NONATOMIC);
        objc_setAssociatedObject(platter, FQXPlatterVideoBaseViewKey, backing, OBJC_ASSOCIATION_RETAIN_NONATOMIC);
    }
    if (surfaceStyle == 1) {
        backing.backgroundColor = FQXVideoBaseFillUIColor();
        backing.layer.borderWidth = 0.5;
        backing.layer.borderColor = FQXVideoBaseBorderUIColor().CGColor;
    } else {
        // RoseMistGlass keeps UIGlassEffect completely transparent & refractive underneath;
        // add only a delicate 0.5pt translucent rose-pearl hairline rim.
        backing.backgroundColor = UIColor.clearColor;
        backing.layer.borderWidth = 0.5;
        backing.layer.borderColor = FQXRoseMistGlassBaseBorderUIColor().CGColor;
    }
    if (backing.superview != container) {
        [container insertSubview:backing atIndex:0];
    } else if (container.subviews.firstObject != backing) {
        [container sendSubviewToBack:backing];
    }
    if (!CGRectEqualToRect(backing.frame, container.bounds)) {
        backing.frame = container.bounds;
    }
    CGFloat r = MIN(CGRectGetWidth(container.bounds), CGRectGetHeight(container.bounds)) * 0.5;
    if (r > 0.5 && fabs(backing.layer.cornerRadius - r) > 0.25) {
        backing.layer.cornerRadius = r;
    }
}

static NSInteger FQXDramaHeaderButtonScalePercent(void) {
    NSInteger v = FQXHotPrefsSnapshot().dramaHeaderButtonScale;
    return (v >= 70 && v <= 130) ? v : 100;
}

static FQXCommentComposerStyle FQXCurrentCommentComposerStyle(void) {
    FQXHotPrefsCache p = FQXHotPrefsSnapshot();
    if (p.hasStoredComposerStyle) return p.commentComposerStyle;
    FQXCommentMaterialStyle material = p.commentMaterialStyle;
    return (FQXIsNativeGlassCommentStyle(material) || material == FQXCommentMaterialGaussianBlur)
        ? FQXCommentComposerDockedGlass
        : FQXCommentComposerNative;
}

static BOOL FQXDramaCommentNoVideoShiftEnabled(void) {
    return FQXHotPrefsSnapshot().dramaCommentNoVideoShift;
}

static BOOL FQXDramaExitCollectAlertHidden(void) {
    return FQXHotPrefsSnapshot().dramaExitCollectAlert;
}

static FQXCommentAppearanceMode FQXCurrentCommentAppearanceMode(void) {
    return FQXHotPrefsSnapshot().commentAppearanceMode;
}

static BOOL FQXCommentAppearanceOverrideActive(void) {
    return FQXHotPrefsSnapshot().commentAppearanceMode != FQXCommentAppearanceFollowApp;
}

UIUserInterfaceStyle FQXHostAppInterfaceStyle(UIWindow *window) {
    static Class adapterCls = Nil;
    static Class serviceCls = Nil;
    static SEL defaultSel = NULL;
    static SEL getSel = NULL;
    static SEL curDarkSel = NULL;
    static SEL darkSel = NULL;
    static dispatch_once_t once;
    dispatch_once(&once, ^{
        defaultSel = sel_registerName("defaultCenter");
        getSel = sel_registerName("getService:");
        curDarkSel = sel_registerName("isCurrentDarkMode");
        darkSel = sel_registerName("isDarkMode");
    });
    if (!adapterCls) adapterCls = objc_lookUpClass("SSUIColorAdaptedManager");
    if (!serviceCls) serviceCls = objc_lookUpClass("HTSServiceCenter");
    if (adapterCls && serviceCls && [serviceCls respondsToSelector:defaultSel]) {
        id center = ((id (*)(id, SEL))objc_msgSend)(serviceCls, defaultSel);
        if (center && [center respondsToSelector:getSel]) {
            id adapter = ((id (*)(id, SEL, Class))objc_msgSend)(center, getSel, adapterCls);
            if (adapter) {
                Method m = class_getInstanceMethod(object_getClass(adapter), curDarkSel);
                if (m && method_getNumberOfArguments(m) == 2) {
                    BOOL dark = ((BOOL (*)(id, SEL))objc_msgSend)(adapter, curDarkSel);
                    return dark ? UIUserInterfaceStyleDark : UIUserInterfaceStyleLight;
                }
                Method m2 = class_getInstanceMethod(object_getClass(adapter), darkSel);
                if (m2 && method_getNumberOfArguments(m2) == 2) {
                    BOOL dark = ((BOOL (*)(id, SEL))objc_msgSend)(adapter, darkSel);
                    return dark ? UIUserInterfaceStyleDark : UIUserInterfaceStyleLight;
                }
            }
        }
    }
    UIUserInterfaceStyle windowStyle = window.overrideUserInterfaceStyle;
    if (windowStyle == UIUserInterfaceStyleUnspecified) windowStyle = window.traitCollection.userInterfaceStyle;
    if (windowStyle != UIUserInterfaceStyleUnspecified) return windowStyle;
    for (UIScene *scene in UIApplication.sharedApplication.connectedScenes) {
        if (![scene isKindOfClass:UIWindowScene.class]) continue;
        UIWindowScene *ws = (UIWindowScene *)scene;
        UIUserInterfaceStyle sceneStyle = ws.traitCollection.userInterfaceStyle;
        if (sceneStyle != UIUserInterfaceStyleUnspecified) {
            return sceneStyle;
        }
        for (UIWindow *win in ws.windows) {
            if (!win.isKeyWindow) continue;
            if (win.overrideUserInterfaceStyle != UIUserInterfaceStyleUnspecified) return win.overrideUserInterfaceStyle;
            return win.traitCollection.userInterfaceStyle;
        }
    }
    return UIScreen.mainScreen.traitCollection.userInterfaceStyle;
}

static BOOL FQXAppIsInNightMode(void) {
    return FQXHostAppInterfaceStyle(nil) == UIUserInterfaceStyleDark;
}

static BOOL FQXCommentsUseDarkTheme(void) {
    FQXCommentAppearanceMode appMode = FQXCurrentCommentAppearanceMode();
    if (appMode == FQXCommentAppearanceLight) return NO;
    if (appMode == FQXCommentAppearanceDark) return YES;
    return FQXAppIsInNightMode();
}

static BOOL FQXGlassEnabled(void) {
    if (FQXHotPrefsSnapshot().glassDisabled) return NO;
    static BOOL sRuntimeGlassAvailable = NO;
    static dispatch_once_t once;
    dispatch_once(&once, ^{
        Class glassCls = objc_lookUpClass("UIGlassEffect");
        Class cornerCls = objc_lookUpClass("UICornerConfiguration");
        sRuntimeGlassAvailable = glassCls != Nil && cornerCls != Nil &&
            [glassCls respondsToSelector:sel_registerName("effectWithStyle:")] &&
            [cornerCls respondsToSelector:sel_registerName("capsuleConfiguration")] &&
            [UIVisualEffectView instancesRespondToSelector:sel_registerName("setCornerConfiguration:")];
    });
    return sRuntimeGlassAvailable;
}

static BOOL FQXAudioGlassEnabled(void) {
    return FQXGlassEnabled() && FQXHotPrefsSnapshot().audioLiquidGlass;
}

static BOOL FQXCommentStylingEnabled(void) {
    if (FQXHotPrefsSnapshot().glassDisabled) return NO;
    FQXCommentMaterialStyle style = FQXCurrentCommentMaterialStyle();
    if (style == FQXCommentMaterialNative) return NO;
    if (style == FQXCommentMaterialGaussianBlur) return YES;
    return FQXGlassEnabled();
}

static FQXCommentMaterialStyle FQXComposerEffectiveMaterialStyle(void) {
    FQXCommentMaterialStyle style = FQXCurrentCommentMaterialStyle();
    if (style == FQXCommentMaterialGaussianBlur) return FQXCommentMaterialGaussianBlur;
    if (FQXIsNativeGlassCommentStyle(style) && FQXGlassEnabled()) return style;
    return FQXGlassEnabled() ? FQXCommentMaterialClearGlass : FQXCommentMaterialGaussianBlur;
}

static BOOL FQXShouldOverrideCommentTheme(void) {
    return FQXCommentStylingEnabled() || FQXCommentAppearanceOverrideActive();
}

static UIUserInterfaceStyle FQXDesiredCommentInterfaceStyle(void) {
    if (!FQXShouldOverrideCommentTheme()) return UIUserInterfaceStyleUnspecified;
    return FQXCommentsUseDarkTheme() ? UIUserInterfaceStyleDark : UIUserInterfaceStyleLight;
}

static UIUserInterfaceStyle FQXDesiredCommentHostOverrideStyle(void) {
    if (!FQXCommentAppearanceOverrideActive()) return UIUserInterfaceStyleUnspecified;
    return FQXDesiredCommentInterfaceStyle();
}

static BOOL FQXCommentActivityBannerEnabled(void) {
    return FQXHotPrefsSnapshot().commentActivityBanner;
}

static BOOL FQXCommentSearchEntranceEnabled(void) {
    return FQXHotPrefsSnapshot().commentSearchEntrance;
}

// Unified Liquid Glass rendering layer shared across Dock, Short-Drama Comments, and Novel Comments.
// Dock dynamic background resampling adapts the iOS 26/27 pattern from ChenYilong/CYLTabBarController (MIT).
static const char FQXK_FQXUnifiedClearDockKey = 0;
#define FQXUnifiedClearDockKey ((const void *)&FQXK_FQXUnifiedClearDockKey)
static const char FQXK_FQXNoVideoShiftSuppressedKey = 0;
#define FQXNoVideoShiftSuppressedKey ((const void *)&FQXK_FQXNoVideoShiftSuppressedKey)
static const char FQXK_FQXAudioIndicatorDedupHiddenKey = 0;
#define FQXAudioIndicatorDedupHiddenKey ((const void *)&FQXK_FQXAudioIndicatorDedupHiddenKey)
static const char FQXK_FQXCommentGlassStyleAppliedKey = 0;
#define FQXCommentGlassStyleAppliedKey ((const void *)&FQXK_FQXCommentGlassStyleAppliedKey)
static const char FQXK_FQXDockHiddenByCommentKey = 0;
#define FQXDockHiddenByCommentKey ((const void *)&FQXK_FQXDockHiddenByCommentKey)
static const char FQXK_FQXSheetTopRimLayerKey = 0;
#define FQXSheetTopRimLayerKey ((const void *)&FQXK_FQXSheetTopRimLayerKey)
static const char FQXK_FQXSheetSavedCornerRadiusKey = 0;
#define FQXSheetSavedCornerRadiusKey ((const void *)&FQXK_FQXSheetSavedCornerRadiusKey)
static const char FQXK_FQXSheetSavedMaskedCornersKey = 0;
#define FQXSheetSavedMaskedCornersKey ((const void *)&FQXK_FQXSheetSavedMaskedCornersKey)
static const char FQXK_FQXSheetSavedCornerCurveKey = 0;
#define FQXSheetSavedCornerCurveKey ((const void *)&FQXK_FQXSheetSavedCornerCurveKey)
static const char FQXK_FQXCommentBannerSavedHeightKey = 0;
#define FQXCommentBannerSavedHeightKey ((const void *)&FQXK_FQXCommentBannerSavedHeightKey)
static const char FQXK_FQXReaderDisappearingKey = 0;
#define FQXReaderDisappearingKey ((const void *)&FQXK_FQXReaderDisappearingKey)
static const char FQXK_FQXReaderSwipeHiddenIndicatorKey = 0;
#define FQXReaderSwipeHiddenIndicatorKey ((const void *)&FQXK_FQXReaderSwipeHiddenIndicatorKey)
static const char FQXK_FQXShelfHeaderFixPendingKey = 0;
#define FQXShelfHeaderFixPendingKey ((const void *)&FQXK_FQXShelfHeaderFixPendingKey)
static const char FQXK_FQXCommentTypographyStampKey = 0;
#define FQXCommentTypographyStampKey ((const void *)&FQXK_FQXCommentTypographyStampKey)
static UIVisualEffect *FQXMakeGlassEffect(NSInteger style, BOOL interactive, UIColor *tintColor) {
    static Class glassCls = Nil;
    static SEL makeSel = NULL;
    static SEL interactiveSel = NULL;
    static SEL tintSel = NULL;
    static dispatch_once_t once;
    dispatch_once(&once, ^{
        glassCls = objc_lookUpClass("UIGlassEffect");
        makeSel = sel_registerName("effectWithStyle:");
        interactiveSel = sel_registerName("setInteractive:");
        tintSel = sel_registerName("setTintColor:");
    });
    if (glassCls && [glassCls respondsToSelector:makeSel]) {
        UIVisualEffect *effect = ((id (*)(id, SEL, NSInteger))objc_msgSend)(glassCls, makeSel, style);
        if (effect) {
            if ([effect respondsToSelector:interactiveSel]) {
                ((void (*)(id, SEL, BOOL))objc_msgSend)(effect, interactiveSel, interactive);
            }
            if (tintColor && [effect respondsToSelector:tintSel]) {
                ((void (*)(id, SEL, id))objc_msgSend)(effect, tintSel, tintColor);
            }
            return effect;
        }
    }
    // Pre-iOS 26 / fallback material degradation
    UIBlurEffectStyle fallbackStyle = (style == 1)
        ? UIBlurEffectStyleSystemThinMaterial
        : UIBlurEffectStyleSystemMaterialDark;
    return [UIBlurEffect effectWithStyle:fallbackStyle];
}

static const char FQXK_FQXAppliedCornerStampKey = 0;
#define FQXAppliedCornerStampKey ((const void *)&FQXK_FQXAppliedCornerStampKey)
static void FQXApplyCornerConfiguration(UIView *view, CGFloat radius, BOOL continuousCard) {
    if (!view) return;
    NSInteger stamp = ((NSInteger)llround(radius * 10.0) << 2) | (continuousCard ? 2 : 1);
    NSNumber *applied = objc_getAssociatedObject(view, FQXAppliedCornerStampKey);
    if (applied && applied.integerValue == stamp) return;
    static Class cornerCls = Nil;
    static Class radiusCls = Nil;
    static SEL setCornerSel = NULL;
    static SEL fixedSel = NULL;
    static SEL uniformSel = NULL;
    static SEL maxSel = NULL;
    static SEL capSel = NULL;
    static dispatch_once_t once;
    dispatch_once(&once, ^{
        cornerCls = objc_lookUpClass("UICornerConfiguration");
        radiusCls = objc_lookUpClass("UICornerRadius");
        setCornerSel = sel_registerName("setCornerConfiguration:");
        fixedSel = sel_registerName("fixedRadius:");
        uniformSel = sel_registerName("configurationWithUniformRadius:");
        maxSel = sel_registerName("capsuleConfigurationWithMaximumRadius:");
        capSel = sel_registerName("capsuleConfiguration");
    });
    if (!cornerCls || ![view respondsToSelector:setCornerSel]) return;
    id config = nil;
    if (radius < 0.0 || (radius > 0.0 && continuousCard)) {
        if (radiusCls && [radiusCls respondsToSelector:fixedSel] && [cornerCls respondsToSelector:uniformSel]) {
            CGFloat fixedR = radius < 0.0 ? 0.0 : radius;
            id radObj = ((id (*)(id, SEL, CGFloat))objc_msgSend)(radiusCls, fixedSel, fixedR);
            if (radObj) {
                config = ((id (*)(id, SEL, id))objc_msgSend)(cornerCls, uniformSel, radObj);
            }
        }
    }
    if (!config && radius > 0.0 && [cornerCls respondsToSelector:maxSel]) {
        config = ((id (*)(id, SEL, CGFloat))objc_msgSend)(cornerCls, maxSel, radius);
    }
    if (!config && radius >= 0.0 && [cornerCls respondsToSelector:capSel]) {
        config = ((id (*)(id, SEL))objc_msgSend)(cornerCls, capSel);
    }
    if (config) {
        ((void (*)(id, SEL, id))objc_msgSend)(view, setCornerSel, config);
        objc_setAssociatedObject(view, FQXAppliedCornerStampKey, @(stamp), OBJC_ASSOCIATION_RETAIN_NONATOMIC);
    }
}

static UIVisualEffectView *FQXNewGlassViewFull(NSInteger style,
                                               BOOL interactive,
                                               CGFloat radius,
                                               BOOL continuousCard,
                                               UIColor *tintColor) {
    UIVisualEffect *effect = FQXMakeGlassEffect(style, interactive, tintColor);
    if (!effect) return nil;
    UIVisualEffectView *surface = [[UIVisualEffectView alloc] initWithEffect:effect];
    if (!surface) return nil;
    FQXApplyCornerConfiguration(surface, radius, continuousCard);
    surface.userInteractionEnabled = NO;
    surface.accessibilityElementsHidden = YES;
    surface.isAccessibilityElement = NO;
    surface.opaque = NO;
    surface.backgroundColor = UIColor.clearColor;
    surface.contentView.backgroundColor = UIColor.clearColor;
    return surface;
}

