- (void)syncCollectionView:(UIScrollView *)scroll;
- (void)prepareForTouchOnView:(UIView *)leaf;
- (void)clearStaleFeedPanIfNeeded;
- (void)scanWindowsForMountedCollections;
- (void)resetFeedGesture;
- (void)cancelActivePan;
- (void)cancelFeedPan:(UIPanGestureRecognizer *)pan;
@end

@implementation FQXFeedDockPanController

+ (instancetype)shared {
    static FQXFeedDockPanController *instance;
    static dispatch_once_t once;
    dispatch_once(&once, ^{ instance = [FQXFeedDockPanController new]; });
    return instance;
}

- (instancetype)init {
    self = [super init];
    if (self) {
        _trackedCollections = [NSHashTable weakObjectsHashTable];
        DKFeedPanReset(&_panState);
    }
    return self;
}

- (void)resetFeedGesture {
    _feedPan = nil;
    _feedPendingPan = nil;
    _feedPendingWindow = nil;
    _activeInteraction = nil;
    DKFeedPanReset(&_panState);
}

- (void)cancelActivePan {
    UIPanGestureRecognizer *active = _feedPan;
    if (active) {
        [self cancelFeedPan:active];
        return;
    }
    [self resetFeedGesture];
}

- (void)cancelFeedPan:(UIPanGestureRecognizer *)pan {
    if (_feedPendingPan == pan) [self resetFeedGesture];
    if (_feedPan != pan) return;
    FQXTabBarInteraction *inter = _activeInteraction;
    BOOL startedCompact = (_panState.startedCompact != 0);
    [self resetFeedGesture];
    [inter setFeedCompact:startedCompact animated:YES];
}

- (void)clearStaleFeedPanIfNeeded {
    UIPanGestureRecognizer *active = _feedPan;
    if (active) {
        UIGestureRecognizerState st = active.state;
        BOOL alive = (st == UIGestureRecognizerStateBegan || st == UIGestureRecognizerStateChanged) &&
                     active.view.window != nil;
        if (!alive) {
            [self resetFeedGesture];
        }
    }
    UIPanGestureRecognizer *pending = _feedPendingPan;
    if (pending) {
        UIGestureRecognizerState pst = pending.state;
        BOOL alive = (pst == UIGestureRecognizerStateBegan || pst == UIGestureRecognizerStateChanged) &&
                     pending.view.window != nil;
        if (!alive) {
            _feedPendingPan = nil;
            _feedPendingWindow = nil;
        }
    }
}

- (void)prepareForTouchOnView:(UIView *)leaf {
    if (!leaf) return;
    [self clearStaleFeedPanIfNeeded];
    for (UIView *cur = leaf; cur; cur = cur.superview) {
        if ([cur isKindOfClass:UIScrollView.class] && ![cur isKindOfClass:UITextView.class] && cur.window) {
            UIScrollView *sv = (UIScrollView *)cur;
            UIPanGestureRecognizer *pan = sv.panGestureRecognizer;
            if (pan) {
                [pan removeTarget:self action:@selector(handleFeedPan:)];
                [pan addTarget:self action:@selector(handleFeedPan:)];
                [_trackedCollections addObject:sv];
            }
        }
    }
}

- (void)syncCollectionView:(UIScrollView *)scroll {
    if (![scroll isKindOfClass:UIScrollView.class] || [scroll isKindOfClass:UITextView.class]) return;
    UIPanGestureRecognizer *pan = scroll.panGestureRecognizer;
    if (!pan) return;
    [pan removeTarget:self action:@selector(handleFeedPan:)];
    if (scroll.window) {
        [_trackedCollections addObject:scroll];
        [pan addTarget:self action:@selector(handleFeedPan:)];
    } else {
        [self cancelFeedPan:pan];
    }
}

static void FQXCollectMountedFeedScrollViews(UIView *root, NSMutableArray<UIScrollView *> *out, NSInteger depth) {
    if (!root || depth > 36) return;
    if ([root isKindOfClass:UIScrollView.class] && ![root isKindOfClass:UITextView.class]) {
        [out addObject:(UIScrollView *)root];
    }
    for (UIView *sub in root.subviews) {
        FQXCollectMountedFeedScrollViews(sub, out, depth + 1);
    }
}

- (void)scanWindowsForMountedCollections {
    NSMutableArray<UIScrollView *> *found = [NSMutableArray array];
    for (UIScene *scene in UIApplication.sharedApplication.connectedScenes) {
        if (![scene isKindOfClass:UIWindowScene.class]) continue;
        for (UIWindow *win in ((UIWindowScene *)scene).windows) {
            if (win.hidden || win.alpha <= 0.01) continue;
            FQXCollectMountedFeedScrollViews(win, found, 0);
        }
    }
    for (UIScrollView *scroll in found) {
        [self syncCollectionView:scroll];
    }
}

static BOOL FQXControllerNameBlocksFeedDockMotion(NSString *name) {
    if (!name.length) return NO;
    return [name containsString:@"SideBar"] ||
           [name containsString:@"Comment"] ||
           [name containsString:@"Episode"] ||
           [name containsString:@"Share"] ||
           [name containsString:@"Search"] ||
           [name containsString:@"Detail"] ||
           [name containsString:@"Reader"] ||
           [name containsString:@"AudioPlay"] ||
           [name containsString:@"Setting"] ||
           [name containsString:@"Alert"] ||
           [name containsString:@"Popover"] ||
           [name hasPrefix:@"FQX"] ||
           [name hasPrefix:@"FanqieX"];
}

- (BOOL)canTrackFeed:(UIScrollView *)feed
                mode:(FQXDockCollapseMode)mode
      outInteraction:(FQXTabBarInteraction **)outInteraction
     waitingForMount:(BOOL *)waitingForMount {
    if (waitingForMount) *waitingForMount = NO;
    if (outInteraction) *outInteraction = nil;
    if (!FQXFeedMotionSupported() || !FQXDockCollapseModeUsesFeedMotion(mode)) return NO;
    if (!feed || [feed isKindOfClass:UITextView.class] || feed.hidden || feed.alpha <= 0.01) return NO;
    UIWindow *win = feed.window;
    if (!win || !feed.isScrollEnabled) return NO;
    CGRect winBounds = win.bounds;
    if (CGRectGetWidth(winBounds) >= CGRectGetHeight(winBounds)) return NO;
    CGRect feedInWin = [feed convertRect:feed.bounds toView:win];

    Class listCls = objc_lookUpClass("FQVShortVideoListViewController");
    Class seriesFeedCls = objc_lookUpClass("SSVideoSeriesFeedViewController");
    Class tbcCls = objc_lookUpClass("SSTabBarController");
    Class tabBarCls = objc_lookUpClass("SSTabBar");
    UIViewController *nearestVC = nil;
    UIViewController *listOwner = nil;
    UIViewController *pinchOwner = nil;
    UIViewController *tbc = nil;
    for (UIResponder *resp = feed.nextResponder; resp; resp = resp.nextResponder) {
        if (!nearestVC && [resp isKindOfClass:UIViewController.class]) {
            nearestVC = (UIViewController *)resp;
        }
        if (!listOwner && listCls && [resp isKindOfClass:listCls]) {
            listOwner = (UIViewController *)resp;
        }
        if (!pinchOwner && seriesFeedCls && [resp isKindOfClass:seriesFeedCls]) {
            pinchOwner = (UIViewController *)resp;
        }
        if (tbcCls && [resp isKindOfClass:tbcCls]) {
            tbc = (UIViewController *)resp;
            break;
        }
    }
    if (!nearestVC || !tbc) return NO;
    if (listOwner) {
        if (FQXVideoBackdropSingleList(listOwner) || FQXVideoBackdropHasTransition(listOwner)) {
            return NO;
        }
        id effPinchOwner = pinchOwner ?: listOwner;
        if (effPinchOwner && [objc_getAssociatedObject(effPinchOwner, FQXPinchPureCleanActiveKey) boolValue]) {
            return NO;
        }
    }
    BOOL selectedRoot = NO;
    for (UIViewController *cur = listOwner ?: nearestVC; cur; cur = cur.parentViewController) {
        if (cur.presentedViewController != nil) return NO;
        NSString *curName = NSStringFromClass(cur.class) ?: @"";
        if (cur != tbc && FQXControllerNameBlocksFeedDockMotion(curName)) return NO;
        UIViewController *parent = cur.parentViewController;
        if ([parent isKindOfClass:UINavigationController.class] &&
            ((UINavigationController *)parent).viewControllers.firstObject != cur) {
            return NO;
        }
        if (parent == tbc) {
            UIViewController *selVC = FQXObjGet(tbc, "selectedViewController");
            if (cur == selVC && tbc.presentedViewController == nil) selectedRoot = YES;
            break;
        }
    }
    if (!selectedRoot) return NO;

    UIView *bar = FQXObjGet(tbc, "customTabBar");
    if (!bar || (tabBarCls && ![bar isKindOfClass:tabBarCls])) return NO;
    if (!bar.window) {
        if (waitingForMount) *waitingForMount = YES;
        return NO;
    }
    if (bar.window != win || FQXIsBarHiddenByComment(bar) || FQXHasVisibleOverlaySheetInWindow(win)) {
        return NO;
    }
    for (UIView *v = bar; v; v = v.superview) {
        if (v.hidden || v.alpha <= 0.01) return NO;
    }
    CGRect barInWin = [bar convertRect:bar.bounds toView:win];
    UIEdgeInsets insets = feed.adjustedContentInset;
    if (!DKFeedScrollGeometryEligible(CGRectGetWidth(winBounds),
                                      CGRectGetHeight(winBounds),
                                      CGRectGetMinX(feedInWin),
                                      CGRectGetWidth(feedInWin),
                                      CGRectGetHeight(feedInWin),
                                      CGRectGetWidth(feed.bounds),
                                      CGRectGetHeight(feed.bounds),
                                      feed.contentSize.width,
                                      feed.contentSize.height,
                                      insets.top,
                                      insets.bottom,
                                      feed.alwaysBounceVertical ? 1 : 0,
                                      CGRectGetMinX(barInWin),
                                      CGRectGetWidth(barInWin))) {
        return NO;
    }
    FQXTabBarInteraction *inter = FQXActiveDockInteractionForBar(bar);
    if (!inter || !inter->_nativeDockBar || !inter->_nativeDockBar.window) {
        if (waitingForMount) *waitingForMount = YES;
        return NO;
    }
    if (CGRectIsEmpty(inter->_feedCapsuleAtRest)) {
        [bar setNeedsLayout];
        [bar layoutIfNeeded];
        if (CGRectIsEmpty(inter->_feedCapsuleAtRest)) {
            if (waitingForMount) *waitingForMount = YES;
            return NO;
        }
    }
    if (outInteraction) *outInteraction = inter;
    return YES;
}

- (void)handleFeedPan:(UIPanGestureRecognizer *)pan {
    UIScrollView *scroll = [pan.view isKindOfClass:UIScrollView.class] ? (UIScrollView *)pan.view : nil;
    if (!scroll) return;
    UIGestureRecognizerState state = pan.state;
    FQXDockCollapseMode mode = FQXCurrentDockCollapseMode();
    BOOL adoptingOnChanged = (state == UIGestureRecognizerStateChanged && !_feedPan && !_feedPendingPan);
    if (state == UIGestureRecognizerStateBegan || adoptingOnChanged) {
        if (!FQXFeedMotionSupported() || !FQXDockCollapseModeUsesFeedMotion(mode)) {
            return;
        }
        if (_feedPan && _feedPan != pan) {
            [self clearStaleFeedPanIfNeeded];
            if (_feedPan && _feedPan != pan) return;
        }
        _feedPendingPan = pan;
        _feedPendingWindow = scroll.window;
        _feedMode = mode;
    }
    if (_feedPendingPan == pan) {
        if ((state != UIGestureRecognizerStateBegan &&
             state != UIGestureRecognizerStateChanged &&
             state != UIGestureRecognizerStateEnded) ||
            mode != _feedMode || scroll.window != _feedPendingWindow) {
            [self resetFeedGesture];
            return;
        }
        BOOL waiting = NO;
        FQXTabBarInteraction *inter = nil;
        if (![self canTrackFeed:scroll mode:mode outInteraction:&inter waitingForMount:&waiting]) {
            if (!waiting || state == UIGestureRecognizerStateEnded) [self resetFeedGesture];
            return;
        }
        _feedPendingPan = nil;
        _feedPendingWindow = nil;
        _feedPan = pan;
        _activeInteraction = inter;
        BOOL siriai = (mode == FQXDockCollapseModeSiriai);
        BOOL startedCompact = [inter feedCompact];
        BOOL caughtMotion = [inter beginFeedDrag];
        CGPoint origin = (caughtMotion && state == UIGestureRecognizerStateBegan)
            ? [pan translationInView:scroll.window] : CGPointZero;
        DKFeedPanBegin(&_panState, CGRectGetHeight(scroll.bounds), siriai ? 1 : 0,
                       startedCompact ? 1 : 0, caughtMotion ? 1 : 0,
                       origin.x, origin.y, state == UIGestureRecognizerStateBegan ? 1 : 0);
    }

    if (_feedPan != pan) return;
    UIWindow *window = scroll.window;
    FQXTabBarInteraction *inter = _activeInteraction;
    if (state == UIGestureRecognizerStateCancelled || state == UIGestureRecognizerStateFailed ||
        mode != _feedMode || !window || !inter || !inter->_nativeDockActive ||
        inter->_bar.window != window || !scroll.isScrollEnabled ||
        FQXIsBarHiddenByComment(inter->_bar) || FQXHasVisibleOverlaySheetInWindow(window)) {
        [self cancelFeedPan:pan];
        return;
    }

    BOOL ended = (state == UIGestureRecognizerStateEnded);
    CGPoint translation = [pan translationInView:window];
    CGFloat velocityY = ended ? [pan velocityInView:window].y : 0.0;
    double deltaProgress = 0.0;
    double endVelocityProgress = 0.0;
    int endCompact = 0;
    int locked = 0;
    DKFeedPanResult result = DKFeedPanUpdate(&_panState, translation.x, translation.y,
                                             velocityY, ended ? 1 : 0,
                                             &deltaProgress, &endCompact, &endVelocityProgress, &locked);
    if (result == DKFeedPanFinishedUnlocked) {
        BOOL keepCompact = (_panState.startedCompact != 0);
        [self resetFeedGesture];
        [inter setFeedCompact:keepCompact animated:YES];
        return;
    }
    if (result == DKFeedPanIgnored) return;
    if (deltaProgress != 0.0) [inter moveFeedDrag:(CGFloat)deltaProgress];
    if (result == DKFeedPanEnded) {
        [self resetFeedGesture];
        [inter endFeedDrag:(endCompact != 0) velocity:(CGFloat)endVelocityProgress];
    }
}

@end

static FQXTabBarInteraction *FQXActiveDockInteractionForBar(UIView *bar) {
    if (!bar) return nil;
    for (FQXTabBarInteraction *inter in FQXTrackedDockInteractions().allObjects) {
        if (inter->_bar == bar && inter->_nativeDockActive) {
            return inter;
        }
    }
    return nil;
}

static BOOL FQXHasVisibleActiveDockInWindow(UIWindow *window) {
    if (!window) return NO;
    for (FQXTabBarInteraction *inter in FQXTrackedDockInteractions().allObjects) {
        UIView *bar = inter->_bar;
        if (inter->_nativeDockActive && bar && bar.window == window && !bar.hidden && bar.alpha > 0.05) {
            return YES;
        }
    }
    return NO;
}

static NSString *const FQXDockGeometryAnimation = @"FanqieX.dock.geometry";

static CGPoint FQXPointInDisplayedDock(UIView *view, UIView *bar, CGPoint point) {
    if ([view.layer animationForKey:FQXDockGeometryAnimation]) {
        CALayer *live = view.layer.presentationLayer, *parent = bar.layer.presentationLayer;
        if (live && parent) return [live convertPoint:point fromLayer:parent];
    }
    return [view convertPoint:point fromView:bar];
}

static CGRect FQXDisplayedDockRect(UIView *view, UIView *bar, CGRect target) {
    if ([view.layer animationForKey:FQXDockGeometryAnimation]) {
        CALayer *live = view.layer.presentationLayer, *parent = bar.layer.presentationLayer;
        if (live && parent) {
            CGRect local = [view.layer convertRect:target fromLayer:bar.layer];
            return [live convertRect:local toLayer:parent];
        }
    }
    return target;
}

static BOOL FQXPointIsInDockBottomEdgeStrip(FQXTabBarInteraction *inter, CGPoint pointInBar) {
    if (!inter || !inter->_nativeDockActive || CGRectIsEmpty(inter->_dockRenderedPlatterRectInBar)) return NO;
    CGFloat maxInteractiveY = CGRectGetMaxY(FQXDisplayedDockRect(inter->_nativeDockBar, inter->_bar,
                                                                inter->_dockRenderedPlatterRectInBar)) + 3.0;
    if (inter->_detachedHostIndex != NSNotFound && inter->_detachedButton && !inter->_detachedButton.hidden) {
        maxInteractiveY = MAX(maxInteractiveY, CGRectGetMaxY(FQXDisplayedDockRect(inter->_detachedButton, inter->_bar, inter->_detachedButton.frame)) + 3.0);
    }
    return pointInBar.y > maxInteractiveY;
}

static UITabBar *FQXNativeDockAtPoint(FQXTabBarInteraction *interaction, UIView *bar, CGPoint point) {
    UITabBar *dock = interaction ? interaction->_nativeDockBar : nil;
    if (!dock || !bar.window || bar.hidden || bar.alpha <= 0.01 || !bar.userInteractionEnabled ||
        dock.superview != bar || dock.hidden || dock.alpha <= 0.01 || !dock.userInteractionEnabled) return nil;
    return CGRectContainsPoint(FQXDisplayedDockRect(dock, bar, interaction->_dockRenderedPlatterRectInBar), point) ? dock : nil;
}

static BOOL (*OrigSSTabBarPointInside)(id, SEL, CGPoint, id);
static BOOL HookSSTabBarPointInside(UIView *bar, SEL cmd, CGPoint point, UIEvent *event) {
    FQXTabBarInteraction *inter = FQXActiveDockInteractionForBar(bar);
    if (inter) {
        if ([inter usesFeedMotion] && inter->_feedControlsHidden) return NO;
        if (inter->_detachedHostIndex != NSNotFound) {
            FQXDetachedDockButtonView *det = inter->_detachedButton;
            if (det && det.superview == bar && !det.hidden && det.alpha > 0.01 && det.userInteractionEnabled) {
                CGPoint ptInDet = FQXPointInDisplayedDock(det, bar, point);
                if ([det pointInside:ptInDet withEvent:event]) {
                    return YES;
                }
            }
        }
        if (FQXNativeDockAtPoint(inter, bar, point)) return YES;
        if ([inter usesFeedMotion] && (inter->_feedSpring.progress > 0.005 || inter->_feedSpring.overtravel != 0.0)) {
            return NO;
        }
        if ([objc_getAssociatedObject(inter->_proxy, &FQXDockCompactKey) boolValue]) return NO;
        // Prevent UITabBar's invisible bottom overhang below the rendered platter from claiming
        // touches inside the iOS Home Indicator edge strip.
        if (FQXPointIsInDockBottomEdgeStrip(inter, point)) {
            return NO;
        }
    }
    return OrigSSTabBarPointInside ? OrigSSTabBarPointInside(bar, cmd, point, event) : NO;
}

static UIView *(*OrigSSTabBarHitTest)(id, SEL, CGPoint, id);
static UIView *HookSSTabBarHitTest(UIView *bar, SEL cmd, CGPoint point, UIEvent *event) {
    FQXTabBarInteraction *inter = FQXActiveDockInteractionForBar(bar);
    if (inter) {
        if ([inter usesFeedMotion] && inter->_feedControlsHidden) return nil;
        if (inter->_detachedHostIndex != NSNotFound) {
            FQXDetachedDockButtonView *det = inter->_detachedButton;
            if (det && det.superview == bar && !det.hidden && det.alpha > 0.01 && det.userInteractionEnabled) {
                CGPoint ptInDet = FQXPointInDisplayedDock(det, bar, point);
                if ([det pointInside:ptInDet withEvent:event]) {
                    UIView *resolved = [det hitTest:ptInDet withEvent:event] ?: (det.hitButton ?: det);
                    if (event && resolved) FQXMarkDockTouchActivity(0.35);
                    static CFTimeInterval lastHitDiagTs = 0;
                    CFTimeInterval now = CACurrentMediaTime();
                    if (now - lastHitDiagTs >= 0.15) {
                        lastHitDiagTs = now;
                        FQXDiagRecordEvent(FQXDiagCategoryUI, @"dock_detached_hit_test", @{
                            @"moduleTitle": det.moduleTitle ?: @"",
                            @"hostIndex": @(inter->_detachedHostIndex),
                            @"pointInBar": @[@(round(point.x * 10.0) / 10.0), @(round(point.y * 10.0) / 10.0)],
                            @"pointInDetached": @[@(round(ptInDet.x * 10.0) / 10.0), @(round(ptInDet.y * 10.0) / 10.0)],
                            @"detachedFrame": FQXDockRectArray(det.frame),
                            @"barBounds": FQXDockRectArray(bar.bounds),
                            @"resolvedClass": NSStringFromClass(resolved.class) ?: @"",
                        }, NO);
                    }
                    return resolved;
                }
            }
        }
        if (FQXPointIsInDockBottomEdgeStrip(inter, point)) {
            return nil;
        }
        UITabBar *dock = FQXNativeDockAtPoint(inter, bar, point);
        if (dock) {
            UIView *hit = [dock hitTest:FQXPointInDisplayedDock(dock, bar, point) withEvent:event];
            if (hit) {
                if (event) FQXMarkDockTouchActivity(0.35);
                return hit;
            }
        }
        if ([inter usesFeedMotion] && (inter->_feedSpring.progress > 0.005 || inter->_feedSpring.overtravel != 0.0)) {
            return nil;
        }
        if ([objc_getAssociatedObject(inter->_proxy, &FQXDockCompactKey) boolValue]) return nil;
    }
    UIView *fallbackHit = OrigSSTabBarHitTest ? OrigSSTabBarHitTest(bar, cmd, point, event) : nil;
    if (event && fallbackHit) FQXMarkDockTouchActivity(0.35);
    return fallbackHit;
}

static UIRectEdge FQXStripBottomEdgeDeferralIfDockVisible(UIViewController *vc, UIRectEdge origEdges) {
    if ((origEdges & UIRectEdgeBottom) == 0 || !vc || !vc.isViewLoaded || !vc.view.window) {
        return origEdges;
    }
    CGRect b = vc.view.bounds;
    if (CGRectGetHeight(b) <= CGRectGetWidth(b)) {
        return origEdges; // Preserve landscape fullscreen edge protection
    }
    if (FQXHasVisibleActiveDockInWindow(vc.view.window)) {
        return origEdges & ~UIRectEdgeBottom;
    }
    return origEdges;
}

static UIRectEdge (*OrigSeriesFeedDeferEdges)(id, SEL);
static UIRectEdge HookSeriesFeedDeferEdges(UIViewController *vc, SEL cmd) {
    UIRectEdge orig = OrigSeriesFeedDeferEdges ? OrigSeriesFeedDeferEdges(vc, cmd) : UIRectEdgeNone;
    return FQXStripBottomEdgeDeferralIfDockVisible(vc, orig);
}

static UIRectEdge (*OrigShortVideoListDeferEdges)(id, SEL);
static UIRectEdge HookShortVideoListDeferEdges(UIViewController *vc, SEL cmd) {
    UIRectEdge orig = OrigShortVideoListDeferEdges ? OrigShortVideoListDeferEdges(vc, cmd) : UIRectEdgeNone;
    return FQXStripBottomEdgeDeferralIfDockVisible(vc, orig);
}

static UIRectEdge (*OrigTabBarControllerDeferEdges)(id, SEL);
static UIRectEdge HookTabBarControllerDeferEdges(UIViewController *vc, SEL cmd) {
    UIRectEdge orig = OrigTabBarControllerDeferEdges ? OrigTabBarControllerDeferEdges(vc, cmd) : UIRectEdgeNone;
    return FQXStripBottomEdgeDeferralIfDockVisible(vc, orig);
}

static void FQXSetNativeTabSelectionLensVisible(UIView *root, BOOL visible, NSInteger depth) {
    if (!root || depth > 5) return;
    NSString *clsName = NSStringFromClass(root.class);
    if ([clsName containsString:@"TabSelectionView"] || [clsName containsString:@"SelectionPlatter"]) {
        // Only override UIKit's lens while the detached module owns selection.
        FQXSetBackdropContentHidden(root, !visible);
        return;
    }
    for (UIView *sub in root.subviews) {
        FQXSetNativeTabSelectionLensVisible(sub, visible, depth + 1);
    }
}

@implementation FQXTabBarInteraction

- (instancetype)init {
    self = [super init];
    if (self) {
        _wiredControls = [NSHashTable weakObjectsHashTable];
        _detachedHostIndex = NSNotFound;
        _dockAppliedStyle = UIUserInterfaceStyleUnspecified;
        _dockAppliedInkState = -1;
        _dockPlatterHeight = 62.0;
        _dockPlatterInset = 21.0;
        _appliedCollapseMode = FQXDockCollapseModeOff;
        _feedLastSelectedIndex = NSNotFound;
        _feedBaseScaleX = 1.0;
        _feedBaseScaleY = 1.0;
        DKFeedSpringInit(&_feedSpring);
    }
    return self;
}

- (BOOL)usesFeedMotion {
    return FQXFeedMotionSupported() && FQXDockCollapseModeUsesFeedMotion(self->_appliedCollapseMode);
}

- (BOOL)feedCompact {
    return self->_feedSpring.compact != 0;
}

static void FQXCollectTabButtonsRecursive(UIView *root, Class buttonClass, NSMutableArray<UIView *> *result) {
    if (!root || !buttonClass) return;
    for (UIView *subview in root.subviews) {
        if ([subview isKindOfClass:buttonClass]) [result addObject:subview];
        else FQXCollectTabButtonsRecursive(subview, buttonClass, result);
    }
}

static void FQXSetViewTransformAndCenter(UIView *view, CGAffineTransform transform, CGPoint center) {
    if (!view) return;
    if (!CGAffineTransformEqualToTransform(view.transform, transform)) view.transform = transform;
    if (!CGPointEqualToPoint(view.center, center)) view.center = center;
}

- (void)cleanupFeedMotionVisuals {
    [self->_feedDisplayLink invalidate];
    self->_feedDisplayLink = nil;
    [UIView performWithoutAnimation:^{
        [CATransaction begin];
        [CATransaction setDisableActions:YES];
        if (self->_siriaiMinimumFillView) {
            [self->_siriaiMinimumFillView removeFromSuperview];
            self->_siriaiMinimumFillView = nil;
        }
        if (self->_feedContentOverlay) {
            [self->_feedContentOverlay removeFromSuperview];
            self->_feedContentOverlay = nil;
        }
        self->_feedDockSlots = nil;
        if (self->_nativeDockBar) {
            if (self->_nativeDockBar.alpha != 1.0) self->_nativeDockBar.alpha = 1.0;
            UIView *platter = FQXFindDockPlatter(self->_nativeDockBar);
            if (platter && platter.alpha != 1.0) platter.alpha = 1.0;
            static Class platterCls = Nil;
            static Class itemPlatterCls = Nil;
            static dispatch_once_t cOnce;
            dispatch_once(&cOnce, ^{
                platterCls = NSClassFromString(@"UIKit._UITabBarPlatterView");
                itemPlatterCls = NSClassFromString(@"UIKit._UITabBarItemPlatterView");
            });
            if ((platterCls || itemPlatterCls) && platter && platter.superview) {
                for (UIView *sib in platter.superview.subviews) {
                    if ((platterCls && [sib isKindOfClass:platterCls]) ||
                        (itemPlatterCls && [sib isKindOfClass:itemPlatterCls])) {
                        if (sib.alpha != 1.0) sib.alpha = 1.0;
                    }
                }
            }
            FQXBackdropBlurView *blur = objc_getAssociatedObject(self->_nativeDockBar, FQXDockBackdropBlurViewKey);
            if (blur && blur.alpha != 1.0) blur.alpha = 1.0;
            self->_nativeDockBar.accessibilityElementsHidden = NO;
        }
        if (self->_dockTitleOverlay) {
            if (!CGAffineTransformIsIdentity(self->_dockTitleOverlay.transform)) {
                self->_dockTitleOverlay.transform = CGAffineTransformIdentity;
            }
            if (self->_dockTitleOverlay.alpha != 1.0) self->_dockTitleOverlay.alpha = 1.0;
            for (UIView *lbl in self->_dockTitleOverlay.arrangedSubviews) {
                if (!CGAffineTransformIsIdentity(lbl.transform)) lbl.transform = CGAffineTransformIdentity;
            }
        }
        if (self->_detachedButton) {
            if (!CGAffineTransformIsIdentity(self->_detachedButton.transform)) {
                self->_detachedButton.transform = CGAffineTransformIdentity;
            }
            [self->_detachedButton setFeedGlyphScale:1.0];
            if (self->_detachedButton.alpha != 1.0) self->_detachedButton.alpha = 1.0;
            self->_detachedButton.accessibilityElementsHidden = NO;
        }
        [CATransaction commit];
    }];
    self->_feedControlsHidden = NO;
}

- (void)syncFeedDockSlotVisuals {
    UITabBar *tabBar = self->_nativeDockBar;
    NSArray<UITabBarItem *> *items = tabBar.items;
    if (![self usesFeedMotion] || !tabBar || items.count == 0) {
        if (self->_feedContentOverlay) {
            [self->_feedContentOverlay removeFromSuperview];
            self->_feedContentOverlay = nil;
        }
        self->_feedDockSlots = nil;
        return;
    }
    if (!self->_feedContentOverlay) {
        UIView *overlay = [[UIView alloc] initWithFrame:self->_bar ? self->_bar.bounds : CGRectZero];
        overlay.userInteractionEnabled = NO;
        overlay.isAccessibilityElement = NO;
        overlay.accessibilityElementsHidden = YES;
        overlay.backgroundColor = UIColor.clearColor;
        overlay.clipsToBounds = NO;
        overlay.hidden = !self->_nativeDockActive;
        self->_feedContentOverlay = overlay;
    }
    NSUInteger count = items.count;
    if (self->_feedDockSlots.count != count) {
        for (FQXFeedDockSlotView *oldSlot in self->_feedDockSlots) {
            [oldSlot removeFromSuperview];
        }
        NSMutableArray<FQXFeedDockSlotView *> *fresh = [NSMutableArray arrayWithCapacity:count];
        for (NSUInteger i = 0; i < count; ++i) {
            FQXFeedDockSlotView *slot = [[FQXFeedDockSlotView alloc] initWithFrame:CGRectMake(0.0, 0.0, 64.0, 62.0)];
            slot.bounds = CGRectMake(0.0, 0.0, 64.0, 62.0);
            slot.slotIndex = i;
            [self->_feedContentOverlay addSubview:slot];
            [fresh addObject:slot];
        }
        self->_feedDockSlots = [fresh copy];
    }

    BOOL isDark = [self isDarkDock];
    BOOL lightBase = (FQXDockMaterialUsesVideoLightBase((int)FQXCurrentDockMaterialMode()) != 0);
    BOOL roseSel = (FQXEffectiveDockSelectionTintStyle() != FQXSelectionTintStyleDefault);
    CGFloat white = isDark ? 1.0 : 0.0;
    UIColor *selectedInk = (lightBase || roseSel)
        ? FQXVideoInkUIColor(1.0)
        : [UIColor colorWithWhite:white alpha:1.0];
    UIColor *normalInk = lightBase
        ? FQXVideoInkUIColor(0.80)
        : [UIColor colorWithWhite:white alpha:(isDark ? 0.68 : 0.86)];
    NSInteger displayMode = [self dockDisplayMode];
    CGFloat ptSize = [self dockIconPointSize];
    CGFloat baseScale = MAX(0.70, MIN(1.30, self->_feedBaseScaleY > 0.05 ? self->_feedBaseScaleY : 1.0));
    NSUInteger hostSel = [self currentSelectedIndex];
    NSUInteger selectedSlot = self->_capsuleHostIndices.count
        ? [self->_capsuleHostIndices indexOfObject:@(hostSel)] : hostSel;

    for (NSUInteger i = 0; i < count; ++i) {
        FQXFeedDockSlotView *slot = self->_feedDockSlots[i];
        slot.slotIndex = i;
        NSString *title = (i < self->_dockTitles.count) ? self->_dockTitles[i] : (items[i].accessibilityLabel ?: @"");
        NSUInteger hostIdx = (i < self->_capsuleHostIndices.count) ? self->_capsuleHostIndices[i].unsignedIntegerValue : i;
        UIButton *hostBtn = (hostIdx < self->_buttons.count && [self->_buttons[hostIdx] isKindOfClass:UIButton.class])
            ? self->_buttons[hostIdx] : nil;
        BOOL selected = (i == selectedSlot);

        BOOL hasIcon = NO;
        BOOL hasCaption = NO;
        BOOL isPrimaryTitle = NO;
        UIImage *normGlyph = nil;
        UIImage *selGlyph = nil;

        if (displayMode == 2) {
            hasCaption = (title.length > 0);
            isPrimaryTitle = YES;
        } else {
            CGFloat symPt = (displayMode == 1) ? MAX(16.0, MIN(26.0, ptSize * 0.72)) : 19.0;
            normGlyph = FQXDockGlyph(title, hostBtn, symPt, NO, normalInk);
            selGlyph = FQXDockGlyph(title, hostBtn, symPt, YES, selectedInk);
            if (normGlyph) {
                hasIcon = YES;
                hasCaption = (displayMode == 0 && title.length > 0);
                isPrimaryTitle = NO;
            } else {
                hasCaption = (title.length > 0);
                isPrimaryTitle = YES;
            }
        }

        slot.hasIcon = hasIcon;
        slot.hasCaption = hasCaption;
        slot.isPrimaryTitle = isPrimaryTitle;

        if (hasIcon) {
            if (slot.iconView.hidden) slot.iconView.hidden = NO;
            slot.iconView.image = normGlyph;
            slot.iconView.highlightedImage = selGlyph ?: normGlyph;
            slot.iconView.highlighted = selected;
            CGFloat iw = MAX(24.0, ceil(normGlyph.size.width) + 2.0);
            CGFloat ih = MAX(22.0, ceil(normGlyph.size.height) + 2.0);
            CGRect ib = CGRectMake(0.0, 0.0, iw, ih);
            if (!CGRectEqualToRect(slot.iconView.bounds, ib)) slot.iconView.bounds = ib;
        } else if (!slot.iconView.hidden) {
            slot.iconView.hidden = YES;
        }

        if (hasCaption) {
            if (slot.captionLabel.hidden) slot.captionLabel.hidden = NO;
            if (![slot.captionLabel.text isEqualToString:title]) slot.captionLabel.text = title;
            if (![slot.captionLabel.textColor isEqual:normalInk]) slot.captionLabel.textColor = normalInk;
            if (![slot.captionLabel.highlightedTextColor isEqual:selectedInk]) slot.captionLabel.highlightedTextColor = selectedInk;
            if (slot.captionLabel.highlighted != selected) slot.captionLabel.highlighted = selected;
            CGFloat fontPt = (isPrimaryTitle ? 15.5 : 10.5) * baseScale;
            UIFontWeight weight = selected ? UIFontWeightSemibold : UIFontWeightMedium;
            UIFont *desiredFont = [UIFont systemFontOfSize:fontPt weight:weight];
            if (![slot.captionLabel.font isEqual:desiredFont]) {
                slot.captionLabel.font = desiredFont;
            }
            CGFloat availW = slot.restSlotWidth > 16.0 ? (slot.restSlotWidth - 4.0) : 56.0;
            CGRect cb = CGRectMake(0.0, 0.0, MAX(20.0, MIN(72.0 * MAX(0.85, self->_feedBaseScaleX), availW)),
                                   ceil(slot.captionLabel.font.lineHeight) + 2.0);
            if (!CGRectEqualToRect(slot.captionLabel.bounds, cb)) slot.captionLabel.bounds = cb;
        } else if (!slot.captionLabel.hidden) {
            slot.captionLabel.hidden = YES;
        }
    }
}

- (void)prepareFeedDockItemsWithPlatter:(UIView *)platter {
    UITabBar *tabBar = self->_nativeDockBar;
    UIView *bar = self->_bar;
    if (![self usesFeedMotion] || !tabBar || !bar || CGRectIsEmpty(self->_feedCapsuleAtRest)) {
        [self syncFeedDockSlotVisuals];
        return;
    }
    [self syncFeedDockSlotVisuals];
    NSUInteger count = self->_feedDockSlots.count;
    if (count == 0) return;

    if (!CGRectEqualToRect(self->_feedContentOverlay.frame, bar.bounds)) {
        self->_feedContentOverlay.frame = bar.bounds;
    }

    NSMutableArray<UIView *> *buttons = [NSMutableArray array];
    Class floatingBtnCls = NSClassFromString(@"_UITabButton");
    if (floatingBtnCls) {
        FQXCollectTabButtonsRecursive(platter, floatingBtnCls, buttons);
        if (!buttons.count) FQXCollectTabButtonsRecursive(tabBar, floatingBtnCls, buttons);
    }
    if (!buttons.count) {
        Class compatBtnCls = NSClassFromString(@"UITabBarButton");
        if (compatBtnCls) FQXCollectTabButtonsRecursive(tabBar, compatBtnCls, buttons);
    }

    [buttons sortUsingComparator:^NSComparisonResult(UIView *left, UIView *right) {
        CGFloat ax = [bar convertPoint:CGPointMake(CGRectGetMidX(left.bounds), CGRectGetMidY(left.bounds)) fromView:left].x;
        CGFloat bx = [bar convertPoint:CGPointMake(CGRectGetMidX(right.bounds), CGRectGetMidY(right.bounds)) fromView:right].x;
        return ax < bx ? NSOrderedAscending : (ax > bx ? NSOrderedDescending : NSOrderedSame);
    }];

    NSMutableArray<NSNumber *> *colCenters = [NSMutableArray arrayWithCapacity:count];
    NSMutableArray<NSNumber *> *colWidths = [NSMutableArray arrayWithCapacity:count];
    CGFloat lastX = -CGFLOAT_MAX;
    for (UIView *button in buttons) {
        CGRect rectInBar = [button convertRect:button.bounds toView:bar];
        if (CGRectGetWidth(rectInBar) < 8.0) continue;
        CGFloat midX = CGRectGetMidX(rectInBar);
        if (fabs(midX - lastX) > 1.0) {
            [colCenters addObject:@(midX)];
            [colWidths addObject:@(CGRectGetWidth(rectInBar))];
            lastX = midX;
        }
    }

    BOOL rtl = ([UIView userInterfaceLayoutDirectionForSemanticContentAttribute:tabBar.semanticContentAttribute]
                == UIUserInterfaceLayoutDirectionRightToLeft);
    CGFloat capMidX = CGRectGetMidX(self->_feedCapsuleAtRest);
    CGRect fallbackTrack = CGRectInset(self->_feedCapsuleAtRest, 4.0 * MAX(0.75, self->_feedBaseScaleX), 0.0);
    CGFloat fallbackSlotW = CGRectGetWidth(fallbackTrack) / (CGFloat)count;
    BOOL useMeasured = (colCenters.count == count);

    for (NSUInteger col = 0; col < count; ++col) {
        NSUInteger index = rtl ? (count - 1 - col) : col;
        FQXFeedDockSlotView *slot = self->_feedDockSlots[index];
        CGFloat cx = useMeasured
            ? colCenters[col].doubleValue
            : (CGRectGetMinX(fallbackTrack) + fallbackSlotW * ((CGFloat)col + 0.5));
        CGFloat sw = useMeasured ? colWidths[col].doubleValue : fallbackSlotW;
        slot.restOffsetX = cx - capMidX;
        slot.restSlotWidth = sw;
        if (slot.hasCaption) {
            CGRect cb = CGRectMake(0.0, 0.0, MAX(20.0, MIN(72.0 * MAX(0.85, self->_feedBaseScaleX), sw - 4.0)),
                                   ceil(slot.captionLabel.font.lineHeight) + 2.0);
            if (!CGRectEqualToRect(slot.captionLabel.bounds, cb)) slot.captionLabel.bounds = cb;
        }
    }
}

- (void)applyFeedSlotsAtTarget:(CGPoint)target
                        scaleX:(CGFloat)sx
                        scaleY:(CGFloat)sy
                    glyphScale:(CGFloat)glyphScale
                  captionScale:(CGFloat)captionScale
                 captionAmount:(CGFloat)captionAmount
                 shownProgress:(double)shownProgress
                        siriai:(BOOL)siriai
                  contentAlpha:(CGFloat)contentAlpha {
    UIView *overlay = self->_feedContentOverlay;
    if (!overlay || !self->_feedDockSlots.count) return;
    if (overlay.alpha != contentAlpha) overlay.alpha = contentAlpha;
    if (contentAlpha <= 0.001) return;

    CGFloat baseScale = MAX(0.70, MIN(1.30, self->_feedBaseScaleY > 0.05 ? self->_feedBaseScaleY : 1.0));
    CGFloat safeGlyph = MAX(0.001, baseScale * glyphScale);
    CGFloat safeTitleScale = MAX(0.001, glyphScale);
    CGFloat safeCapScale = MAX(0.001, captionScale);
    CGAffineTransform iconXform = CGAffineTransformMakeScale(safeGlyph, safeGlyph);
    CGAffineTransform primaryTitleXform = CGAffineTransformMakeScale(safeTitleScale, safeTitleScale);
    CGAffineTransform capXform = CGAffineTransformMakeScale(safeCapScale, safeCapScale);
    double rawIconY = 0.0;
    double rawCapY = 0.0;
    DKFeedComputeSlotVerticalOffsets(siriai ? 1 : 0,
                                     shownProgress,
                                     sy,
                                     baseScale,
                                     glyphScale,
                                     captionScale,
                                     &rawIconY,
                                     &rawCapY);
    CGFloat iconOffsetY = (CGFloat)rawIconY;
    CGFloat capOffsetY = (CGFloat)rawCapY;
    const CGPoint slotMid = CGPointMake(32.0, 31.0);

    for (FQXFeedDockSlotView *slot in self->_feedDockSlots) {
        CGPoint slotCenter = CGPointMake(target.x + slot.restOffsetX * sx, target.y);
        if (!CGPointEqualToPoint(slot.center, slotCenter)) slot.center = slotCenter;

        if (slot.hasIcon && slot.hasCaption) {
            FQXSetViewTransformAndCenter(slot.iconView, iconXform, CGPointMake(slotMid.x, slotMid.y + iconOffsetY));
            if (slot.captionLabel.alpha != captionAmount) slot.captionLabel.alpha = captionAmount;
            if (captionAmount > 0.001) {
                FQXSetViewTransformAndCenter(slot.captionLabel, capXform, CGPointMake(slotMid.x, slotMid.y + capOffsetY));
            }
        } else if (slot.hasIcon) {
            FQXSetViewTransformAndCenter(slot.iconView, iconXform, slotMid);
        } else if (slot.hasCaption) {
            if (slot.captionLabel.alpha != 1.0) slot.captionLabel.alpha = 1.0;
            FQXSetViewTransformAndCenter(slot.captionLabel, primaryTitleXform, slotMid);
        }
    }
}

- (void)applySiriaiSurface:(DKSiriaiDockGeometry)shape target:(CGPoint)target {
    UITabBar *tabBar = self->_nativeDockBar;
    UIView *bar = self->_bar;
    if (!tabBar || !bar) return;
    CGFloat glassAlpha = (shape.whiteAmount == 1.0) ? 0.0 : (CGFloat)shape.surfaceAlpha;
    if (tabBar.alpha != glassAlpha) tabBar.alpha = glassAlpha;

    CGFloat fillAlpha = (CGFloat)(shape.whiteAmount * shape.surfaceAlpha);
    if (fillAlpha <= 0.0005 && (!self->_siriaiMinimumFillView || self->_siriaiMinimumFillView.alpha == 0.0)) return;

    if (fillAlpha > 0.0005) {
        if (!self->_siriaiMinimumFillView) {
            UIView *fill = [[UIView alloc] initWithFrame:CGRectZero];
            fill.userInteractionEnabled = NO;
            fill.isAccessibilityElement = NO;
            fill.accessibilityElementsHidden = YES;
            fill.backgroundColor = UIColor.whiteColor;
            fill.layer.cornerCurve = kCACornerCurveContinuous;
            self->_siriaiMinimumFillView = fill;
        }
        if (self->_siriaiMinimumFillView.superview != bar) {
            UIView *above = (self->_feedContentOverlay && self->_feedContentOverlay.superview == bar)
                ? self->_feedContentOverlay : tabBar;
            [bar insertSubview:self->_siriaiMinimumFillView aboveSubview:above];
        }
        CGRect fillBounds = CGRectMake(0.0, 0.0, shape.width, shape.height);
        if (!CGRectEqualToRect(self->_siriaiMinimumFillView.bounds, fillBounds)) {
            self->_siriaiMinimumFillView.bounds = fillBounds;
        }
        if (!CGPointEqualToPoint(self->_siriaiMinimumFillView.center, target)) {
            self->_siriaiMinimumFillView.center = target;
        }
        CGFloat radius = shape.height * 0.5;
        if (self->_siriaiMinimumFillView.layer.cornerRadius != radius) {
            self->_siriaiMinimumFillView.layer.cornerRadius = radius;
        }
    }
    if (self->_siriaiMinimumFillView && self->_siriaiMinimumFillView.alpha != fillAlpha) {
        self->_siriaiMinimumFillView.alpha = fillAlpha;
    }
}

- (void)applyFeedMotion:(double)progress {
    UITabBar *tabBar = self->_nativeDockBar;
    UIView *bar = self->_bar;
    CGFloat width = CGRectGetWidth(self->_feedCapsuleAtRest);
    CGFloat height = CGRectGetHeight(self->_feedCapsuleAtRest);
    if (!tabBar || !bar || width <= 0.0 || height <= 0.0) return;

    [UIView performWithoutAnimation:^{
        [CATransaction begin];
        [CATransaction setDisableActions:YES];

        BOOL hasDetached = (self->_detachedHostIndex != NSNotFound &&
                            self->_detachedButton != nil &&
                            !CGRectIsEmpty(self->_feedDetachedAtRest));
        CGPoint pivot = CGPointMake(CGRectGetMidX(self->_feedCapsuleAtRest), CGRectGetMidY(self->_feedCapsuleAtRest));

        if (self->_appliedCollapseMode == FQXDockCollapseModeSiriai) {
            CGRect group = self->_feedCapsuleAtRest;
            if (hasDetached) group = CGRectUnion(group, self->_feedDetachedAtRest);
            CGFloat x = CGRectGetMinX(group);
            CGFloat y = CGRectGetMinY(group);
            CGFloat bottomLimit = MAX(height + 4.0, CGRectGetMaxY(bar.bounds) - y);
            CGFloat camDiam = hasDetached ? CGRectGetWidth(self->_feedDetachedAtRest) : 0.0;
            CGFloat gap = hasDetached ? self->_feedGap : 0.0;
            DKSiriaiDockGeometry shape = DKSiriaiDockShape(width, height, camDiam, gap, bottomLimit, progress);
            DKSiriaiApplyRebound(&shape, self->_feedSpring.overtravel, CGRectGetWidth(group), camDiam, bottomLimit);
            if (self->_feedSpring.overtravel < 0.0) {
                double boostX = 1.0 - 0.22 * self->_feedSpring.overtravel;
                double boostY = fmin(boostX, bottomLimit / fmax(1.0, shape.height));
                double midX = CGRectGetWidth(group) * 0.5;
                shape.centerX = midX + (shape.centerX - midX) * boostX;
                shape.cameraX = midX + (shape.cameraX - midX) * boostX;
                shape.width *= boostX;
                shape.height *= boostY;
                shape.cameraScale *= boostY;
            }
            if (self->_feedSpring.siriaiOpeningMaterial > 1.0) {
                DKSiriaiSetDockMaterial(&shape, self->_feedSpring.siriaiOpeningMaterial);
            }
            CGPoint target = CGPointMake(x + shape.centerX, y + shape.centerY);
            CGFloat sx = MAX(0.001, shape.width / width);
            CGFloat sy = MAX(0.001, shape.height / height);
            CGPoint hostCenter = CGPointMake(target.x + (self->_feedHostCenterAtRest.x - pivot.x) * sx,
                                             target.y + (self->_feedHostCenterAtRest.y - pivot.y) * sy);
            FQXSetViewTransformAndCenter(tabBar,
                                         CGAffineTransformMakeScale(self->_feedBaseScaleX * sx, self->_feedBaseScaleY * sy),
                                         hostCenter);
            self->_dockRenderedPlatterRectInBar = CGRectMake(target.x - shape.width * 0.5,
                                                             target.y - shape.height * 0.5,
                                                             shape.width,
                                                             shape.height);
            [self applySiriaiSurface:shape target:target];
            BOOL controlsHidden = (shape.contentAlpha < 0.10);
            self->_feedControlsHidden = controlsHidden;
            if (tabBar.accessibilityElementsHidden != controlsHidden) {
                tabBar.accessibilityElementsHidden = controlsHidden;
            }
            CGFloat openRebound = (self->_feedSpring.overtravel < 0.0) ? MAX(1.0, sy) : 1.0;
            CGFloat effectiveGlyphScale = MAX(0.001, shape.glyphScale * openRebound);
            CGFloat effectiveCaptionScale = MAX(0.001, shape.captionScale * openRebound);
            double siriShown = fmin(1.0, fmax(0.0, progress)) + self->_feedSpring.overtravel;
            [self applyFeedSlotsAtTarget:target
                                  scaleX:sx
                                  scaleY:sy
                              glyphScale:effectiveGlyphScale
                            captionScale:effectiveCaptionScale
                           captionAmount:shape.captionAmount
                           shownProgress:siriShown
                                  siriai:YES
                            contentAlpha:shape.contentAlpha];
            if (hasDetached) {
                CGFloat cameraScale = MAX(0.001, shape.cameraScale);
                CGPoint detCenter = CGPointMake(x + shape.cameraX, y + shape.cameraY);
                FQXSetViewTransformAndCenter(self->_detachedButton,
                                             CGAffineTransformMakeScale(cameraScale, cameraScale),
                                             detCenter);
                [self->_detachedButton setFeedGlyphScale:(effectiveGlyphScale / cameraScale)];
                if (self->_detachedButton.alpha != shape.contentAlpha) {
                    self->_detachedButton.alpha = shape.contentAlpha;
                }
                if (self->_detachedButton.accessibilityElementsHidden != controlsHidden) {
                    self->_detachedButton.accessibilityElementsHidden = controlsHidden;
                }
            }
            [CATransaction commit];
            return;
        }

        // TikTok interaction mode: 81% group width, 80% height, count * 44pt min capsule width, 91% uniform glyph scale.
        double shownProgress = progress + self->_feedSpring.overtravel;
        CGFloat camDiam = hasDetached ? CGRectGetWidth(self->_feedDetachedAtRest) : 0.0;
        CGFloat camMidY = hasDetached ? CGRectGetMidY(self->_feedDetachedAtRest) : pivot.y;
        DKSiriaiDockGeometry shape = DKTikTokDockShape(CGRectGetMinX(self->_feedCapsuleAtRest),
                                                       CGRectGetMinY(self->_feedCapsuleAtRest),
                                                       width,
                                                       height,
                                                       camMidY,
                                                       camDiam,
                                                       hasDetached ? self->_feedGap : 0.0,
                                                       (unsigned)MAX((NSUInteger)1, tabBar.items.count),
                                                       shownProgress);
        CGFloat sx = MAX(0.001, shape.width / width);
        CGFloat sy = MAX(0.001, shape.height / height);
        CGPoint target = CGPointMake(shape.centerX, shape.centerY);
        CGPoint hostCenter = CGPointMake(target.x + (self->_feedHostCenterAtRest.x - pivot.x) * sx,
                                         target.y + (self->_feedHostCenterAtRest.y - pivot.y) * sy);
        FQXSetViewTransformAndCenter(tabBar,
                                     CGAffineTransformMakeScale(self->_feedBaseScaleX * sx, self->_feedBaseScaleY * sy),
                                     hostCenter);
        self->_dockRenderedPlatterRectInBar = CGRectMake(target.x - shape.width * 0.5,
                                                         target.y - shape.height * 0.5,
                                                         shape.width,
                                                         shape.height);
        if (self->_siriaiMinimumFillView && self->_siriaiMinimumFillView.alpha != 0.0) {
            self->_siriaiMinimumFillView.alpha = 0.0;
        }
        if (tabBar.alpha != 1.0) tabBar.alpha = 1.0;
        self->_feedControlsHidden = NO;
        if (tabBar.accessibilityElementsHidden) tabBar.accessibilityElementsHidden = NO;

        [self applyFeedSlotsAtTarget:target
                              scaleX:sx
                              scaleY:sy
                          glyphScale:shape.glyphScale
                        captionScale:shape.captionScale
                       captionAmount:shape.captionAmount
                       shownProgress:shownProgress
                              siriai:NO
                        contentAlpha:1.0];
        if (hasDetached) {
            CGFloat cameraScale = MAX(0.001, shape.cameraScale);
            CGPoint detCenter = CGPointMake(shape.cameraX, shape.cameraY);
            FQXSetViewTransformAndCenter(self->_detachedButton,
                                         CGAffineTransformMakeScale(cameraScale, cameraScale),
                                         detCenter);
            [self->_detachedButton setFeedGlyphScale:(shape.glyphScale / cameraScale)];
            if (self->_detachedButton.alpha != 1.0) self->_detachedButton.alpha = 1.0;
            if (self->_detachedButton.accessibilityElementsHidden) {
                self->_detachedButton.accessibilityElementsHidden = NO;
            }
        }
        [CATransaction commit];
    }];
}

- (void)startFeedDisplayLink {
    if (self->_feedDisplayLink) {
        if (self->_feedDisplayLink.paused) self->_feedDisplayLink.paused = NO;
        return;
    }
    FQXFeedSpringTarget *target = [FQXFeedSpringTarget new];
    target.owner = self;
    CADisplayLink *link = [CADisplayLink displayLinkWithTarget:target selector:@selector(advance:)];
    if ([link respondsToSelector:@selector(setPreferredFrameRateRange:)]) {
        link.preferredFrameRateRange = CAFrameRateRangeMake(60, 120, 120);
    }
    [link addToRunLoop:NSRunLoop.mainRunLoop forMode:NSRunLoopCommonModes];
    self->_feedDisplayLink = link;
}

- (void)scheduleSiriaiFadeIfNeeded {
    uint64_t ticket = ++self->_feedSpring.siriaiFadeGeneration;
    __weak FQXTabBarInteraction *weakSelf = self;
    dispatch_after(dispatch_time(DISPATCH_TIME_NOW, (int64_t)(DKSiriaiFadeDelay * NSEC_PER_SEC)),
                   dispatch_get_main_queue(), ^{
        FQXTabBarInteraction *strongSelf = weakSelf;
        if (!strongSelf || ![strongSelf usesFeedMotion]) return;
        if (DKFeedSpringTriggerSiriaiFade(&strongSelf->_feedSpring, ticket)) {
            [strongSelf startFeedDisplayLink];
        }
    });
}

- (void)syncSiriaiHideLinePreference {
    if (self->_appliedCollapseMode != FQXDockCollapseModeSiriai) return;
    BOOL hideLine = [NSUserDefaults.standardUserDefaults boolForKey:DockSiriaiHideLinePrefKey];
    int startLink = 0;
    int scheduleFade = 0;
    BOOL linkActive = (self->_feedDisplayLink != nil && !self->_feedDisplayLink.paused);
    DKFeedSpringUpdateHideLine(&self->_feedSpring, hideLine ? 1 : 0, linkActive ? 1 : 0, &startLink, &scheduleFade);
    if (startLink) [self startFeedDisplayLink];
    if (scheduleFade) [self scheduleSiriaiFadeIfNeeded];
}

- (void)finishFeedSpringAndApply {
    [self->_feedDisplayLink invalidate];
    self->_feedDisplayLink = nil;
    double applyProgress = 0.0;
    int scheduleFade = 0;
    DKFeedSpringFinish(&self->_feedSpring, &applyProgress, &scheduleFade);
    [self applyFeedMotion:applyProgress];
    if (scheduleFade) [self scheduleSiriaiFadeIfNeeded];
}

- (void)advanceFeedSpring:(CADisplayLink *)link {
    if (![self usesFeedMotion] || !self->_nativeDockActive || !self->_nativeDockBar.window) {
        [self finishFeedSpringAndApply];
        return;
    }
    double applyProgress = 0.0;
    int shouldApply = 0;
    int scheduleFade = 0;
    DKFeedAdvanceResult res = DKFeedSpringAdvance(&self->_feedSpring,
                                                  link.timestamp,
                                                  link.targetTimestamp,
                                                  UIAccessibilityIsReduceMotionEnabled() ? 1 : 0,
                                                  &applyProgress,
                                                  &shouldApply,
                                                  &scheduleFade);
    if (shouldApply) [self applyFeedMotion:applyProgress];
    if (res == DKFeedAdvancePauseLink) {
        link.paused = YES;
    } else if (res == DKFeedAdvanceFinished) {
        [self->_feedDisplayLink invalidate];
        self->_feedDisplayLink = nil;
        if (scheduleFade) [self scheduleSiriaiFadeIfNeeded];
    }
}

- (void)ensureFeedDisplayLinkPaused {
    if (self->_feedDisplayLink) {
        if (!self->_feedDisplayLink.paused) self->_feedDisplayLink.paused = YES;
        return;
    }
    FQXFeedSpringTarget *target = [FQXFeedSpringTarget new];
    target.owner = self;
    CADisplayLink *link = [CADisplayLink displayLinkWithTarget:target selector:@selector(advance:)];
    if ([link respondsToSelector:@selector(setPreferredFrameRateRange:)]) {
        link.preferredFrameRateRange = CAFrameRateRangeMake(60, 120, 120);
    }
    link.paused = YES;
    [link addToRunLoop:NSRunLoop.mainRunLoop forMode:NSRunLoopCommonModes];
    self->_feedDisplayLink = link;
}

- (BOOL)beginFeedDrag {
    if (![self usesFeedMotion] || !self->_nativeDockActive || !self->_nativeDockBar.window) return NO;
    BOOL runningUnpaused = (self->_feedDisplayLink != nil && !self->_feedDisplayLink.paused);
    int direct = DKFeedSpringBeginDrag(&self->_feedSpring, runningUnpaused ? 1 : 0);
    [self ensureFeedDisplayLinkPaused];
    return direct != 0;
}

- (void)moveFeedDrag:(CGFloat)delta {
    if (![self usesFeedMotion]) return;
    double frame = self->_feedDisplayLink
        ? (self->_feedDisplayLink.targetTimestamp - self->_feedDisplayLink.timestamp) : 0.0;
    BOOL paused = (!self->_feedDisplayLink || self->_feedDisplayLink.paused);
    if (DKFeedSpringMoveDrag(&self->_feedSpring, delta, CACurrentMediaTime(), frame, paused ? 1 : 0)) {
        [self startFeedDisplayLink];
    }
}

- (void)endFeedDrag:(BOOL)compact velocity:(CGFloat)velocity {
    if (![self usesFeedMotion]) return;
    double frame = self->_feedDisplayLink
        ? (self->_feedDisplayLink.targetTimestamp - self->_feedDisplayLink.timestamp) : (1.0 / 60.0);
    BOOL linkActive = (self->_feedDisplayLink != nil && !self->_feedDisplayLink.paused);
    BOOL canAnimate = (self->_nativeDockBar.window != nil && !UIAccessibilityIsReduceMotionEnabled());
    double applyProgress = 0.0;
    int finishedImmediately = 0;
    int startLink = 0;
    int scheduleFade = 0;
    DKFeedSpringEndDrag(&self->_feedSpring, compact ? 1 : 0, velocity, CACurrentMediaTime(),
                        frame, linkActive ? 1 : 0, canAnimate ? 1 : 0,
                        &applyProgress, &finishedImmediately, &startLink, &scheduleFade);
    if (finishedImmediately) {
        [self->_feedDisplayLink invalidate];
        self->_feedDisplayLink = nil;
        [self applyFeedMotion:applyProgress];
        if (scheduleFade) [self scheduleSiriaiFadeIfNeeded];
    } else if (startLink) {
        [self startFeedDisplayLink];
    }
}

- (void)setFeedCompact:(BOOL)compact animated:(BOOL)animated {
    if (![self usesFeedMotion] || !self->_nativeDockBar) return;
    BOOL linkActive = (self->_feedDisplayLink != nil && !self->_feedDisplayLink.paused);
    BOOL canAnimate = (self->_nativeDockBar.window != nil && !UIAccessibilityIsReduceMotionEnabled());
    double applyProgress = 0.0;
    int finishedImmediately = 0;
    int startLink = 0;
    int scheduleFade = 0;
    DKFeedSpringSetCompact(&self->_feedSpring, compact ? 1 : 0, animated ? 1 : 0, CACurrentMediaTime(),
                           linkActive ? 1 : 0, canAnimate ? 1 : 0,
                           &applyProgress, &finishedImmediately, &startLink, &scheduleFade);
    if (finishedImmediately) {
        [self->_feedDisplayLink invalidate];
        self->_feedDisplayLink = nil;
        [self applyFeedMotion:applyProgress];
        if (scheduleFade) [self scheduleSiriaiFadeIfNeeded];
    } else if (startLink) {
        [self startFeedDisplayLink];
    }
}

- (void)settleFeedMotionImmediate {
    if (![self usesFeedMotion]) return;
    if (self->_feedSpring.following) {
        self->_feedSpring.following = 0;
    }
    if (self->_feedDisplayLink || self->_feedSpring.overtravel != 0.0) {
        [self finishFeedSpringAndApply];
    }
}

- (void)refreshForCollapseModeChange {
    FQXDockCollapseMode desired = FQXFeedMotionSupported() ? FQXCurrentDockCollapseMode() : FQXDockCollapseModeOff;
    if (desired != self->_appliedCollapseMode) {
        [self cleanupFeedMotionVisuals];
        DKFeedSpringInit(&self->_feedSpring);
        self->_feedSpring.siriai = (desired == FQXDockCollapseModeSiriai) ? 1 : 0;
        self->_feedSpring.siriaiHidesLine = (desired == FQXDockCollapseModeSiriai &&
                                             [NSUserDefaults.standardUserDefaults boolForKey:DockSiriaiHideLinePrefKey]) ? 1 : 0;
        self->_appliedCollapseMode = desired;
        self->_dockSignature = nil;
        if (self->_nativeDockBar && self->_buttons.count) {
            [self syncDockItems];
            if (self->_bar && self->_proxy) {
                [self layoutNativeDockInBar:self->_bar proxy:self->_proxy forceMeasure:YES];
            }
        }
    } else if (desired == FQXDockCollapseModeSiriai) {
        [self syncSiriaiHideLinePreference];
        BOOL linkRunning = (self->_feedDisplayLink != nil && !self->_feedDisplayLink.paused);
        if (!linkRunning && !self->_feedSpring.following) {
            [self applyFeedMotion:self->_feedSpring.progress];
        }
    }
}

- (BOOL)usesNativeSegmentedSelector {
    return [self->_nativeControl isKindOfClass:UISegmentedControl.class] &&
           self->_nativeControl.superview != nil &&
           !self->_nativeControl.hidden;
}

- (BOOL)isDarkDock {
    UIUserInterfaceStyle dockStyle = self->_proxy ? self->_proxy.overrideUserInterfaceStyle : UIUserInterfaceStyleUnspecified;
    if (dockStyle == UIUserInterfaceStyleDark) return YES;
    if (dockStyle == UIUserInterfaceStyleLight) return NO;
    return self->_proxy.traitCollection.userInterfaceStyle == UIUserInterfaceStyleDark;
}

- (UIUserInterfaceStyle)desiredDockGlassStyle {
    if (FQXDockMaterialUsesVideoLightBase((int)FQXCurrentDockMaterialMode())) {
        return UIUserInterfaceStyleLight;
    }
    // Match the page's optical backdrop polarity (Dark on full-screen video/night, Light on
    // bright pages). On iOS 26/27, forcing Light override on a dark video page makes
    // UIGlassEffectStyleClear render Light-mode's milky-white luminosity veil, whereas Dark
    // override with tintColor == nil renders pure colorless refractive glass with zero tint.
    return [self isDarkDock] ? UIUserInterfaceStyleDark : UIUserInterfaceStyleLight;
}

- (NSUInteger)currentSelectedIndex {
    if ([self usesNativeSegmentedSelector]) {
        NSInteger idx = ((UISegmentedControl *)self->_nativeControl).selectedSegmentIndex;
        if (idx >= 0 && (NSUInteger)idx < self->_buttons.count) return (NSUInteger)idx;
    }
    if (self->_bar) {
        SEL selItemSel = @selector(selectedItem);
        SEL itemsSel = @selector(items);
        if ([self->_bar respondsToSelector:selItemSel] && [self->_bar respondsToSelector:itemsSel]) {
            id selItem = ((id (*)(id, SEL))objc_msgSend)(self->_bar, selItemSel);
            NSArray *barItems = ((id (*)(id, SEL))objc_msgSend)(self->_bar, itemsSel);
            if (selItem && [barItems isKindOfClass:NSArray.class]) {
                NSUInteger idx = [barItems indexOfObjectIdenticalTo:selItem];
                if (idx != NSNotFound && idx < self->_buttons.count) return idx;
            }
        }
        id barDelegate = FQXObjGet(self->_bar, "delegate");
        if (barDelegate) {
            NSInteger delIdx = FQXIntGet(barDelegate, "selectedIndex", -1);
            if (delIdx >= 0 && (NSUInteger)delIdx < self->_buttons.count) return (NSUInteger)delIdx;
        }
    }
    for (NSUInteger i = 0; i < self->_buttons.count; ++i) {
        UIButton *btn = self->_buttons[i];
        if ([btn isKindOfClass:UIButton.class] && btn.isSelected) return i;
    }
    if (self->_restingLens && self->_restingLens.superview && self->_buttons.count) {
        CGFloat midX = CGRectGetMidX(self->_restingLens.frame);
        NSUInteger bestIdx = 0;
        CGFloat bestDist = CGFLOAT_MAX;
        for (NSUInteger i = 0; i < self->_buttons.count; ++i) {
            UIButton *btn = self->_buttons[i];
            if (![btn isKindOfClass:UIButton.class] || !btn.superview) continue;
            CGRect bf = [btn.superview convertRect:btn.frame toView:self->_restingLens.superview];
            CGFloat dist = fabs(CGRectGetMidX(bf) - midX);
            if (dist < bestDist) {
                bestDist = dist;
                bestIdx = i;
            }
        }
        return bestIdx;
    }
    return 0;
}

- (void)ensureDockZOrderInBar:(UIView *)bar {
    if (!bar) return;
    UITabBar *tabBar = self->_nativeDockBar;
    FQXDetachedDockButtonView *det = self->_detachedButton;
    BOOL showDetached = (self->_detachedHostIndex != NSNotFound && det != nil && !det.hidden);

    if (tabBar && tabBar.superview == bar) {
        UIView *anchor = nil;
        NSUInteger proxyIdx = (self->_proxy && self->_proxy.superview == bar)
            ? [bar.subviews indexOfObjectIdenticalTo:self->_proxy] : NSNotFound;
        NSUInteger overlayIdx = (self->_overlay && self->_overlay.superview == bar)
            ? [bar.subviews indexOfObjectIdenticalTo:self->_overlay] : NSNotFound;
        if (proxyIdx != NSNotFound && overlayIdx != NSNotFound) {
            anchor = (overlayIdx > proxyIdx) ? self->_overlay : self->_proxy;
        } else if (overlayIdx != NSNotFound) {
            anchor = self->_overlay;
        } else if (proxyIdx != NSNotFound) {
            anchor = self->_proxy;
        }
        if (anchor) {
            NSUInteger tabIdx = [bar.subviews indexOfObjectIdenticalTo:tabBar];
            NSUInteger anchorIdx = [bar.subviews indexOfObjectIdenticalTo:anchor];
            if (tabIdx != NSNotFound && anchorIdx != NSNotFound && tabIdx < anchorIdx) {
                [bar insertSubview:tabBar aboveSubview:anchor];
            }
        }
        UIStackView *titles = self->_dockTitleOverlay;
        CGRect platter = self->_dockRenderedPlatterRectInBar;
        if (titles && self->_nativeDockActive && !CGRectIsEmpty(platter)) {
            BOOL feedTextOnly = ([self usesFeedMotion] && !self->_dockIconOverlay && [self dockDisplayMode] == 2);
            if (feedTextOnly) {
                CGFloat fontSize = 15.5 * self->_feedBaseScaleY;
                if (titles.semanticContentAttribute != tabBar.semanticContentAttribute)
                    titles.semanticContentAttribute = tabBar.semanticContentAttribute;
                for (UILabel *label in titles.arrangedSubviews) {
                    if (fabs(label.font.pointSize - fontSize) > 0.05)
                        label.font = [UIFont systemFontOfSize:fontSize weight:label.highlighted ? UIFontWeightSemibold : UIFontWeightMedium];
                }
            } else {
                CGFloat scale = tabBar.transform.d;
                BOOL captions = self->_dockIconOverlay != nil;
                BOOL compact = [objc_getAssociatedObject(self->_proxy, &FQXDockCompactKey) boolValue];
                CGFloat fontSize = (captions ? 10.5 : 15.5) * scale;
                CGRect track = CGRectInset(platter, 4.0 * scale, 0.0);
                CGRect frame = captions ? CGRectOffset(track, 0, (compact ? 6.0 : 11.5) * scale) : track;
                CGFloat titleAlpha = captions && compact ? 0.0 : 1.0;
                if (!CGAffineTransformIsIdentity(titles.transform)) titles.transform = CGAffineTransformIdentity;
                if (titles.alpha != titleAlpha) titles.alpha = titleAlpha;
                if (!CGRectEqualToRect(titles.frame, frame)) titles.frame = frame;
                if (titles.semanticContentAttribute != tabBar.semanticContentAttribute)
                    titles.semanticContentAttribute = tabBar.semanticContentAttribute;
                for (UILabel *label in titles.arrangedSubviews) {
                    if (fabs(label.font.pointSize - fontSize) > 0.05)
                        label.font = [UIFont systemFontOfSize:fontSize weight:label.highlighted ? UIFontWeightSemibold : UIFontWeightMedium];
                }
            }
            NSArray<UIView *> *siblings = bar.subviews;
            NSUInteger index = [siblings indexOfObjectIdenticalTo:titles];
            if (index == NSNotFound || index < [siblings indexOfObjectIdenticalTo:tabBar])
                [bar insertSubview:titles aboveSubview:tabBar];
            UIStackView *icons = self->_dockIconOverlay;
            if (icons) {
                CGFloat scale = tabBar.transform.d;
                BOOL compact = [objc_getAssociatedObject(self->_proxy, &FQXDockCompactKey) boolValue];
                CGRect track = CGRectInset(platter, 4.0 * scale, 0.0);
                CGFloat iconH = (compact ? 23.6 : 22.0) * scale;
                CGRect iconFrame = CGRectMake(track.origin.x,
                    CGRectGetMidY(track) - iconH * 0.5 - (compact ? 0.0 : 7.0) * scale,
                    track.size.width, iconH);
                if (!CGRectEqualToRect(icons.frame, iconFrame)) icons.frame = iconFrame;
                icons.semanticContentAttribute = titles.semanticContentAttribute;
                if (icons.superview != bar ||
                    [bar.subviews indexOfObjectIdenticalTo:icons] < [bar.subviews indexOfObjectIdenticalTo:tabBar])
                    [bar insertSubview:icons aboveSubview:tabBar];
            }
        }
        UIView *feedOverlay = self->_feedContentOverlay;
        if (feedOverlay && [self usesFeedMotion]) {
            if (feedOverlay.superview != bar ||
                [bar.subviews indexOfObjectIdenticalTo:feedOverlay] < [bar.subviews indexOfObjectIdenticalTo:tabBar]) {
                [bar insertSubview:feedOverlay aboveSubview:tabBar];
            }
        }
        UIView *siriaiFill = self->_siriaiMinimumFillView;
        if (siriaiFill && siriaiFill.superview == bar) {
            UIView *above = (feedOverlay && feedOverlay.superview == bar) ? feedOverlay : tabBar;
            if ([bar.subviews indexOfObjectIdenticalTo:siriaiFill] < [bar.subviews indexOfObjectIdenticalTo:above]) {
                [bar insertSubview:siriaiFill aboveSubview:above];
            }
        }
    }

    if (showDetached) {
        if (det.superview != bar) {
            if (tabBar && tabBar.superview == bar) {
                [bar insertSubview:det aboveSubview:tabBar];
            } else {
                [bar addSubview:det];
            }
        } else if (bar.subviews.lastObject != det) {
            [bar bringSubviewToFront:det];
        }
    }

    // AlignedGlass's InstallTabRecovery attaches a 0.75s UILongPressGestureRecognizer onto
    // SSTabBar.superview when BottomMine is off. Setting cancelsTouchesInView = NO keeps
    // long-press recovery working while preventing it from ever cancelling quick Dock taps.
    UIView *barParent = bar.superview;
    if (barParent) {
        static Class recoveryDelCls = Nil;
        static dispatch_once_t rOnce;
        dispatch_once(&rOnce, ^{ recoveryDelCls = objc_lookUpClass("FanqieXBottomToggles176"); });
        if (recoveryDelCls) {
            for (UIGestureRecognizer *gr in barParent.gestureRecognizers) {
                if ([gr isKindOfClass:UILongPressGestureRecognizer.class] &&
                    [gr.delegate isKindOfClass:recoveryDelCls] &&
                    gr.cancelsTouchesInView) {
                    gr.cancelsTouchesInView = NO;
                }
            }
        }
    }
}

- (void)triggerHostNavigationForHostIndex:(NSUInteger)hostIdx
                           fallbackButton:(UIButton *)fallbackBtn
                                   source:(NSString *)source {
    if (self->_routingHostDockNavigation || !self->_bar.window) return;
    self->_routingHostDockNavigation = YES;
    FQXMarkDockTouchActivity(0.30);
    NSUInteger beforeSel = [self currentSelectedIndex];
    UIButton *hostBtn = (hostIdx < self->_buttons.count && [self->_buttons[hostIdx] isKindOfClass:UIButton.class])
        ? self->_buttons[hostIdx]
        : ([fallbackBtn isKindOfClass:UIButton.class] ? fallbackBtn : nil);
    NSString *methodUsed = @"none";
    BOOL triggered = NO;
    UIView *bar = self->_bar;
    NSArray *barItems = FQXObjGet(bar, "items");
    BOOL hasItem = [barItems isKindOfClass:NSArray.class] && hostIdx < barItems.count;
    SEL select = sel_registerName("setSelectIndex:");
    Method selectMethod = class_getInstanceMethod(object_getClass(bar), select);
    if (hasItem && selectMethod && strcmp(method_getTypeEncoding(selectMethod), "v24@0:8q16") == 0) {
        // The host's own button tap uses this entry point, including native interception.
        ((void (*)(id, SEL, NSInteger))objc_msgSend)(bar, select, (NSInteger)hostIdx);
        methodUsed = @"host_bar_select_index";
        triggered = YES;
    } else if (hostBtn && (hostBtn.allControlEvents & UIControlEventTouchUpInside)) {
        [hostBtn sendActionsForControlEvents:UIControlEventTouchUpInside];
        methodUsed = @"host_button_touch_up_inside";
        triggered = YES;
    }

    if (!triggered && hasItem) {
        id barDelegate = FQXObjGet(bar, "delegate");
        SEL indexedSelect = sel_registerName("tabBar:didSelectItem:selectIndex:");
        Method indexedMethod = class_getInstanceMethod(object_getClass(barDelegate), indexedSelect);
        if (indexedMethod && strcmp(method_getTypeEncoding(indexedMethod), "v40@0:8@16@24q32") == 0) {
            ((void (*)(id, SEL, id, id, NSInteger))objc_msgSend)(barDelegate, indexedSelect, bar,
                                                               barItems[hostIdx], (NSInteger)hostIdx);
            methodUsed = @"bar_delegate_did_select_index";
            triggered = YES;
        }
        SEL didSel = @selector(tabBar:didSelectItem:);
        if (!triggered && [barDelegate respondsToSelector:didSel]) {
            Method m = class_getInstanceMethod(object_getClass(barDelegate), didSel);
            if (m && strcmp(method_getTypeEncoding(m), "v32@0:8@16@24") == 0) {
                id item = barItems[hostIdx];
                if ([bar respondsToSelector:@selector(setSelectedItem:)]) {
                    Method sm = class_getInstanceMethod(object_getClass(bar), @selector(setSelectedItem:));
                    if (sm && strcmp(method_getTypeEncoding(sm), "v24@0:8@16") == 0) {
                        ((void (*)(id, SEL, id))objc_msgSend)(bar, @selector(setSelectedItem:), item);
                    }
                }
                ((void (*)(id, SEL, id, id))objc_msgSend)(barDelegate, didSel, bar, item);
                methodUsed = @"bar_delegate_did_select_item";
                triggered = YES;
            }
        }
    }

    if (!triggered && bar) {
        id owner = FQXObjGet(bar, "delegate");
        UITabBarController *tbc = [owner isKindOfClass:UITabBarController.class] ? (UITabBarController *)owner : nil;
        if (!tbc) {
            UIResponder *resp = bar.nextResponder;
            NSInteger hops = 0;
            while (resp && hops < 12) {
                if ([resp isKindOfClass:UITabBarController.class]) {
                    tbc = (UITabBarController *)resp;
                    break;
                }
                resp = resp.nextResponder;
                hops++;
            }
        }
        if (tbc && hostIdx < tbc.viewControllers.count) {
            tbc.selectedIndex = hostIdx;
            methodUsed = @"tabbar_controller_selected_index";
            triggered = YES;
        }
    }

    NSUInteger finalSel = [self currentSelectedIndex];
    self->_routingHostDockNavigation = NO;
    if (hostIdx != beforeSel && [self usesFeedMotion]) {
        self->_feedLastSelectedIndex = finalSel;
        [[FQXFeedDockPanController shared] resetFeedGesture];
        [self setFeedCompact:NO animated:NO];
    }

    BOOL isDetachedSource = [source hasPrefix:@"detached"];
    if (isDetachedSource) {
        FQXDiagRecordEvent(FQXDiagCategoryUI, @"dock_detached_navigation", @{
            @"source": source ?: @"detached_tap",
            @"targetHostIndex": @(hostIdx),
            @"moduleTitle": self->_detachedButton.moduleTitle ?: @"",
            @"beforeIndex": @(beforeSel),
            @"afterIndex": @(finalSel),
            @"hadHostButton": @(hostBtn != nil),
            @"methodUsed": methodUsed,
            @"triggered": @(triggered),
        }, NO);
    } else if ([source isEqualToString:@"dock_tap_rescue"] ||
               (![methodUsed isEqualToString:@"host_bar_select_index"] &&
                ![methodUsed isEqualToString:@"host_button_touch_up_inside"]) ||
               finalSel != hostIdx) {
        FQXDiagRecordEvent(FQXDiagCategoryUI, @"dock_tab_navigation", @{
            @"source": source ?: @"native_tabbar",
            @"targetHostIndex": @(hostIdx),
            @"beforeIndex": @(beforeSel),
            @"afterIndex": @(finalSel),
            @"hadHostButton": @(hostBtn != nil),
            @"methodUsed": methodUsed,
            @"triggered": @(triggered),
        }, NO);
    }

    __weak FQXTabBarInteraction *weakSelf = self;
    dispatch_async(dispatch_get_main_queue(), ^{
        FQXTabBarInteraction *laterSelf = weakSelf;
        if (laterSelf && laterSelf->_nativeDockActive) {
            [laterSelf syncSelectionExclusivityAnimated:YES];
            [laterSelf ensureDockZOrderInBar:laterSelf->_bar];
            FQXScheduleCYLGlassResample(laterSelf->_bar, laterSelf->_proxy);
        }
    });
}

- (NSInteger)dockDisplayMode {
    NSUserDefaults *ud = NSUserDefaults.standardUserDefaults;
    id stored = [ud objectForKey:BottomDisplayModePrefKey];
    if (stored && [stored respondsToSelector:@selector(integerValue)]) {
        NSInteger v = [stored integerValue];
        if (v >= 0 && v <= 2) return v;
    }
    return [ud boolForKey:@"FanqieX.BottomIconsOnly.1"] ? 1 : 0;
}

- (CGFloat)dockIconPointSize {
    id stored = [NSUserDefaults.standardUserDefaults objectForKey:@"FanqieX.BottomIconPointSize.1"];
    if ([stored respondsToSelector:@selector(doubleValue)]) {
        CGFloat v = (CGFloat)[stored doubleValue];
        if (v >= 16.0 && v <= 34.0) return v;
    }
    return 27.0;
}

- (void)applyDockItemImagesToItems:(NSArray<UITabBarItem *> *)items {
    if (items.count == 0) return;
    BOOL isDark = [self isDarkDock];
    FQXDockMaterialMode mode = FQXCurrentDockMaterialMode();
    BOOL lightBase = (FQXDockMaterialUsesVideoLightBase((int)mode) != 0);
    NSInteger effSel = FQXEffectiveDockSelectionTintStyle();
    BOOL roseSel = (effSel != FQXSelectionTintStyleDefault);
    self->_dockAppliedInkState = (isDark ? 1 : 0) | ((NSInteger)mode << 1) | (effSel << 5);
    CGFloat white = isDark ? 1.0 : 0.0;
    UIColor *selectedInk = (lightBase || roseSel)
        ? FQXVideoInkUIColor(1.0)
        : [UIColor colorWithWhite:white alpha:1.0];
    UIColor *normalInk = lightBase
        ? FQXVideoInkUIColor(0.80)
        : [UIColor colorWithWhite:white alpha:(isDark ? 0.68 : 0.86)];
    NSInteger displayMode = [self dockDisplayMode];
    BOOL textOnly = displayMode == 2;
    for (UILabel *label in self->_dockTitleOverlay.arrangedSubviews) {
        label.textColor = normalInk;
        label.highlightedTextColor = selectedInk;
    }
    CGFloat ptSize = [self dockIconPointSize];
    NSArray<NSString *> *titles = self->_dockTitles;
    NSArray<UIButton *> *buttons = self->_buttons;
    NSArray<NSNumber *> *hostIndices = self->_capsuleHostIndices;
    for (NSUInteger i = 0; i < items.count; ++i) {
        UITabBarItem *item = items[i];
        NSString *title = (i < titles.count) ? titles[i] : (item.accessibilityLabel ?: @"");
        NSUInteger hostIdx = (i < hostIndices.count) ? hostIndices[i].unsignedIntegerValue : i;
        UIButton *btn = (hostIdx < buttons.count && [buttons[hostIdx] isKindOfClass:UIButton.class]) ? buttons[hostIdx] : nil;
        // Preserve UIKit's item footprint for hit testing and selection, with the
        // actual text above the lens so its moving highlight cannot obscure it.
        if (self->_dockIconOverlay) {
            UIImageView *glyph = (UIImageView *)self->_dockIconOverlay.arrangedSubviews[i];
            UIImage *normal = FQXDockGlyph(title, btn, 19.0, NO, normalInk);
            glyph.image = normal ?: FQXDockTitleImage(title, normalInk, NO);
            glyph.highlightedImage = FQXDockGlyph(title, btn, 19.0, YES, selectedInk)
                                    ?: FQXDockTitleImage(title, selectedInk, YES);
            UILabel *caption = (UILabel *)self->_dockTitleOverlay.arrangedSubviews[i];
            caption.text = normal ? title : @"";
        }
        if ([self usesFeedMotion]) {
            UIImage *placeholder = FQXDockItemImage(title, btn, displayMode, ptSize, YES, UIColor.clearColor)
                                   ?: FQXDockTitleImage(title, UIColor.clearColor, YES);
            item.image = placeholder;
            item.selectedImage = placeholder;
        } else if (textOnly || self->_dockIconOverlay) {
            if (!item.image) {
                UIImage *placeholder = FQXDockTitleImage(title, UIColor.clearColor, YES);
                item.image = placeholder;
                item.selectedImage = placeholder;
            }
        } else {
            item.image = FQXDockItemImage(title, btn, displayMode, ptSize, NO, normalInk);
            item.selectedImage = FQXDockItemImage(title, btn, displayMode, ptSize, YES, selectedInk);
        }
    }
    if ([self usesFeedMotion]) {
        [self syncFeedDockSlotVisuals];
    }
    if (self->_detachedHostIndex != NSNotFound &&
        (NSUInteger)self->_detachedHostIndex < buttons.count &&
        self->_detachedButton) {
        NSUInteger detIdx = (NSUInteger)self->_detachedHostIndex;
        UIButton *detBtn = [buttons[detIdx] isKindOfClass:UIButton.class] ? buttons[detIdx] : nil;
        NSString *detTitle = self->_detachedButton.moduleTitle ?: FQXDockButtonTitle(detBtn, self->_bar, detIdx);
        // Right circular button uses module icon (with automatic fallback if custom title-only module).
        UIImage *normImg = FQXDockItemImage(detTitle, detBtn, 1, ptSize, NO, normalInk);
        UIImage *selImg = FQXDockItemImage(detTitle, detBtn, 1, ptSize, YES, selectedInk);
        [self->_detachedButton updateImagesNormal:normImg selected:selImg];
        [self->_detachedButton syncUnreadBadgeFromHostButton:detBtn];
    }
}

- (void)syncDetachedDockMaterial:(BOOL)glassDark {
    if (!self->_detachedButton || self->_detachedHostIndex == NSNotFound) return;
    FQXDockMaterialMode mode = FQXCurrentDockMaterialMode();
    BOOL reduce = UIAccessibilityIsReduceTransparencyEnabled();
    BOOL isVideoBase = (mode == FQXDockMaterialVideoBase);
    BOOL isRoseMistGlass = (mode == FQXDockMaterialRoseMistGlass);
    BOOL lightBase = isVideoBase || isRoseMistGlass;
    NSInteger surfaceStyle = isVideoBase ? 1 : (isRoseMistGlass ? 2 : 0);
    NSInteger effSel = FQXEffectiveDockSelectionTintStyle();
    BOOL wantsClear = (mode == FQXDockMaterialIOS18Gaussian || isVideoBase) && !reduce;
    UIVisualEffect *effect = wantsClear ? nil : FQXMakeDockEffectForMode(mode, glassDark, YES, reduce);
    NSInteger stamp = (reduce ? 8000 : 0) + (effSel * 2000) + (FQXGlassDarkTintEnabled() ? 1000 : 0) + (glassDark ? 100 : 0) + (NSInteger)mode + 1;
    UIColor *selColor = FQXDockSelectionColorForMode(mode, [self isDarkDock]);
    [self->_detachedButton applySurfaceStyle:surfaceStyle selectionTintStyle:effSel];
    [self->_detachedButton applyGlassEffect:effect
                           interfaceStyle:lightBase ? UIUserInterfaceStyleLight : self->_dockAppliedStyle
                           selectionColor:selColor
                       reduceTransparency:(reduce && !isVideoBase && !isRoseMistGlass)
                               styleStamp:stamp];
    FQXApplyDockBackdropBlur(self->_detachedButton.glassView,
                             self->_detachedButton.glassView.contentView,
                             self->_detachedButton.selectionLens,
                             self->_detachedButton.glassView.contentView.bounds,
                             -1,
                             glassDark,
                             mode,
                             DockBlurPrefKey);
}

- (void)syncSelectionExclusivityAnimated:(BOOL)animated {
    UITabBar *tabBar = self->_nativeDockBar;
    if (!tabBar || !tabBar.items.count) return;
    NSUInteger hostSel = [self currentSelectedIndex];
    NSUInteger capPos = self->_capsuleHostIndices.count
        ? [self->_capsuleHostIndices indexOfObject:@(hostSel)]
        : hostSel;
    if (self->_feedDockSlots.count) {
        CGFloat baseScale = MAX(0.70, MIN(1.30, self->_feedBaseScaleY > 0.05 ? self->_feedBaseScaleY : 1.0));
        for (FQXFeedDockSlotView *slot in self->_feedDockSlots) {
            BOOL selected = (slot.slotIndex == capPos);
            if (slot.hasIcon && slot.iconView.highlighted != selected) {
                slot.iconView.highlighted = selected;
            }
            if (slot.hasCaption && slot.captionLabel.highlighted != selected) {
                slot.captionLabel.highlighted = selected;
                CGFloat fontPt = (slot.isPrimaryTitle ? 15.5 : 10.5) * baseScale;
                slot.captionLabel.font = [UIFont systemFontOfSize:fontPt
                                                           weight:(selected ? UIFontWeightSemibold : UIFontWeightMedium)];
            }
        }
    }
    NSUInteger slot = 0;
    for (UILabel *label in self->_dockTitleOverlay.arrangedSubviews) {
        BOOL selected = slot == capPos;
        if (self->_dockIconOverlay) {
            UIImageView *glyph = (UIImageView *)self->_dockIconOverlay.arrangedSubviews[slot];
            glyph.highlighted = selected;
        }
        ++slot;
        if (label.highlighted != selected) {
            label.highlighted = selected;
            label.font = [UIFont systemFontOfSize:label.font.pointSize weight:selected ? UIFontWeightSemibold : UIFontWeightMedium];
        }
    }
    if (self->_detachedHostIndex != NSNotFound &&
        self->_detachedButton &&
        hostSel == (NSUInteger)self->_detachedHostIndex) {
        FQXSetNativeTabSelectionLensVisible(tabBar, NO, 0);
        if (tabBar.selectedItem != nil) {
            tabBar.selectedItem = nil;
        }
        [self->_detachedButton setModuleSelected:YES animated:animated];
        return;
    }

    if (self->_detachedButton) {
        [self->_detachedButton setModuleSelected:NO animated:animated];
    }
    if (capPos != NSNotFound && capPos < tabBar.items.count) {
        UITabBarItem *desiredItem = tabBar.items[capPos];
        if (tabBar.selectedItem != desiredItem) {
            tabBar.selectedItem = desiredItem;
        }
    }
    FQXSetNativeTabSelectionLensVisible(tabBar, YES, 0);
    FQXSyncNativeTabSelectionVideoPill(tabBar, FQXEffectiveDockSelectionTintStyle(), 0);
}

- (BOOL)syncDockItems {
    UITabBar *tabBar = self->_nativeDockBar;
    if (!tabBar || !self->_buttons.count) return NO;
    NSInteger displayMode = [self dockDisplayMode];
    CGFloat ptSize = [self dockIconPointSize];
    NSMutableArray<NSString *> *allTitles = [NSMutableArray arrayWithCapacity:self->_buttons.count];
    for (NSUInteger i = 0; i < self->_buttons.count; ++i) {
        UIButton *btn = self->_buttons[i];
        NSString *title = [btn isKindOfClass:UIButton.class] ? FQXDockButtonTitle(btn, self->_bar, i) : @"";
        [allTitles addObject:title];
    }
    FQXDockDetachedUpdateHostModules(allTitles);
    NSString *detachedReason = nil;
    NSInteger detIdx = FQXDockDetachedResolveIndexWithReason(allTitles, &detachedReason);
    self->_detachedHostIndex = detIdx;

    NSUInteger selected = [self currentSelectedIndex];
    NSString *current = selected < allTitles.count ? allTitles[selected] : nil;
    BOOL usesFeed = [self usesFeedMotion];
    BOOL captions = !usesFeed && displayMode == 0 && ([current isEqualToString:@"短剧"] || [current isEqualToString:@"视频"]) &&
        [NSUserDefaults.standardUserDefaults boolForKey:DockLegacyScrollZoomPrefKey];
    NSMutableString *sig = [NSMutableString stringWithFormat:@"dm=%ld|pt=%.1f|det=%ld|captions=%d|feed=%d|",
                            (long)displayMode, ptSize, (long)(detIdx == NSNotFound ? -1 : detIdx), captions, usesFeed];
    NSMutableArray<NSString *> *capsuleTitles = [NSMutableArray arrayWithCapacity:allTitles.count];
    NSMutableArray<NSNumber *> *capsuleIndices = [NSMutableArray arrayWithCapacity:allTitles.count];
    for (NSUInteger i = 0; i < allTitles.count; ++i) {
        [sig appendFormat:@"%@|", allTitles[i]];
        if (detIdx != NSNotFound && i == (NSUInteger)detIdx) continue;
        [capsuleTitles addObject:allTitles[i]];
        [capsuleIndices addObject:@(i)];
    }

    BOOL rebuilt = ![sig isEqualToString:self->_dockSignature];
    if (rebuilt) {
        NSMutableArray<UITabBarItem *> *items = [NSMutableArray arrayWithCapacity:capsuleTitles.count];
        for (NSUInteger i = 0; i < capsuleTitles.count; ++i) {
            UITabBarItem *item = [[UITabBarItem alloc] initWithTitle:nil image:nil tag:(NSInteger)i];
            item.accessibilityLabel = capsuleTitles[i];
            [items addObject:item];
        }
        self->_capsuleHostIndices = [capsuleIndices copy];
        self->_dockTitles = [capsuleTitles copy];
        self->_dockSignature = [sig copy];
        [self->_dockTitleOverlay removeFromSuperview];
        self->_dockTitleOverlay = nil;
        [self->_dockIconOverlay removeFromSuperview];
        self->_dockIconOverlay = nil;
        if (!usesFeed && (displayMode == 2 || captions)) {
            UIStackView *titles = [[UIStackView alloc] initWithFrame:CGRectZero];
            titles.hidden = !self->_nativeDockActive;
            titles.userInteractionEnabled = NO;
            titles.accessibilityElementsHidden = YES;
            titles.axis = UILayoutConstraintAxisHorizontal;
            titles.distribution = UIStackViewDistributionFillEqually;
            titles.alignment = UIStackViewAlignmentCenter;
            if (captions) {
                UIStackView *icons = [[UIStackView alloc] initWithFrame:CGRectZero];
                icons.hidden = titles.hidden;
                icons.userInteractionEnabled = NO;
                icons.accessibilityElementsHidden = YES;
                icons.distribution = UIStackViewDistributionFillEqually;
                self->_dockIconOverlay = icons;
            }
            for (NSString *title in capsuleTitles) {
                if (captions) {
                    UIImageView *glyph = [UIImageView new];
                    glyph.contentMode = UIViewContentModeScaleAspectFit;
                    [self->_dockIconOverlay addArrangedSubview:glyph];
                }
                UILabel *label = [UILabel new];
                label.text = title;
                label.textAlignment = NSTextAlignmentCenter;
                label.font = [UIFont systemFontOfSize:15.5 weight:UIFontWeightMedium];
                label.adjustsFontSizeToFitWidth = YES;
                label.minimumScaleFactor = 0.7;
                [titles addArrangedSubview:label];
            }
            self->_dockTitleOverlay = titles;
        }

        if (detIdx != NSNotFound && (NSUInteger)detIdx < self->_buttons.count) {
            if (!self->_detachedButton) {
                FQXDetachedDockButtonView *circle = [[FQXDetachedDockButtonView alloc] initWithFrame:CGRectMake(0.0, 0.0, 56.0, 56.0)];
                circle.hidden = YES;
                objc_setAssociatedObject(circle, FQXOwnedGlassElementKey, @YES, OBJC_ASSOCIATION_RETAIN_NONATOMIC);
                objc_setAssociatedObject(circle.glassView, FQXOwnedGlassElementKey, @YES, OBJC_ASSOCIATION_RETAIN_NONATOMIC);
                __weak FQXTabBarInteraction *weakSelf = self;
                circle.onTouchDiagnostic = ^(NSString *stage, NSDictionary<NSString *, id> *info) {
                    FQXMarkDockTouchActivity(0.35);
                    FQXTabBarInteraction *strongSelf = weakSelf;
                    NSMutableDictionary<NSString *, id> *payload = [NSMutableDictionary dictionaryWithDictionary:(info ?: @{})];
                    payload[@"stage"] = stage ?: @"";
                    payload[@"hostIndex"] = @(strongSelf ? strongSelf->_detachedHostIndex : NSNotFound);
                    FQXDiagRecordEvent(FQXDiagCategoryUI, @"dock_detached_touch", payload, NO);
                };
                circle.onTapModule = ^(UIButton *hostButton) {
                    FQXTabBarInteraction *strongSelf = weakSelf;
                    if (!strongSelf) return;
                    NSInteger targetIdx = strongSelf->_detachedHostIndex;
                    if (targetIdx == NSNotFound) return;
                    [strongSelf triggerHostNavigationForHostIndex:(NSUInteger)targetIdx
                                                   fallbackButton:hostButton
                                                           source:@"detached_circle_tap"];
                };
                self->_detachedButton = circle;
            }
            self->_detachedButton.moduleTitle = allTitles[(NSUInteger)detIdx];
            self->_detachedButton.targetHostButton = self->_buttons[(NSUInteger)detIdx];
        } else if (self->_detachedButton) {
            self->_detachedButton.hidden = YES;
            [self->_detachedButton removeFromSuperview];
            self->_detachedButton = nil;
        }
        // Give UIKit complete items before it creates the selected and normal
        // image views. A settings transition can otherwise capture empty items.
        [self applyDockItemImagesToItems:items];
        [UIView performWithoutAnimation:^{
            UITabBarItemPositioning positioning = displayMode == 2 ? UITabBarItemPositioningFill : UITabBarItemPositioningAutomatic;
            if (tabBar.itemPositioning != positioning) tabBar.itemPositioning = positioning;
            [tabBar setItems:items animated:NO];
            [self syncSelectionExclusivityAnimated:NO];
        }];
        FQXDiagRecordEvent(FQXDiagCategoryUI, @"dock_detached_state", @{
            @"prefEnabled": @(FQXDockDetachedIsEnabled()),
            @"detachedEnabled": @(detIdx != NSNotFound),
            @"detachedActive": @(detIdx != NSNotFound),
            @"storedModule": FQXDockDetachedStoredModule(),
            @"detachedModule": (detIdx != NSNotFound && (NSUInteger)detIdx < allTitles.count) ? allTitles[(NSUInteger)detIdx] : @"",
            @"resolvedIndex": @(detIdx == NSNotFound ? -1 : detIdx),
            @"visibleTitles": allTitles,
            @"capsuleCount": @(capsuleTitles.count),
            @"totalVisibleModules": @(allTitles.count),
            @"bottomMineEnabled": @(FQXDockIsModuleAllowedByBottomPrefs(@"我的")),
            @"inactiveReason": detachedReason ?: @"unknown",
        }, NO);
    } else if (detIdx != NSNotFound && (NSUInteger)detIdx < self->_buttons.count && self->_detachedButton) {
        UIButton *detBtn = self->_buttons[(NSUInteger)detIdx];
        self->_detachedButton.targetHostButton = detBtn;
        [self->_detachedButton syncUnreadBadgeFromHostButton:detBtn];
    }

    if (!rebuilt) [self syncSelectionExclusivityAnimated:(tabBar.window != nil)];
    return rebuilt;
}

- (void)layoutNativeDockInBar:(UIView *)bar proxy:(UIVisualEffectView *)proxy forceMeasure:(BOOL)forceMeasure {
    UITabBar *tabBar = self->_nativeDockBar;
    if (!tabBar || !bar || !proxy) return;
    CGRect proxyFrame = proxy.frame;
    if (CGRectGetWidth(proxyFrame) < 60.0 || CGRectGetHeight(proxyFrame) < 30.0) return;

    BOOL hasDetached = (self->_detachedHostIndex != NSNotFound && self->_detachedButton != nil);
    NSUInteger itemCount = tabBar.items.count;
    CGFloat barW = CGRectGetWidth(bar.bounds);
    BOOL usesFeed = [self usesFeedMotion];
    if (usesFeed && bar.window && CGRectGetWidth(bar.window.bounds) >= CGRectGetHeight(bar.window.bounds)) {
        [[FQXFeedDockPanController shared] resetFeedGesture];
        [self setFeedCompact:NO animated:NO];
    }
    BOOL compact = !usesFeed && [objc_getAssociatedObject(proxy, &FQXDockCompactKey) boolValue];
    BOOL barWidthChanged = fabs(barW - self->_dockLastBarWidth) > 0.5;
    if (barWidthChanged || hasDetached != self->_dockLastDetachedActive || itemCount != self->_dockLastItemCount)
        self->_expandedDockFraction = CGSizeZero;
    if (forceMeasure || barWidthChanged || hasDetached != self->_dockLastDetachedActive || itemCount != self->_dockLastItemCount) {
        self->_dockPlatterMeasured = NO;
        self->_dockPlatterInset = 21.0;
        self->_dockLastBarWidth = barW;
    }

    CGFloat liftY = 0.0;
    if (bar.window) {
        CGFloat safeBottom = bar.window.safeAreaInsets.bottom;
        if (safeBottom >= 24.0) {
            CGRect proxyInWin = [bar convertRect:proxyFrame toView:bar.window];
            CGFloat screenH = CGRectGetHeight(bar.window.bounds);
            CGFloat desiredMaxY = screenH - 22.0;
            CGFloat overflow = CGRectGetMaxY(proxyInWin) - desiredMaxY;
            if (overflow > 0.5) {
                CGFloat maxSafeLift = MIN(6.0, MAX(2.0, CGRectGetMinY(proxyFrame) + 2.0));
                liftY = round(MIN(overflow, maxSafeLift) * 2.0) / 2.0;
            }
        }
    }

    if (compact && self->_expandedDockFraction.height > 0) liftY = self->_lastDockLiftY;
    BOOL geometryChanged = forceMeasure || !self->_dockPlatterMeasured || barWidthChanged ||
                           hasDetached != self->_dockLastDetachedActive ||
                           itemCount != self->_dockLastItemCount ||
                           fabs(liftY - self->_lastDockLiftY) > 0.5 ||
                           fabs(CGRectGetMinX(proxyFrame) - CGRectGetMinX(self->_dockLastProxyFrame)) > 0.5 ||
                           fabs(CGRectGetMinY(proxyFrame) - CGRectGetMinY(self->_dockLastProxyFrame)) > 0.5 ||
                           fabs(CGRectGetWidth(proxyFrame) - CGRectGetWidth(self->_dockLastProxyFrame)) > 0.5 ||
                           fabs(CGRectGetHeight(proxyFrame) - CGRectGetHeight(self->_dockLastProxyFrame)) > 0.5;

    BOOL isDark = (self->_dockAppliedStyle == UIUserInterfaceStyleDark);
    if (!geometryChanged) {
        BOOL feedAnimating = usesFeed && (self->_feedSpring.following ||
                                          (self->_feedDisplayLink != nil && !self->_feedDisplayLink.paused));
        if (feedAnimating && self->_feedDockSlots.count == itemCount) {
            return;
        }
        UIView *platter = FQXFindDockPlatter(tabBar);
        FQXApplyNativeDockMaterial(tabBar, platter, isDark);
        if (usesFeed) {
            if (self->_feedDockSlots.count != itemCount) {
                [self prepareFeedDockItemsWithPlatter:platter];
            }
            [self syncSiriaiHideLinePreference];
            if (hasDetached) [self syncDetachedDockMaterial:isDark];
            [self syncSelectionExclusivityAnimated:NO];
            [self ensureDockZOrderInBar:bar];
            [self applyFeedMotion:self->_feedSpring.progress];
            return;
        }
        if (platter && CGRectGetHeight(platter.bounds) > 10.0) {
            self->_dockRenderedPlatterRectInBar = [platter convertRect:platter.bounds toView:bar];
        }
        if (hasDetached) {
            [self syncDetachedDockMaterial:isDark];
        }
        [self syncSelectionExclusivityAnimated:NO];
        [self ensureDockZOrderInBar:bar];
        return;
    }

    if (!CGAffineTransformIsIdentity(tabBar.transform)) {
        tabBar.transform = CGAffineTransformIdentity;
    }
    if (self->_detachedButton) {
        if (!CGAffineTransformIsIdentity(self->_detachedButton.transform)) {
            self->_detachedButton.transform = CGAffineTransformIdentity;
        }
        [self->_detachedButton setFeedGlyphScale:1.0];
    }

    CGFloat barH = MAX(CGRectGetHeight(bar.bounds), CGRectGetHeight(proxyFrame) + 12.0);
    CGFloat sideMargin = (barW >= 390.0) ? 16.0 : 12.0;
    CGFloat maxGroupW = MAX(180.0, barW - sideMargin * 2.0);
    CGFloat targetW = hasDetached ? MIN(CGRectGetWidth(proxyFrame), maxGroupW) : CGRectGetWidth(proxyFrame);
    CGFloat targetH = CGRectGetHeight(proxyFrame);
    CGFloat gap = (barW >= 410.0) ? 12.0 : ((barW >= 375.0) ? 10.0 : 8.0);
    CGFloat circleD = targetH;
    CGFloat availCapsuleW = hasDetached ? MAX(96.0, targetW - gap - circleD) : targetW;
    CGFloat maxAllowedBarW = MAX(220.0, barW + 48.0);
    UIView *platter = nil;

    for (NSUInteger pass = 0; pass < 2; ++pass) {
        CGFloat platterH = self->_dockPlatterHeight > 20.0 ? self->_dockPlatterHeight : 62.0;
        CGFloat scale = MAX(0.70, MIN(1.30, targetH / platterH));
        CGFloat desiredBarW = (availCapsuleW / scale) + 2.0 * self->_dockPlatterInset;
        desiredBarW = MAX(120.0, MIN(maxAllowedBarW, desiredBarW));
        CGRect curBounds = tabBar.bounds;
        if (fabs(CGRectGetWidth(curBounds) - desiredBarW) > 0.5 || fabs(CGRectGetHeight(curBounds) - barH) > 0.5) {
            tabBar.bounds = CGRectMake(0.0, 0.0, desiredBarW, barH);
        }
        [tabBar layoutIfNeeded];
        platter = FQXFindDockPlatter(tabBar);
        if (!platter || CGRectGetHeight(platter.bounds) <= 10.0) break;

        CGRect pf = [platter convertRect:platter.bounds toView:tabBar];
        CGFloat measuredH = CGRectGetHeight(pf);
        // Only adopt measured horizontal inset when the platter is actually constrained by
        // UIKit's side inset (8..32pt). For 2-3 tab Docks at natural width, UIKit stops
        // growing the platter and leaves extra margin; absorbing that margin would explode
        // desiredBarW on subsequent passes.
        CGFloat rawInset = (CGRectGetWidth(tabBar.bounds) - CGRectGetWidth(pf)) * 0.5;
        CGFloat measuredInset = (rawInset >= 8.0 && rawInset <= 32.0) ? rawInset : 21.0;
        CGFloat offX = CGRectGetMidX(pf) - CGRectGetMidX(tabBar.bounds);
        CGFloat offY = CGRectGetMidY(pf) - CGRectGetMidY(tabBar.bounds);
        BOOL metricChanged = !self->_dockPlatterMeasured ||
                             fabs(measuredH - self->_dockPlatterHeight) > 0.5 ||
                             fabs(measuredInset - self->_dockPlatterInset) > 0.5 ||
                             fabs(offX - self->_dockPlatterMidOffsetX) > 0.5 ||
                             fabs(offY - self->_dockPlatterMidOffsetY) > 0.5;
        self->_dockPlatterHeight = measuredH;
        self->_dockPlatterInset = measuredInset;
        self->_dockPlatterMidOffsetX = offX;
        self->_dockPlatterMidOffsetY = offY;
        self->_dockPlatterMeasured = YES;
        if (!metricChanged) break;
    }

    FQXApplyNativeDockMaterial(tabBar, platter, isDark);

    CGFloat finalScale = MAX(0.70, MIN(1.30, targetH / MAX(20.0, self->_dockPlatterHeight)));
    // Small UITabBars stop growing at their intrinsic platter width. Anchor both
    // compact axes to the previous *visible* group, including its optional circle.
    CGFloat scaleX = finalScale;
    if (compact && self->_expandedDockFraction.height > 0 && platter) {
        CGRect measured = [platter convertRect:platter.bounds toView:tabBar];
        if (measured.size.width > 0 && measured.size.height > 0) {
            finalScale = targetH * self->_expandedDockFraction.height / measured.size.height;
            CGFloat extra = hasDetached ? round(measured.size.height * finalScale) + gap : 0.0;
            scaleX = MAX(1.0, targetW * self->_expandedDockFraction.width - extra) / measured.size.width;
        }
    }
    if (hasDetached) {
        CGRect pf = (platter && CGRectGetHeight(platter.bounds) > 10.0)
            ? [platter convertRect:platter.bounds toView:tabBar]
            : CGRectZero;
        // CRITICAL: Never clamp rendered platter width smaller than UIKit's real platter
        // width (doing so caused the left capsule to physically collide with the right circle).
        CGFloat pfW = (CGRectGetWidth(pf) > 20.0) ? CGRectGetWidth(pf) : (availCapsuleW / finalScale);
        CGFloat pfH = (CGRectGetHeight(pf) > 10.0) ? CGRectGetHeight(pf) : MAX(20.0, self->_dockPlatterHeight);
        CGFloat realCapsuleW = pfW * scaleX;
        CGFloat realCapsuleH = pfH * finalScale;
        circleD = round(realCapsuleH);

        CGFloat totalGroupW = realCapsuleW + gap + circleD;
        if (totalGroupW > maxGroupW) {
            if (gap > 8.0) {
                gap = MAX(8.0, gap - (totalGroupW - maxGroupW));
                totalGroupW = realCapsuleW + gap + circleD;
            }
            if (totalGroupW > maxGroupW && (pfW + pfH) > 1.0) {
                CGFloat shrinkScale = (maxGroupW - gap) / (pfW + pfH);
                finalScale = MAX(0.64, MIN(finalScale, shrinkScale));
                scaleX = finalScale;
                realCapsuleW = pfW * finalScale;
                realCapsuleH = pfH * finalScale;
                circleD = round(realCapsuleH);
            }
        }

        CGFloat groupW = realCapsuleW + gap + circleD;
        CGFloat groupMinX = CGRectGetMidX(proxyFrame) - groupW * 0.5;
        if (barW >= groupW + sideMargin * 2.0) {
            groupMinX = MAX(sideMargin, MIN(barW - groupW - sideMargin, groupMinX));
        } else {
            groupMinX = MAX(6.0, (barW - groupW) * 0.5);
        }
        CGFloat capsuleRealMaxX = groupMinX + realCapsuleW;
        CGFloat circleMinX = round(capsuleRealMaxX + gap);
        if (circleMinX - capsuleRealMaxX < 8.0) {
            circleMinX = ceil(capsuleRealMaxX + 8.0);
        }
        if (circleMinX + circleD > barW - 6.0) {
            CGFloat excess = (circleMinX + circleD) - (barW - 6.0);
            groupMinX = MAX(6.0, groupMinX - excess);
            capsuleRealMaxX = groupMinX + realCapsuleW;
            circleMinX = ceil(capsuleRealMaxX + MAX(8.0, gap));
        }
        CGFloat effectiveMidY = CGRectGetMidY(proxyFrame) - liftY;
        CGFloat capsuleMidX = groupMinX + realCapsuleW * 0.5;
        CGPoint center = CGPointMake(capsuleMidX - self->_dockPlatterMidOffsetX * scaleX,
                                     effectiveMidY - self->_dockPlatterMidOffsetY * finalScale);
        if (fabs(tabBar.center.x - center.x) > 0.25 || fabs(tabBar.center.y - center.y) > 0.25) {
            tabBar.center = center;
        }
        CGAffineTransform xform = CGAffineTransformMakeScale(scaleX, finalScale);
        if (!CGAffineTransformEqualToTransform(tabBar.transform, xform)) {
            tabBar.transform = xform;
        }

        CGRect circleFrame = CGRectMake(circleMinX,
                                        round(effectiveMidY - circleD * 0.5),
                                        circleD,
                                        circleD);
        if (self->_detachedButton.superview != bar) {
            [bar insertSubview:self->_detachedButton aboveSubview:tabBar];
        }
        if (!CGRectEqualToRect(self->_detachedButton.frame, circleFrame)) {
            self->_detachedButton.frame = circleFrame;
            [self->_detachedButton layoutIfNeeded];
        }
        [self syncDetachedDockMaterial:isDark];
        [self ensureDockZOrderInBar:bar];

        CGRect platterInBar = platter ? [platter convertRect:platter.bounds toView:bar]
                                      : CGRectMake(groupMinX, effectiveMidY - realCapsuleH * 0.5, realCapsuleW, realCapsuleH);
        self->_dockRenderedPlatterRectInBar = platterInBar;
        CGFloat actualGap = CGRectGetMinX(circleFrame) - CGRectGetMaxX(platterInBar);
        CGFloat overlapPt = MAX(0.0, CGRectGetMaxX(platterInBar) - CGRectGetMinX(circleFrame));
        NSString *layoutSig = [NSString stringWithFormat:@"%ld|%.0f|%.0f|%.0f|%.0f|%.1f",
                               (long)self->_detachedHostIndex,
                               CGRectGetMinX(platterInBar), CGRectGetMaxX(platterInBar),
                               CGRectGetMinX(circleFrame), CGRectGetWidth(circleFrame), actualGap];
        NSString *prevLayoutSig = objc_getAssociatedObject(bar, FQXDockDetachedLayoutSigKey);
        if (!prevLayoutSig || ![prevLayoutSig isEqualToString:layoutSig]) {
            objc_setAssociatedObject(bar, FQXDockDetachedLayoutSigKey, layoutSig, OBJC_ASSOCIATION_COPY_NONATOMIC);
            FQXDiagRecordEvent(FQXDiagCategoryUI, @"dock_detached_layout", @{
                @"detachedModule": self->_detachedButton.moduleTitle ?: @"",
                @"detachedHostIndex": @(self->_detachedHostIndex),
                @"capsuleCount": @(itemCount),
                @"capsulePlatterFrameInBar": FQXDockRectArray(platterInBar),
                @"detachedFrameInBar": FQXDockRectArray(circleFrame),
                @"actualGapPt": @(round(actualGap * 10.0) / 10.0),
                @"overlapPt": @(round(overlapPt * 10.0) / 10.0),
                @"finalScale": @(round(finalScale * 1000.0) / 1000.0),
                @"liftY": @(liftY),
                @"proxyFrameInBar": FQXDockRectArray(proxyFrame),
                @"barBounds": FQXDockRectArray(bar.bounds),
            }, NO);
        }
    } else {
        if (self->_detachedButton && !self->_detachedButton.hidden) {
            self->_detachedButton.hidden = YES;
        }
        CGFloat effectiveMidY = CGRectGetMidY(proxyFrame) - liftY;
        CGPoint center = CGPointMake(CGRectGetMidX(proxyFrame) - self->_dockPlatterMidOffsetX * scaleX,
                                     effectiveMidY - self->_dockPlatterMidOffsetY * finalScale);
        if (fabs(tabBar.center.x - center.x) > 0.25 || fabs(tabBar.center.y - center.y) > 0.25) {
            tabBar.center = center;
        }
        CGAffineTransform xform = CGAffineTransformMakeScale(scaleX, finalScale);
        if (!CGAffineTransformEqualToTransform(tabBar.transform, xform)) {
            tabBar.transform = xform;
        }
        if (platter && CGRectGetHeight(platter.bounds) > 10.0) {
            self->_dockRenderedPlatterRectInBar = [platter convertRect:platter.bounds toView:bar];
        } else {
            CGRect fallbackRect = proxyFrame;
            fallbackRect.origin.y -= liftY;
            self->_dockRenderedPlatterRectInBar = fallbackRect;
        }
        [self ensureDockZOrderInBar:bar];
    }

    [self syncSelectionExclusivityAnimated:NO];
    self->_feedBaseScaleX = scaleX;
    self->_feedBaseScaleY = finalScale;
    self->_feedHostCenterAtRest = tabBar.center;
    self->_feedCapsuleAtRest = self->_dockRenderedPlatterRectInBar;
    if (hasDetached) {
        self->_feedDetachedAtRest = self->_detachedButton.frame;
        self->_feedGap = MAX(8.0, CGRectGetMinX(self->_feedDetachedAtRest) - CGRectGetMaxX(self->_feedCapsuleAtRest));
    } else {
        self->_feedDetachedAtRest = CGRectZero;
        self->_feedGap = 0.0;
    }
    if (!compact && targetW > 0 && targetH > 0) {
        CGRect group = self->_dockRenderedPlatterRectInBar;
        if (hasDetached) group = CGRectUnion(group, self->_detachedButton.frame);
        self->_expandedDockFraction = CGSizeMake(group.size.width / targetW, group.size.height / targetH);
    }
    self->_dockLastProxyFrame = proxyFrame;
    self->_lastDockLiftY = liftY;
    self->_dockLastItemCount = itemCount;
    self->_dockLastDetachedActive = hasDetached;
    if (usesFeed) {
        [self prepareFeedDockItemsWithPlatter:platter];
        [self ensureDockZOrderInBar:bar];
        [self syncSiriaiHideLinePreference];
        [self applyFeedMotion:self->_feedSpring.progress];
    }
}

- (void)setLegacyDockOverlay:(UIView *)overlay {
    UIView *previous = self->_overlay;
    if (previous == overlay) return;
    if (self->_nativeDockActive && previous.superview != self->_bar) {
        FQXSetBackdropContentHidden(previous, NO);
        previous.userInteractionEnabled = YES;
    }
    self->_overlay = overlay;
}

- (void)setNativeDockVisible:(BOOL)visible restoreProxy:(BOOL)restoreProxy {
    BOOL wasVisible = self->_nativeDockActive;
    BOOL showDetached = visible && (self->_detachedHostIndex != NSNotFound) && (self->_detachedButton != nil);
    self->_nativeDockActive = visible;
    if (!visible && wasVisible && [self usesFeedMotion]) {
        [[FQXFeedDockPanController shared] resetFeedGesture];
        [self setFeedCompact:NO animated:NO];
    }
    // The modal transition must never animate the exchange between two sets of glyphs.
    [UIView performWithoutAnimation:^{
        if (visible || restoreProxy) {
            FQXDockMaterialOwner owner = visible ? FQXDockMaterialOwnerNative : FQXDockMaterialOwnerProxy;
            FQXSetDockMaterialOwner(self->_bar, self->_proxy, owner, showDetached);
            FQXSetBackdropContentHidden(self->_overlay, visible);
            if (self->_overlay && self->_overlay.userInteractionEnabled == visible)
                self->_overlay.userInteractionEnabled = !visible;
        }
        if (self->_nativeDockBar && self->_nativeDockBar.hidden == visible)
            self->_nativeDockBar.hidden = !visible;
        if (self->_feedContentOverlay && self->_feedContentOverlay.hidden == visible)
            self->_feedContentOverlay.hidden = !visible;
        if (!visible && self->_siriaiMinimumFillView && self->_siriaiMinimumFillView.alpha != 0.0)
            self->_siriaiMinimumFillView.alpha = 0.0;
        if (self->_dockTitleOverlay && self->_dockTitleOverlay.hidden == visible)
            self->_dockTitleOverlay.hidden = !visible;
        if (self->_dockIconOverlay && self->_dockIconOverlay.hidden == visible)
            self->_dockIconOverlay.hidden = !visible;
        if (self->_detachedButton && self->_detachedButton.hidden == showDetached)
            self->_detachedButton.hidden = !showDetached;
        if (visible) [self ensureDockZOrderInBar:self->_bar];
    }];
    if (visible || restoreProxy) {
        FQXAuditVisibleDockGlassLayers(self->_bar, self->_proxy, visible ? self->_nativeDockBar : nil,
                                      showDetached ? self->_detachedButton : nil);
    }
}

#pragma mark - UITabBarDelegate & Tap Rescue

static const char FQXDockTouchBeganKey = 0;

- (BOOL)gestureRecognizer:(UIGestureRecognizer *)gr shouldReceiveTouch:(UITouch *)touch {
    if (gr == self->_dockTapRescueGesture) {
        gFQXActiveDockTouch = touch;
        FQXMarkDockTouchActivity(0.40);
        objc_setAssociatedObject(gr, &FQXDockTouchBeganKey, @(CACurrentMediaTime()), OBJC_ASSOCIATION_RETAIN_NONATOMIC);
    }
    return YES;
}

- (BOOL)gestureRecognizer:(UIGestureRecognizer *)gr shouldRecognizeSimultaneouslyWithGestureRecognizer:(UIGestureRecognizer *)other {
    (void)gr; (void)other;
    return YES;
}

- (void)handleDockTapRescue:(UITapGestureRecognizer *)gr {
    if (gr.state != UIGestureRecognizerStateEnded) return;
    if (!self->_nativeDockActive || gr != self->_dockTapRescueGesture) return;
    UIView *bar = self->_bar;
    UITabBar *tabBar = self->_nativeDockBar;
    UIWindow *window = bar.window;
    NSNumber *touchBegan = objc_getAssociatedObject(gr, &FQXDockTouchBeganKey);
    if (!window || !touchBegan || gr.view != tabBar || tabBar.superview != bar) return;

    CGRect platterRect = FQXDisplayedDockRect(tabBar, bar, self->_dockRenderedPlatterRectInBar);
    if (CGRectGetWidth(platterRect) < 40.0 || CGRectGetHeight(platterRect) < 20.0) return;
    CGPoint ptInBar = [gr locationInView:bar];
    if (FQXNativeDockAtPoint(self, bar, ptInBar) != tabBar) return;

    NSArray<UITabBarItem *> *items = tabBar.items;
    NSUInteger count = items.count;
    if (count == 0) return;

    CGFloat relX = (ptInBar.x - CGRectGetMinX(platterRect)) / MAX(1.0, CGRectGetWidth(platterRect));
    relX = MIN(0.9999, MAX(0.0, relX));
    NSUInteger slotIdx = (NSUInteger)floor(relX * (CGFloat)count);
    if (slotIdx >= count) slotIdx = count - 1;
    if ([UIView userInterfaceLayoutDirectionForSemanticContentAttribute:tabBar.semanticContentAttribute] == UIUserInterfaceLayoutDirectionRightToLeft) {
        slotIdx = (count - 1) - slotIdx;
    }
    NSUInteger tappedHostIdx = (slotIdx < self->_capsuleHostIndices.count)
        ? self->_capsuleHostIndices[slotIdx].unsignedIntegerValue : slotIdx;
    if (tappedHostIdx >= self->_buttons.count) return;

    UITabBarItem *tappedItem = items[slotIdx];
    CGPoint pointInWindow = [bar convertPoint:ptInBar toView:window];
    __weak FQXTabBarInteraction *weakSelf = self;
    dispatch_after(dispatch_time(DISPATCH_TIME_NOW, (int64_t)(0.035 * NSEC_PER_SEC)), dispatch_get_main_queue(), ^{
        FQXTabBarInteraction *s = weakSelf;
        if (!s || !s->_nativeDockActive || s->_bar != bar || s->_nativeDockBar != tabBar ||
            bar.window != window || tabBar.superview != bar ||
            objc_getAssociatedObject(gr, &FQXDockTouchBeganKey) != touchBegan ||
            s->_lastNativeTabSelectTime >= touchBegan.doubleValue) return;
        NSArray<UITabBarItem *> *currentItems = tabBar.items;
        if (slotIdx >= currentItems.count || currentItems[slotIdx] != tappedItem) return;
        NSUInteger currentHostIdx = (slotIdx < s->_capsuleHostIndices.count)
            ? s->_capsuleHostIndices[slotIdx].unsignedIntegerValue : slotIdx;
        if (currentHostIdx != tappedHostIdx) return;
        // A newly presented overlay can win hit testing after the touch ended.
        UIView *hit = [window hitTest:pointInWindow withEvent:nil];
        if (hit != tabBar && ![hit isDescendantOfView:tabBar]) return;
        s->_lastNativeTabSelectTime = CACurrentMediaTime();
        [s triggerHostNavigationForHostIndex:tappedHostIdx fallbackButton:nil source:@"dock_tap_rescue"];
    });
}

- (void)tabBar:(UITabBar *)tabBar didSelectItem:(UITabBarItem *)item {
    if (self->_routingHostDockNavigation || !self->_nativeDockActive ||
        tabBar != self->_nativeDockBar || tabBar.superview != self->_bar || !tabBar.window) return;
    FQXMarkDockTouchActivity(0.30);
    NSUInteger idx = [tabBar.items indexOfObjectIdenticalTo:item];
    if (idx == NSNotFound) return;
    NSUInteger hostIdx = (idx < self->_capsuleHostIndices.count)
        ? self->_capsuleHostIndices[idx].unsignedIntegerValue : idx;
    if (hostIdx >= self->_buttons.count) return;
    CFTimeInterval now = CACurrentMediaTime();
    NSNumber *touchBegan = objc_getAssociatedObject(self->_dockTapRescueGesture, &FQXDockTouchBeganKey);
    if (touchBegan && self->_lastNativeTabSelectTime >= touchBegan.doubleValue && now - self->_lastNativeTabSelectTime < 0.25) return;
    self->_lastNativeTabSelectTime = now;
    // The host switch can lay out or replace the UIKit Dock that delivered this callback.
    __weak FQXTabBarInteraction *weakSelf = self;
    dispatch_async(dispatch_get_main_queue(), ^{
        FQXTabBarInteraction *interaction = weakSelf;
        if (!interaction || interaction->_lastNativeTabSelectTime != now ||
            !interaction->_nativeDockActive || interaction->_nativeDockBar != tabBar ||
            tabBar.superview != interaction->_bar || !tabBar.window) return;
        NSArray<UITabBarItem *> *items = tabBar.items;
        if (idx >= items.count || items[idx] != item) return;
        NSArray<NSNumber *> *indices = interaction->_capsuleHostIndices;
        NSUInteger currentHostIdx = idx < indices.count ? indices[idx].unsignedIntegerValue : idx;
        if (currentHostIdx != hostIdx || hostIdx >= interaction->_buttons.count) return;
        [interaction triggerHostNavigationForHostIndex:hostIdx fallbackButton:nil source:@"native_tabbar_did_select"];
    });
}

- (void)onNativeValueChanged:(UIControl *)sender {
    if (![sender isKindOfClass:UISegmentedControl.class]) return;
    FQXMarkDockTouchActivity(0.30);
    FQXScheduleCYLGlassResample(self->_bar, self->_proxy);
}

- (void)updateLens:(UIVisualEffectView *)lens native:(UIView *)native {
    if (native) self->_nativeControl = native;
    if (lens) {
        self->_restingLens = lens;
        if (!self->_overlay && lens.superview && lens.superview != self->_proxy &&
            lens.superview.superview == self->_bar) {
            [self setLegacyDockOverlay:lens.superview];
        }
    }
    // Runs inside FQHBottomPolish178R7 AFTER Lrepair_front and Lmaterial_update.
    // Re-enforce single-owner proxy neutralization and topmost z-order for detachedButton.
    if (self->_nativeDockActive) {
        [self setNativeDockVisible:YES restoreProxy:NO];
    }
}

- (void)syncWithBar:(UIView *)bar
              proxy:(UIVisualEffectView *)proxy
            buttons:(NSArray<UIButton *> *)buttons
             native:(UIView *)native
               lens:(UIVisualEffectView *)lens {
    if (self->_bar != bar) {
        [[FQXFeedDockPanController shared] resetFeedGesture];
        [self cleanupFeedMotionVisuals];
        DKFeedSpringInit(&self->_feedSpring);
        self->_appliedCollapseMode = FQXDockCollapseModeOff;
        self->_feedLastSelectedIndex = NSNotFound;
        self->_feedCapsuleAtRest = CGRectZero;
        self->_feedDetachedAtRest = CGRectZero;
        [self setNativeDockVisible:NO restoreProxy:YES];
        if (self->_dockTapRescueGesture.view) {
            [self->_dockTapRescueGesture.view removeGestureRecognizer:self->_dockTapRescueGesture];
        }
        self->_dockTapRescueGesture.delegate = nil;
        self->_dockTapRescueGesture = nil;
        [self->_nativeDockBar removeFromSuperview];
        self->_nativeDockBar.delegate = nil;
        self->_nativeDockBar = nil;
        [self->_dockTitleOverlay removeFromSuperview];
        self->_dockTitleOverlay = nil;
        [self->_dockIconOverlay removeFromSuperview];
        self->_dockIconOverlay = nil;
        [self->_detachedButton removeFromSuperview];
        self->_detachedButton = nil;
        self->_capsuleHostIndices = nil;
        self->_detachedHostIndex = NSNotFound;
        self->_dockLastDetachedActive = NO;
        self->_dockSignature = nil;
        self->_dockPlatterMeasured = NO;
        self->_dockRenderedPlatterRectInBar = CGRectZero;
        self->_lastDockLiftY = 0.0;
        self->_lastNativeTabSelectTime = 0.0;
        self->_dockAppliedStyle = UIUserInterfaceStyleUnspecified;
        self->_dockAppliedInkState = -1;
    }
    self->_bar = bar;
    self->_proxy = proxy;
    self->_nativeControl = native;
    if (lens) self->_restingLens = lens;
    self->_buttons = [buttons copy];

    // Use the buttons' current container. A removed lens can still reference
    // the outgoing overlay until UIKit finishes dismissing the settings sheet.
    UIView *overlay = nil;
    if (!native && buttons.count) {
        UIView *parent = buttons.firstObject.superview;
        if (parent && parent != proxy && parent != proxy.contentView && parent.superview == bar) {
            overlay = parent;
        }
    }
    if (!overlay && self->_restingLens.superview.superview == bar && self->_restingLens.superview != proxy) {
        overlay = self->_restingLens.superview;
    }
    [self setLegacyDockOverlay:overlay];

    BOOL hiddenProxy = proxy.hidden || CGRectGetWidth(proxy.frame) < 60.0 || CGRectGetHeight(proxy.frame) < 30.0;
    BOOL circle = overlay.hidden || proxy.contentView.hidden;
    if (circle || hiddenProxy || buttons.count < 2 || !FQXGlassEnabled() || [self usesNativeSegmentedSelector]) {
        [self setNativeDockVisible:NO restoreProxy:YES];
        FQXApplyDockProxyMaterial(bar, proxy, lens);
        if ([native isKindOfClass:UISegmentedControl.class]) {
            UIControl *seg = (UIControl *)native;
            if (![self->_wiredControls containsObject:seg]) {
                [seg addTarget:self action:@selector(onNativeValueChanged:) forControlEvents:UIControlEventValueChanged];
                [self->_wiredControls addObject:seg];
            }
        }
        return;
    }

    FQXDockCollapseMode desiredCollapseMode = FQXFeedMotionSupported() ? FQXCurrentDockCollapseMode() : FQXDockCollapseModeOff;
    if (desiredCollapseMode != self->_appliedCollapseMode) {
        [[FQXFeedDockPanController shared] resetFeedGesture];
        [self cleanupFeedMotionVisuals];
        DKFeedSpringInit(&self->_feedSpring);
        self->_feedSpring.siriai = (desiredCollapseMode == FQXDockCollapseModeSiriai) ? 1 : 0;
        self->_feedSpring.siriaiHidesLine = (desiredCollapseMode == FQXDockCollapseModeSiriai &&
                                             [NSUserDefaults.standardUserDefaults boolForKey:DockSiriaiHideLinePrefKey]) ? 1 : 0;
        self->_appliedCollapseMode = desiredCollapseMode;
        self->_dockSignature = nil;
        if (FQXDockCollapseModeUsesFeedMotion(desiredCollapseMode)) {
            [[FQXFeedDockPanController shared] scanWindowsForMountedCollections];
        }
    }

    NSUInteger curSelIdx = [self currentSelectedIndex];
    if (self->_feedLastSelectedIndex != curSelIdx) {
        BOOL wasColdStart = (self->_feedLastSelectedIndex == NSNotFound);
        if ([self usesFeedMotion]) {
            if (!wasColdStart) {
                [[FQXFeedDockPanController shared] resetFeedGesture];
                if (self->_feedSpring.compact || self->_feedSpring.progress > 0.005 || self->_feedSpring.overtravel != 0.0) {
                    [self setFeedCompact:NO animated:YES];
                }
            }
            dispatch_async(dispatch_get_main_queue(), ^{
                [[FQXFeedDockPanController shared] scanWindowsForMountedCollections];
            });
            dispatch_after(dispatch_time(DISPATCH_TIME_NOW, (int64_t)((wasColdStart ? 0.25 : 0.35) * NSEC_PER_SEC)),
                           dispatch_get_main_queue(), ^{
                [[FQXFeedDockPanController shared] scanWindowsForMountedCollections];
            });
            if (wasColdStart) {
                dispatch_after(dispatch_time(DISPATCH_TIME_NOW, (int64_t)(0.90 * NSEC_PER_SEC)),
                               dispatch_get_main_queue(), ^{
                    [[FQXFeedDockPanController shared] scanWindowsForMountedCollections];
                });
            }
        }
        self->_feedLastSelectedIndex = curSelIdx;
    }

    if (!self->_nativeDockBar) {
        UITabBar *tabBar = [[UITabBar alloc] initWithFrame:bar.bounds];
        tabBar.hidden = YES;
        tabBar.delegate = self;
        tabBar.clipsToBounds = NO;
        objc_setAssociatedObject(tabBar, FQXOwnedGlassElementKey, @YES, OBJC_ASSOCIATION_RETAIN_NONATOMIC);
        UITapGestureRecognizer *rescueTap = [[UITapGestureRecognizer alloc] initWithTarget:self action:@selector(handleDockTapRescue:)];
        rescueTap.cancelsTouchesInView = NO;
        rescueTap.delaysTouchesBegan = NO;
        rescueTap.delaysTouchesEnded = NO;
        rescueTap.delegate = self;
        [tabBar addGestureRecognizer:rescueTap];
        self->_dockTapRescueGesture = rescueTap;
        self->_nativeDockBar = tabBar;
        self->_dockPlatterMeasured = NO;
        self->_dockLastProxyFrame = CGRectZero;
        self->_dockRenderedPlatterRectInBar = CGRectZero;
    }

    if (self->_nativeDockBar.superview != bar) {
        [bar addSubview:self->_nativeDockBar];
    }
    [self ensureDockZOrderInBar:bar];

    UIUserInterfaceStyle desiredStyle = [self desiredDockGlassStyle];
    BOOL styleChanged = (self->_dockAppliedStyle != desiredStyle) ||
                        (self->_nativeDockBar.overrideUserInterfaceStyle != desiredStyle);
    if (styleChanged) {
        self->_dockAppliedStyle = desiredStyle;
        if (self->_nativeDockBar.overrideUserInterfaceStyle != desiredStyle) {
            self->_nativeDockBar.overrideUserInterfaceStyle = desiredStyle;
        }
    }

    NSInteger desiredInk = [self isDarkDock] ? 1 : 0;
    BOOL inkChanged = (self->_dockAppliedInkState != desiredInk);
    BOOL itemsRebuilt = [self syncDockItems];
    if (inkChanged && !itemsRebuilt) {
        [self applyDockItemImagesToItems:self->_nativeDockBar.items];
    }
    if (styleChanged || itemsRebuilt) {
        UIView *curPlatter = FQXFindDockPlatter(self->_nativeDockBar);
        if (curPlatter) {
            objc_setAssociatedObject(curPlatter, FQXPlatterAppliedStyleKey, nil, OBJC_ASSOCIATION_RETAIN_NONATOMIC);
            objc_setAssociatedObject(curPlatter, FQXPlatterAppliedEffectKey, nil, OBJC_ASSOCIATION_RETAIN_NONATOMIC);
            static Class platterCls = Nil;
            static Class itemPlatterCls = Nil;
            static dispatch_once_t spOnce;
            dispatch_once(&spOnce, ^{
                platterCls = NSClassFromString(@"UIKit._UITabBarPlatterView");
                itemPlatterCls = NSClassFromString(@"UIKit._UITabBarItemPlatterView");
            });
            if ((platterCls || itemPlatterCls) && curPlatter.superview) {
                for (UIView *sib in curPlatter.superview.subviews) {
                    if ((platterCls && [sib isKindOfClass:platterCls]) ||
                        (itemPlatterCls && [sib isKindOfClass:itemPlatterCls])) {
                        objc_setAssociatedObject(sib, FQXPlatterAppliedStyleKey, nil, OBJC_ASSOCIATION_RETAIN_NONATOMIC);
                        objc_setAssociatedObject(sib, FQXPlatterAppliedEffectKey, nil, OBJC_ASSOCIATION_RETAIN_NONATOMIC);
                    }
                }
            }
        }
    }

    // Keep the same material and navigation controls mounted in both feed sizes.
    if (self->_nativeDockActive) {
        [self layoutNativeDockInBar:bar proxy:proxy forceMeasure:itemsRebuilt];
        [self setNativeDockVisible:YES restoreProxy:NO];
    } else {
        [UIView performWithoutAnimation:^{
            // Measure the live UIKit provider before handing off from the proxy.
            self->_nativeDockBar.hidden = NO;
            [self layoutNativeDockInBar:bar proxy:proxy forceMeasure:YES];
            [self setNativeDockVisible:YES restoreProxy:NO];
        }];
    }
}

- (void)teardown {
    [[FQXFeedDockPanController shared] resetFeedGesture];
    [self cleanupFeedMotionVisuals];
    DKFeedSpringInit(&self->_feedSpring);
    self->_appliedCollapseMode = FQXDockCollapseModeOff;
    self->_feedLastSelectedIndex = NSNotFound;
    self->_feedCapsuleAtRest = CGRectZero;
    self->_feedDetachedAtRest = CGRectZero;
    [self setNativeDockVisible:NO restoreProxy:YES];
    if (self->_dockTapRescueGesture.view) {
        [self->_dockTapRescueGesture.view removeGestureRecognizer:self->_dockTapRescueGesture];
    }
    self->_dockTapRescueGesture.delegate = nil;
    self->_dockTapRescueGesture = nil;
    self->_nativeDockBar.delegate = nil;
    [self->_nativeDockBar removeFromSuperview];
    self->_nativeDockBar = nil;
    [self->_dockTitleOverlay removeFromSuperview];
    self->_dockTitleOverlay = nil;
    [self->_dockIconOverlay removeFromSuperview];
    self->_dockIconOverlay = nil;
    [self->_detachedButton removeFromSuperview];
    self->_detachedButton = nil;
    self->_capsuleHostIndices = nil;
    self->_detachedHostIndex = NSNotFound;
    self->_dockLastDetachedActive = NO;
    self->_dockSignature = nil;
    self->_dockTitles = nil;
    self->_dockPlatterMeasured = NO;
    self->_dockRenderedPlatterRectInBar = CGRectZero;
    self->_lastDockLiftY = 0.0;
    self->_lastNativeTabSelectTime = 0.0;
    self->_dockAppliedStyle = UIUserInterfaceStyleUnspecified;
    self->_dockAppliedInkState = -1;
}

@end

#pragma mark - DYKiller-Style Top Drama Channel Capsule (Long-Press Floating Glass & Drag)

@interface FQXFlexGlassView : UIVisualEffectView
@property(nonatomic, weak) UIView *flexSourceView;
@end

@implementation FQXFlexGlassView
- (UIView *)_flexInteractionGestureView {
    UIView *source = self.flexSourceView;
    if (source && source.window) return source;
    SEL sel = sel_registerName("_flexInteractionGestureView");
    if ([UIVisualEffectView instancesRespondToSelector:sel]) {
        struct objc_super sup = { self, UIVisualEffectView.class };
        return ((id (*)(struct objc_super *, SEL))objc_msgSendSuper)(&sup, sel);
    }
    return nil;
}
@end

typedef NS_ENUM(NSInteger, FQXTopCapsuleTouchMode) {
    FQXTopCapsuleTouchIdle = 0,
    FQXTopCapsuleTouchPressing = 1,
    FQXTopCapsuleTouchDragging = 2,
};

static const char FQXK_FQXDramaTopCapsuleKey = 0;
#define FQXDramaTopCapsuleKey ((const void *)&FQXK_FQXDramaTopCapsuleKey)
static const char FQXK_FQXDramaTopGlassStampKey = 0;
