static UIFont *FQXScaledDramaTitleFontForTabs(UIView *tabs) {
    if (!tabs) return nil;
    UIFont *baseFont = objc_getAssociatedObject(tabs, FQXDramaBaseTitleFontKey);
    if (![baseFont isKindOfClass:UIFont.class]) {
        UIFont *cur = FQXObjGet(tabs, "titleFont");
        if ([cur isKindOfClass:UIFont.class]) {
            baseFont = cur;
            objc_setAssociatedObject(tabs, FQXDramaBaseTitleFontKey, baseFont, OBJC_ASSOCIATION_RETAIN_NONATOMIC);
        }
    }
    if (![baseFont isKindOfClass:UIFont.class]) return nil;
    NSInteger scalePct = FQXDramaHeaderButtonScalePercent();
    if (scalePct == 100) return baseFont;
    CGFloat scale = (CGFloat)scalePct / 100.0;
    CGFloat pt = round(MAX(11.0, MIN(22.0, baseFont.pointSize * scale)) * 2.0) / 2.0;
    if (fabs(pt - baseFont.pointSize) < 0.25) return baseFont;
    return [baseFont fontWithSize:pt];
}

static void FQXStabilizeDramaCategoryCellModel(id model, UIFont *lockedFont) {
    if (!model) return;
    // Mirror AlignedGlass's verified ShelfPrepareTabModel boundary: lock zoom scales,
    // stroke animation, and selected font to lockedFont so swiping never shifts font
    // size, weight, baseline, or capsule width (and honors DramaHeaderButtonScale).
    FQXSafeSetBoolProp(model, "isTitleLabelZoomEnabled", "setTitleLabelZoomEnabled:", NO);
    FQXSafeSetBoolProp(model, "isCellWidthZoomEnabled", "setCellWidthZoomEnabled:", NO);
    FQXSafeSetBoolProp(model, "isSelectedAnimationEnabled", "setSelectedAnimationEnabled:", NO);
    FQXSafeSetBoolProp(model, "isTitleLabelStrokeWidthEnabled", "setTitleLabelStrokeWidthEnabled:", NO);
    FQXSafeSetDoubleProp(model, "titleLabelNormalZoomScale", "setTitleLabelNormalZoomScale:", 1.0);
    FQXSafeSetDoubleProp(model, "titleLabelCurrentZoomScale", "setTitleLabelCurrentZoomScale:", 1.0);
    FQXSafeSetDoubleProp(model, "titleLabelSelectedZoomScale", "setTitleLabelSelectedZoomScale:", 1.0);
    FQXSafeSetDoubleProp(model, "cellWidthNormalZoomScale", "setCellWidthNormalZoomScale:", 1.0);
    FQXSafeSetDoubleProp(model, "cellWidthCurrentZoomScale", "setCellWidthCurrentZoomScale:", 1.0);
    FQXSafeSetDoubleProp(model, "cellWidthSelectedZoomScale", "setCellWidthSelectedZoomScale:", 1.0);
    FQXSafeSetDoubleProp(model, "titleLabelVerticalOffset", "setTitleLabelVerticalOffset:", 0.0);
    FQXSafeSetDoubleProp(model, "titleLabelZoomSelectedVerticalOffset", "setTitleLabelZoomSelectedVerticalOffset:", 0.0);
    FQXSafeSetUIntProp(model, "titleLabelAnchorPointStyle", "setTitleLabelAnchorPointStyle:", 0);
    UIFont *targetFont = [lockedFont isKindOfClass:UIFont.class] ? lockedFont : FQXObjGet(model, "titleFont");
    if ([targetFont isKindOfClass:UIFont.class]) {
        FQXSafeSetObjProp(model, "titleFont", "setTitleFont:", targetFont);
        FQXSafeSetObjProp(model, "titleSelectedFont", "setTitleSelectedFont:", targetFont);
    }
}

static void FQXResetLabelTransformAndFont(UILabel *label, UIFont *lockedFont) {
    if (![label isKindOfClass:UILabel.class]) return;
    if (!CGAffineTransformIsIdentity(label.transform)) {
        label.transform = CGAffineTransformIdentity;
    }
    if (lockedFont && (!label.font || ![label.font isEqual:lockedFont])) {
        label.font = lockedFont;
    }
    if (label.textAlignment != NSTextAlignmentCenter) {
        label.textAlignment = NSTextAlignmentCenter;
    }
    UIView *host = label.superview;
    if (host && CGRectGetWidth(host.bounds) >= 12.0 && CGRectGetHeight(host.bounds) >= 12.0 &&
        label.translatesAutoresizingMaskIntoConstraints) {
        CGSize fit = [label sizeThatFits:host.bounds.size];
        CGFloat w = MIN(CGRectGetWidth(host.bounds), ceil(fit.width) + 2.0);
        CGFloat h = MIN(CGRectGetHeight(host.bounds), ceil(fit.height) + 2.0);
        if (w > 4.0 && h > 4.0) {
            CGRect target = CGRectMake(round((CGRectGetWidth(host.bounds) - w) * 0.5 * 2.0) / 2.0,
                                       round((CGRectGetHeight(host.bounds) - h) * 0.5 * 2.0) / 2.0,
                                       w, h);
            if (fabs(CGRectGetMidX(label.frame) - CGRectGetMidX(target)) > 0.5 ||
                fabs(CGRectGetMidY(label.frame) - CGRectGetMidY(target)) > 0.5 ||
                CGRectGetWidth(label.frame) + 0.5 < ceil(fit.width)) {
                label.frame = target;
            }
        }
    }
}

static const char FQXK_DramaTabSavedNormalColorKey = 0;
#define DramaTabSavedNormalColorKey ((const void *)&FQXK_DramaTabSavedNormalColorKey)
static const char FQXK_DramaTabSavedSelectedColorKey = 0;
#define DramaTabSavedSelectedColorKey ((const void *)&FQXK_DramaTabSavedSelectedColorKey)

static void FQXApplyDramaTabVideoInk(UIView *tabs) {
    if (!tabs) return;
    BOOL lightBase = (FQXDramaButtonSurfaceStyleMode() != FQXDramaButtonSurfaceDefaultGlass);
    BOOL roseSel = (FQXEffectiveDramaSelectionTintStyle() != FQXSelectionTintStyleDefault);
    UIColor *darkNormal = FQXVideoInkUIColor(0.80);
    UIColor *darkSelected = FQXVideoInkUIColor(1.0);

    // Save/update tab-level colors
    UIColor *savedNorm = objc_getAssociatedObject(tabs, DramaTabSavedNormalColorKey);
    UIColor *savedSel = objc_getAssociatedObject(tabs, DramaTabSavedSelectedColorKey);
    if (lightBase || roseSel) {
        if (!savedNorm) {
            UIColor *curN = FQXObjGet(tabs, "titleColor");
            if ([curN isKindOfClass:UIColor.class]) {
                objc_setAssociatedObject(tabs, DramaTabSavedNormalColorKey, curN, OBJC_ASSOCIATION_RETAIN_NONATOMIC);
                savedNorm = curN;
            }
        }
        if (!savedSel) {
            UIColor *curS = FQXObjGet(tabs, "titleSelectedColor");
            if ([curS isKindOfClass:UIColor.class]) {
                objc_setAssociatedObject(tabs, DramaTabSavedSelectedColorKey, curS, OBJC_ASSOCIATION_RETAIN_NONATOMIC);
                savedSel = curS;
            }
        }
        if (lightBase) {
            FQXSafeSetObjProp(tabs, "titleColor", "setTitleColor:", darkNormal);
        } else if (savedNorm) {
            FQXSafeSetObjProp(tabs, "titleColor", "setTitleColor:", savedNorm);
        }
        FQXSafeSetObjProp(tabs, "titleSelectedColor", "setTitleSelectedColor:", darkSelected);
    } else {
        if (savedNorm) {
            FQXSafeSetObjProp(tabs, "titleColor", "setTitleColor:", savedNorm);
            objc_setAssociatedObject(tabs, DramaTabSavedNormalColorKey, nil, OBJC_ASSOCIATION_RETAIN_NONATOMIC);
        }
        if (savedSel) {
            FQXSafeSetObjProp(tabs, "titleSelectedColor", "setTitleSelectedColor:", savedSel);
            objc_setAssociatedObject(tabs, DramaTabSavedSelectedColorKey, nil, OBJC_ASSOCIATION_RETAIN_NONATOMIC);
        }
    }

    NSArray *ds = FQXObjGet(tabs, "dataSource");
    if ([ds isKindOfClass:NSArray.class]) {
        for (NSUInteger i = 0; i < ds.count && i < 24; ++i) {
            id model = ds[i];
            BOOL isSel = FQXBoolGet(model, "isSelected", NO);
            UIColor *mSavedNorm = objc_getAssociatedObject(model, DramaTabSavedNormalColorKey);
            UIColor *mSavedSel = objc_getAssociatedObject(model, DramaTabSavedSelectedColorKey);
            if (lightBase || roseSel) {
                if (!mSavedNorm) {
                    UIColor *cn = FQXObjGet(model, "titleNormalColor");
                    if ([cn isKindOfClass:UIColor.class]) {
                        objc_setAssociatedObject(model, DramaTabSavedNormalColorKey, cn, OBJC_ASSOCIATION_RETAIN_NONATOMIC);
                        mSavedNorm = cn;
                    }
                }
                if (!mSavedSel) {
                    UIColor *cs = FQXObjGet(model, "titleSelectedColor");
                    if ([cs isKindOfClass:UIColor.class]) {
                        objc_setAssociatedObject(model, DramaTabSavedSelectedColorKey, cs, OBJC_ASSOCIATION_RETAIN_NONATOMIC);
                        mSavedSel = cs;
                    }
                }
                UIColor *effNorm = lightBase ? darkNormal : (mSavedNorm ?: FQXObjGet(model, "titleNormalColor"));
                UIColor *effSel = darkSelected;
                if (effNorm) FQXSafeSetObjProp(model, "titleNormalColor", "setTitleNormalColor:", effNorm);
                FQXSafeSetObjProp(model, "titleSelectedColor", "setTitleSelectedColor:", effSel);
                UIColor *curColor = isSel ? effSel : effNorm;
                if (curColor) FQXSafeSetObjProp(model, "titleCurrentColor", "setTitleCurrentColor:", curColor);
            } else {
                if (mSavedNorm) {
                    FQXSafeSetObjProp(model, "titleNormalColor", "setTitleNormalColor:", mSavedNorm);
                    objc_setAssociatedObject(model, DramaTabSavedNormalColorKey, nil, OBJC_ASSOCIATION_RETAIN_NONATOMIC);
                }
                if (mSavedSel) {
                    FQXSafeSetObjProp(model, "titleSelectedColor", "setTitleSelectedColor:", mSavedSel);
                    objc_setAssociatedObject(model, DramaTabSavedSelectedColorKey, nil, OBJC_ASSOCIATION_RETAIN_NONATOMIC);
                }
                UIColor *curColor = isSel ? mSavedSel : mSavedNorm;
                if (curColor) FQXSafeSetObjProp(model, "titleCurrentColor", "setTitleCurrentColor:", curColor);
            }
        }
    }

    UICollectionView *cv = FQXObjGet(tabs, "collectionView");
    if ([cv isKindOfClass:UICollectionView.class]) {
        for (UICollectionViewCell *cell in cv.visibleCells) {
            NSIndexPath *ip = [cv indexPathForCell:cell];
            BOOL isSel = NO;
            if (ip && [ds isKindOfClass:NSArray.class] && ip.item >= 0 && (NSUInteger)ip.item < ds.count) {
                isSel = FQXBoolGet(ds[(NSUInteger)ip.item], "isSelected", NO);
            }
            UILabel *lbl = FQXObjGet(cell, "titleLabel");
            UILabel *maskLbl = FQXObjGet(cell, "maskTitleLabel");
            for (UILabel *l in @[lbl ?: NSNull.null, maskLbl ?: NSNull.null]) {
                if (![l isKindOfClass:UILabel.class]) continue;
                UIColor *lSaved = objc_getAssociatedObject(l, DramaTabSavedNormalColorKey);
                if (lightBase || (roseSel && isSel)) {
                    if (!lSaved && l.textColor) {
                        objc_setAssociatedObject(l, DramaTabSavedNormalColorKey, l.textColor, OBJC_ASSOCIATION_RETAIN_NONATOMIC);
                    }
                    l.textColor = isSel ? darkSelected : darkNormal;
                } else if (lSaved) {
                    l.textColor = lSaved;
                    objc_setAssociatedObject(l, DramaTabSavedNormalColorKey, nil, OBJC_ASSOCIATION_RETAIN_NONATOMIC);
                }
            }
        }
    }
}

static void FQXStabilizeDramaCategoryTabs(UIView *tabs) {
    if (!FQXGlassEnabled() || !FQXDramaHeaderForTabs(tabs)) return;
    FQXSafeSetBoolProp(tabs, "isTitleLabelZoomEnabled", "setTitleLabelZoomEnabled:", NO);
    FQXSafeSetBoolProp(tabs, "isCellWidthZoomEnabled", "setCellWidthZoomEnabled:", NO);
    FQXSafeSetBoolProp(tabs, "isTitleLabelStrokeWidthEnabled", "setTitleLabelStrokeWidthEnabled:", NO);
    FQXSafeSetBoolProp(tabs, "isSelectedAnimationEnabled", "setSelectedAnimationEnabled:", NO);
    FQXSafeSetDoubleProp(tabs, "titleLabelZoomScale", "setTitleLabelZoomScale:", 1.0);
    FQXSafeSetDoubleProp(tabs, "cellWidthZoomScale", "setCellWidthZoomScale:", 1.0);
    FQXSafeSetDoubleProp(tabs, "titleLabelZoomSelectedVerticalOffset", "setTitleLabelZoomSelectedVerticalOffset:", 0.0);
    FQXSafeSetUIntProp(tabs, "titleLabelAnchorPointStyle", "setTitleLabelAnchorPointStyle:", 0);
    UIFont *lockedFont = FQXScaledDramaTitleFontForTabs(tabs);
    if ([lockedFont isKindOfClass:UIFont.class]) {
        FQXSafeSetObjProp(tabs, "titleFont", "setTitleFont:", lockedFont);
        FQXSafeSetObjProp(tabs, "titleSelectedFont", "setTitleSelectedFont:", lockedFont);
    }
    NSArray *ds = FQXObjGet(tabs, "dataSource");
    if ([ds isKindOfClass:NSArray.class]) {
        for (NSUInteger i = 0; i < ds.count && i < 24; ++i) {
            FQXStabilizeDramaCategoryCellModel(ds[i], lockedFont);
        }
    }
    UICollectionView *cv = FQXObjGet(tabs, "collectionView");
    if ([cv isKindOfClass:UICollectionView.class]) {
        for (UICollectionViewCell *cell in cv.visibleCells) {
            FQXResetLabelTransformAndFont(FQXObjGet(cell, "titleLabel"), lockedFont);
            FQXResetLabelTransformAndFont(FQXObjGet(cell, "maskTitleLabel"), lockedFont);
        }
    }
    FQXApplyDramaTabVideoInk(tabs);
}

static void FQXInitDramaCompactOrigMaps(void) {
    static dispatch_once_t once;
    dispatch_once(&once, ^{
        gFQXDramaCompactOrigElems = [NSMutableDictionary dictionary];
        gFQXDramaCompactOrigItem = [NSMutableDictionary dictionary];
        gFQXDramaCompactOrigSize = [NSMutableDictionary dictionary];
    });
}

static IMP FQXLookupDramaCompactOrig(NSDictionary<NSString *, NSValue *> *map, Class cls) {
    for (Class c = cls; c; c = class_getSuperclass(c)) {
        NSString *name = NSStringFromClass(c);
        if (!name.length) continue;
        NSValue *val = map[name];
        if (val) return (IMP)val.pointerValue;
    }
    return NULL;
}

// Collapse dead minimumInteritemSpacing around hidden 0.5pt Drama category cells so hiding middle
// sub-tabs (e.g. 看剧/漫剧) renders tightly spaced, centered titles like [推荐 最近 收藏] with
// zero empty gap, while keeping real NSIndexPaths intact for tap/drag/AlignedGlass capsule sizing.
static BOOL FQXComputeDramaCompactedRects(UICollectionViewLayout *layout,
                                          CGRect outCompacted[24],
                                          BOOL outHidden[24],
                                          NSInteger *outCount,
                                          CGSize *outContentSize) {
    if (!layout || gFQXDramaCompactComputing || !FQXGlassEnabled()) return NO;
    if (!objc_getAssociatedObject(layout, FQXDramaCompactLayoutActiveKey)) return NO;
    UICollectionView *cv = layout.collectionView;
    if (!cv || [cv numberOfSections] < 1) return NO;
    NSInteger count = [cv numberOfItemsInSection:0];
    if (count < 1 || count > 24) return NO;

    Class cls = object_getClass(layout);
    IMP itemImp = FQXLookupDramaCompactOrig(gFQXDramaCompactOrigItem, cls);
    IMP sizeImp = FQXLookupDramaCompactOrig(gFQXDramaCompactOrigSize, cls);
    if (!itemImp) return NO;

    gFQXDramaCompactComputing = YES;
    CGRect raw[24];
    NSInteger visibleCount = 0;
    NSInteger hiddenCount = 0;
    NSInteger firstVisible = -1;
    NSInteger lastVisible = -1;
    for (NSInteger i = 0; i < count; ++i) {
        NSIndexPath *ip = [NSIndexPath indexPathForItem:i inSection:0];
        UICollectionViewLayoutAttributes *a =
            ((UICollectionViewLayoutAttributes *(*)(id, SEL, id))itemImp)(layout, @selector(layoutAttributesForItemAtIndexPath:), ip);
        raw[i] = a ? a.frame : CGRectZero;
        BOOL isHidden = (CGRectGetWidth(raw[i]) <= 2.0 || CGRectGetHeight(raw[i]) <= 4.0);
        outHidden[i] = isHidden;
        if (isHidden) {
            hiddenCount++;
        } else {
            visibleCount++;
            if (firstVisible < 0) firstVisible = i;
            lastVisible = i;
        }
    }
    CGSize origSize = sizeImp
        ? ((CGSize (*)(id, SEL))sizeImp)(layout, @selector(collectionViewContentSize))
        : cv.contentSize;
    gFQXDramaCompactComputing = NO;

    NSInteger scalePct = FQXDramaHeaderButtonScalePercent();
    BOOL scaled = (scalePct != 100);
    CGFloat scale = (CGFloat)scalePct / 100.0;
    if ((!scaled && hiddenCount == 0) || visibleCount == 0 || firstVisible < 0 || lastVisible < 0) {
        objc_setAssociatedObject(layout, FQXDramaCompactHiddenCountKey, @0, OBJC_ASSOCIATION_RETAIN_NONATOMIC);
        objc_setAssociatedObject(layout, FQXDramaCompactRemovedGapKey, @0, OBJC_ASSOCIATION_RETAIN_NONATOMIC);
        return NO;
    }

    // Measure native inter-item gap from any two adjacent visible items first.
    CGFloat spacing = -1.0;
    for (NSInteger i = 0; i + 1 < count; ++i) {
        if (!outHidden[i] && !outHidden[i + 1]) {
            CGFloat g = CGRectGetMinX(raw[i + 1]) - CGRectGetMaxX(raw[i]);
            if (g >= 4.0 && g <= 36.0) {
                spacing = g;
                break;
            }
        }
    }
    if (spacing < 0.0 && [layout isKindOfClass:UICollectionViewFlowLayout.class]) {
        UICollectionViewFlowLayout *fl = (UICollectionViewFlowLayout *)layout;
        CGFloat cand = (fl.scrollDirection == UICollectionViewScrollDirectionHorizontal)
            ? fl.minimumLineSpacing : fl.minimumInteritemSpacing;
        if (cand >= 6.0 && cand <= 32.0) spacing = cand;
    }
    if (spacing < 0.0) spacing = 18.0;

    UIView *tabsView = nil;
    for (UIView *cur = cv.superview; cur; cur = cur.superview) {
        if (FQXDramaHeaderForTabs(cur)) {
            tabsView = cur;
            break;
        }
    }
    UIFont *scaledFont = scaled ? FQXScaledDramaTitleFontForTabs(tabsView) : nil;
    NSArray *ds = scaled ? FQXObjGet(tabsView, "dataSource") : nil;
    if (![ds isKindOfClass:NSArray.class]) ds = nil;

    CGFloat itemWidths[24];
    CGFloat totalItemW = 0.0;
    CGFloat extraTextPad = round(MAX(4.0, MIN(10.0, 6.0 * scale)));
    for (NSInteger i = 0; i < count; ++i) {
        if (outHidden[i]) {
            itemWidths[i] = 0.5;
            continue;
        }
        CGFloat w = round(raw[i].size.width * 2.0) / 2.0;
        if (scaled) {
            NSString *title = ((NSUInteger)i < ds.count) ? FQXObjGet(ds[(NSUInteger)i], "title") : nil;
            if ([title isKindOfClass:NSString.class] && title.length > 0 && scaledFont) {
                CGFloat textW = ceil([title sizeWithAttributes:@{NSFontAttributeName: scaledFont}].width);
                w = round((textW + extraTextPad) * 2.0) / 2.0;
            } else {
                w = round(MAX(20.0, raw[i].size.width * scale) * 2.0) / 2.0;
            }
        }
        itemWidths[i] = w;
        totalItemW += w;
    }

    CGFloat effectiveSpacing = scaled ? (round(MAX(8.0, MIN(28.0, spacing * scale)) * 2.0) / 2.0) : spacing;
    if (scaled && visibleCount > 1 && CGRectGetWidth(cv.bounds) > 80.0) {
        CGFloat leadEst = MAX(6.0, MIN(16.0, CGRectGetMinX(raw[firstVisible])));
        CGFloat availForGaps = CGRectGetWidth(cv.bounds) - leadEst * 2.0 - totalItemW;
        CGFloat neededGaps = effectiveSpacing * (CGFloat)(visibleCount - 1);
        if (neededGaps > availForGaps && availForGaps > 0.0) {
            CGFloat fitted = floor((availForGaps / (CGFloat)(visibleCount - 1)) * 2.0) / 2.0;
            effectiveSpacing = MAX(8.0, MIN(effectiveSpacing, fitted));
        }
    }

    CGFloat leadPad = FQXDramaCompactedLeadingPad(scale);
    CGFloat cursorX = leadPad;
    BOOL placedAny = NO;
    for (NSInteger i = 0; i < count; ++i) {
        if (!outHidden[i]) {
            if (placedAny) cursorX += effectiveSpacing;
            CGFloat cellH = raw[i].size.height;
            CGFloat cellY = raw[i].origin.y;
            if (scaledFont) {
                CGFloat minH = ceil(scaledFont.lineHeight) + 2.0;
                if (cellH < minH) {
                    CGFloat midY = CGRectGetMidY(raw[i]);
                    cellH = minH;
                    cellY = round((midY - cellH * 0.5) * 2.0) / 2.0;
                }
            }
            outCompacted[i] = CGRectMake(round(cursorX * 2.0) / 2.0,
                                         cellY,
                                         itemWidths[i],
                                         cellH);
            cursorX = CGRectGetMaxX(outCompacted[i]);
            placedAny = YES;
        } else {
            outCompacted[i] = CGRectMake(cursorX, raw[i].origin.y, 0.5, MAX(1.0, raw[i].size.height));
        }
    }

    CGFloat removedGap = MAX(0.0, CGRectGetMaxX(raw[lastVisible]) - CGRectGetMaxX(outCompacted[lastVisible]));
    CGFloat trailing = leadPad;
    if (outContentSize) {
        *outContentSize = CGSizeMake(MAX(1.0, cursorX + trailing), MAX(1.0, origSize.height));
    }
    if (outCount) *outCount = count;
    objc_setAssociatedObject(layout, FQXDramaCompactHiddenCountKey, @(hiddenCount), OBJC_ASSOCIATION_RETAIN_NONATOMIC);
    objc_setAssociatedObject(layout, FQXDramaCompactRemovedGapKey, @(round(removedGap * 10.0) / 10.0), OBJC_ASSOCIATION_RETAIN_NONATOMIC);
    return scaled || (hiddenCount > 0) || (removedGap > 1.0);
}

static const char FQXK_FQXShelfCompactLayoutKindKey = 0;
#define FQXShelfCompactLayoutKindKey ((const void *)&FQXK_FQXShelfCompactLayoutKindKey)
static const char FQXK_FQXShelfCompactFallbackGapKey = 0;
#define FQXShelfCompactFallbackGapKey ((const void *)&FQXK_FQXShelfCompactFallbackGapKey)
static BOOL FQXComputeShelfCompactedRects(UICollectionViewLayout *layout,
                                          CGRect outCompacted[24],
                                          BOOL outHidden[24],
                                          NSInteger *outCount,
                                          CGSize *outContentSize);

static BOOL FQXIsLayoutCompactionTagged(UICollectionViewLayout *layout) {
    return layout && (objc_getAssociatedObject(layout, FQXDramaCompactLayoutActiveKey) != nil ||
                      objc_getAssociatedObject(layout, FQXShelfCompactLayoutKindKey) != nil);
}

static BOOL FQXComputeAnyCompactedRects(UICollectionViewLayout *layout,
                                        CGRect outCompacted[24],
                                        BOOL outHidden[24],
                                        NSInteger *outCount,
                                        CGSize *outContentSize) {
    if (objc_getAssociatedObject(layout, FQXDramaCompactLayoutActiveKey)) {
        return FQXComputeDramaCompactedRects(layout, outCompacted, outHidden, outCount, outContentSize);
    }
    if (objc_getAssociatedObject(layout, FQXShelfCompactLayoutKindKey)) {
        return FQXComputeShelfCompactedRects(layout, outCompacted, outHidden, outCount, outContentSize);
    }
    return NO;
}

static NSArray<UICollectionViewLayoutAttributes *> *FQXCompactAttrsInRectWithOrig(UICollectionViewLayout *layout,
                                                                                   SEL cmd,
                                                                                   CGRect rect,
                                                                                   IMP orig) {
    if (!orig) return nil;
    if (gFQXDramaCompactComputing || !FQXIsLayoutCompactionTagged(layout)) {
        return ((NSArray<UICollectionViewLayoutAttributes *> *(*)(id, SEL, CGRect))orig)(layout, cmd, rect);
    }
    gFQXDramaCompactComputing = YES;
    NSArray<UICollectionViewLayoutAttributes *> *origAttrs =
        ((NSArray<UICollectionViewLayoutAttributes *> *(*)(id, SEL, CGRect))orig)(layout, cmd, rect);
    gFQXDramaCompactComputing = NO;
    CGRect compacted[24];
    BOOL hidden[24];
    NSInteger count = 0;
    CGSize newSize = CGSizeZero;
    if (!FQXComputeAnyCompactedRects(layout, compacted, hidden, &count, &newSize)) {
        return origAttrs;
    }
    NSMutableArray<UICollectionViewLayoutAttributes *> *result =
        [NSMutableArray arrayWithCapacity:(origAttrs.count + (NSUInteger)count)];
    BOOL seen[24] = {0};
    for (UICollectionViewLayoutAttributes *attr in origAttrs) {
        if (attr.representedElementCategory == UICollectionElementCategoryCell &&
            attr.indexPath.section == 0 &&
            attr.indexPath.item >= 0 && attr.indexPath.item < count) {
            NSInteger idx = attr.indexPath.item;
            seen[idx] = YES;
            UICollectionViewLayoutAttributes *copy = [attr copy];
            copy.frame = compacted[idx];
            if (hidden[idx]) {
                copy.alpha = 0.0;
                copy.hidden = YES;
            }
            [result addObject:copy];
        } else {
            [result addObject:attr];
        }
    }
    IMP itemImp = FQXLookupDramaCompactOrig(gFQXDramaCompactOrigItem, object_getClass(layout));
    if (itemImp) {
        gFQXDramaCompactComputing = YES;
        for (NSInteger i = 0; i < count; ++i) {
            if (seen[i] || hidden[i]) continue;
            if (!CGRectIntersectsRect(compacted[i], rect)) continue;
            NSIndexPath *ip = [NSIndexPath indexPathForItem:i inSection:0];
            UICollectionViewLayoutAttributes *rawAttr =
                ((UICollectionViewLayoutAttributes *(*)(id, SEL, id))itemImp)(layout, @selector(layoutAttributesForItemAtIndexPath:), ip);
            if (rawAttr) {
                UICollectionViewLayoutAttributes *copy = [rawAttr copy];
                copy.frame = compacted[i];
                [result addObject:copy];
            }
        }
        gFQXDramaCompactComputing = NO;
    }
    return result;
}

static UICollectionViewLayoutAttributes *FQXCompactAttrForItemWithOrig(UICollectionViewLayout *layout,
                                                                       SEL cmd,
                                                                       NSIndexPath *indexPath,
                                                                       IMP orig) {
    if (!orig) return nil;
    if (gFQXDramaCompactComputing ||
        !FQXIsLayoutCompactionTagged(layout) ||
        indexPath.section != 0 || indexPath.item < 0 || indexPath.item >= 24) {
        return ((UICollectionViewLayoutAttributes *(*)(id, SEL, id))orig)(layout, cmd, indexPath);
    }
    gFQXDramaCompactComputing = YES;
    UICollectionViewLayoutAttributes *origAttr =
        ((UICollectionViewLayoutAttributes *(*)(id, SEL, id))orig)(layout, cmd, indexPath);
    gFQXDramaCompactComputing = NO;
    if (!origAttr) return nil;
    CGRect compacted[24];
    BOOL hidden[24];
    NSInteger count = 0;
    CGSize newSize = CGSizeZero;
    if (!FQXComputeAnyCompactedRects(layout, compacted, hidden, &count, &newSize) ||
        indexPath.item >= count) {
        return origAttr;
    }
    UICollectionViewLayoutAttributes *copy = [origAttr copy];
    copy.frame = compacted[indexPath.item];
    if (hidden[indexPath.item]) {
        copy.alpha = 0.0;
        copy.hidden = YES;
    }
    return copy;
}

static CGSize FQXCompactContentSizeWithOrig(UICollectionViewLayout *layout, SEL cmd, IMP orig) {
    if (!orig) return CGSizeZero;
    if (gFQXDramaCompactComputing || !FQXIsLayoutCompactionTagged(layout)) {
        return ((CGSize (*)(id, SEL))orig)(layout, cmd);
    }
    gFQXDramaCompactComputing = YES;
    CGSize origSize = ((CGSize (*)(id, SEL))orig)(layout, cmd);
    gFQXDramaCompactComputing = NO;
    CGRect compacted[24];
    BOOL hidden[24];
    NSInteger count = 0;
    CGSize newSize = CGSizeZero;
    if (FQXComputeAnyCompactedRects(layout, compacted, hidden, &count, &newSize)) {
        return newSize;
    }
    return origSize;
}

static void FQXInstallCompactLayoutHooksOnClass(Class cls) {
    if (!cls) return;
    FQXInitDramaCompactOrigMaps();
    NSString *clsName = NSStringFromClass(cls);
    if (!clsName.length || gFQXDramaCompactOrigElems[clsName]) return;

    __block IMP origElems = NULL;
    IMP elemsHook = imp_implementationWithBlock(^NSArray<UICollectionViewLayoutAttributes *> *(UICollectionViewLayout *layout, CGRect rect) {
        return FQXCompactAttrsInRectWithOrig(layout, @selector(layoutAttributesForElementsInRect:), rect, origElems);
    });
    if (FQXInstallOwnedHook(cls, @selector(layoutAttributesForElementsInRect:), NO,
                            "@48@0:8{CGRect={CGPoint=dd}{CGSize=dd}}16",
                            elemsHook, &origElems) && origElems) {
        gFQXDramaCompactOrigElems[clsName] = [NSValue valueWithPointer:(const void *)origElems];
    } else {
        imp_removeBlock(elemsHook);
    }

    __block IMP origItem = NULL;
    IMP itemHook = imp_implementationWithBlock(^UICollectionViewLayoutAttributes *(UICollectionViewLayout *layout, NSIndexPath *indexPath) {
        return FQXCompactAttrForItemWithOrig(layout, @selector(layoutAttributesForItemAtIndexPath:), indexPath, origItem);
    });
    if (FQXInstallOwnedHook(cls, @selector(layoutAttributesForItemAtIndexPath:), NO,
                            "@24@0:8@16",
                            itemHook, &origItem) && origItem) {
        gFQXDramaCompactOrigItem[clsName] = [NSValue valueWithPointer:(const void *)origItem];
    } else {
        imp_removeBlock(itemHook);
    }

    __block IMP origSize = NULL;
    IMP sizeHook = imp_implementationWithBlock(^CGSize(UICollectionViewLayout *layout) {
        return FQXCompactContentSizeWithOrig(layout, @selector(collectionViewContentSize), origSize);
    });
    if (FQXInstallOwnedHook(cls, @selector(collectionViewContentSize), NO,
                            "{CGSize=dd}16@0:8",
                            sizeHook, &origSize) && origSize) {
        gFQXDramaCompactOrigSize[clsName] = [NSValue valueWithPointer:(const void *)origSize];
    } else {
        imp_removeBlock(sizeHook);
    }
}

static void FQXEnsureDramaCompactLayoutForCollectionView(UICollectionView *cv, UIView *header) {
    if (![cv isKindOfClass:UICollectionView.class]) return;
    UICollectionViewLayout *layout = cv.collectionViewLayout;
    if (!layout) return;
    FQXInstallCompactLayoutHooksOnClass(object_getClass(layout));

    UIView *resolvedHeader = header;
    id feedOwner = FQXObjGet(resolvedHeader, "delegate");
    if (!feedOwner) {
        for (UIView *cur = cv.superview; cur; cur = cur.superview) {
            UIView *cand = FQXDramaHeaderForTabs(cur);
            if (cand) {
                resolvedHeader = cand;
                feedOwner = FQXObjGet(resolvedHeader, "delegate");
                break;
            }
        }
    }

    static const char FQXK_FQXDramaCompactVisMaskKey = 0;
    #define FQXDramaCompactVisMaskKey ((const void *)&FQXK_FQXDramaCompactVisMaskKey)
    NSUInteger visMask = 0;
    if ([cv numberOfSections] > 0) {
        NSInteger cnt = MIN([cv numberOfItemsInSection:0], 24);
        visMask = ((NSUInteger)cnt << 24);
        NSArray<NSNumber *> *vis = FQXDramaVisibleTabIndicesForFeed(feedOwner);
        for (NSNumber *n in vis) {
            NSInteger idx = n.integerValue;
            if (idx >= 0 && idx < 24) visMask |= (1UL << (NSUInteger)idx);
        }
    }
    BOOL wasTagged = [objc_getAssociatedObject(layout, FQXDramaCompactLayoutActiveKey) boolValue];
    NSInteger curScale = FQXDramaHeaderButtonScalePercent();
    NSNumber *prevScale = objc_getAssociatedObject(layout, FQXDramaCompactAppliedScaleKey);
    NSNumber *prevMask = objc_getAssociatedObject(layout, FQXDramaCompactVisMaskKey);
    BOOL scaleChanged = (!prevScale || prevScale.integerValue != curScale);
    BOOL maskChanged = FQXShouldCommitDramaCompactVisMask(
        feedOwner != nil ? 1 : 0,
        prevMask ? (unsigned int)prevMask.unsignedIntegerValue : 0u,
        (unsigned int)visMask,
        prevMask != nil ? 1 : 0) != 0;
    if (!wasTagged || scaleChanged || maskChanged) {
        objc_setAssociatedObject(layout, FQXDramaCompactLayoutActiveKey, @YES, OBJC_ASSOCIATION_RETAIN_NONATOMIC);
        objc_setAssociatedObject(layout, FQXDramaCompactAppliedScaleKey, @(curScale), OBJC_ASSOCIATION_RETAIN_NONATOMIC);
        if (maskChanged) {
            objc_setAssociatedObject(layout, FQXDramaCompactVisMaskKey, @(visMask), OBJC_ASSOCIATION_RETAIN_NONATOMIC);
        }
        if (![objc_getAssociatedObject(layout, FQXDramaCompactRelayoutScheduledKey) boolValue]) {
            objc_setAssociatedObject(layout, FQXDramaCompactRelayoutScheduledKey, @YES, OBJC_ASSOCIATION_RETAIN_NONATOMIC);
            __weak UICollectionViewLayout *weakLayout = layout;
            __weak UICollectionView *weakCV = cv;
            __weak UIView *weakHeader = resolvedHeader;
            dispatch_async(dispatch_get_main_queue(), ^{
                UICollectionViewLayout *strongLayout = weakLayout;
                UICollectionView *strongCV = weakCV;
                UIView *strongHeader = weakHeader;
                if (strongLayout) {
                    objc_setAssociatedObject(strongLayout, FQXDramaCompactRelayoutScheduledKey, nil, OBJC_ASSOCIATION_RETAIN_NONATOMIC);
                    if (!gFQXDramaCompactComputing) [strongLayout invalidateLayout];
                }
                if (strongCV && strongCV.window && !gFQXDramaCompactComputing) [strongCV layoutIfNeeded];
                if (strongHeader && strongHeader.window) [strongHeader setNeedsLayout];
            });
        }
    }
}

static BOOL FQXDramaHeaderHostIsDark(UIView *header, UIView *tabs, NSString *__autoreleasing *outSource);
static UIView *FQXFindDramaListContainerForFeed(id feedVC);
static void FQXSelectDramaTabIndex(id feedVC, NSInteger targetIndex);

@interface FQXDramaTopCapsuleInteraction : NSObject <UIGestureRecognizerDelegate> {
@public
    __weak UIView *_tabsView;
    __weak UICollectionView *_collectionView;
    __weak UIVisualEffectView *_outerGlass;
    __weak UIView *_flatLens;
    FQXFlexGlassView *_pillGlass;
    UILongPressGestureRecognizer *_pressGesture;
    UILongPressGestureRecognizer *_dragGesture;
    UITapGestureRecognizer *_tapGesture;
    FQXTopCapsuleTouchMode _mode;
    NSInteger _lastSelectedIndex;
    BOOL _paging;
    NSInteger _hoverIndex;
    NSInteger _pendingTapIndex;
    CFTimeInterval _pendingTapExpiry;
    CFTimeInterval _lastSwipeTime;
    CGFloat _anchorX;
    NSString *_lastDarkSource;
}
- (void)placePillAtRestingAnimated:(BOOL)animated;
- (void)placePillAtIndex:(NSInteger)sel animated:(BOOL)animated;
- (CGRect)itemRectForIndex:(NSInteger)index;
- (CGFloat)anchorXForIndex:(NSInteger)index;
- (CGRect)pillRectForAnchorX:(CGFloat)anchorX;
- (void)updatePillForNativeSwipe;
- (void)settlePillAtIndex:(NSInteger)index;
@end

@implementation FQXDramaTopCapsuleInteraction

- (instancetype)init {
    self = [super init];
    if (self) {
        _lastSelectedIndex = NSNotFound;
        _hoverIndex = NSNotFound;
        _pendingTapIndex = NSNotFound;
    }
    return self;
}

- (BOOL)currentResolvedDarkState {
    UIView *header = FQXDramaHeaderForTabs(self->_tabsView);
    if (header) {
        NSString *src = nil;
        BOOL dark = FQXDramaHeaderHostIsDark(header, self->_tabsView, &src);
        self->_lastDarkSource = src;
        return dark;
    }
    UIVisualEffectView *outer = self->_outerGlass;
    self->_lastDarkSource = @"outer_trait";
    return (outer.overrideUserInterfaceStyle == UIUserInterfaceStyleDark) ||
           (outer.overrideUserInterfaceStyle == UIUserInterfaceStyleUnspecified &&
            outer.traitCollection.userInterfaceStyle == UIUserInterfaceStyleDark);
}

- (void)syncRestingPillCorners {
    if (!self->_pillGlass) return;
    CGRect pb = self->_pillGlass.contentView.bounds;
    CGFloat radius = MIN(CGRectGetWidth(pb), CGRectGetHeight(pb)) * 0.5;
    if (radius > 0.5) {
        self->_pillGlass.contentView.layer.cornerCurve = kCACornerCurveContinuous;
        if (fabs(self->_pillGlass.contentView.layer.cornerRadius - radius) > 0.25) {
            self->_pillGlass.contentView.layer.cornerRadius = radius;
        }
        if (!self->_pillGlass.contentView.clipsToBounds) {
            self->_pillGlass.contentView.clipsToBounds = YES;
        }
    }
}

- (void)applyMaterialToOuter:(UIVisualEffectView *)outer isDark:(BOOL)isDark {
    if (!outer || !self->_pillGlass) return;
    NSInteger surfMode = FQXDramaButtonSurfaceStyleMode();
    BOOL videoBase = (surfMode == FQXDramaButtonSurfaceVideoBase);
    BOOL roseMistGlass = (surfMode == FQXDramaButtonSurfaceRoseMistGlass);
    BOOL lightBase = videoBase || roseMistGlass;
    NSInteger effSel = FQXEffectiveDramaSelectionTintStyle();
    BOOL softRoseSel = (effSel == FQXSelectionTintStyleSoftRoseMist);
    BOOL glassRoseSel = (effSel == FQXSelectionTintStyleRoseMistGlass);
    BOOL darkTint = FQXGlassDarkTintEnabled();
    BOOL blurDark = darkTint ? isDark : FQXAppIsInNightMode();
    if (videoBase) {
        FQXClearDockBackdropBlur(outer);
    } else {
        FQXApplyBackdropBlur(outer, outer.contentView, nil, outer.bounds, -1, blurDark, DramaHeaderBlurPrefKey);
    }
    BOOL reduce = UIAccessibilityIsReduceTransparencyEnabled();
    UIUserInterfaceStyle uiStyle = lightBase ? UIUserInterfaceStyleLight : (isDark ? UIUserInterfaceStyleDark : UIUserInterfaceStyleLight);
    if (outer.overrideUserInterfaceStyle != uiStyle) {
        outer.overrideUserInterfaceStyle = uiStyle;
    }
    if (self->_pillGlass.overrideUserInterfaceStyle != uiStyle) {
        self->_pillGlass.overrideUserInterfaceStyle = uiStyle;
    }
    if (outer.backgroundColor && ![outer.backgroundColor isEqual:UIColor.clearColor]) {
        outer.backgroundColor = UIColor.clearColor;
    }
    if (!videoBase && outer.contentView.backgroundColor && ![outer.contentView.backgroundColor isEqual:UIColor.clearColor]) {
        outer.contentView.backgroundColor = UIColor.clearColor;
    }

    BOOL pillInteractiveLens = glassRoseSel || (!softRoseSel && (darkTint || reduce || self->_paging || (self->_mode != FQXTopCapsuleTouchIdle)));
    NSInteger scalePct = FQXDramaHeaderButtonScalePercent();
    NSInteger stamp = (isDark ? 2 : 1) | (reduce ? 4 : 0) | (darkTint ? 8 : 0) |
                      (pillInteractiveLens ? 16 : 0) | ((surfMode & 3) << 13) |
                      ((effSel & 3) << 15) | (scalePct << 5);
    NSNumber *applied = objc_getAssociatedObject(outer, FQXDramaTopGlassStampKey);
    BOOL outerLost = videoBase
        ? (outer.effect != nil)
        : (!outer.effect || [outer.effect isKindOfClass:UIBlurEffect.class]);
    BOOL pillLost = glassRoseSel && (!self->_pillGlass.effect || [self->_pillGlass.effect isKindOfClass:UIBlurEffect.class]);
    if (applied && applied.integerValue == stamp && !outerLost && !pillLost) {
        FQXSyncPlatterSurfaceBacking(outer, surfMode);
        FQXSyncVideoSelectedPillOverlayInView(self->_pillGlass, effSel);
        if (!pillInteractiveLens) [self syncRestingPillCorners];
        FQXApplyDramaTabVideoInk(self->_tabsView);
        return;
    }
    objc_setAssociatedObject(outer, FQXDramaTopGlassStampKey, @(stamp), OBJC_ASSOCIATION_RETAIN_NONATOMIC);

    NSInteger glassStyle = reduce ? 0 : 1;
    UIColor *outerTint = roseMistGlass
        ? FQXRoseMistGlassBaseTintUIColor()
        : ((!reduce && darkTint && isDark) ? [UIColor colorWithWhite:0.0 alpha:0.30] : nil);
    UIVisualEffect *outerEffect = videoBase ? nil : FQXMakeGlassEffect(glassStyle, NO, outerTint);
    UIVisualEffect *pillEffect = nil;
    UIColor *pillContentFill = UIColor.clearColor;
    if (softRoseSel) {
        pillEffect = nil;
        pillContentFill = UIColor.clearColor;
    } else if (glassRoseSel) {
        // Real interactive iOS 26 Liquid Glass lens underneath our translucent 5-stop rose-mist gradient.
        pillEffect = FQXMakeGlassEffect(glassStyle, YES, nil);
        pillContentFill = UIColor.clearColor;
    } else if (pillInteractiveLens) {
        UIColor *pillTint = nil;
        if (darkTint) {
            pillTint = [UIColor colorWithWhite:0.0 alpha:(isDark ? 0.45 : 0.10)];
        } else if (reduce) {
            pillTint = [UIColor colorWithWhite:(isDark ? 1.0 : 0.0) alpha:0.12];
        }
        pillEffect = FQXMakeGlassEffect(glassStyle, YES, pillTint);
    } else if (videoBase) {
        pillContentFill = [UIColor colorWithWhite:0.0 alpha:0.085];
    } else {
        pillContentFill = isDark
            ? [UIColor colorWithWhite:1.0 alpha:0.16]
            : [UIColor colorWithWhite:0.0 alpha:0.08];
    }

    void (^changes)(void) = ^{
        outer.overrideUserInterfaceStyle = uiStyle;
        outer.effect = outerEffect;
        FQXSyncPlatterSurfaceBacking(outer, surfMode);
        self->_pillGlass.overrideUserInterfaceStyle = uiStyle;
        self->_pillGlass.effect = pillEffect;
        self->_pillGlass.backgroundColor = UIColor.clearColor;
        self->_pillGlass.contentView.backgroundColor = pillContentFill;
        FQXSyncVideoSelectedPillOverlayInView(self->_pillGlass, effSel);
        if (!pillInteractiveLens) {
            [self syncRestingPillCorners];
        }
        FQXApplyDramaTabVideoInk(self->_tabsView);
    };
    if (applied && !pillInteractiveLens && !self->_paging && self->_mode == FQXTopCapsuleTouchIdle) {
        [UIView animateWithDuration:0.12
                              delay:0.0
                            options:UIViewAnimationOptionBeginFromCurrentState | UIViewAnimationOptionAllowUserInteraction
                         animations:changes
                         completion:nil];
    } else {
        [UIView performWithoutAnimation:changes];
    }
    NSInteger blurStrength = FQXBlurPercent([NSUserDefaults.standardUserDefaults doubleForKey:DramaHeaderBlurPrefKey]);
    UICollectionViewLayout *cvLayout = self->_collectionView.collectionViewLayout;
    NSNumber *hiddenCnt = cvLayout ? objc_getAssociatedObject(cvLayout, FQXDramaCompactHiddenCountKey) : nil;
    NSNumber *removedGap = cvLayout ? objc_getAssociatedObject(cvLayout, FQXDramaCompactRemovedGapKey) : nil;
    NSNumber *centerDeltaX = objc_getAssociatedObject(outer, FQXDramaOuterCenterDeltaXKey);
    FQXDiagRecordEvent(FQXDiagCategoryUI, @"drama_top_glass_material", @{
        @"isDark": @(isDark),
        @"darkSource": self->_lastDarkSource ?: @"unknown",
        @"darkTint": @(darkTint),
        @"overrideStyle": @((NSInteger)uiStyle),
        @"outerHasTint": @(outerTint != nil),
        @"outerEffectClass": outerEffect ? (NSStringFromClass(outerEffect.class) ?: @"") : @"nil",
        @"pillEffectClass": pillEffect ? (NSStringFromClass(pillEffect.class) ?: @"") : @"nil",
        @"pillInteractiveLens": @(pillInteractiveLens),
        @"pillHidden": @(self->_pillGlass.hidden),
        @"pillFrame": FQXDockRectArray(self->_pillGlass.frame),
        @"outerWidth": @(round(CGRectGetWidth(outer.bounds) * 10.0) / 10.0),
        @"outerHeight": @(round(CGRectGetHeight(outer.bounds) * 10.0) / 10.0),
        @"buttonScalePercent": @(scalePct),
        @"outerCenterDeltaX": centerDeltaX ?: @0,
        @"selectedIndex": @(self->_lastSelectedIndex == NSNotFound ? -1 : self->_lastSelectedIndex),
        @"hiddenItemCount": hiddenCnt ?: @0,
        @"compactedRemovedGapPt": removedGap ?: @0,
        @"visibleGlassLayers": @(pillEffect ? 2 : 1),
        @"blurStrength": @(blurStrength),
        @"reduceTransparency": @(reduce),
    }, NO);
}

- (NSArray<NSValue *> *)visibleItemRectsInCollection:(NSMutableArray<NSNumber *> *)outIndices {
    UICollectionView *cv = self->_collectionView;
    if (!cv) return @[];
    NSInteger count = [cv numberOfItemsInSection:0];
    if (count <= 0 || count > 24) return @[];
    NSMutableArray<NSValue *> *rects = [NSMutableArray arrayWithCapacity:(NSUInteger)count];
    for (NSInteger i = 0; i < count; ++i) {
        NSIndexPath *ip = [NSIndexPath indexPathForItem:i inSection:0];
        UICollectionViewLayoutAttributes *attr = [cv layoutAttributesForItemAtIndexPath:ip];
        CGRect f = attr ? attr.frame : CGRectZero;
        if (CGRectGetWidth(f) < 6.0 || CGRectGetHeight(f) < 6.0) continue;
        [rects addObject:[NSValue valueWithCGRect:f]];
        if (outIndices) [outIndices addObject:@(i)];
    }
    return rects;
}

- (NSInteger)currentHostSelectedIndex {
    UIView *tabs = self->_tabsView;
    UICollectionView *cv = self->_collectionView;
    if (!tabs || !cv) return NSNotFound;
    NSInteger count = ([cv numberOfSections] > 0) ? [cv numberOfItemsInSection:0] : 0;
    if (count <= 0) return NSNotFound;

    // 1. Authoritative rendered cell-model state (matches the bright selected title label immediately,
    // unlike owner.curTabIndex which lags behind during tab taps and programmatic switches).
    NSArray *ds = FQXObjGet(tabs, "dataSource");
    if ([ds isKindOfClass:NSArray.class]) {
        for (NSUInteger i = 0; i < ds.count && i < (NSUInteger)count && i < 24; ++i) {
            if (FQXBoolGet(ds[i], "isSelected", NO)) {
                UICollectionViewLayoutAttributes *a =
                    [cv layoutAttributesForItemAtIndexPath:[NSIndexPath indexPathForItem:(NSInteger)i inSection:0]];
                if (!a || CGRectGetWidth(a.frame) >= 6.0) return (NSInteger)i;
            }
        }
    }

    // 2. Synchronous JXCategoryBaseView.selectedIndex
    NSInteger tabSel = FQXIntGet(tabs, "selectedIndex", -1);
    if (tabSel >= 0 && tabSel < count) {
        UICollectionViewLayoutAttributes *a =
            [cv layoutAttributesForItemAtIndexPath:[NSIndexPath indexPathForItem:tabSel inSection:0]];
        if (!a || CGRectGetWidth(a.frame) >= 6.0) return tabSel;
    }

    // 3. Fallback to owner.curTabIndex
    id owner = FQXObjGet(tabs, "delegate");
    SEL indexSelector = sel_registerName("curTabIndex");
    Method indexMethod = class_getInstanceMethod(object_getClass(owner), indexSelector);
    if (indexMethod && strcmp(method_getTypeEncoding(indexMethod), "q16@0:8") == 0) {
        NSInteger index = ((NSInteger (*)(id, SEL))objc_msgSend)(owner, indexSelector);
        if (index >= 0 && index < count) {
            UICollectionViewLayoutAttributes *a =
                [cv layoutAttributesForItemAtIndexPath:[NSIndexPath indexPathForItem:index inSection:0]];
            if (!a || CGRectGetWidth(a.frame) >= 6.0) return index;
        }
    }
    return NSNotFound;
}

- (NSInteger)itemIndexAtCollectionX:(CGFloat)x {
    NSMutableArray<NSNumber *> *indices = [NSMutableArray array];
    NSArray<NSValue *> *rects = [self visibleItemRectsInCollection:indices];
    NSInteger nearest = NSNotFound;
    CGFloat best = CGFLOAT_MAX;
    for (NSUInteger i = 0; i < rects.count; ++i) {
        CGRect f = rects[i].CGRectValue;
        if (x >= CGRectGetMinX(f) && x <= CGRectGetMaxX(f)) return indices[i].integerValue;
        CGFloat d = fabs(x - CGRectGetMidX(f));
        if (d < best) {
            best = d;
            nearest = indices[i].integerValue;
        }
    }
    return nearest;
}

- (CGRect)pillRectForAnchorX:(CGFloat)anchorX {
    UICollectionView *cv = self->_collectionView;
    UIVisualEffectView *outer = self->_outerGlass;
    if (!cv || !outer) return CGRectZero;
    NSArray<NSValue *> *rects = [self visibleItemRectsInCollection:nil];
    if (!rects.count) return CGRectZero;
    CGFloat pillW = CGRectGetWidth(rects.firstObject.CGRectValue);
    CGRect prevRect = CGRectZero;
    BOOL hasPrev = NO;
    for (NSValue *val in rects) {
        CGRect r = val.CGRectValue;
        CGFloat mid = CGRectGetMidX(r);
        if (anchorX <= mid) {
            if (!hasPrev) {
                pillW = CGRectGetWidth(r);
            } else {
                CGFloat from = CGRectGetMidX(prevRect);
                CGFloat progress = mid > from ? (anchorX - from) / (mid - from) : 1.0;
                pillW = CGRectGetWidth(prevRect) + (CGRectGetWidth(r) - CGRectGetWidth(prevRect)) * progress;
            }
            hasPrev = NO;
            break;
        }
        prevRect = r;
        hasPrev = YES;
    }
    if (hasPrev) pillW = CGRectGetWidth(prevRect);
    CGFloat scale = (CGFloat)FQXDramaHeaderButtonScalePercent() / 100.0;
    pillW += FQXDramaCapsulePillExtraWidth(scale);

    CGPoint inOuter = [cv convertPoint:CGPointMake(anchorX, CGRectGetMidY(cv.bounds)) toView:outer.contentView];
    CGRect ob = outer.contentView.bounds;
    CGFloat insetY = FQXDramaCapsulePillInsetY(scale);
    CGFloat pillH = MAX(18.0, CGRectGetHeight(ob) - insetY * 2.0);
    CGFloat minX = insetY;
    CGFloat maxX = MAX(minX, CGRectGetWidth(ob) - pillW - insetY);
    CGFloat x = MIN(maxX, MAX(minX, inOuter.x - pillW * 0.5));
    return CGRectMake(x, (CGRectGetHeight(ob) - pillH) * 0.5, MIN(pillW, CGRectGetWidth(ob) - insetY * 2.0), pillH);
}

- (void)placePill:(CGRect)target animated:(BOOL)animated {
    if (!self->_pillGlass) return;
    if (CGRectGetWidth(target) < 12.0 || CGRectGetHeight(target) < 12.0) {
        if (!self->_pillGlass.hidden) self->_pillGlass.hidden = YES;
        return;
    }
    if (self->_pillGlass.hidden) self->_pillGlass.hidden = NO;
    if (fabs(CGRectGetMinX(self->_pillGlass.frame) - CGRectGetMinX(target)) < 0.25 &&
        fabs(CGRectGetMinY(self->_pillGlass.frame) - CGRectGetMinY(target)) < 0.25 &&
        fabs(CGRectGetWidth(self->_pillGlass.frame) - CGRectGetWidth(target)) < 0.25 &&
        fabs(CGRectGetHeight(self->_pillGlass.frame) - CGRectGetHeight(target)) < 0.25) {
        return;
    }
    if (animated && !UIAccessibilityIsReduceMotionEnabled()) {
        [UIView animateWithDuration:0.22
                              delay:0.0
             usingSpringWithDamping:1.0
              initialSpringVelocity:0.0
                            options:UIViewAnimationOptionBeginFromCurrentState |
                                    UIViewAnimationOptionAllowUserInteraction |
                                    UIViewAnimationOptionCurveEaseOut
                         animations:^{
            self->_pillGlass.frame = target;
            if (!self->_pillGlass.effect) [self syncRestingPillCorners];
        } completion:nil];
    } else {
        [UIView performWithoutAnimation:^{
            self->_pillGlass.frame = target;
            if (!self->_pillGlass.effect) [self syncRestingPillCorners];
        }];
    }
}

- (CGRect)itemRectForIndex:(NSInteger)index {
    UICollectionView *cv = self->_collectionView;
    if (index == NSNotFound || index < 0 || !cv || [cv numberOfSections] <= 0 || index >= [cv numberOfItemsInSection:0]) {
        return CGRectZero;
    }
    NSIndexPath *ip = [NSIndexPath indexPathForItem:index inSection:0];
    UICollectionViewLayoutAttributes *attr = [cv layoutAttributesForItemAtIndexPath:ip];
    if (attr) return CGRectGetWidth(attr.frame) >= 6.0 ? attr.frame : CGRectZero;
    UICollectionViewCell *cell = [cv cellForItemAtIndexPath:ip];
    return cell && !cell.hidden && CGRectGetWidth(cell.frame) >= 6.0 ? cell.frame : CGRectZero;
}

- (CGFloat)anchorXForIndex:(NSInteger)index {
    CGRect itemRect = [self itemRectForIndex:index];
    if (CGRectGetWidth(itemRect) < 6.0) return 0.0;
    UICollectionView *cv = self->_collectionView;
    int hasLabel = 0;
    double labelMidX = 0.0;
    if (cv && index >= 0 && [cv numberOfSections] > 0 && index < [cv numberOfItemsInSection:0]) {
        UICollectionViewCell *cell = [cv cellForItemAtIndexPath:[NSIndexPath indexPathForItem:index inSection:0]];
        if (cell && !cell.hidden && cell.alpha > 0.05 && CGRectEqualToRect(cell.frame, itemRect)) {
            UILabel *lbl = FQXObjGet(cell, "titleLabel");
            if ([lbl isKindOfClass:UILabel.class] && lbl.superview && CGRectGetWidth(lbl.bounds) >= 6.0) {
                CGPoint p = [lbl.superview convertPoint:lbl.center toView:cv];
                if (isfinite(p.x)) {
                    hasLabel = 1;
                    labelMidX = p.x;
                }
            }
        }
    }
    return (CGFloat)FQXResolveDramaItemAnchorX(CGRectGetMinX(itemRect), CGRectGetWidth(itemRect), hasLabel, labelMidX);
}

- (void)updatePillForNativeSwipe {
    if (!self->_pillGlass || !self->_outerGlass || !self->_collectionView) return;
    if (self->_mode != FQXTopCapsuleTouchIdle) return;

    NSInteger count = ([self->_collectionView numberOfSections] > 0) ? [self->_collectionView numberOfItemsInSection:0] : 0;
    if (count < 2) return;
    UIScrollView *pagerSV = FQXObjGet(FQXObjGet(self->_tabsView, "listContainer"), "scrollView") ?:
        FQXObjGet(self->_tabsView, "contentScrollView");
    // Host selection can emit scroll callbacks for a programmatic jump over hidden tabs.
    if (![pagerSV isKindOfClass:UIScrollView.class] || !pagerSV.scrollEnabled ||
        !(pagerSV.isDragging || pagerSV.isDecelerating || self->_paging)) return;
    CGFloat pageW = CGRectGetWidth(pagerSV.bounds);
    if (pageW <= 100.0) return;
    CGFloat continuous = MAX(0.0, MIN((CGFloat)(count - 1), pagerSV.contentOffset.x / pageW));
    NSInteger leftIndex = MIN((NSInteger)floor(continuous), count - 2);
    NSInteger rightIndex = leftIndex + 1;
    CGFloat ratio = continuous - (CGFloat)leftIndex;
    CGRect leftRect = [self itemRectForIndex:leftIndex];
    CGRect rightRect = [self itemRectForIndex:rightIndex];
    if (CGRectGetWidth(leftRect) < 6.0 || CGRectGetWidth(rightRect) < 6.0) return;
    if (ratio <= 0.012 || ratio >= 0.988) {
        if (self->_paging) [self settlePillAtIndex:(ratio >= 0.988 ? rightIndex : leftIndex)];
        return;
    }

    BOOL wasPaging = self->_paging;
    self->_paging = YES;
    self->_lastSwipeTime = CACurrentMediaTime();
    self->_pendingTapIndex = NSNotFound;
    self->_pendingTapExpiry = 0.0;

    CGFloat lx = [self anchorXForIndex:leftIndex];
    CGFloat rx = [self anchorXForIndex:rightIndex];
    CGFloat anchorX = lx + (rx - lx) * ratio;
    self->_anchorX = anchorX;
    [self->_pillGlass.layer removeAllAnimations];
    [self placePill:[self pillRectForAnchorX:anchorX] animated:NO];
    if (!wasPaging) {
        [self applyMaterialToOuter:self->_outerGlass isDark:[self currentResolvedDarkState]];
    }
}

- (void)settlePillAtIndex:(NSInteger)index {
    BOOL wasPaging = self->_paging;
    self->_paging = NO;
    self->_lastSwipeTime = 0.0;
    if (CGRectGetWidth([self itemRectForIndex:index]) < 6.0) index = [self currentHostSelectedIndex];
    BOOL changed = self->_lastSelectedIndex != NSNotFound && self->_lastSelectedIndex != index;
    self->_lastSelectedIndex = index;
    // Preserve the committed position while the title models catch up.
    self->_pendingTapIndex = index;
    self->_pendingTapExpiry = index == NSNotFound ? 0.0 : CACurrentMediaTime() + 0.35;
    if (wasPaging) [self->_pillGlass.layer removeAllAnimations];
    [self placePillAtIndex:index animated:changed && !wasPaging];
    if (wasPaging) [self applyMaterialToOuter:self->_outerGlass isDark:[self currentResolvedDarkState]];
}

- (void)placePillAtIndex:(NSInteger)sel animated:(BOOL)animated {
    if (self->_paging) {
        // Keep the live interpolated swipe position untouched until paging finishes.
        return;
    }
    CGRect itemRect = [self itemRectForIndex:sel];
    if (CGRectGetWidth(itemRect) >= 6.0) {
        self->_anchorX = [self anchorXForIndex:sel];
        [self placePill:[self pillRectForAnchorX:self->_anchorX] animated:animated];
        return;
    }
    [self placePill:CGRectZero animated:NO];
}

- (void)placePillAtRestingAnimated:(BOOL)animated {
    [self placePillAtIndex:[self currentHostSelectedIndex] animated:animated];
}

- (BOOL)gestureRecognizer:(UIGestureRecognizer *)gr shouldRecognizeSimultaneouslyWithGestureRecognizer:(UIGestureRecognizer *)other {
    (void)gr; (void)other;
    return YES;
}

- (BOOL)gestureRecognizerShouldBegin:(UIGestureRecognizer *)gr {
    if (gr != self->_dragGesture) return YES;
    UICollectionView *cv = self->_collectionView;
    if (!cv || cv.isDragging) return NO;
    CGFloat x = [gr locationInView:cv].x;
    NSInteger idx = [self itemIndexAtCollectionX:x];
    NSInteger sel = [self currentHostSelectedIndex];
    return idx != NSNotFound && idx == sel;
}

- (void)handlePress:(UILongPressGestureRecognizer *)gr {
    UICollectionView *cv = self->_collectionView;
    if (!cv) return;
    if (gr.state == UIGestureRecognizerStateBegan) {
        CGFloat x = [gr locationInView:cv].x;
        NSInteger idx = [self itemIndexAtCollectionX:x];
        if (idx == NSNotFound) return;
        CGRect itemRect = [self itemRectForIndex:idx];
        if (CGRectGetWidth(itemRect) < 6.0) return;
        self->_paging = NO;
        self->_lastSwipeTime = 0.0;
        self->_mode = FQXTopCapsuleTouchPressing;
        [self applyMaterialToOuter:self->_outerGlass isDark:[self currentResolvedDarkState]];
    } else if (gr.state == UIGestureRecognizerStateEnded ||
               gr.state == UIGestureRecognizerStateCancelled ||
               gr.state == UIGestureRecognizerStateFailed) {
        if (self->_mode != FQXTopCapsuleTouchPressing) return;
        self->_mode = FQXTopCapsuleTouchIdle;
        [self applyMaterialToOuter:self->_outerGlass isDark:[self currentResolvedDarkState]];
        [self placePillAtRestingAnimated:YES];
    }
}

- (void)handleTap:(UITapGestureRecognizer *)gr {
    UICollectionView *cv = self->_collectionView;
    UIView *tabs = self->_tabsView;
    UIVisualEffectView *outer = self->_outerGlass;
    if (gr.state != UIGestureRecognizerStateEnded || !cv.window || cv.isDragging ||
        !outer || outer.hidden || !CGRectContainsPoint(outer.bounds, [gr locationInView:outer])) return;

    NSInteger index = [self itemIndexAtCollectionX:[gr locationInView:cv].x];
    id feed = FQXObjGet(FQXDramaHeaderForTabs(tabs), "delegate");
    NSArray *models = FQXObjGet(feed, "tabModels");
    if (![models isKindOfClass:NSArray.class] || index < 0 || index >= (NSInteger)models.count ||
        !FQXDramaCategoryModelVisible(models[index])) return;
    id targetModel = models[index];

    // UIKit may miss a cell after its layout has been compacted. Give its normal selection
    // the first chance to finish, then send the same native click for the visible target.
    __weak typeof(self) weakSelf = self;
    __weak id weakFeed = feed;
    dispatch_async(dispatch_get_main_queue(), ^{
        typeof(self) interaction = weakSelf;
        id owner = weakFeed;
        if (!interaction || !owner || !cv.window || interaction->_collectionView != cv ||
            interaction->_mode != FQXTopCapsuleTouchIdle || !FQXDramaCategoryMasterEnabled() ||
            FQXObjGet(owner, "simpleTabView") != tabs) return;
        NSArray *currentModels = FQXObjGet(owner, "tabModels");
        if (![currentModels isKindOfClass:NSArray.class] || index >= (NSInteger)currentModels.count ||
            currentModels[index] != targetModel || !FQXDramaCategoryModelVisible(targetModel)) return;

        UIView *container = FQXFindDramaListContainerForFeed(owner);
        if (FQXIntGet(owner, "curTabIndex", -1) == index ||
            FQXIntGet(container, "currentIndex", -1) == index ||
            [interaction currentHostSelectedIndex] == index) return;
        FQXSelectDramaTabIndex(owner, index);
    });
}

- (void)updateDragAtGesture:(UILongPressGestureRecognizer *)gr animated:(BOOL)animated {
    UICollectionView *cv = self->_collectionView;
    if (!cv) return;
    NSArray<NSValue *> *rects = [self visibleItemRectsInCollection:nil];
    if (!rects.count) return;
    CGFloat minAnchor = CGRectGetMidX(rects.firstObject.CGRectValue);
    CGFloat maxAnchor = CGRectGetMidX(rects.lastObject.CGRectValue);
    CGFloat x = [gr locationInView:cv].x;
    self->_anchorX = MIN(maxAnchor, MAX(minAnchor, x));
    NSInteger idx = [self itemIndexAtCollectionX:self->_anchorX];
    if (idx != NSNotFound && idx != self->_hoverIndex) {
        self->_hoverIndex = idx;
        UISelectionFeedbackGenerator *gen = [[UISelectionFeedbackGenerator alloc] init];
        [gen selectionChanged];
    }
    [self placePill:[self pillRectForAnchorX:self->_anchorX] animated:animated];
}

- (void)handleDrag:(UILongPressGestureRecognizer *)gr {
    UICollectionView *cv = self->_collectionView;
    UIView *tabs = self->_tabsView;
    if (!cv || !tabs) return;
    if (gr.state == UIGestureRecognizerStateBegan) {
        self->_mode = FQXTopCapsuleTouchDragging;
        [self applyMaterialToOuter:self->_outerGlass isDark:[self currentResolvedDarkState]];
        self->_hoverIndex = [self currentHostSelectedIndex];
        cv.panGestureRecognizer.enabled = NO;
        UIImpactFeedbackGenerator *impact = [[UIImpactFeedbackGenerator alloc] initWithStyle:UIImpactFeedbackStyleLight];
        [impact impactOccurred];
        [self updateDragAtGesture:gr animated:YES];
    } else if (gr.state == UIGestureRecognizerStateChanged) {
        [self updateDragAtGesture:gr animated:NO];
    } else if (self->_mode == FQXTopCapsuleTouchDragging) {
        self->_mode = FQXTopCapsuleTouchIdle;
        [self applyMaterialToOuter:self->_outerGlass isDark:[self currentResolvedDarkState]];
        cv.panGestureRecognizer.enabled = YES;
        NSInteger target = self->_hoverIndex;
        self->_hoverIndex = NSNotFound;
        NSInteger cur = [self currentHostSelectedIndex];
        if (gr.state == UIGestureRecognizerStateEnded && target != NSNotFound && target != cur) {
            NSIndexPath *ip = [NSIndexPath indexPathForItem:target inSection:0];
            SEL sel = @selector(collectionView:didSelectItemAtIndexPath:);
            if ([tabs respondsToSelector:sel]) {
                ((void (*)(id, SEL, id, id))objc_msgSend)(tabs, sel, cv, ip);
            }
            self->_lastSelectedIndex = target;
            [self placePillAtRestingAnimated:YES];
        } else {
            [self placePillAtRestingAnimated:YES];
        }
    }
}

- (void)releaseSelectionOwnership {
    UIVisualEffectView *outer = self->_outerGlass;
    if (outer && self->_pillGlass &&
        objc_getAssociatedObject(outer, FQXDramaHeaderSelectionOwnerKey()) == self->_pillGlass) {
        objc_setAssociatedObject(outer, FQXDramaHeaderSelectionOwnerKey(), nil, OBJC_ASSOCIATION_RETAIN_NONATOMIC);
        // hidden still describes whether the host has one valid selected item.
        // Restore only the alpha owned by this replacement, not its geometry.
        if (self->_flatLens.superview == outer.contentView && self->_flatLens.alpha == 0.0) {
            [UIView performWithoutAnimation:^{ self->_flatLens.alpha = 1.0; }];
        }
    }
    if (outer) {
        objc_setAssociatedObject(outer, FQXDramaTopGlassStampKey, nil, OBJC_ASSOCIATION_RETAIN_NONATOMIC);
    }
    self->_flatLens = nil;
    self->_outerGlass = nil;
}

- (void)invalidate {
    if (self->_pressGesture.view) [self->_pressGesture.view removeGestureRecognizer:self->_pressGesture];
    if (self->_dragGesture.view) [self->_dragGesture.view removeGestureRecognizer:self->_dragGesture];
    if (self->_tapGesture.view) [self->_tapGesture.view removeGestureRecognizer:self->_tapGesture];
    [self releaseSelectionOwnership];
    [self->_pillGlass removeFromSuperview];
    self->_pillGlass = nil;
    if (self->_mode == FQXTopCapsuleTouchDragging && self->_collectionView) {
        self->_collectionView.panGestureRecognizer.enabled = YES;
    }
    self->_mode = FQXTopCapsuleTouchIdle;
    self->_paging = NO;
    self->_lastSelectedIndex = NSNotFound;
    self->_hoverIndex = NSNotFound;
    self->_pendingTapIndex = NSNotFound;
    self->_pendingTapExpiry = 0.0;
    self->_lastSwipeTime = 0.0;
}

- (void)syncWithTabs:(UIView *)tabs {
    if (!tabs || !FQXGlassEnabled()) {
        [self invalidate];
        return;
    }
    UIView *categories = tabs.superview;
    UICollectionView *cv = FQXObjGet(tabs, "collectionView");
    if (!categories || ![cv isKindOfClass:UICollectionView.class]) {
        [self invalidate];
        return;
    }
    UIVisualEffectView *outer = objc_getAssociatedObject(categories, FQXDramaHeaderSurfaceKey());
    if (![outer isKindOfClass:UIVisualEffectView.class] || outer.superview != categories ||
        outer.hidden || CGRectGetWidth(outer.bounds) < 30.0 || CGRectGetHeight(outer.bounds) > 60.0) {
        [self invalidate];
        return;
    }

    UIView *flat = objc_getAssociatedObject(outer, FQXDramaHeaderFallbackSelectionKey());
    if (![flat isKindOfClass:UIView.class] || flat.superview != outer.contentView) flat = nil;
    if (self->_outerGlass != outer || (self->_collectionView && self->_collectionView != cv)) {
        [self invalidate];
    }

    self->_tabsView = tabs;
    self->_collectionView = cv;
    self->_outerGlass = outer;
    self->_flatLens = flat;

    if (!self->_pillGlass) {
        FQXFlexGlassView *pill = [[FQXFlexGlassView alloc] initWithEffect:nil];
        pill.flexSourceView = cv;
        pill.userInteractionEnabled = NO;
        pill.accessibilityElementsHidden = YES;
        FQXApplyCornerConfiguration(pill, 0.0, NO);
        objc_setAssociatedObject(pill, FQXOwnedGlassElementKey, @YES, OBJC_ASSOCIATION_RETAIN_NONATOMIC);
        self->_pillGlass = pill;
    }
    if (self->_pillGlass.flexSourceView != cv) self->_pillGlass.flexSourceView = cv;
    if (self->_pillGlass.superview != outer.contentView) {
        [outer.contentView addSubview:self->_pillGlass];
    }
    if (objc_getAssociatedObject(outer, FQXDramaHeaderSelectionOwnerKey()) != self->_pillGlass) {
        objc_setAssociatedObject(outer, FQXDramaHeaderSelectionOwnerKey(), self->_pillGlass, OBJC_ASSOCIATION_RETAIN_NONATOMIC);
    }
    if (flat && flat.alpha != 0.0) {
        [UIView performWithoutAnimation:^{ flat.alpha = 0.0; }];
    }

    if (!self->_pressGesture) {
        self->_pressGesture = [[UILongPressGestureRecognizer alloc] initWithTarget:self action:@selector(handlePress:)];
        self->_pressGesture.minimumPressDuration = 0.0;
        self->_pressGesture.cancelsTouchesInView = NO;
        self->_pressGesture.delaysTouchesEnded = NO;
        self->_pressGesture.delegate = self;
    }
    if (self->_pressGesture.view != cv) {
        [self->_pressGesture.view removeGestureRecognizer:self->_pressGesture];
        [cv addGestureRecognizer:self->_pressGesture];
    }
    if (!self->_dragGesture) {
        self->_dragGesture = [[UILongPressGestureRecognizer alloc] initWithTarget:self action:@selector(handleDrag:)];
        self->_dragGesture.minimumPressDuration = 0.22;
        self->_dragGesture.cancelsTouchesInView = NO;
        self->_dragGesture.delaysTouchesEnded = NO;
        self->_dragGesture.delegate = self;
    }
    if (self->_dragGesture.view != cv) {
        [self->_dragGesture.view removeGestureRecognizer:self->_dragGesture];
        [cv addGestureRecognizer:self->_dragGesture];
    }
    if (!self->_tapGesture) {
        self->_tapGesture = [[UITapGestureRecognizer alloc] initWithTarget:self action:@selector(handleTap:)];
        self->_tapGesture.cancelsTouchesInView = NO;
        self->_tapGesture.delaysTouchesEnded = NO;
        self->_tapGesture.delegate = self;
        [self->_tapGesture requireGestureRecognizerToFail:self->_dragGesture];
    }
    if (self->_tapGesture.view != cv) {
        [self->_tapGesture.view removeGestureRecognizer:self->_tapGesture];
        [cv addGestureRecognizer:self->_tapGesture];
    }

    UIView *header = FQXDramaHeaderForTabs(tabs);
    FQXStabilizeDramaCategoryTabs(tabs);
    FQXEnsureDramaCompactLayoutForCollectionView(cv, header);
    NSString *darkSource = nil;
    BOOL isDark = header ? FQXDramaHeaderHostIsDark(header, tabs, &darkSource)
                         : ((outer.overrideUserInterfaceStyle == UIUserInterfaceStyleDark) ||
                            (outer.overrideUserInterfaceStyle == UIUserInterfaceStyleUnspecified &&
                             outer.traitCollection.userInterfaceStyle == UIUserInterfaceStyleDark));
    self->_lastDarkSource = darkSource ?: @"outer_trait";

    if (self->_paging && self->_lastSwipeTime > 0.0 && (CACurrentMediaTime() - self->_lastSwipeTime) > 0.25) {
        self->_paging = NO;
        self->_lastSwipeTime = 0.0;
    }
    if (self->_mode == FQXTopCapsuleTouchIdle && !self->_paging) {
        NSInteger sel = [self currentHostSelectedIndex];
        if (self->_pendingTapIndex != NSNotFound) {
            if (sel == self->_pendingTapIndex) {
                self->_pendingTapIndex = NSNotFound;
                self->_pendingTapExpiry = 0.0;
            } else if (CACurrentMediaTime() < self->_pendingTapExpiry) {
                sel = self->_pendingTapIndex;
            } else {
                self->_pendingTapIndex = NSNotFound;
                self->_pendingTapExpiry = 0.0;
            }
        }
        BOOL selChanged = (self->_lastSelectedIndex != NSNotFound && sel != NSNotFound && sel != self->_lastSelectedIndex);
        self->_lastSelectedIndex = sel;
        [self placePillAtIndex:sel animated:selChanged];
    }
    [self applyMaterialToOuter:outer isDark:isDark];
}

@end

static UILabel *FQXFindFirstVisibleLabel(UIView *root, NSInteger depth) {
    if (!root || root.hidden || root.alpha <= 0.01 || depth > 4) return nil;
    if ([root isKindOfClass:UILabel.class]) {
        UILabel *lbl = (UILabel *)root;
        if (lbl.text.length > 0 && lbl.textColor) return lbl;
    }
    for (UIView *sub in root.subviews) {
        UILabel *found = FQXFindFirstVisibleLabel(sub, depth + 1);
        if (found) return found;
    }
    return nil;
}

static BOOL FQXColorLuminance(UIColor *color, UITraitCollection *traits, CGFloat *outLuma) {
    if (![color isKindOfClass:UIColor.class]) return NO;
    UIColor *resolved = traits ? [color resolvedColorWithTraitCollection:traits] : color;
    CGFloat r = 0, g = 0, b = 0, a = 0, w = 0;
    if ([resolved getRed:&r green:&g blue:&b alpha:&a]) {
        if (a >= 0.45) {
            if (outLuma) *outLuma = (r + g * 2.0 + b) * 0.25;
            return YES;
        }
    } else if ([resolved getWhite:&w alpha:&a]) {
        if (a >= 0.45) {
            if (outLuma) *outLuma = w;
            return YES;
        }
    }
    return NO;
}

static BOOL FQXDramaHeaderHostIsDark(UIView *header, UIView *tabs, NSString *__autoreleasing *outSource) {
    id feed = FQXObjGet(header, "delegate");
    UIView *content = FQXObjGet(feed, "contentView");
    id owner = FQXObjGet(feed, "rootTabBarController");
    NSArray *models = FQXObjGet(feed, "tabModels");
    NSArray *cells = FQXObjGet(tabs, "dataSource");
    NSInteger selected = -1;
    if ([cells isKindOfClass:NSArray.class]) {
        for (NSUInteger i = 0; i < cells.count && i < 24; ++i) {
            if (FQXBoolGet(cells[i], "isSelected", NO)) {
                selected = (NSInteger)i;
                break;
            }
        }
    }
    if (selected < 0) {
        id tabsDel = FQXObjGet(tabs, "delegate");
        NSInteger curIdx = FQXIntGet(tabsDel, "curTabIndex", -1);
        if (curIdx >= 0) selected = curIdx;
    }

    // 1. Authoritative host tab-model background polarity when available.
    SEL bgSel = sel_registerName("bottomTabBackgroundColorWithTabModel:");
    if (selected >= 0 && [models isKindOfClass:NSArray.class] && (NSUInteger)selected < models.count &&
        owner && [owner respondsToSelector:bgSel]) {
        Method m = class_getInstanceMethod(object_getClass(owner), bgSel);
        if (m && strcmp(method_getTypeEncoding(m), "@24@0:8@16") == 0) {
            UIColor *tabColor = ((id (*)(id, SEL, id))objc_msgSend)(owner, bgSel, models[(NSUInteger)selected]);
            CGFloat luma = 0.0;
            if (FQXColorLuminance(tabColor, content ? content.traitCollection : header.traitCollection, &luma)) {
                if (outSource) *outSource = @"tab_model_bg";
                return luma < 0.5;
            }
        }
    }

    // 2. Inspect active category label ink luminance (white ink => dark video backdrop;
    // dark ink => light content page), matching real visual polarity immediately on tab switch.
    UICollectionView *cv = FQXObjGet(tabs, "collectionView");
    if ([cv isKindOfClass:UICollectionView.class]) {
        UICollectionViewCell *cell = (selected >= 0)
            ? [cv cellForItemAtIndexPath:[NSIndexPath indexPathForItem:selected inSection:0]]
            : nil;
        if (!cell) {
            for (UICollectionViewCell *vc in cv.visibleCells) {
                if (!vc.hidden && vc.alpha > 0.1 && CGRectGetWidth(vc.bounds) > 4.0) {
                    cell = vc;
                    break;
                }
            }
        }
        UILabel *lbl = cell ? FQXFindFirstVisibleLabel(cell, 0) : nil;
        CGFloat inkLuma = 0.0;
        if (lbl && FQXColorLuminance(lbl.textColor, lbl.traitCollection, &inkLuma)) {
            if (inkLuma >= 0.65) {
                if (outSource) *outSource = @"active_label_ink";
                return YES;
            }
            if (inkLuma <= 0.38) {
                if (outSource) *outSource = @"active_label_ink";
                return NO;
            }
        }
    }

    // 3. Fallback to feed contentView background color.
    UIColor *contentBg = FQXObjGet(content, "backgroundColor");
    CGFloat bgLuma = 0.0;
    if (FQXColorLuminance(contentBg, content ? content.traitCollection : header.traitCollection, &bgLuma)) {
        if (outSource) *outSource = @"content_bg";
        return bgLuma < 0.5;
    }

    if (outSource) *outSource = @"default_dark";
    return YES;
}

static const char FQXK_FQXSearchBtnGlassStampKey = 0;
#define FQXSearchBtnGlassStampKey ((const void *)&FQXK_FQXSearchBtnGlassStampKey)
static const char FQXK_FQXSearchBtnCircleGlassKey = 0;
#define FQXSearchBtnCircleGlassKey ((const void *)&FQXK_FQXSearchBtnCircleGlassKey)
static const char FQXK_FQXSearchBtnOrigImageKey = 0;
#define FQXSearchBtnOrigImageKey ((const void *)&FQXK_FQXSearchBtnOrigImageKey)
static FQXFlexGlassView *FQXEnsureDramaSearchCircleGlass(UIButton *searchBtn) {
    if (!searchBtn) return nil;
    FQXFlexGlassView *circle = objc_getAssociatedObject(searchBtn, FQXSearchBtnCircleGlassKey);
    if (![circle isKindOfClass:FQXFlexGlassView.class]) {
        circle = [[FQXFlexGlassView alloc] initWithEffect:nil];
        circle.flexSourceView = searchBtn;
        circle.userInteractionEnabled = NO;
        circle.accessibilityElementsHidden = YES;
        circle.isAccessibilityElement = NO;
        circle.opaque = NO;
        circle.clipsToBounds = NO;
        circle.backgroundColor = UIColor.clearColor;
        circle.contentView.backgroundColor = UIColor.clearColor;
        FQXApplyCornerConfiguration(circle, 0.0, NO);
        objc_setAssociatedObject(circle, FQXOwnedGlassElementKey, @YES, OBJC_ASSOCIATION_RETAIN_NONATOMIC);
        objc_setAssociatedObject(searchBtn, FQXSearchBtnCircleGlassKey, circle, OBJC_ASSOCIATION_RETAIN_NONATOMIC);
    }
    if (circle.flexSourceView != searchBtn) circle.flexSourceView = searchBtn;
    if (circle.superview != searchBtn) {
        [searchBtn insertSubview:circle atIndex:0];
    } else if (searchBtn.subviews.firstObject != circle) {
        [searchBtn sendSubviewToBack:circle];
    }
    if (!CGRectEqualToRect(circle.frame, searchBtn.bounds)) {
        circle.frame = searchBtn.bounds;
    }
    return circle;
}

static void FQXSyncDramaSearchButtonGlass(UIButton *searchBtn,
                                          BOOL isDark,
                                          NSString *darkSource,
                                          CGRect outerFrameInHeader) {
    if (!searchBtn) return;
    NSInteger surfMode = FQXDramaButtonSurfaceStyleMode();
    BOOL videoBase = (surfMode == FQXDramaButtonSurfaceVideoBase);
    BOOL roseMistGlass = (surfMode == FQXDramaButtonSurfaceRoseMistGlass);
    BOOL lightBase = videoBase || roseMistGlass;
    BOOL reduce = UIAccessibilityIsReduceTransparencyEnabled();
    BOOL darkTint = FQXGlassDarkTintEnabled();
    UIUserInterfaceStyle uiStyle = lightBase ? UIUserInterfaceStyleLight : (isDark ? UIUserInterfaceStyleDark : UIUserInterfaceStyleLight);
    if (searchBtn.overrideUserInterfaceStyle != uiStyle) {
        searchBtn.overrideUserInterfaceStyle = uiStyle;
    }
    if (searchBtn.backgroundColor && ![searchBtn.backgroundColor isEqual:UIColor.clearColor]) {
        searchBtn.backgroundColor = UIColor.clearColor;
    }
    if (searchBtn.clipsToBounds) {
        searchBtn.clipsToBounds = NO;
    }

    UIButtonConfiguration *cur = searchBtn.configuration;
    FQXFlexGlassView *circle = FQXEnsureDramaSearchCircleGlass(searchBtn);
    if (!circle) return;
    if (circle.overrideUserInterfaceStyle != uiStyle) {
        circle.overrideUserInterfaceStyle = uiStyle;
    }

    NSInteger scalePct = FQXDramaHeaderButtonScalePercent();
    NSInteger stamp = (isDark ? 2 : 1) | (reduce ? 4 : 0) | (darkTint ? 8 : 0) | ((surfMode & 3) << 12) | (scalePct << 5);
    NSNumber *applied = objc_getAssociatedObject(searchBtn, FQXSearchBtnGlassStampKey);
    BOOL effectMissing = videoBase
        ? (circle.effect != nil)
        : (!circle.effect || [circle.effect isKindOfClass:UIBlurEffect.class]);
    BOOL configHasBgGlass = (cur && cur.background.visualEffect != nil);
    if (applied && applied.integerValue == stamp && !effectMissing && !configHasBgGlass) {
        FQXSyncPlatterSurfaceBacking(circle, surfMode);
        if (videoBase) FQXClearDockBackdropBlur(searchBtn);
        return;
    }

    if (cur) {
        UIImage *origImg = objc_getAssociatedObject(searchBtn, FQXSearchBtnOrigImageKey);
        if (![origImg isKindOfClass:UIImage.class] && [cur.image isKindOfClass:UIImage.class]) {
            origImg = cur.image;
            objc_setAssociatedObject(searchBtn, FQXSearchBtnOrigImageKey, origImg, OBJC_ASSOCIATION_RETAIN_NONATOMIC);
        }
        UIImage *iconImg = origImg ?: cur.image;
        if (scalePct != 100 || lightBase) {
            CGFloat scale = (CGFloat)scalePct / 100.0;
            CGFloat symPt = round(MAX(14.0, MIN(29.0, 23.0 * scale)) * 2.0) / 2.0;
            UIImageSymbolConfiguration *symCfg =
                [UIImageSymbolConfiguration configurationWithPointSize:symPt
                                                                weight:UIImageSymbolWeightRegular
                                                                 scale:UIImageSymbolScaleMedium];
            UIImage *sym = [UIImage systemImageNamed:@"magnifyingglass" withConfiguration:symCfg];
            if (sym) {
                UIColor *iconTint = lightBase
                    ? FQXVideoInkUIColor(1.0)
                    : (isDark ? UIColor.whiteColor : [UIColor colorWithWhite:0.12 alpha:0.92]);
                iconImg = [sym imageWithTintColor:iconTint renderingMode:UIImageRenderingModeAlwaysOriginal];
            }
        }
        UIButtonConfiguration *cfg = [UIButtonConfiguration plainButtonConfiguration];
        cfg.image = iconImg;
        cfg.contentInsets = NSDirectionalEdgeInsetsZero;
        cfg.background.visualEffect = nil;
        cfg.background.backgroundColor = UIColor.clearColor;
        cfg.baseBackgroundColor = UIColor.clearColor;
        searchBtn.configuration = cfg;
    }
    UIColor *tint = roseMistGlass
        ? FQXRoseMistGlassBaseTintUIColor()
        : ((!videoBase && !reduce && darkTint && isDark) ? [UIColor colorWithWhite:0.0 alpha:0.30] : nil);
    UIVisualEffect *glassEffect = videoBase ? nil : FQXMakeGlassEffect(reduce ? 0 : 1, YES, tint);
    circle.effect = glassEffect;
    circle.backgroundColor = UIColor.clearColor;
    circle.contentView.backgroundColor = UIColor.clearColor;
    FQXApplyCornerConfiguration(circle, 0.0, NO);
    FQXSyncPlatterSurfaceBacking(circle, surfMode);
    if (videoBase) FQXClearDockBackdropBlur(searchBtn);
    if (circle.superview != searchBtn) {
        [searchBtn insertSubview:circle atIndex:0];
    } else if (searchBtn.subviews.firstObject != circle) {
        [searchBtn sendSubviewToBack:circle];
    }
    objc_setAssociatedObject(searchBtn, FQXSearchBtnGlassStampKey, @(stamp), OBJC_ASSOCIATION_RETAIN_NONATOMIC);
    if (FQXDiagnosticsHubIsEnabled()) {
        NSInteger blurStrength = FQXBlurPercent([NSUserDefaults.standardUserDefaults doubleForKey:DramaHeaderBlurPrefKey]);
        CGFloat centerDelta = CGRectIsEmpty(outerFrameInHeader)
            ? 0.0
            : (CGRectGetMidY(searchBtn.frame) - CGRectGetMidY(outerFrameInHeader));
        FQXDiagRecordEvent(FQXDiagCategoryUI, @"drama_search_glass_material", @{
            @"isDark": @(isDark),
            @"darkSource": darkSource ?: @"unknown",
            @"darkTint": @(darkTint),
            @"overrideStyle": @((NSInteger)uiStyle),
            @"hasTint": @(tint != nil),
            @"effectClass": glassEffect ? (NSStringFromClass(glassEffect.class) ?: @"") : @"nil",
            @"blurStrength": @(blurStrength),
            @"buttonScalePercent": @(scalePct),
            @"reduceTransparency": @(reduce),
            @"singleLayer": @YES,
            @"circleFrame": FQXDockRectArray(searchBtn.frame),
            @"outerHeight": @(round(CGRectGetHeight(outerFrameInHeader) * 10.0) / 10.0),
            @"alignedCenterYDelta": @(round(centerDelta * 10.0) / 10.0),
        }, NO);
    }
}

static NSHashTable<UIView *> *FQXTrackedDramaHeaders(void) {
    static NSHashTable<UIView *> *headers;
    static dispatch_once_t once;
    dispatch_once(&once, ^{ headers = [NSHashTable weakObjectsHashTable]; });
    return headers;
}

static UIView *FQXFindDramaListContainerInView(UIView *root, NSInteger depth, Class containerCls) {
    if (!root || !containerCls || depth > 4) return nil;
    if ([root isKindOfClass:containerCls]) return root;
    for (UIView *sub in root.subviews) {
        UIView *found = FQXFindDramaListContainerInView(sub, depth + 1, containerCls);
        if (found) return found;
    }
    return nil;
}

static UIView *FQXFindDramaListContainerForFeed(id feedVC) {
    if (!feedVC) return nil;
    static Class containerCls = Nil;
    static dispatch_once_t once;
    dispatch_once(&once, ^{ containerCls = objc_lookUpClass("FQRJXCategoryListContainerView"); });
    if (!containerCls) return nil;
    UIView *tabs = FQXObjGet(feedVC, "simpleTabView");
    UIView *cand = FQXObjGet(tabs, "listContainer");
    if ([cand isKindOfClass:containerCls]) return cand;
    cand = FQXObjGet(feedVC, "listContainerView") ?: FQXObjGet(feedVC, "containerView");
    if ([cand isKindOfClass:containerCls]) return cand;
    UIView *content = FQXObjGet(feedVC, "contentView");
    if ([content isKindOfClass:UIView.class]) {
        cand = FQXFindDramaListContainerInView(content, 0, containerCls);
        if (cand) return cand;
    }
    if ([feedVC isKindOfClass:UIViewController.class]) {
        UIViewController *vc = (UIViewController *)feedVC;
        if (vc.isViewLoaded && vc.view) {
            cand = FQXFindDramaListContainerInView(vc.view, 0, containerCls);
            if (cand) return cand;
        }
    }
    return nil;
}

static NSInteger FQXCurrentDramaTabIndexForFeed(id feedVC, UIView *listContainer) {
    if (!feedVC) return NSNotFound;
    NSArray *models = FQXObjGet(feedVC, "tabModels");
    NSInteger total = [models isKindOfClass:NSArray.class] ? (NSInteger)models.count : 0;
    if (total <= 0) return NSNotFound;

    // The page commit leads the title models when visible swipes arrive close together.
    NSInteger lcIdx = FQXIntGet(listContainer, "currentIndex", -1);
    if (lcIdx >= 0 && lcIdx < total) return lcIdx;
    NSInteger curIdx = FQXIntGet(feedVC, "curTabIndex", -1);
    if (curIdx >= 0 && curIdx < total) return curIdx;

    UIView *tabs = FQXObjGet(feedVC, "simpleTabView");
    NSArray *ds = FQXObjGet(tabs, "dataSource");
    if ([ds isKindOfClass:NSArray.class] && (NSInteger)ds.count == total) {
        for (NSInteger i = 0; i < total && i < 24; ++i) {
            if (FQXBoolGet(ds[(NSUInteger)i], "isSelected", NO)) return i;
        }
    }
    NSInteger tabSel = FQXIntGet(tabs, "selectedIndex", -1);
    if (tabSel >= 0 && tabSel < total) return tabSel;
    return NSNotFound;
}

static void FQXSyncDramaTopCapsuleForHeader(UIView *header);

static void FQXSelectDramaTabIndex(id feedVC, NSInteger targetIndex) {
    if (!feedVC || targetIndex < 0) return;
    UIView *tabs = FQXObjGet(feedVC, "simpleTabView");
    UICollectionView *cv = FQXObjGet(tabs, "collectionView");
    BOOL dispatched = NO;
    if ([tabs isKindOfClass:UIView.class] && [cv isKindOfClass:UICollectionView.class]) {
        NSInteger count = [cv numberOfItemsInSection:0];
        if (targetIndex < count) {
            SEL didSel = @selector(collectionView:didSelectItemAtIndexPath:);
            if ([tabs respondsToSelector:didSel]) {
                NSIndexPath *ip = [NSIndexPath indexPathForItem:targetIndex inSection:0];
                ((void (*)(id, SEL, id, id))objc_msgSend)(tabs, didSel, cv, ip);
                dispatched = YES;
            }
        }
    }
    if (!dispatched) {
        SEL selectSel = sel_registerName("selectItemAtIndex:");
        if (tabs && [tabs respondsToSelector:selectSel]) {
            Method m = class_getInstanceMethod(object_getClass(tabs), selectSel);
            if (m && strcmp(method_getTypeEncoding(m), "v24@0:8q16") == 0) {
                ((void (*)(id, SEL, NSInteger))objc_msgSend)(tabs, selectSel, targetIndex);
            }
        }
        UIView *listContainer = FQXFindDramaListContainerForFeed(feedVC);
        SEL clickSel = sel_registerName("didClickSelectedItemAtIndex:");
        if (listContainer && [listContainer respondsToSelector:clickSel]) {
            Method m = class_getInstanceMethod(object_getClass(listContainer), clickSel);
            if (m && strcmp(method_getTypeEncoding(m), "v24@0:8q16") == 0) {
                ((void (*)(id, SEL, NSInteger))objc_msgSend)(listContainer, clickSel, targetIndex);
            }
        }
    }
    UIView *header = FQXObjGet(feedVC, "headerView");
    if ([header isKindOfClass:UIView.class]) {
        __weak UIView *weakHeader = header;
        dispatch_async(dispatch_get_main_queue(), ^{
            UIView *strongHeader = weakHeader;
            if (strongHeader && strongHeader.window) {
                FQXSyncDramaTopCapsuleForHeader(strongHeader);
            }
        });
    }
}

@interface FQXDramaVisiblePagerPanController : NSObject <UIGestureRecognizerDelegate> {
@public
    __weak id _feedVC;
    __weak UIView *_listContainer;
    __weak UIScrollView *_pagerScroll;
    UIPanGestureRecognizer *_panGesture;
    BOOL _visibleStepSwipeActive;
}

@end

@implementation FQXDramaVisiblePagerPanController

- (instancetype)initWithFeed:(id)feedVC container:(UIView *)container scrollView:(UIScrollView *)scroll {
    self = [super init];
    if (self) {
        _feedVC = feedVC;
        _listContainer = container;
        _pagerScroll = scroll;
        UIPanGestureRecognizer *pan = [[UIPanGestureRecognizer alloc] initWithTarget:self action:@selector(handlePan:)];
        pan.maximumNumberOfTouches = 1;
        // A recognized page drag must cancel the underlying card or control's touch.
        pan.cancelsTouchesInView = YES;
        pan.delaysTouchesBegan = NO;
        pan.delaysTouchesEnded = YES;
        pan.delegate = self;
        pan.enabled = NO;
        _panGesture = pan;
        [container addGestureRecognizer:pan];
    }
    return self;
}

- (BOOL)gestureRecognizer:(UIGestureRecognizer *)gestureRecognizer shouldReceiveTouch:(UITouch *)touch {
    if (gestureRecognizer != self->_panGesture) return YES;
    if (!self->_visibleStepSwipeActive) return NO;
    UIView *container = self->_listContainer;
    id feed = self->_feedVC;
    if (!container || !container.window || container.hidden || !feed) return NO;

    UIView *header = FQXObjGet(feed, "headerView");
    if ([header isKindOfClass:UIView.class] && !header.hidden && header.window == container.window) {
        CGPoint locInHeader = [touch locationInView:header];
        if (CGRectContainsPoint(CGRectInset(header.bounds, 0.0, -8.0), locInHeader)) return NO;
    }
    // Keep the original touch owner even after the finger leaves a nested carousel.
    for (UIView *view = touch.view; view && view != container; view = view.superview) {
        if ([view isKindOfClass:UIScrollView.class] && view != self->_pagerScroll) {
            UIScrollView *scroll = (UIScrollView *)view;
            if (scroll.scrollEnabled && scroll.userInteractionEnabled &&
                scroll.contentSize.width > CGRectGetWidth(scroll.bounds) + 2.0) return NO;
        }
    }
    return YES;
}

- (BOOL)gestureRecognizerShouldBegin:(UIGestureRecognizer *)gestureRecognizer {
    if (gestureRecognizer != self->_panGesture) return YES;
    if (!self->_visibleStepSwipeActive) return NO;
    UIView *container = self->_listContainer;
    if (!container.window || container.hidden || !self->_feedVC) return NO;

    CGPoint direction = [self->_panGesture translationInView:container];
    if (fmax(fabs(direction.x), fabs(direction.y)) < 4.0) {
        direction = [self->_panGesture velocityInView:container];
    }
    return fabs(direction.x) > fabs(direction.y) * 1.45;
}

- (BOOL)gestureRecognizer:(UIGestureRecognizer *)gr shouldRecognizeSimultaneouslyWithGestureRecognizer:(UIGestureRecognizer *)other {
    (void)gr; (void)other;
    return NO;
}

- (BOOL)gestureRecognizer:(UIGestureRecognizer *)gestureRecognizer
    shouldBeRequiredToFailByGestureRecognizer:(UIGestureRecognizer *)other {
    UIView *container = self->_listContainer;
    // Cancelling view touches does not order a separate host card tap recognizer.
    // Hold taps until the same touch fails horizontal swipe recognition.
    return gestureRecognizer == self->_panGesture && self->_visibleStepSwipeActive && container &&
           [other isKindOfClass:UITapGestureRecognizer.class] && [other.view isDescendantOfView:container];
}

- (void)handlePan:(UIPanGestureRecognizer *)pan {
    if (pan.state != UIGestureRecognizerStateEnded) return;
    if (!self->_visibleStepSwipeActive) return;
    UIView *container = self->_listContainer;
    id feed = self->_feedVC;
    if (!container || !feed) return;

    CGPoint trans = [pan translationInView:container];
    CGPoint vel = [pan velocityInView:container];
    if (fabs(trans.y) > fabs(trans.x) * 0.9 && fabs(vel.x) < 340.0) return;

    NSInteger step = 0;
    if (trans.x <= -46.0 || vel.x <= -340.0) {
        step = 1;
    } else if (trans.x >= 46.0 || vel.x >= 340.0) {
        step = -1;
    }
    if (step == 0) return;

    NSArray<NSNumber *> *visible = FQXDramaVisibleTabIndicesForFeed(feed);
    if (visible.count < 2) return;
    NSInteger cur = FQXCurrentDramaTabIndexForFeed(feed, container);
    if (cur == NSNotFound) return;

    NSInteger target = NSNotFound;
    NSUInteger curPos = [visible indexOfObject:@(cur)];
    if (curPos != NSNotFound) {
        NSInteger nextPos = (NSInteger)curPos + step;
        if (nextPos >= 0 && nextPos < (NSInteger)visible.count) {
            target = visible[(NSUInteger)nextPos].integerValue;
        }
    } else if (step > 0) {
        for (NSNumber *n in visible) {
            if (n.integerValue > cur) { target = n.integerValue; break; }
        }
    } else {
        for (NSNumber *n in visible.reverseObjectEnumerator) {
            if (n.integerValue < cur) { target = n.integerValue; break; }
        }
    }
    if (target == NSNotFound || target == cur) return;

    UISelectionFeedbackGenerator *gen = [[UISelectionFeedbackGenerator alloc] init];
    [gen selectionChanged];
    FQXSelectDramaTabIndex(feed, target);
    FQXDiagRecordEvent(FQXDiagCategoryUI, @"drama_pager_visible_swipe", @{
        @"fromIndex": @(cur),
        @"toIndex": @(target),
        @"direction": (step > 0) ? @"left_next" : @"right_prev",
        @"visibleIndices": visible,
        @"hostIndex": @(FQXIntGet(feed, "curTabIndex", -1)),
        @"pagerIndex": @(FQXIntGet(container, "currentIndex", -1)),
    }, NO);
}

@end

static void FQXSyncDramaPagerScrollPolicyForFeed(id feedVC) {
    if (!feedVC || !FQXGlassEnabled()) return;
    static Class feedCls = Nil;
    static dispatch_once_t once;
    dispatch_once(&once, ^{ feedCls = objc_lookUpClass("SSVideoSeriesFeedViewController"); });
    if (feedCls && ![feedVC isKindOfClass:feedCls]) return;

    NSArray *models = FQXObjGet(feedVC, "tabModels");
    if (![models isKindOfClass:NSArray.class] || models.count == 0) return;

    UIView *listContainer = FQXFindDramaListContainerForFeed(feedVC);
    UIScrollView *pagerScroll = FQXObjGet(listContainer, "scrollView");
    if (!listContainer || ![pagerScroll isKindOfClass:UIScrollView.class]) return;

    BOOL masterVisible = FQXDramaCategoryMasterEnabled();
    NSArray<NSNumber *> *visibleIndices = FQXDramaVisibleTabIndicesForFeed(feedVC);
    NSInteger total = (NSInteger)models.count;
    NSInteger hiddenCount = MAX(0, total - (NSInteger)visibleIndices.count);

    // When top bar is hidden OR <= 1 visible category exists, lock horizontal pager completely.
    // When some sub-categories are hidden (e.g. 看剧/漫剧 off, 推荐/最近/收藏 on), disable raw
    // contiguous UIScrollView paging (which would physically drag through hidden pages) and
    // enable our step-pan gesture that jumps cleanly between visible tabs only.
    BOOL allowNativeScroll = masterVisible && (visibleIndices.count >= 2) && (hiddenCount == 0);
    BOOL allowVisibleStepPan = masterVisible && (visibleIndices.count >= 2) && (hiddenCount > 0);

    if (pagerScroll.scrollEnabled != allowNativeScroll) {
        pagerScroll.scrollEnabled = allowNativeScroll;
    }

    FQXDramaVisiblePagerPanController *panCtl = objc_getAssociatedObject(listContainer, FQXDramaPagerControllerKey);
    if (!panCtl && allowVisibleStepPan) {
        panCtl = [[FQXDramaVisiblePagerPanController alloc] initWithFeed:feedVC
                                                               container:listContainer
                                                              scrollView:pagerScroll];
        objc_setAssociatedObject(listContainer, FQXDramaPagerControllerKey, panCtl, OBJC_ASSOCIATION_RETAIN_NONATOMIC);
    }
    if (panCtl) {
        panCtl->_feedVC = feedVC;
        panCtl->_listContainer = listContainer;
        panCtl->_pagerScroll = pagerScroll;
        panCtl->_visibleStepSwipeActive = allowVisibleStepPan;
        if (panCtl->_panGesture.view != listContainer) {
            [panCtl->_panGesture.view removeGestureRecognizer:panCtl->_panGesture];
            [listContainer addGestureRecognizer:panCtl->_panGesture];
        }
        if (panCtl->_panGesture.enabled != allowVisibleStepPan) {
            panCtl->_panGesture.enabled = allowVisibleStepPan;
        }
    }

    // If a sub-category is explicitly hidden while top bar is visible and the pager is currently
    // sitting on that hidden tab, bounce cleanly back to the first visible category.
    if (masterVisible && hiddenCount > 0 && visibleIndices.count > 0) {
        NSInteger cur = FQXCurrentDramaTabIndexForFeed(feedVC, listContainer);
        if (cur != NSNotFound && cur >= 0 && cur < total && ![visibleIndices containsObject:@(cur)]) {
            NSNumber *lastTsNum = objc_getAssociatedObject(listContainer, FQXDramaPagerRedirectTsKey);
            CFTimeInterval now = CACurrentMediaTime();
            if (!lastTsNum || (now - lastTsNum.doubleValue) > 0.30) {
                objc_setAssociatedObject(listContainer, FQXDramaPagerRedirectTsKey, @(now), OBJC_ASSOCIATION_RETAIN_NONATOMIC);
                NSInteger fallbackIdx = visibleIndices.firstObject.integerValue;
                __weak id weakFeed = feedVC;
                dispatch_async(dispatch_get_main_queue(), ^{
                    id strongFeed = weakFeed;
                    if (!strongFeed) return;
                    NSArray<NSNumber *> *curVis = FQXDramaVisibleTabIndicesForFeed(strongFeed);
                    if (curVis.count == 0 || !FQXDramaCategoryMasterEnabled()) return;
                    UIView *lc = FQXFindDramaListContainerForFeed(strongFeed);
                    NSInteger nowIdx = FQXCurrentDramaTabIndexForFeed(strongFeed, lc);
                    if (nowIdx != NSNotFound && ![curVis containsObject:@(nowIdx)]) {
                        FQXSelectDramaTabIndex(strongFeed, curVis.firstObject.integerValue);
                    }
                });
                FQXDiagRecordEvent(FQXDiagCategoryUI, @"drama_pager_hidden_redirect", @{
                    @"hiddenIndex": @(cur),
                    @"redirectIndex": @(fallbackIdx),
                    @"visibleIndices": visibleIndices,
                }, NO);
            }
        }
    }

    NSString *policySig = [NSString stringWithFormat:@"m=%d|t=%ld|h=%ld|ns=%d|vp=%d|v=%@",
                           masterVisible ? 1 : 0, (long)total, (long)hiddenCount,
                           allowNativeScroll ? 1 : 0, allowVisibleStepPan ? 1 : 0,
                           [visibleIndices componentsJoinedByString:@","]];
    NSString *prevSig = objc_getAssociatedObject(listContainer, FQXDramaPagerPolicySigKey);
    if (!prevSig || ![prevSig isEqualToString:policySig]) {
        objc_setAssociatedObject(listContainer, FQXDramaPagerPolicySigKey, policySig, OBJC_ASSOCIATION_COPY_NONATOMIC);
        FQXDiagRecordEvent(FQXDiagCategoryUI, @"drama_pager_swipe_policy", @{
            @"masterVisible": @(masterVisible),
            @"totalTabs": @(total),
            @"hiddenCount": @(hiddenCount),
            @"visibleIndices": visibleIndices,
            @"nativeScrollEnabled": @(allowNativeScroll),
            @"visibleStepPanEnabled": @(allowVisibleStepPan),
        }, NO);
    }
}

static BOOL FQXDramaHeaderAlignInFlight = NO;
static const char FQXK_DramaSavedScrollMaskKey = 0;
#define FQXDramaSavedScrollMaskKey ((const void *)&FQXK_DramaSavedScrollMaskKey)

static void FQXSetViewLayerMaskSuppressed(UIView *view, BOOL suppress) {
    if (![view isKindOfClass:UIView.class]) return;
    CALayer *curMask = view.layer.mask;
    if (suppress) {
        if (curMask) {
            objc_setAssociatedObject(view, FQXDramaSavedScrollMaskKey, curMask, OBJC_ASSOCIATION_RETAIN_NONATOMIC);
            view.layer.mask = nil;
        }
    } else {
        CALayer *saved = objc_getAssociatedObject(view, FQXDramaSavedScrollMaskKey);
        if (saved) {
            if (!curMask) view.layer.mask = saved;
            objc_setAssociatedObject(view, FQXDramaSavedScrollMaskKey, nil, OBJC_ASSOCIATION_RETAIN_NONATOMIC);
        }
    }
}

static void FQXSyncDramaScrollMaskSuppression(UIView *header, UIView *categories, UIView *tabs, BOOL suppress) {
    FQXSetViewLayerMaskSuppressed(categories, suppress);
    FQXSetViewLayerMaskSuppressed(tabs, suppress);
    CALayer *hostMask = FQXObjGet(header, "scrollMaskLayer");
    if ([hostMask isKindOfClass:CALayer.class] && [categories isKindOfClass:UIView.class]) {
        if (suppress && categories.layer.mask == hostMask) {
            objc_setAssociatedObject(categories, FQXDramaSavedScrollMaskKey, hostMask, OBJC_ASSOCIATION_RETAIN_NONATOMIC);
            categories.layer.mask = nil;
        } else if (!suppress && !categories.layer.mask &&
                   objc_getAssociatedObject(categories, FQXDramaSavedScrollMaskKey) == hostMask) {
            categories.layer.mask = hostMask;
            objc_setAssociatedObject(categories, FQXDramaSavedScrollMaskKey, nil, OBJC_ASSOCIATION_RETAIN_NONATOMIC);
        }
    }
}

static void FQXAlignDramaHeaderCapsuleAndSearch(UIView *header) {
    if (FQXDramaHeaderAlignInFlight || !header || !header.window) return;
    CGRect headerBounds = header.bounds;
    if (CGRectGetWidth(headerBounds) < 120.0 || CGRectGetHeight(headerBounds) < 34.0) return;

    FQXDramaHeaderAlignInFlight = YES;

    UIButton *searchBtn = nil;
    for (UIView *subview in header.subviews) {
        if ([subview isKindOfClass:UIButton.class] && [subview.accessibilityLabel isEqualToString:@"搜索"]) {
            searchBtn = (UIButton *)subview;
            break;
        }
    }

    id headerOwner = FQXObjGet(header, "delegate");
    UIView *headerTabs = FQXObjGet(headerOwner, "simpleTabView");
    UICollectionView *headerCV = FQXObjGet(headerTabs, "collectionView");
    if ([headerTabs isKindOfClass:UIView.class]) {
        FQXStabilizeDramaCategoryTabs(headerTabs);
    }
    if ([headerCV isKindOfClass:UICollectionView.class]) {
        FQXEnsureDramaCompactLayoutForCollectionView(headerCV, header);
    }
    FQXSyncDramaPagerScrollPolicyForFeed(headerOwner);

    NSString *darkSource = nil;
    BOOL isDark = FQXDramaHeaderHostIsDark(header, headerTabs, &darkSource);
    BOOL blurDark = FQXGlassDarkTintEnabled() ? isDark : FQXAppIsInNightMode();

    NSInteger scalePct = FQXDramaHeaderButtonScalePercent();
    CGFloat scale = (CGFloat)scalePct / 100.0;
    CGFloat baseH = MIN(38.0, MAX(32.0, CGRectGetHeight(headerBounds) - 2.0));
    CGFloat targetH = round(MAX(26.0, MIN(48.0, baseH * scale)));

    CGFloat safeTopInHeader = CGRectGetMinY(headerBounds);
    if (header.window && CGRectGetHeight(header.window.bounds) > CGRectGetWidth(header.window.bounds)) {
        CGFloat winSafeTop = header.window.safeAreaInsets.top;
        if (winSafeTop > 0.0) {
            CGRect r = [header.window convertRect:CGRectMake(0.0, winSafeTop, 1.0, 1.0) toView:header];
            if (r.origin.y > safeTopInHeader) safeTopInHeader = r.origin.y;
        }
    }

    UIView *categories = FQXObjGet(header, "tabContainer");
    UIVisualEffectView *outer = categories ? objc_getAssociatedObject(categories, FQXDramaHeaderSurfaceKey()) : nil;
    if (![outer isKindOfClass:UIVisualEffectView.class] || outer.superview != categories ||
        outer.hidden || CGRectGetWidth(outer.bounds) < 30.0 || CGRectGetHeight(outer.bounds) > 60.0) {
        if (searchBtn && !searchBtn.hidden) {
            if (header.clipsToBounds) header.clipsToBounds = NO;
            CGRect curSearch = searchBtn.frame;
            CGFloat searchMidY = (CGRectGetHeight(curSearch) > 10.0)
                ? CGRectGetMidY(curSearch)
                : (safeTopInHeader + 4.0 + targetH * 0.5);
            CGFloat targetY = round(MAX(safeTopInHeader + 1.0, searchMidY - targetH * 0.5));
            CGRect targetSearch = CGRectMake(round(CGRectGetMaxX(headerBounds) - 12.0 - targetH),
                                             targetY,
                                             targetH,
                                             targetH);
            if (fabs(CGRectGetMinX(curSearch) - targetSearch.origin.x) > 0.5 ||
                fabs(CGRectGetMinY(curSearch) - targetSearch.origin.y) > 0.5 ||
                fabs(CGRectGetWidth(curSearch) - targetSearch.size.width) > 0.5 ||
                fabs(CGRectGetHeight(curSearch) - targetSearch.size.height) > 0.5) {
                searchBtn.frame = targetSearch;
            }
            FQXSyncDramaSearchButtonGlass(searchBtn, isDark, darkSource, CGRectZero);
            FQXFlexGlassView *circle = objc_getAssociatedObject(searchBtn, FQXSearchBtnCircleGlassKey);
            UIView *blurHost = circle ? circle.contentView : searchBtn;
            if (FQXDramaButtonUsesVideoBase()) {
                FQXClearDockBackdropBlur(searchBtn);
            } else {
                FQXApplyBackdropBlur(searchBtn, blurHost, nil, blurHost.bounds, -1, blurDark, DramaHeaderBlurPrefKey);
            }
        }
        FQXDramaHeaderAlignInFlight = NO;
        return;
    }

    [CATransaction begin];
    [CATransaction setDisableActions:YES];

    if (header.clipsToBounds) header.clipsToBounds = NO;
    if (categories.clipsToBounds) categories.clipsToBounds = NO;
    if (outer.clipsToBounds) outer.clipsToBounds = NO;
    for (UIView *anc = categories.superview; anc && anc != header; anc = anc.superview) {
        if (anc.clipsToBounds) anc.clipsToBounds = NO;
    }
    CGFloat maxCapsuleW = CGRectGetWidth(headerBounds) - ((searchBtn && !searchBtn.hidden) ? (targetH + 32.0) : 24.0);
    if (maxCapsuleW < 100.0) maxCapsuleW = CGRectGetWidth(headerBounds) - 16.0;
    BOOL fitsInHeader = NO;
    if ([headerCV isKindOfClass:UICollectionView.class]) {
        CGFloat contentW = headerCV.collectionViewLayout.collectionViewContentSize.width;
        fitsInHeader = (contentW > 1.0 && contentW <= maxCapsuleW + 1.0);
        if (fitsInHeader) {
            if (headerCV.scrollEnabled) headerCV.scrollEnabled = NO;
            if (headerCV.clipsToBounds) headerCV.clipsToBounds = NO;
            if ([headerTabs isKindOfClass:UIView.class] && headerTabs.clipsToBounds) {
                headerTabs.clipsToBounds = NO;
            }
            if ([headerTabs isKindOfClass:UIView.class] && CGRectGetWidth(headerTabs.bounds) + 1.0 < contentW) {
                CGRect tf = headerTabs.frame;
                tf.size.width = ceil(contentW);
                headerTabs.frame = tf;
            }
            if (CGRectGetWidth(headerCV.bounds) + 1.0 < contentW) {
                CGRect cvf = headerCV.frame;
                cvf.size.width = ceil(contentW);
                headerCV.frame = cvf;
            }
            CGFloat leadingOffset = -headerCV.adjustedContentInset.left;
            if (fabs(headerCV.contentOffset.x - leadingOffset) > 0.25) {
                [headerCV setContentOffset:CGPointMake(leadingOffset, headerCV.contentOffset.y) animated:NO];
            }
        } else {
            if (!headerCV.scrollEnabled) headerCV.scrollEnabled = YES;
            if (!headerCV.clipsToBounds) headerCV.clipsToBounds = YES;
        }
        FQXSyncDramaScrollMaskSuppression(
            header,
            categories,
            headerTabs,
            FQXShouldSuppressDramaScrollMask(fitsInHeader ? 1 : 0, FQXGlassEnabled() ? 1 : 0) != 0);
    }
    FQXApplyCornerConfiguration(outer, 0.0, NO);

    // Recompute tight symmetric capsule horizontal span directly from the compacted/scaled visible cells.
    CGRect of = outer.frame;
    CGRect firstInCat = CGRectZero;
    BOOL hasVisInCat = NO;
    if ([headerCV isKindOfClass:UICollectionView.class] && [headerCV numberOfSections] > 0) {
        NSInteger itemCount = [headerCV numberOfItemsInSection:0];
        CGRect firstVis = CGRectZero;
        CGRect lastVis = CGRectZero;
        BOOL hasVis = NO;
        for (NSInteger i = 0; i < itemCount && i < 24; ++i) {
            NSIndexPath *ip = [NSIndexPath indexPathForItem:i inSection:0];
            UICollectionViewLayoutAttributes *a = [headerCV layoutAttributesForItemAtIndexPath:ip];
            if (!a || CGRectGetWidth(a.frame) < 6.0 || CGRectGetHeight(a.frame) < 6.0) continue;
            if (!hasVis) {
                firstVis = a.frame;
                hasVis = YES;
            }
            lastVis = a.frame;
        }
        if (hasVis) {
            firstInCat = [headerCV convertRect:firstVis toView:categories];
            CGRect lastInCat = [headerCV convertRect:lastVis toView:categories];
            hasVisInCat = YES;
            CGFloat padX = FQXDramaCapsuleOuterHorizontalPad(scale);
            CGFloat desiredLeft = round((CGRectGetMinX(firstInCat) - padX) * 2.0) / 2.0;
            CGFloat desiredRight = round((CGRectGetMaxX(lastInCat) + padX) * 2.0) / 2.0;
            if (!fitsInHeader) {
                CGRect viewport = [headerCV convertRect:headerCV.bounds toView:categories];
                desiredLeft = CGRectGetMinX(viewport);
                desiredRight = CGRectGetMaxX(viewport);
            }
            CGFloat desiredW = desiredRight - desiredLeft;
            if (desiredW > maxCapsuleW) {
                CGFloat mid = (desiredLeft + desiredRight) * 0.5;
                desiredW = maxCapsuleW;
                desiredLeft = round((mid - desiredW * 0.5) * 2.0) / 2.0;
            }
            if (desiredW >= 30.0 && desiredW <= CGRectGetWidth(headerBounds) - 12.0) {
                if (fitsInHeader && CGRectGetWidth(categories.bounds) + 0.5 < desiredLeft + desiredW + 2.0) {
                    CGRect catFrame = categories.frame;
                    catFrame.size.width = ceil(MAX(CGRectGetWidth(catFrame), desiredLeft + desiredW + 2.0));
                    categories.frame = catFrame;
                }
                if (fabs(of.origin.x - desiredLeft) > 0.5 || fabs(of.size.width - desiredW) > 0.5) {
                    of.origin.x = desiredLeft;
                    of.size.width = desiredW;
                    outer.frame = of;
                }
            }
        }
    }

    CGFloat targetMidY = hasVisInCat ? CGRectGetMidY(firstInCat) : CGRectGetMidY(of);
    if ([headerCV isKindOfClass:UICollectionView.class]) {
        for (UICollectionViewCell *cell in headerCV.visibleCells) {
            if (cell.hidden || cell.alpha <= 0.05 || CGRectGetWidth(cell.bounds) < 6.0) continue;
            UILabel *lbl = FQXObjGet(cell, "titleLabel");
            if ([lbl isKindOfClass:UILabel.class] && lbl.superview && CGRectGetHeight(lbl.bounds) >= 8.0) {
                CGPoint lblMid = [lbl.superview convertPoint:lbl.center toView:categories];
                if (isfinite(lblMid.y)) {
                    targetMidY = lblMid.y;
                    break;
                }
            }
        }
    }
    CGFloat desiredY = round((targetMidY - targetH * 0.5) * 2.0) / 2.0;
    if (fabs(CGRectGetHeight(of) - targetH) > 0.5 || fabs(of.origin.y - desiredY) > 0.5) {
        of.origin.y = desiredY;
        of.size.height = targetH;
        outer.frame = of;
    }

    CGRect outerInHeader = [categories convertRect:outer.frame toView:header];
    CGFloat shiftYInHeader = FQXDramaCapsuleCategoriesShiftY(
        CGRectGetMinY(outerInHeader),
        CGRectGetMaxY(outerInHeader),
        CGRectGetMinY(headerBounds),
        CGRectGetMaxY(headerBounds),
        safeTopInHeader,
        (int)scalePct
    );
    if (fabs(shiftYInHeader) > 0.5 && categories.superview) {
        // Shift categories container as a unit so outer glass, selection pill, and tab labels
        // always share the exact same vertical centerline.
        CGPoint p0 = [header convertPoint:CGPointZero toView:categories.superview];
        CGPoint p1 = [header convertPoint:CGPointMake(0.0, shiftYInHeader) toView:categories.superview];
        CGFloat deltaYInSuper = p1.y - p0.y;
        CGRect cf = categories.frame;
        cf.origin.y = round((cf.origin.y + deltaYInSuper) * 2.0) / 2.0;
        categories.frame = cf;
        outerInHeader = [categories convertRect:outer.frame toView:header];
    }

    if (searchBtn && !searchBtn.hidden) {
        CGRect curSearch = searchBtn.frame;
        CGFloat targetY = round(CGRectGetMidY(outerInHeader) - targetH * 0.5);
        CGRect targetSearch = CGRectMake(round(CGRectGetMaxX(headerBounds) - 12.0 - targetH),
                                         targetY,
                                         targetH,
                                         targetH);
        if (fabs(CGRectGetMinX(curSearch) - targetSearch.origin.x) > 0.5 ||
            fabs(CGRectGetMinY(curSearch) - targetSearch.origin.y) > 0.5 ||
            fabs(CGRectGetWidth(curSearch) - targetSearch.size.width) > 0.5 ||
            fabs(CGRectGetHeight(curSearch) - targetSearch.size.height) > 0.5) {
            searchBtn.frame = targetSearch;
        }
        FQXSyncDramaSearchButtonGlass(searchBtn, isDark, darkSource, outerInHeader);
        FQXFlexGlassView *circle = FQXEnsureDramaSearchCircleGlass(searchBtn);
        if (circle) {
            FQXApplyCornerConfiguration(circle, 0.0, NO);
            if (FQXDramaButtonUsesVideoBase()) {
                FQXClearDockBackdropBlur(searchBtn);
            } else {
                FQXApplyBackdropBlur(searchBtn, circle.contentView, nil, circle.contentView.bounds, -1, blurDark, DramaHeaderBlurPrefKey);
            }
        }
    }

    // Center the visible capsule horizontally against the true window center (Dynamic Island
    // axis) rather than an asymmetric or pre-compaction header container frame.
    if (categories.superview && header.window) {
        CGRect outerInWin = [categories convertRect:outer.frame toView:header.window];
        CGFloat winW = CGRectGetWidth(header.window.bounds);
        CGFloat outerW = CGRectGetWidth(outerInWin);
        if (winW > 120.0 && outerW >= 30.0) {
            CGFloat desiredMidX = CGRectGetMidX(header.window.bounds);
            if (searchBtn && !searchBtn.hidden) {
                CGRect searchInWin = [header convertRect:searchBtn.frame toView:header.window];
                if (CGRectGetWidth(searchInWin) > 10.0) {
                    CGFloat maxMidX = CGRectGetMinX(searchInWin) - 8.0 - outerW * 0.5;
                    if (desiredMidX > maxMidX) desiredMidX = maxMidX;
                }
            }
            CGFloat minMidX = 12.0 + outerW * 0.5;
            if (desiredMidX < minMidX) desiredMidX = minMidX;
            CGFloat deltaXInWin = desiredMidX - CGRectGetMidX(outerInWin);
            if (fabs(deltaXInWin) > 0.5) {
                CGPoint p0 = [header.window convertPoint:CGPointZero toView:categories.superview];
                CGPoint p1 = [header.window convertPoint:CGPointMake(deltaXInWin, 0.0) toView:categories.superview];
                CGFloat deltaXInSuper = p1.x - p0.x;
                CGRect cf = categories.frame;
                cf.origin.x = round((cf.origin.x + deltaXInSuper) * 2.0) / 2.0;
                categories.frame = cf;
            }
            CGRect finalOuterInWin = [categories convertRect:outer.frame toView:header.window];
            CGFloat residual = round((CGRectGetMidX(finalOuterInWin) - desiredMidX) * 10.0) / 10.0;
            objc_setAssociatedObject(outer, FQXDramaOuterCenterDeltaXKey, @(residual), OBJC_ASSOCIATION_RETAIN_NONATOMIC);
        }
    }

    [CATransaction commit];
    FQXDramaHeaderAlignInFlight = NO;
}

static BOOL FQXDramaCapsuleSyncInFlight = NO;

static void FQXApplyDramaScrollMaskOnlyForHeader(UIView *header) {
    if (!NSThread.isMainThread || !header || !header.window) return;
    UIView *categories = FQXObjGet(header, "tabContainer");
    id headerOwner = FQXObjGet(header, "delegate");
    UIView *headerTabs = FQXObjGet(headerOwner, "simpleTabView");
    if (!FQXGlassEnabled()) {
        FQXSyncDramaScrollMaskSuppression(header, categories, headerTabs, NO);
        return;
    }
    CGRect headerBounds = header.bounds;
    if (CGRectGetWidth(headerBounds) < 120.0 || CGRectGetHeight(headerBounds) < 34.0) return;
    UICollectionView *headerCV = FQXObjGet(headerTabs, "collectionView");
    if (![headerCV isKindOfClass:UICollectionView.class]) return;
    NSInteger scalePct = FQXDramaHeaderButtonScalePercent();
    CGFloat scale = (CGFloat)scalePct / 100.0;
    CGFloat baseH = MIN(38.0, MAX(32.0, CGRectGetHeight(headerBounds) - 2.0));
    CGFloat targetH = round(MAX(26.0, MIN(48.0, baseH * scale)));
    BOOL hasVisibleSearch = NO;
    for (UIView *subview in header.subviews) {
        if ([subview isKindOfClass:UIButton.class] && !subview.hidden &&
            [subview.accessibilityLabel isEqualToString:@"搜索"]) {
            hasVisibleSearch = YES;
            break;
        }
    }
    CGFloat maxCapsuleW = CGRectGetWidth(headerBounds) - (hasVisibleSearch ? (targetH + 32.0) : 24.0);
    if (maxCapsuleW < 100.0) maxCapsuleW = CGRectGetWidth(headerBounds) - 16.0;
    CGFloat contentW = headerCV.contentSize.width;
    BOOL fitsInHeader = (contentW > 1.0 && contentW <= maxCapsuleW + 1.0);
    FQXSyncDramaScrollMaskSuppression(
        header,
        categories,
        headerTabs,
        FQXShouldSuppressDramaScrollMask(fitsInHeader ? 1 : 0, 1) != 0);
}

static void FQXSyncDramaTopCapsuleForHeader(UIView *header) {
    if (!header) return;
    BOOL glassOn = FQXGlassEnabled();
    if (!FQXShouldRunDramaCapsuleFullSync(NSThread.isMainThread ? 1 : 0,
                                          FQXDramaCapsuleSyncInFlight ? 1 : 0,
                                          header.window != nil ? 1 : 0,
                                          glassOn ? 1 : 0,
                                          0)) {
        return;
    }
    FQXDramaCapsuleSyncInFlight = YES;
    if (!glassOn) {
        UIView *tabs = FQXObjGet(FQXObjGet(header, "delegate"), "simpleTabView");
        FQXSyncDramaScrollMaskSuppression(header, FQXObjGet(header, "tabContainer"), tabs, NO);
        FQXDramaTopCapsuleInteraction *interaction = objc_getAssociatedObject(tabs, FQXDramaTopCapsuleKey);
        [interaction invalidate];
        FQXDramaCapsuleSyncInFlight = NO;
        return;
    }
    [FQXTrackedDramaHeaders() addObject:header];
    FQXAlignDramaHeaderCapsuleAndSearch(header);
    id owner = FQXObjGet(header, "delegate");
    UIView *tabs = FQXObjGet(owner, "simpleTabView");
    if ([tabs isKindOfClass:UIView.class]) {
        FQXDramaTopCapsuleInteraction *interaction = objc_getAssociatedObject(tabs, FQXDramaTopCapsuleKey);
        if (!interaction) {
            interaction = [[FQXDramaTopCapsuleInteraction alloc] init];
            objc_setAssociatedObject(tabs, FQXDramaTopCapsuleKey, interaction, OBJC_ASSOCIATION_RETAIN_NONATOMIC);
        }
        [interaction syncWithTabs:tabs];
    }
    FQXDramaCapsuleSyncInFlight = NO;
}

