static volatile int FQXDramaDefaultsRefreshScheduled = 0;
static void FQXScheduleDramaHeadersAndPagersRefresh(void) {
    if (!__sync_bool_compare_and_swap(&FQXDramaDefaultsRefreshScheduled, 0, 1)) return;
    dispatch_async(dispatch_get_main_queue(), ^{
        __sync_lock_release(&FQXDramaDefaultsRefreshScheduled);
        FQXHotPrefsCache prefs = FQXHotPrefsSnapshot();
        static BOOL sDramaVisInit = NO;
        static BOOL sLastDanmakuBtn = YES;
        static BOOL sLastAuthorDecl = YES;
        static BOOL sLastOrigNovel = YES;
        BOOL dramaVisChanged = !sDramaVisInit ||
            sLastDanmakuBtn != prefs.dramaShowDanmakuButton ||
            sLastAuthorDecl != prefs.dramaAuthorDeclaration ||
            sLastOrigNovel != prefs.dramaOriginalNovel;
        sDramaVisInit = YES;
        sLastDanmakuBtn = prefs.dramaShowDanmakuButton;
        sLastAuthorDecl = prefs.dramaAuthorDeclaration;
        sLastOrigNovel = prefs.dramaOriginalNovel;
        if (dramaVisChanged) {
            FQXRefreshAllDramaSeriesPills();
            FQXRefreshAllDramaControlsInWindows();
        }
        for (UIView *header in FQXTrackedDramaHeaders().allObjects) {
            if (!header) continue;
            id owner = FQXObjGet(header, "delegate");
            UIView *tabs = FQXObjGet(owner, "simpleTabView");
            UICollectionView *cv = FQXObjGet(tabs, "collectionView");
            if ([cv isKindOfClass:UICollectionView.class] && cv.window && !gFQXDramaCompactComputing) {
                [cv.collectionViewLayout invalidateLayout];
                [cv layoutIfNeeded];
            }
            FQXSyncDramaPagerScrollPolicyForFeed(owner);
            FQXSyncDramaTopCapsuleForHeader(header);
        }
    });
}

static NSHashTable<FQXTabBarInteraction *> *FQXTrackedDockInteractions(void) {
    static NSHashTable<FQXTabBarInteraction *> *table;
    static dispatch_once_t once;
    dispatch_once(&once, ^{ table = [NSHashTable weakObjectsHashTable]; });
    return table;
}

static void FQXRefreshAllDockAppearances(void) {
    if (!NSThread.isMainThread) {
        dispatch_async(dispatch_get_main_queue(), ^{ FQXRefreshAllDockAppearances(); });
        return;
    }
    for (FQXTabBarInteraction *inter in FQXTrackedDockInteractions().allObjects) {
        inter->_dockSignature = nil;
        if (inter->_nativeDockBar && inter->_buttons.count) {
            [inter syncDockItems];
            if (inter->_bar && inter->_proxy) {
                [inter layoutNativeDockInBar:inter->_bar proxy:inter->_proxy forceMeasure:YES];
                if (inter->_nativeDockActive) {
                    [inter setNativeDockVisible:YES restoreProxy:NO];
                }
            }
        }
        [inter->_bar setNeedsLayout];
    }
}

