@implementation FQXDockMotion
+ (UIImage *)roundedDramaIconNamed:(NSString *)name size:(CGFloat)size {
    UIBezierPath *outline = [UIBezierPath bezierPath];
    BOOL comment = [name isEqualToString:@"ellipsis.bubble"];
    if ([name isEqualToString:@"star"]) {
        CGPoint vertices[10];
        for (NSUInteger i = 0; i < 10; i++) {
            CGFloat angle = -M_PI_2 + i * M_PI / 5;
            CGFloat radius = i % 2 ? 6.5 : 13.0;
            vertices[i] = CGPointMake(16 + radius * cos(angle), 16.5 + radius * sin(angle));
        }
        for (NSUInteger i = 0; i < 10; i++) {
            CGPoint point = vertices[i];
            CGPoint previous = vertices[(i + 9) % 10];
            CGPoint next = vertices[(i + 1) % 10];
            CGFloat roundness = i % 2 ? 0.16 : 0.27;
            CGPoint entry = CGPointMake(point.x + (previous.x - point.x) * roundness,
                                        point.y + (previous.y - point.y) * roundness);
            CGPoint exit = CGPointMake(point.x + (next.x - point.x) * roundness,
                                       point.y + (next.y - point.y) * roundness);
            if (i == 0) [outline moveToPoint:entry];
            else [outline addLineToPoint:entry];
            [outline addQuadCurveToPoint:exit controlPoint:point];
        }
    } else if (comment) {
        [outline moveToPoint:CGPointMake(7.8, 23)];
        [outline addCurveToPoint:CGPointMake(3.3, 15) controlPoint1:CGPointMake(4.8, 21.2) controlPoint2:CGPointMake(3.3, 18.5)];
        [outline addCurveToPoint:CGPointMake(16, 4.8) controlPoint1:CGPointMake(3.3, 9.1) controlPoint2:CGPointMake(8.8, 4.8)];
        [outline addCurveToPoint:CGPointMake(28.7, 15) controlPoint1:CGPointMake(23.2, 4.8) controlPoint2:CGPointMake(28.7, 9.1)];
        [outline addCurveToPoint:CGPointMake(16, 25.1) controlPoint1:CGPointMake(28.7, 20.9) controlPoint2:CGPointMake(23.2, 25.1)];
        [outline addQuadCurveToPoint:CGPointMake(12.8, 24.7) controlPoint:CGPointMake(14.3, 25.1)];
        [outline addQuadCurveToPoint:CGPointMake(7.7, 28) controlPoint:CGPointMake(10.6, 27.2)];
        [outline addQuadCurveToPoint:CGPointMake(6.6, 26.9) controlPoint:CGPointMake(6.1, 28.5)];
        [outline addQuadCurveToPoint:CGPointMake(7.8, 23) controlPoint:CGPointMake(7.7, 24.7)];
    } else if ([name isEqualToString:@"heart"]) {
        [outline moveToPoint:CGPointMake(16, 9.1)];
        [outline addCurveToPoint:CGPointMake(3.4, 13.2) controlPoint1:CGPointMake(11.7, 2.5) controlPoint2:CGPointMake(3.4, 5.1)];
        [outline addCurveToPoint:CGPointMake(15.1, 26.5) controlPoint1:CGPointMake(3.4, 19) controlPoint2:CGPointMake(9.6, 23.5)];
        [outline addQuadCurveToPoint:CGPointMake(16.9, 26.5) controlPoint:CGPointMake(16, 27.1)];
        [outline addCurveToPoint:CGPointMake(28.6, 13.2) controlPoint1:CGPointMake(22.4, 23.5) controlPoint2:CGPointMake(28.6, 19)];
        [outline addCurveToPoint:CGPointMake(16, 9.1) controlPoint1:CGPointMake(28.6, 5.1) controlPoint2:CGPointMake(20.3, 2.5)];
    } else if ([name isEqualToString:@"paperplane"]) {
        [outline moveToPoint:CGPointMake(4.8, 12.9)];
        [outline addLineToPoint:CGPointMake(25.6, 4.7)];
        [outline addQuadCurveToPoint:CGPointMake(28, 7.1) controlPoint:CGPointMake(29.3, 3.2)];
        [outline addLineToPoint:CGPointMake(20.2, 27.1)];
        [outline addQuadCurveToPoint:CGPointMake(17.4, 27.2) controlPoint:CGPointMake(18.7, 30.7)];
        [outline addLineToPoint:CGPointMake(14, 18.4)];
        [outline addLineToPoint:CGPointMake(4.9, 15.7)];
        [outline addQuadCurveToPoint:CGPointMake(4.8, 12.9) controlPoint:CGPointMake(1.3, 14.6)];
    } else {
        return nil;
    }
    [outline closePath];
    if ([name isEqualToString:@"paperplane"]) {
        [outline moveToPoint:CGPointMake(14, 18.4)];
        [outline addLineToPoint:CGPointMake(26.9, 5.8)];
    }
    outline.lineWidth = 2.3;
    outline.lineCapStyle = kCGLineCapRound;
    outline.lineJoinStyle = kCGLineJoinRound;
    UIGraphicsImageRenderer *renderer = [[UIGraphicsImageRenderer alloc] initWithSize:CGSizeMake(size, size)];
    UIImage *image = [renderer imageWithActions:^(UIGraphicsImageRendererContext *context) {
        CGContextScaleCTM(context.CGContext, size / 32, size / 32);
        [UIColor.whiteColor setStroke];
        [outline stroke];
        if (comment) {
            [UIColor.whiteColor setFill];
            for (CGFloat x = 10; x <= 20; x += 5)
                [[UIBezierPath bezierPathWithOvalInRect:CGRectMake(x, 13.7, 2.2, 2.2)] fill];
        }
    }];
    return [image imageWithRenderingMode:UIImageRenderingModeAlwaysTemplate];
}

// A native UITabBar can render a narrower platter than its view bounds.
// Measure the visible anchor on its live layer, including in-flight reversal.
static CALayer *FQXDockDisplayLayer(UIView *view, UIView *bar, BOOL live) {
    return live && bar.layer.presentationLayer ? (view.layer.presentationLayer ?: view.layer) : view.layer;
}

static CGRect FQXDockAnchorRect(UIView *anchor, UIView *bar, BOOL live) {
    CALayer *layer = FQXDockDisplayLayer(anchor, bar, live);
    CALayer *parent = layer == anchor.layer ? bar.layer : bar.layer.presentationLayer;
    return [layer convertRect:layer.bounds toLayer:parent];
}

static void FQXEnumerateDockSurfaces(UIView *dock, void (^visit)(UIView *, UIView *)) {
    FQXTabBarInteraction *interaction = objc_getAssociatedObject(dock, TabInteractionKey);
    if (interaction && interaction->_nativeDockActive) {
        UITabBar *tab = interaction->_nativeDockBar;
        visit(tab, FQXFindDockPlatter(tab) ?: tab);
        if (interaction->_dockTitleOverlay) visit(interaction->_dockTitleOverlay, interaction->_dockTitleOverlay);
        if (interaction->_dockIconOverlay) visit(interaction->_dockIconOverlay, interaction->_dockIconOverlay);
        if (interaction->_detachedButton && !interaction->_detachedButton.hidden)
            visit(interaction->_detachedButton, interaction->_detachedButton);
    } else {
        visit(dock, dock);
        if (interaction && interaction->_overlay && !interaction->_overlay.hidden)
            visit(interaction->_overlay, interaction->_overlay);
    }
}

// Host fallback buttons can clear their title strings during layout. Keep only
// their outgoing captions alive for the short fade, outside UIKit's title state.
static const char FQXFallbackCaptionKey = 0;

static NSArray<UILabel *> *FQXFallbackDockLabels(FQXTabBarInteraction *interaction) {
    if (!interaction || interaction->_nativeDockActive || [interaction dockDisplayMode] != 0) return @[];
    // The segmented renderer also draws its visible titles with these host
    // buttons. Its own clear segment titles only supply accessibility labels.
    NSMutableArray<UILabel *> *labels = [NSMutableArray arrayWithCapacity:interaction->_buttons.count];
    for (UIButton *button in interaction->_buttons)
        if ([button isKindOfClass:UIButton.class] && button.titleLabel) [labels addObject:button.titleLabel];
    return labels;
}

static BOOL FQXDockLabelVisible(UILabel *label, UIView *bar) {
    if (!label.text.length || !label.window) return NO;
    UIColor *ink = nil;
    if (label.attributedText.length)
        ink = [label.attributedText attribute:NSForegroundColorAttributeName atIndex:0 effectiveRange:NULL];
    if (!ink) ink = label.highlighted && label.highlightedTextColor ? label.highlightedTextColor : label.textColor;
    if (ink && CGColorGetAlpha(ink.CGColor) < 0.01) return NO;
    for (UIView *view = label; view && view != bar; view = view.superview)
        if (view.hidden || view.layer.opacity < 0.01) return NO;
    return YES;
}

static void FQXPrepareFallbackTitles(FQXTabBarInteraction *interaction, UIView *bar) {
    for (UILabel *label in FQXFallbackDockLabels(interaction)) {
        UIView *prior = objc_getAssociatedObject(label, &FQXFallbackCaptionKey);
        if (prior || !FQXDockLabelVisible(label, bar)) continue;
        UIView *copy = [label snapshotViewAfterScreenUpdates:NO];
        if (!copy) continue;
        copy.frame = label.frame;
        copy.userInteractionEnabled = NO;
        copy.accessibilityElementsHidden = YES;
        copy.autoresizingMask = UIViewAutoresizingFlexibleLeftMargin | UIViewAutoresizingFlexibleRightMargin |
                                UIViewAutoresizingFlexibleTopMargin | UIViewAutoresizingFlexibleBottomMargin;
        copy.hidden = YES;
        copy.alpha = (label.layer.presentationLayer ?: label.layer).opacity;
        [label.superview addSubview:copy];
        objc_setAssociatedObject(label, &FQXFallbackCaptionKey, copy, OBJC_ASSOCIATION_RETAIN_NONATOMIC);
    }
}

static void FQXAnimateFallbackTitles(FQXTabBarInteraction *interaction, UIView *bar, BOOL compact) {
    for (UILabel *label in FQXFallbackDockLabels(interaction)) {
        UIView *copy = objc_getAssociatedObject(label, &FQXFallbackCaptionKey);
        BOOL visible = FQXDockLabelVisible(label, bar);
        if (compact && !visible && copy && !UIAccessibilityIsReduceMotionEnabled()) {
            copy.hidden = NO;
            [UIView animateWithDuration:0.10 delay:0.0 options:UIViewAnimationOptionBeginFromCurrentState
                             animations:^{ copy.alpha = 0.0; }
                             completion:^(__unused BOOL finished) {
                [copy removeFromSuperview];
                if (objc_getAssociatedObject(label, &FQXFallbackCaptionKey) == copy)
                    objc_setAssociatedObject(label, &FQXFallbackCaptionKey, nil, OBJC_ASSOCIATION_RETAIN_NONATOMIC);
            }];
        } else {
            CGFloat from = copy ? (copy.layer.presentationLayer ?: copy.layer).opacity : 0.0;
            [copy removeFromSuperview];
            objc_setAssociatedObject(label, &FQXFallbackCaptionKey, nil, OBJC_ASSOCIATION_RETAIN_NONATOMIC);
            if (!compact && visible && !UIAccessibilityIsReduceMotionEnabled() && from < label.layer.opacity) {
                CABasicAnimation *fade = [CABasicAnimation animationWithKeyPath:@"opacity"];
                fade.fromValue = @(from);
                fade.toValue = @(label.layer.opacity);
                fade.duration = 0.13;
                [label.layer addAnimation:fade forKey:@"FanqieX.dock.caption"];
            }
        }
    }
}

+ (void)prepareDock:(UIView *)dock inBar:(UIView *)bar {
    (void)bar;
    UIViewPropertyAnimator *previous = objc_getAssociatedObject(dock, DockAnimatorKey);
    if (previous) {
        if (previous.state == UIViewAnimatingStateActive) [previous stopAnimation:YES];
        objc_setAssociatedObject(dock, DockAnimatorKey, nil, OBJC_ASSOCIATION_RETAIN_NONATOMIC);
    }
    if (!dock.window || UIAccessibilityIsReduceMotionEnabled()) {
        objc_setAssociatedObject(dock, DockSnapshotKey, nil, OBJC_ASSOCIATION_RETAIN_NONATOMIC);
        return;
    }
    // Capture live presentation geometry instead of a static raster screenshot so the real
    // UIGlassEffect continues refracting live background content throughout collapse & expand.
    CGRect liveFrame = dock.layer.presentationLayer ? dock.layer.presentationLayer.frame : dock.frame;
    objc_setAssociatedObject(dock, DockSnapshotKey, [NSValue valueWithCGRect:liveFrame], OBJC_ASSOCIATION_RETAIN_NONATOMIC);
}

+ (void)animateDock:(UIView *)dock fromFrame:(CGRect)frame compact:(BOOL)compact button:(UIView *)button {
    if ([dock isKindOfClass:UIVisualEffectView.class]) {
        UIVisualEffectView *proxy = (UIVisualEffectView *)dock;
        if (compact) {
            // Transfer material ownership cleanly to proxy before frame 0 of the collapse morph.
            FQXSetDockMaterialOwner(dock.superview, proxy, FQXDockMaterialOwnerProxy, NO);
            FQXApplyDockProxyMaterial(dock.superview, proxy, nil);
        } else if (FQXGetDockMaterialOwner(proxy) != FQXDockMaterialOwnerNative) {
            // Only style proxy when native UITabBar does NOT own the expanded Dock (e.g. fallback).
            FQXApplyDockProxyMaterial(dock.superview, proxy, nil);
        } else {
            // Expanded Dock is owned by nativeDockBar; keep proxy neutralized so zero milky flash occurs.
            FQXEnforceNativeProxyNeutralized(proxy);
        }
    }
    NSValue *captured = objc_getAssociatedObject(dock, DockSnapshotKey);
    objc_setAssociatedObject(dock, DockSnapshotKey, nil, OBJC_ASSOCIATION_RETAIN_NONATOMIC);
    UIViewPropertyAnimator *previous = objc_getAssociatedObject(dock, DockAnimatorKey);
    if (previous) {
        if (previous.state == UIViewAnimatingStateActive) [previous stopAnimation:YES];
        objc_setAssociatedObject(dock, DockAnimatorKey, nil, OBJC_ASSOCIATION_RETAIN_NONATOMIC);
    }
    BOOL reduceMotion = UIAccessibilityIsReduceMotionEnabled();
    CALayer *layer = dock.layer;
    CALayer *presentation = layer.presentationLayer;
    CGRect start = captured ? captured.CGRectValue : (presentation ? presentation.frame : frame);
    CGRect target = dock.frame;
    if (!compact) {
        [button.layer removeAnimationForKey:@"FanqieX.dock.position"];
        [button.layer removeAnimationForKey:DockContentAnimation];
    }
    if (reduceMotion || CGRectIsEmpty(start) || CGRectIsEmpty(target) || CGRectEqualToRect(start, target)) {
        for (NSString *key in @[@"bounds", @"position", @"cornerRadius"]) {
            NSString *animationKey = [@"FanqieX.dock." stringByAppendingString:key];
            [layer removeAnimationForKey:animationKey];
            [button.layer removeAnimationForKey:animationKey];
        }
        return;
    }

    // Interruptible live UIKit Q-elastic spring morph directly on the UIGlassEffect surface:
    // continuous optical edge refraction, zero opacity-0 blink, zero static snapshot ghost.
    [UIView performWithoutAnimation:^{
        dock.frame = start;
        dock.layer.cornerRadius = MIN(CGRectGetWidth(start), CGRectGetHeight(start)) * 0.5;
        if (compact && button) {
            button.alpha = 0.0;
            button.transform = CGAffineTransformMakeScale(0.76, 0.76);
        }
    }];
    UISpringTimingParameters *timing = [[UISpringTimingParameters alloc]
        initWithDampingRatio:compact ? 0.66 : 0.62];
    UIViewPropertyAnimator *animator = [[UIViewPropertyAnimator alloc] initWithDuration:0.48 timingParameters:timing];
    __weak UIView *weakDock = dock;
    __weak UIView *weakButton = button;
    [animator addAnimations:^{
        UIView *strongDock = weakDock;
        UIView *strongBtn = weakButton;
        if (strongDock) {
            strongDock.frame = target;
            strongDock.layer.cornerRadius = MIN(CGRectGetWidth(target), CGRectGetHeight(target)) * 0.5;
        }
        if (compact && strongBtn) {
            strongBtn.alpha = 1.0;
            strongBtn.transform = CGAffineTransformIdentity;
        }
    }];
    [animator addCompletion:^(UIViewAnimatingPosition position) {
        (void)position;
        UIView *strongDock = weakDock;
        if (strongDock && objc_getAssociatedObject(strongDock, DockAnimatorKey) == animator) {
            objc_setAssociatedObject(strongDock, DockAnimatorKey, nil, OBJC_ASSOCIATION_RETAIN_NONATOMIC);
        }
    }];
    objc_setAssociatedObject(dock, DockAnimatorKey, animator, OBJC_ASSOCIATION_RETAIN_NONATOMIC);
    [animator startAnimation];
}

// A reused host button may replace its UIImageView between icon+caption and icon-only.
// Key by the button so its visible glyph can continue across that replacement.
static void FQXEnumerateZoomGlyphs(FQXTabBarInteraction *interaction, UIView *surface,
                                   void (^visit)(UIView *, UIImageView *)) {
    if (!interaction) return;
    if (surface == interaction->_dockIconOverlay) {
        for (UIImageView *glyph in interaction->_dockIconOverlay.arrangedSubviews) visit(glyph, glyph);
    } else if (!interaction->_nativeDockActive) {
        for (UIButton *button in interaction->_buttons) {
            if (![button isDescendantOfView:surface] || button.hidden) continue;
            for (UIView *sub in button.subviews.reverseObjectEnumerator) {
                if (![sub isKindOfClass:UIImageView.class] || sub.hidden || sub.alpha < 0.01) continue;
                UIImageView *glyph = (UIImageView *)sub;
                if (!glyph.image && !glyph.highlightedImage) continue;
                visit(button, glyph);
                break;
            }
        }
    }
}

static CGRect FQXZoomGlyphRect(UIImageView *glyph, UIView *bar, BOOL live) {
    CALayer *layer = FQXDockDisplayLayer(glyph, bar, live);
    CGRect box = layer.bounds;
    UIImage *image = (glyph.highlighted ? glyph.highlightedImage : nil) ?: glyph.image;
    CGSize size = image.size;
    if (size.width > 0 && size.height > 0 &&
        (glyph.contentMode == UIViewContentModeScaleAspectFit || glyph.contentMode == UIViewContentModeCenter)) {
        CGFloat scale = glyph.contentMode == UIViewContentModeCenter ? 1 :
            MIN(box.size.width / size.width, box.size.height / size.height);
        box = CGRectMake(CGRectGetMidX(box) - size.width * scale / 2,
                         CGRectGetMidY(box) - size.height * scale / 2, size.width * scale, size.height * scale);
    }
    CALayer *parent = layer == glyph.layer ? bar.layer : bar.layer.presentationLayer;
    return [layer convertRect:box toLayer:parent];
}

+ (void)setScrollZoomVelocity:(CGFloat)screenHeightsPerSecond forDock:(UIView *)dock {
    if (dock) objc_setAssociatedObject(dock, &FQXScrollZoomVelocityKey, @(screenHeightsPerSecond), OBJC_ASSOCIATION_RETAIN_NONATOMIC);
}

+ (void)prepareScrollZoomDock:(UIView *)dock inBar:(UIView *)bar {
    FQXDockTracking *tracking = objc_getAssociatedObject(dock, &FQXScrollZoomTrackingKey);
    if (tracking && tracking->finishing) return; // finish already captured this exact drag sample
    NSNumber *speed = objc_getAssociatedObject(dock, &FQXScrollZoomVelocityKey);
    objc_setAssociatedObject(dock, &FQXScrollZoomVelocityKey, nil, OBJC_ASSOCIATION_RETAIN_NONATOMIC);
    if (!dock.window || UIAccessibilityIsReduceMotionEnabled()) {
        objc_setAssociatedObject(dock, &FQXScrollZoomSnapshotKey, nil, OBJC_ASSOCIATION_RETAIN_NONATOMIC);
        return;
    }
    FQXTabBarInteraction *interaction = objc_getAssociatedObject(dock, TabInteractionKey);
    FQXPrepareFallbackTitles(interaction, bar);
    NSMapTable *start = [NSMapTable weakToStrongObjectsMapTable];
    if (speed) [start setObject:speed forKey:bar];
    FQXEnumerateDockSurfaces(dock, ^(UIView *view, UIView *anchor) {
        if (view.superview != bar) return;
        CALayer *live = view.layer.presentationLayer ?: view.layer;
        [start setObject:@[[NSValue valueWithCGRect:FQXDockAnchorRect(anchor, bar, YES)], @(live.opacity)] forKey:view];
        FQXEnumerateZoomGlyphs(interaction, view, ^(UIView *owner, UIImageView *glyph) {
            [start setObject:[NSValue valueWithCGRect:FQXZoomGlyphRect(glyph, bar, YES)] forKey:owner];
        });
    });
    objc_setAssociatedObject(dock, &FQXScrollZoomSnapshotKey, start, OBJC_ASSOCIATION_RETAIN_NONATOMIC);
}

+ (void)setDock:(UIView *)dock compact:(BOOL)compact {
    if ([objc_getAssociatedObject(dock, &FQXDockCompactKey) boolValue] != compact)
        objc_setAssociatedObject(dock, &FQXDockCompactKey, compact ? @YES : nil, OBJC_ASSOCIATION_RETAIN_NONATOMIC);
}

typedef struct {
    double startTime, from, target, velocity, omega, damping;
} FQXZoomSpring;

static const double FQXZoomDuration = 0.60;

// Solve the underdamped spring in absolute expanded(0)..compact(1) coordinates.
// Its derivative survives a reversal even when UIKit has already laid out the new endpoint.
static double FQXZoomSpringValue(FQXZoomSpring spring, double seconds, double *velocity) {
    double decay = spring.omega * spring.damping;
    double frequency = sqrt(spring.omega * spring.omega - decay * decay);
    double displacement = spring.from - spring.target;
    double sineTerm = (spring.velocity + decay * displacement) / frequency;
    double cosine = cos(frequency * seconds), sine = sin(frequency * seconds);
    double offset = displacement * cosine + sineTerm * sine;
    double envelope = exp(-decay * seconds);
    if (velocity)
        *velocity = envelope * (frequency * (sineTerm * cosine - displacement * sine) - decay * offset);
    return spring.target + envelope * offset;
}

static double FQXZoomSpringDuration(FQXZoomSpring spring) {
    return FQXZoomDuration * (spring.target == 1 ? 19.0 : 19.4) / spring.omega;
}

static BOOL FQXConfigureZoomRelease(FQXZoomSpring *spring, double from, double velocity) {
    double remaining = fabs(spring->target - from);
    if (remaining <= 0.0001) return NO;
    spring->from = from;
    double far = MAX(0., MIN(1., (remaining - .25) / .65));
    double slow = MAX(0., 1. - fabs(velocity) / 2.0);
    spring->omega *= 1. - .40 * far * slow;
    // Bound velocity in units of the *remaining* interval. The optical target
    // may differ from the model by a pixel; extrapolating it hundreds of times
    // near an endpoint would visibly throw both the platter and its glyphs.
    double limit = .62 * spring->omega * remaining;
    spring->velocity = MAX(-limit, MIN(limit, velocity));
    return YES;
}

static NSArray<NSNumber *> *FQXZoomSamples(UIView *dock, BOOL compact, double speed, CFTimeInterval now,
                                           FQXDockTracking *tracking, CFTimeInterval *duration) {
    FQXZoomSpring spring = { now, compact ? 0 : 1, compact ? 1 : 0,
        (compact ? 1 : -1) * MIN(3.5, MAX(0, speed)), compact ? 19.0 : 19.4, compact ? 0.67 : 0.65 };
    NSValue *saved = objc_getAssociatedObject(dock, &FQXScrollZoomSpringKey);
    BOOL moving = YES;
    if (tracking) {
        moving = FQXConfigureZoomRelease(&spring, tracking->progress, tracking->releaseVelocity);
    } else if (saved) {
        FQXZoomSpring prior;
        [saved getValue:&prior size:sizeof(prior)];
        double elapsed = now - prior.startTime;
        if (prior.target != spring.target && elapsed >= 0 && elapsed < FQXZoomSpringDuration(prior)) {
            double velocity;
            double live = FQXZoomSpringValue(prior, elapsed, &velocity);
            moving = FQXConfigureZoomRelease(&spring, live, velocity);
        }
    }
    // An endpoint can still need subpixel renderer alignment, but it has no
    // new logical travel. A subsequent grab must not inherit a full-size spring.
    objc_setAssociatedObject(dock, &FQXScrollZoomSpringKey,
        moving ? [NSValue valueWithBytes:&spring objCType:@encode(FQXZoomSpring)] : nil, OBJC_ASSOCIATION_RETAIN_NONATOMIC);
    *duration = moving ? FQXZoomSpringDuration(spring) : .12;
    if (!moving) return @[@0, @0.33, @0.64, @0.84, @0.95, @1];
    NSUInteger intervals = (NSUInteger)ceil(*duration * 120.0);
    NSMutableArray *progress = [NSMutableArray arrayWithCapacity:intervals + 1];
    for (NSUInteger i = 0; i <= intervals; i++) {
        double value = FQXZoomSpringValue(spring, *duration * i / intervals, NULL);
        [progress addObject:@(i == intervals ? 1.0 : (value - spring.from) / (spring.target - spring.from))];
    }
    return progress;
}

static CGRect FQXZoomMixRect(CGRect from, CGRect to, double p) {
    return CGRectMake(from.origin.x + (to.origin.x - from.origin.x) * p,
                      from.origin.y + (to.origin.y - from.origin.y) * p,
                      from.size.width + (to.size.width - from.size.width) * p,
                      from.size.height + (to.size.height - from.size.height) * p);
}

static CAAnimationGroup *FQXZoomGeometryGroup(UIView *view, UIView *bar, CGRect to, CGRect parentTo,
        NSArray<NSNumber *> *progress, NSArray<NSNumber *> *keyTimes, CFTimeInterval duration,
        CGRect (^rectAt)(double), CGRect (^parentAt)(double)) {
    CALayer *layer = view.layer;
    CGPoint toCenter = CGPointMake(CGRectGetMidX(to), CGRectGetMidY(to));
    UIView *parent = view.superview;
    CGPoint anchor = [parent convertPoint:toCenter fromView:bar];
    CGPoint axisX = [parent convertPoint:CGPointMake(toCenter.x + 1.0, toCenter.y) fromView:bar];
    CGPoint axisY = [parent convertPoint:CGPointMake(toCenter.x, toCenter.y + 1.0) fromView:bar];
    CGVector dx = CGVectorMake(axisX.x - anchor.x, axisX.y - anchor.y);
    CGVector dy = CGVectorMake(axisY.x - anchor.x, axisY.y - anchor.y);
    NSMutableArray *positions = [NSMutableArray arrayWithCapacity:progress.count];
    NSMutableArray *transforms = [NSMutableArray arrayWithCapacity:progress.count];
    for (NSNumber *sample in progress) {
        CGRect rect = rectAt(sample.doubleValue);
        CGPoint center = CGPointMake(CGRectGetMidX(rect), CGRectGetMidY(rect));
        CGFloat sx = rect.size.width / to.size.width, sy = rect.size.height / to.size.height;
        if (parentAt) {
            CGRect outer = parentAt(sample.doubleValue);
            CGFloat px = outer.size.width / parentTo.size.width, py = outer.size.height / parentTo.size.height;
            center.x = CGRectGetMidX(parentTo) + (center.x - CGRectGetMidX(outer)) / px;
            center.y = CGRectGetMidY(parentTo) + (center.y - CGRectGetMidY(outer)) / py;
            sx /= px;
            sy /= py;
        }
        CGFloat offsetX = center.x - toCenter.x, offsetY = center.y - toCenter.y;
        CGPoint local = CGPointMake(anchor.x + dx.dx * offsetX + dy.dx * offsetY,
                                    anchor.y + dx.dy * offsetX + dy.dy * offsetY);
        CGPoint pos = CGPointMake(local.x + (layer.position.x - anchor.x) * sx,
                                  local.y + (layer.position.y - anchor.y) * sy);
        [positions addObject:[NSValue valueWithCGPoint:pos]];
        [transforms addObject:[NSValue valueWithCATransform3D:CATransform3DScale(layer.transform, sx, sy, 1)]];
    }
    CAKeyframeAnimation *position = [CAKeyframeAnimation animationWithKeyPath:@"position"];
    position.values = positions;
    position.keyTimes = keyTimes;
    position.duration = duration;
    CAKeyframeAnimation *transform = [CAKeyframeAnimation animationWithKeyPath:@"transform"];
    transform.values = transforms;
    transform.keyTimes = keyTimes;
    transform.duration = duration;
    CAAnimationGroup *group = [CAAnimationGroup animation];
    group.timingFunction = [CAMediaTimingFunction functionWithName:kCAMediaTimingFunctionLinear];
    group.duration = duration;
    group.animations = @[position, transform];
    return group;
}

static void FQXAnimateZoomRect(UIView *view, UIView *bar, CGRect from, CGRect to,
                               CGRect parentFrom, CGRect parentTo, NSArray<NSNumber *> *progress, CFTimeInterval duration) {
    CALayer *layer = view.layer;
    [layer removeAnimationForKey:FQXDockGeometryAnimation];
    if (!progress.count || CGRectIsEmpty(from) || CGRectIsEmpty(to)) return;
    BOOL nested = !CGRectIsEmpty(parentFrom) && !CGRectIsEmpty(parentTo);
    if (CGRectEqualToRect(from, to) && (!nested || CGRectEqualToRect(parentFrom, parentTo))) return;
    CGRect (^outer)(double) = nil;
    if (nested) outer = ^CGRect(double p) { return FQXZoomMixRect(parentFrom, parentTo, p); };
    CAAnimationGroup *group = FQXZoomGeometryGroup(view, bar, to, parentTo, progress, nil, duration,
        ^CGRect(double p) { return FQXZoomMixRect(from, to, p); }, outer);
    // Leave beginTime implicit so every release group starts at this transaction's
    // commit. Building sibling glyph keyframes must not consume their first frame.
    [layer addAnimation:group forKey:FQXDockGeometryAnimation];
}

// Interactive geometry is installed once per drag. Scrubbing advances the local
// clocks over a single millisecond; the host model frames and hit targets stay put.
static const CFTimeInterval FQXTrackingInterval = 0.001;

static CGRect FQXTrackingRect(FQXDockTrackingLayer *item, double start, double p) {
    if (p == start) return item->grabbed;
    return p < start ? FQXZoomMixRect(item->expanded, item->grabbed, p / start) :
        FQXZoomMixRect(item->grabbed, item->compact, (p - start) / (1.0 - start));
}

static CGFloat FQXTrackingAlpha(FQXDockTrackingLayer *item, double start, double p) {
    if (!item->caption || p == start) return item->grabbedOpacity;
    // The reference captions disappear before the capsule reaches its small size.
    double weight = MAX(0., 1. - p / 0.82), initial = MAX(0., 1. - start / 0.82);
    if (p < start && initial < 1.)
        return item->grabbedOpacity + (1. - item->grabbedOpacity) * (weight - initial) / (1. - initial);
    return initial > 0 ? item->grabbedOpacity * weight / initial : weight;
}

static CGRect FQXMapTrackingRect(CGRect rect, CGRect source, CGRect destination, CGFloat widthScale, CGFloat heightScale) {
    CGFloat mx = CGRectGetMidX(destination) + (CGRectGetMidX(rect) - CGRectGetMidX(source)) * destination.size.width / source.size.width;
    CGFloat my = CGRectGetMidY(destination) + (CGRectGetMidY(rect) - CGRectGetMidY(source)) * destination.size.height / source.size.height;
    CGSize size = CGSizeMake(rect.size.width * widthScale, rect.size.height * heightScale);
    return CGRectMake(mx - size.width * .5, my - size.height * .5, size.width, size.height);
}

static FQXDockTrackingLayer *FQXAddTrackingLayer(FQXDockTracking *track, UIView *view, UIView *owner,
        CGRect model, CGRect opposite, CGRect live, FQXDockTrackingLayer *parent, CFTimeInterval now) {
    if (!view.window || CGRectIsEmpty(model) || CGRectIsEmpty(opposite)) return nil;
    FQXDockTrackingLayer *item = [FQXDockTrackingLayer new];
    item->view = view;
    item->anchor = view;
    item->owner = owner;
    item->parent = parent;
    item->model = model;
    item->expanded = track->fromCompact ? opposite : model;
    item->compact = track->fromCompact ? model : opposite;
    item->grabbed = CGRectIsEmpty(live) ? model : live;
    CALayer *layer = view.layer;
    item->grabbedOpacity = (layer.presentationLayer ?: layer).opacity;
    id resume = [track->resumeFrames objectForKey:owner];
    if ([resume isKindOfClass:NSArray.class]) {
        item->grabbed = [resume[0] CGRectValue];
        item->grabbedOpacity = [resume[1] doubleValue];
    } else if (resume) item->grabbed = [resume CGRectValue];
    item->clock = [layer convertTime:now fromLayer:nil];
    item->originalOffset = layer.timeOffset;
    item->originalSpeed = layer.speed;
    [track->layers addObject:item];
    return item;
}

static void FQXAddTrackingCaption(FQXDockTracking *track, UIButton *button, NSString *title, UIView *bar,
        FQXDockTrackingLayer *surface, CGRect source, CGRect destination, CFTimeInterval now) {
    UILabel *label = button.titleLabel;
    if (!label) return;
    CGRect slot = [button convertRect:button.bounds toView:bar];
    if (CGRectIsEmpty(slot)) return;
    BOOL visible = FQXDockLabelVisible(label, bar);
    // A custom module without any glyph keeps its only label at both sizes.
    if (track->fromCompact && visible) return;
    UIView *caption = label;
    CGRect model, opposite, live;
    if (!track->fromCompact) {
        if (!visible) return;
        model = FQXDockAnchorRect(label, bar, NO);
        if (CGRectIsEmpty(model)) return;
        CGRect relative = CGRectMake((model.origin.x-slot.origin.x)/slot.size.width,
                                     (model.origin.y-slot.origin.y)/slot.size.height,
                                     model.size.width/slot.size.width, model.size.height/slot.size.height);
        objc_setAssociatedObject(button, &FQXExpandedCaptionRectKey, [NSValue valueWithCGRect:relative], OBJC_ASSOCIATION_RETAIN_NONATOMIC);
        opposite = FQXMapTrackingRect(model, source, destination, .90, .90);
        live = FQXDockAnchorRect(label, bar, YES);
    } else {
        if (!title.length) return;
        UILabel *copy = [UILabel new];
        copy.userInteractionEnabled = NO;
        copy.accessibilityElementsHidden = YES;
        copy.text = title;
        copy.font = label.font;
        copy.textColor = (label.highlighted ? label.highlightedTextColor : nil) ?: label.textColor;
        copy.textAlignment = NSTextAlignmentCenter;
        CGRect expandedSlot = FQXMapTrackingRect(slot, source, destination,
            destination.size.width/source.size.width, destination.size.height/source.size.height);
        NSValue *cached = objc_getAssociatedObject(button, &FQXExpandedCaptionRectKey);
        CGRect relative = cached ? cached.CGRectValue : CGRectMake(0, .55, 1, .36);
        opposite = CGRectMake(expandedSlot.origin.x + relative.origin.x*expandedSlot.size.width,
                              expandedSlot.origin.y + relative.origin.y*expandedSlot.size.height,
                              relative.size.width*expandedSlot.size.width, relative.size.height*expandedSlot.size.height);
        model = FQXMapTrackingRect(opposite, destination, source, .90, .90);
        UIView *prior = objc_getAssociatedObject(label, &FQXFallbackCaptionKey);
        live = prior && !prior.hidden ? FQXDockAnchorRect(prior, bar, YES) : model;
        copy.alpha = prior && !prior.hidden ? (prior.layer.presentationLayer ?: prior.layer).opacity : 0;
        [prior removeFromSuperview];
        objc_setAssociatedObject(label, &FQXFallbackCaptionKey, nil, OBJC_ASSOCIATION_RETAIN_NONATOMIC);
        copy.frame = [button convertRect:model fromView:bar];
        [button addSubview:copy];
        caption = copy;
    }
    FQXDockTrackingLayer *item = FQXAddTrackingLayer(track, caption, label, model, opposite, live, surface, now);
    if (item) {
        item->caption = YES;
        item->hostCaption = label;
        item->temporaryCaption = caption != label;
        if (item->temporaryCaption && ![track->resumeFrames objectForKey:label]) item->grabbedOpacity = caption.alpha;
    } else if (caption != label) {
        [caption removeFromSuperview];
    }
}

static double FQXVisibleZoomProgress(double largeWidth, double smallWidth, double liveWidth, double fallback) {
    double travel = smallWidth - largeWidth;
    return fabs(travel) > .5 ? MAX(0., MIN(1., (liveWidth - largeWidth) / travel)) : fallback;
}

// A regrab can begin on the spring's overshoot. Its first drag segment then
// starts at that displayed width, rather than at the nominal endpoint.
static double FQXTrackingProgressForWidth(double large, double grabbed, double small,
                                          double start, double width, double hint) {
    double best = hint, error = CGFLOAT_MAX;
    for (int segment = 0; segment < 2; segment++) {
        double p0 = segment ? start : 0., p1 = segment ? 1. : start;
        double a = segment ? grabbed : large, b = segment ? small : grabbed;
        if (p1 <= p0 || fabs(b - a) <= .0001) continue;
        double t = MIN(1., MAX(0., (width - a) / (b - a)));
        double distance = fabs(width - (a + t * (b - a)));
        double candidate = p0 + t * (p1 - p0);
        if (distance < error - .0001 || (fabs(distance - error) <= .0001 && fabs(candidate - hint) < fabs(best - hint))) {
            best = candidate;
            error = distance;
        }
    }
    return best;
}

static NSMapTable *FQXCaptureTrackingFrames(FQXDockTracking *track) {
    NSMapTable *captured = [NSMapTable weakToStrongObjectsMapTable];
    UIView *bar = track->bar;
    FQXDockTrackingLayer *driver = track->driver;
    BOOL live = driver && driver->anchor.layer.presentationLayer && bar.layer.presentationLayer;
    if (live) {
        CGRect frame = FQXDockAnchorRect(driver->anchor, bar, YES);
        track->progress = FQXTrackingProgressForWidth(driver->expanded.size.width, driver->grabbed.size.width,
            driver->compact.size.width, track->start, frame.size.width, track->progress);
    }
    for (FQXDockTrackingLayer *item in track->layers) {
        UIView *owner = item->owner;
        if (!owner) continue;
        // All available presentation layers are from the last rendered scene.
        // A new glyph/caption has no scene yet; project it at the same measured
        // fraction instead of mixing in the not-yet-displayed final pan update.
        BOOL displayed = live && item->view.layer.presentationLayer && item->anchor.layer.presentationLayer;
        CGRect frame = displayed ? (item->glyph ? FQXZoomGlyphRect((UIImageView *)item->view, bar, YES) :
                                                 FQXDockAnchorRect(item->anchor, bar, YES)) :
                                   FQXTrackingRect(item, track->start, track->progress);
        CGFloat alpha = displayed ? item->view.layer.presentationLayer.opacity : FQXTrackingAlpha(item, track->start, track->progress);
        NSValue *rect = [NSValue valueWithCGRect:frame];
        [captured setObject:item->glyph ? (id)rect : @[rect, @(alpha)] forKey:owner];
    }
    return captured;
}

static double FQXStartZoomTracking(UIView *dock, CGRect expanded, CGRect compact,
                                   double heldProgress, NSMapTable *heldFrames) {
    BOOL small = [objc_getAssociatedObject(dock, &FQXDockCompactKey) boolValue];
    UIView *bar = dock.superview;
    if (!dock.window || dock.hidden || CGRectIsEmpty(expanded) || CGRectIsEmpty(compact)) return small ? 1 : 0;
    FQXTabBarInteraction *interaction = objc_getAssociatedObject(dock, TabInteractionKey);
    FQXDockTracking *track = [FQXDockTracking new];
    track->layers = [NSMutableArray array];
    track->fromCompact = small;
    track->bar = bar;
    track->dock = dock;
    track->expandedFrame = expanded;
    track->compactFrame = compact;
    track->resumeFrames = heldFrames;
    track->start = heldFrames ? heldProgress : (small ? 1 : 0);
    CFTimeInterval now = CACurrentMediaTime();
    NSValue *spring = objc_getAssociatedObject(dock, &FQXScrollZoomSpringKey);
    if (!heldFrames && spring) {
        FQXZoomSpring prior;
        [spring getValue:&prior size:sizeof(prior)];
        double elapsed = now - prior.startTime;
        if (elapsed >= 0 && elapsed < FQXZoomSpringDuration(prior))
            track->start = MIN(1., MAX(0., FQXZoomSpringValue(prior, elapsed, NULL)));
    }
    CGRect source = small ? compact : expanded, destination = small ? expanded : compact;
    CGFloat sx = destination.size.width/source.size.width, sy = destination.size.height/source.size.height;
    CGFloat iconScale = small ? 1./.90 : .90;
    FQXEnumerateDockSurfaces(dock, ^(UIView *view, UIView *anchor) {
        if (view.hidden || view.superview != bar) return;
        CGRect model = FQXDockAnchorRect(anchor, bar, NO);
        CGRect opposite = FQXMapTrackingRect(model, source, destination,
            interaction && view == interaction->_detachedButton ? sy : sx, sy);
        BOOL isIcons = interaction && view == interaction->_dockIconOverlay;
        BOOL isCaptions = interaction && interaction->_dockIconOverlay && view == interaction->_dockTitleOverlay;
        if (isIcons || isCaptions) {
            CGFloat otherScale = interaction->_nativeDockBar.transform.d * sy;
            // Native icon+caption stacks use these same offsets at settled layout.
            CGFloat shift = isIcons ? 7.0 : -5.5;
            opposite.origin.y += (small ? -1 : 1) * shift * otherScale;
            if (isIcons) {
                CGFloat h = model.size.height * iconScale;
                opposite.origin.y += (opposite.size.height - h) * .5;
                opposite.size.height = h;
            }
        }
        FQXDockTrackingLayer *surface = FQXAddTrackingLayer(track, view, view, model, opposite,
            FQXDockAnchorRect(anchor, bar, YES), nil, now);
        if (!surface) return;
        surface->anchor = anchor;
        if (view == dock || (interaction && view == interaction->_nativeDockBar)) {
            track->driver = surface;
            if (!heldFrames && anchor.layer.presentationLayer && bar.layer.presentationLayer)
                track->start = FQXVisibleZoomProgress(surface->expanded.size.width, surface->compact.size.width,
                                                     surface->grabbed.size.width, track->start);
        }
        surface->caption = isCaptions;
        FQXEnumerateZoomGlyphs(interaction, view, ^(UIView *owner, UIImageView *glyph) {
            CGRect box = FQXZoomGlyphRect(glyph, bar, NO);
            CGRect target = FQXMapTrackingRect(box, model, opposite, iconScale, iconScale);
            if ([owner isKindOfClass:UIButton.class] && [interaction dockDisplayMode] == 0) {
                CGRect slot = [owner convertRect:owner.bounds toView:bar];
                CGFloat slotY = CGRectGetMidY(destination) + (CGRectGetMidY(slot) - CGRectGetMidY(source)) * sy;
                target.origin.y = slotY - target.size.height * .5 - (small ? destination.size.height * .12 : 0);
                NSUInteger index = [interaction->_buttons indexOfObjectIdenticalTo:(UIButton *)owner];
                FQXAddTrackingCaption(track, (UIButton *)owner, FQXDockButtonTitle((UIButton *)owner, bar, index),
                                      bar, surface, source, destination, now);
            }
            FQXDockTrackingLayer *item = FQXAddTrackingLayer(track, glyph, owner, box, target,
                FQXZoomGlyphRect(glyph, bar, YES), surface, now);
            if (item) item->glyph = YES;
        });
    });
    track->resumeFrames = nil;
    track->progress = track->sampleProgress = track->start;
    track->sampleTime = now;
    if (!track->layers.count) return small ? 1 : 0;
    NSMutableArray<NSNumber *> *samples = [NSMutableArray array];
    for (NSUInteger i=0; i<=16; ++i) [samples addObject:@(i / 16.)];
    if (![samples containsObject:@(track->start)]) {
        [samples addObject:@(track->start)];
        [samples sortUsingSelector:@selector(compare:)];
    }
    [CATransaction begin];
    [CATransaction setDisableActions:YES];
    for (FQXDockTrackingLayer *item in track->layers) {
        FQXDockTrackingLayer *parent = item->parent;
        CGRect (^outer)(double) = nil;
        if (parent) outer = ^CGRect(double p) { return FQXTrackingRect(parent, track->start, p); };
        CAAnimationGroup *group = FQXZoomGeometryGroup(item->view, bar, item->model, parent ? parent->model : CGRectZero,
            samples, samples, FQXTrackingInterval, ^CGRect(double p) { return FQXTrackingRect(item, track->start, p); }, outer);
        if (item->caption) {
            NSMutableArray *alphas = [NSMutableArray arrayWithCapacity:samples.count];
            for (NSNumber *p in samples) [alphas addObject:@(FQXTrackingAlpha(item, track->start, p.doubleValue))];
            CAKeyframeAnimation *fade = [CAKeyframeAnimation animationWithKeyPath:@"opacity"];
            fade.values = alphas;
            fade.keyTimes = samples;
            fade.duration = FQXTrackingInterval;
            group.animations = [group.animations arrayByAddingObject:fade];
        }
        group.beginTime = item->clock;
        group.fillMode = kCAFillModeBoth;
        group.removedOnCompletion = NO;
        CALayer *layer = item->view.layer;
        [layer removeAnimationForKey:@"FanqieX.dock.caption"];
        layer.speed = 0;
        layer.timeOffset = item->clock + track->progress * FQXTrackingInterval;
        [layer addAnimation:group forKey:FQXDockGeometryAnimation];
    }
    [CATransaction commit];
    objc_setAssociatedObject(dock, &FQXScrollZoomSpringKey, nil, OBJC_ASSOCIATION_RETAIN_NONATOMIC);
    objc_setAssociatedObject(dock, &FQXScrollZoomTrackingKey, track, OBJC_ASSOCIATION_RETAIN_NONATOMIC);
    return track->progress;
}

+ (double)beginScrollZoomTracking:(UIView *)dock expandedFrame:(CGRect)expanded compactFrame:(CGRect)compact {
    FQXDockTracking *prior = objc_getAssociatedObject(dock, &FQXScrollZoomTrackingKey);
    if (prior && !prior->finishing) return prior->progress;
    if (!prior) return FQXStartZoomTracking(dock, expanded, compact, 0, nil);
    // The previous target still has a queued layout. Regrab the visible frames
    // now; its normal polish callback will rebase once on the committed model.
    NSMapTable *frames = FQXCaptureTrackingFrames(prior);
    double p = prior->progress;
    [self cancelScrollZoomTracking:dock];
    return FQXStartZoomTracking(dock, expanded, compact, p, frames);
}

+ (void)updateScrollZoomTracking:(UIView *)dock progress:(double)p {
    FQXDockTracking *track = objc_getAssociatedObject(dock, &FQXScrollZoomTrackingKey);
    if (!track || track->finishing || !isfinite(p)) return;
    p = MIN(1., MAX(0., p));
    if (track->progress == p) return;
    CFTimeInterval now = CACurrentMediaTime(), dt = now - track->sampleTime;
    if (dt >= 1. / 240.) {
        track->measuredVelocity = (p - track->sampleProgress) / dt;
        track->hasMeasuredVelocity = YES;
        track->sampleProgress = p;
        track->sampleTime = now;
    }
    track->progress = p;
    [CATransaction begin];
    [CATransaction setDisableActions:YES];
    for (FQXDockTrackingLayer *item in track->layers)
        item->view.layer.timeOffset = item->clock + p * FQXTrackingInterval;
    [CATransaction commit];
}

static void FQXReleaseTrackingLayers(FQXDockTracking *track, BOOL settling) {
    NSArray *labels = settling ? FQXFallbackDockLabels(objc_getAssociatedObject(track->dock, TabInteractionKey)) : nil;
    [CATransaction begin];
    [CATransaction setDisableActions:YES];
    for (FQXDockTrackingLayer *item in track->layers) {
        CALayer *layer = item->view.layer;
        [layer removeAnimationForKey:FQXDockGeometryAnimation];
        layer.timeOffset = item->originalOffset;
        layer.speed = item->originalSpeed;
        UILabel *label = item->hostCaption;
        BOOL keepCaption = label && [labels containsObject:label] && label.window && track->bar;
        if (label && !keepCaption) {
            UIView *copy = objc_getAssociatedObject(label, &FQXFallbackCaptionKey);
            [copy removeFromSuperview];
            objc_setAssociatedObject(label, &FQXFallbackCaptionKey, nil, OBJC_ASSOCIATION_RETAIN_NONATOMIC);
        }
        if (item->temporaryCaption) {
            UIView *copy = item->view;
            if (keepCaption) {
                [track->bar addSubview:copy];
                copy.frame = FQXTrackingRect(item, track->start, track->progress);
                copy.alpha = FQXTrackingAlpha(item, track->start, track->progress);
                objc_setAssociatedObject(label, &FQXFallbackCaptionKey, copy, OBJC_ASSOCIATION_RETAIN_NONATOMIC);
            } else {
                [copy removeFromSuperview];
            }
        }
    }
    [CATransaction commit];
    [track->layers removeAllObjects];
}

+ (void)finishScrollZoomTracking:(UIView *)dock compact:(BOOL)target velocity:(double)velocity {
    FQXDockTracking *track = objc_getAssociatedObject(dock, &FQXScrollZoomTrackingKey);
    if (!track || track->finishing) return;
    track->finishing = YES;
    double v = isfinite(velocity) ? MIN(6., MAX(-6., velocity)) : 0.;
    if (CACurrentMediaTime() - track->sampleTime > .08) v = 0.;
    else if (track->hasMeasuredVelocity) {
        double seen = track->measuredVelocity;
        v = v * seen > 0 ? copysign(MIN(fabs(v), fabs(seen)), v) : 0.;
    }
    track->releaseVelocity = v;
    FQXTabBarInteraction *interaction = objc_getAssociatedObject(dock, TabInteractionKey);
    FQXPrepareFallbackTitles(interaction, dock.superview);
    NSMapTable *captured = FQXCaptureTrackingFrames(track);
    for (FQXDockTrackingLayer *item in track->layers) {
        if (!item->hostCaption || item->temporaryCaption) continue;
        UIView *copy = objc_getAssociatedObject(item->hostCaption, &FQXFallbackCaptionKey);
        copy.alpha = FQXTrackingAlpha(item, track->start, track->progress);
    }
    objc_setAssociatedObject(dock, &FQXScrollZoomSnapshotKey, captured, OBJC_ASSOCIATION_RETAIN_NONATOMIC);
    if (track->fromCompact == target)
        [self animateDock:dock fromFrame:dock.frame compact:target];
}

+ (void)cancelScrollZoomTracking:(UIView *)dock {
    FQXDockTracking *track = objc_getAssociatedObject(dock, &FQXScrollZoomTrackingKey);
    if (track) FQXReleaseTrackingLayers(track, NO);
    if (track || objc_getAssociatedObject(dock, &FQXScrollZoomSpringKey)) {
        FQXTabBarInteraction *interaction = objc_getAssociatedObject(dock, TabInteractionKey);
        FQXEnumerateDockSurfaces(dock, ^(UIView *view, __unused UIView *anchor) {
            [view.layer removeAnimationForKey:FQXDockGeometryAnimation];
            [view.layer removeAnimationForKey:@"FanqieX.dock.caption"];
            FQXEnumerateZoomGlyphs(interaction, view, ^(__unused UIView *owner, UIImageView *glyph) {
                [glyph.layer removeAnimationForKey:FQXDockGeometryAnimation];
            });
        });
        for (UILabel *label in FQXFallbackDockLabels(interaction)) {
            UIView *copy = objc_getAssociatedObject(label, &FQXFallbackCaptionKey);
            [copy removeFromSuperview];
            objc_setAssociatedObject(label, &FQXFallbackCaptionKey, nil, OBJC_ASSOCIATION_RETAIN_NONATOMIC);
            [label.layer removeAnimationForKey:@"FanqieX.dock.caption"];
        }
    }
    objc_setAssociatedObject(dock, &FQXScrollZoomTrackingKey, nil, OBJC_ASSOCIATION_RETAIN_NONATOMIC);
    objc_setAssociatedObject(dock, &FQXScrollZoomSpringKey, nil, OBJC_ASSOCIATION_RETAIN_NONATOMIC);
    objc_setAssociatedObject(dock, &FQXScrollZoomSnapshotKey, nil, OBJC_ASSOCIATION_RETAIN_NONATOMIC);
    objc_setAssociatedObject(dock, &FQXScrollZoomVelocityKey, nil, OBJC_ASSOCIATION_RETAIN_NONATOMIC);
}


+ (void)animateDock:(UIView *)dock fromFrame:(CGRect)frame compact:(BOOL)compact {
    NSMapTable *start = objc_getAssociatedObject(dock, &FQXScrollZoomSnapshotKey);
    objc_setAssociatedObject(dock, &FQXScrollZoomSnapshotKey, nil, OBJC_ASSOCIATION_RETAIN_NONATOMIC);
    UIView *bar = dock.superview;
    FQXTabBarInteraction *interaction = objc_getAssociatedObject(dock, TabInteractionKey);
    FQXDockTracking *tracking = objc_getAssociatedObject(dock, &FQXScrollZoomTrackingKey);
    if (tracking && !tracking->finishing) {
        // UIKit delivered an older model change after the new gesture began.
        // Rebase the paused tracks to that model without moving the visible Dock.
        NSMapTable *frames = FQXCaptureTrackingFrames(tracking);
        CGFloat p = tracking->progress;
        CGRect expanded = tracking->expandedFrame, compactFrame = tracking->compactFrame;
        [self cancelScrollZoomTracking:dock];
        FQXStartZoomTracking(dock, expanded, compactFrame, p, frames);
        return;
    }
    if (tracking) {
        FQXReleaseTrackingLayers(tracking, YES);
        objc_setAssociatedObject(dock, &FQXScrollZoomTrackingKey, nil, OBJC_ASSOCIATION_RETAIN_NONATOMIC);
    }
    FQXAnimateFallbackTitles(interaction, bar, compact);
    CFTimeInterval now = CACurrentMediaTime();
    CFTimeInterval duration = 0;
    NSArray *progress = dock.window && !UIAccessibilityIsReduceMotionEnabled() ?
        FQXZoomSamples(dock, compact, [[start objectForKey:bar] doubleValue], now, tracking, &duration) : nil;
    if (!progress) objc_setAssociatedObject(dock, &FQXScrollZoomSpringKey, nil, OBJC_ASSOCIATION_RETAIN_NONATOMIC);
    FQXEnumerateDockSurfaces(dock, ^(UIView *view, UIView *anchor) {
        if (view.superview != bar) return;
        CALayer *layer = view.layer;
        [layer removeAnimationForKey:@"FanqieX.dock.caption"];
        NSArray *saved = [start objectForKey:view];
        CGRect from = saved ? [saved[0] CGRectValue] : (view == dock ? frame : CGRectZero);
        CGRect to = FQXDockAnchorRect(anchor, bar, NO);
        FQXAnimateZoomRect(view, bar, from, to, CGRectZero, CGRectZero, progress, duration);
        FQXEnumerateZoomGlyphs(interaction, view, ^(UIView *owner, UIImageView *glyph) {
            NSValue *oldGlyph = [start objectForKey:owner];
            FQXAnimateZoomRect(glyph, bar, oldGlyph ? oldGlyph.CGRectValue : CGRectZero, FQXZoomGlyphRect(glyph, bar, NO),
                               from, to, progress, duration);
        });
        if (progress && saved && fabs([saved[1] doubleValue] - layer.opacity) > 0.01) {
            CABasicAnimation *fade = [CABasicAnimation animationWithKeyPath:@"opacity"];
            fade.fromValue = saved[1];
            fade.toValue = @(layer.opacity);
            fade.duration = compact ? 0.10 : 0.13;
            fade.timingFunction = [CAMediaTimingFunction functionWithName:kCAMediaTimingFunctionEaseInEaseOut];
            [layer addAnimation:fade forKey:@"FanqieX.dock.caption"];
        }
    });
}

+ (void)syncTabBar:(UIView *)bar
             proxy:(UIVisualEffectView *)proxy
           buttons:(NSArray<UIButton *> *)buttons
            native:(UIView *)native
              lens:(UIVisualEffectView *)lens {
    if (!proxy) return;
    FQXTabBarInteraction *interaction = objc_getAssociatedObject(proxy, TabInteractionKey);
    if (!bar && lens) {
        [interaction updateLens:lens native:native];
        return;
    }
    if (!buttons.count) {
        [self cancelScrollZoomTracking:proxy];
        [interaction teardown];
        return;
    }
    if (!interaction) {
        interaction = [FQXTabBarInteraction new];
        objc_setAssociatedObject(proxy, TabInteractionKey, interaction, OBJC_ASSOCIATION_RETAIN_NONATOMIC);
    }
    [FQXTrackedDockInteractions() addObject:interaction];
    [interaction syncWithBar:bar proxy:proxy buttons:buttons native:native lens:lens];
}

+ (CGRect)renderedDockFrameForProxy:(UIView *)proxy {
    FQXTabBarInteraction *interaction = objc_getAssociatedObject(proxy, TabInteractionKey);
    if (interaction && interaction->_nativeDockActive &&
        interaction->_bar == proxy.superview && !interaction->_nativeDockBar.hidden) {
        if ([interaction usesFeedMotion] && !CGRectIsEmpty(interaction->_feedCapsuleAtRest)) {
            return interaction->_feedCapsuleAtRest;
        }
        return interaction->_dockRenderedPlatterRectInBar;
    }
    return CGRectZero;
}

+ (BOOL)proxyAllowsDramaCapsuleTouch:(UIView *)capsule atPoint:(CGPoint)point {
    if (!capsule) return NO;
    FQXTabBarInteraction *inter = objc_getAssociatedObject(capsule, TabInteractionKey);
    UIView *bar = capsule.superview;
    if (!inter || !inter->_nativeDockActive || inter->_bar != bar || !bar) {
        return CGRectContainsPoint(capsule.bounds, point);
    }
    if (![inter usesFeedMotion]) {
        return CGRectContainsPoint(capsule.bounds, point);
    }
    if (inter->_appliedCollapseMode == FQXDockCollapseModeSiriai && inter->_feedControlsHidden) {
        return NO;
    }
    CGPoint ptInBar = [bar convertPoint:point fromView:capsule];
    if (FQXPointIsInDockBottomEdgeStrip(inter, ptInBar)) {
        return NO;
    }
    if (CGRectContainsPoint(FQXDisplayedDockRect(inter->_nativeDockBar, bar, inter->_dockRenderedPlatterRectInBar), ptInBar)) {
        return YES;
    }
    if (inter->_detachedHostIndex != NSNotFound && inter->_detachedButton &&
        inter->_detachedButton.superview == bar && !inter->_detachedButton.hidden &&
        inter->_detachedButton.alpha > 0.01 && inter->_detachedButton.userInteractionEnabled) {
        CGPoint ptInDet = FQXPointInDisplayedDock(inter->_detachedButton, bar, ptInBar);
        if ([inter->_detachedButton pointInside:ptInDet withEvent:nil]) {
            return YES;
        }
    }
    return NO;
}

+ (void)refreshDockCollapseMode {
    FQXInvalidateHotPrefsCache();
    FQXDockCollapseMode mode = FQXCurrentDockCollapseMode();
    [[FQXFeedDockPanController shared] resetFeedGesture];
    if (FQXFeedMotionSupported() && FQXDockCollapseModeUsesFeedMotion(mode)) {
        [[FQXFeedDockPanController shared] scanWindowsForMountedCollections];
    }
    for (FQXTabBarInteraction *inter in FQXTrackedDockInteractions().allObjects) {
        [inter refreshForCollapseModeChange];
        [inter->_bar setNeedsLayout];
    }
    FQXRefreshAllDramaControlsInWindows();
}

+ (void)invalidateDramaDockPage:(UIViewController *)page {
    static char pendingKey;
    if (objc_getAssociatedObject(page, &pendingKey)) return;
    objc_setAssociatedObject(page, &pendingKey, @YES, OBJC_ASSOCIATION_RETAIN_NONATOMIC);
    __weak UIViewController *weakPage = page;
    dispatch_async(dispatch_get_main_queue(), ^{
        UIViewController *mountedPage = weakPage;
        if (!mountedPage) return;
        objc_setAssociatedObject(mountedPage, &pendingKey, nil, OBJC_ASSOCIATION_RETAIN_NONATOMIC);
        if (mountedPage.viewIfLoaded.window) FQXRefreshDramaControllerControls(mountedPage);
    });
}

+ (void)refreshAudioGlass {
    FQXInvalidateHotPrefsCache();
    FQXRefreshAllAudioGlass();
}

