static BOOL FQXColorIsLightNeutralInk(UIColor *color, UITraitCollection *traits) {
    if (![color isKindOfClass:UIColor.class]) return NO;
    UIColor *resolved = traits ? [color resolvedColorWithTraitCollection:traits] : color;
    CGFloat r = 0, g = 0, b = 0, a = 0, w = 0;
    if ([resolved getRed:&r green:&g blue:&b alpha:&a]) {
        CGFloat mx = MAX(r, MAX(g, b));
        CGFloat mn = MIN(r, MIN(g, b));
        return a > 0.15 && (mx - mn) < 0.14 && mx > 0.55;
    }
    if ([resolved getWhite:&w alpha:&a]) {
        return a > 0.15 && w > 0.55;
    }
    return NO;
}

static void FQXApplyDramaButtonVideoInkTree(UIView *view, UIView *glass, BOOL active, NSInteger depth) {
    if (!view || view == glass || depth > 5) return;
    UIColor *darkInk = FQXVideoInkUIColor(1.0);
    if ([view isKindOfClass:UILabel.class]) {
        UILabel *lbl = (UILabel *)view;
        UIColor *saved = objc_getAssociatedObject(lbl, DramaSurfaceSavedTextColKey);
        if (active) {
            if (!saved && FQXColorIsLightNeutralInk(lbl.textColor, lbl.traitCollection)) {
                objc_setAssociatedObject(lbl, DramaSurfaceSavedTextColKey, lbl.textColor, OBJC_ASSOCIATION_RETAIN_NONATOMIC);
                saved = lbl.textColor;
            }
            if (saved && ![lbl.textColor isEqual:darkInk]) lbl.textColor = darkInk;
        } else if (saved) {
            lbl.textColor = saved;
            objc_setAssociatedObject(lbl, DramaSurfaceSavedTextColKey, nil, OBJC_ASSOCIATION_RETAIN_NONATOMIC);
        }
    } else if ([view isKindOfClass:UIButton.class]) {
        UIButton *btn = (UIButton *)view;
        UIColor *saved = objc_getAssociatedObject(btn, DramaSurfaceSavedTextColKey);
        if (active) {
            UIColor *curTitleCol = [btn titleColorForState:UIControlStateNormal];
            if (!saved && FQXColorIsLightNeutralInk(curTitleCol, btn.traitCollection)) {
                objc_setAssociatedObject(btn, DramaSurfaceSavedTextColKey, curTitleCol, OBJC_ASSOCIATION_RETAIN_NONATOMIC);
                saved = curTitleCol;
            }
            if (saved) [btn setTitleColor:darkInk forState:UIControlStateNormal];
            if (!objc_getAssociatedObject(btn, DramaSurfaceSavedTintColKey) && btn.tintColor) {
                objc_setAssociatedObject(btn, DramaSurfaceSavedTintColKey, btn.tintColor, OBJC_ASSOCIATION_RETAIN_NONATOMIC);
            }
            btn.tintColor = darkInk;
        } else {
            if (saved) {
                [btn setTitleColor:saved forState:UIControlStateNormal];
                objc_setAssociatedObject(btn, DramaSurfaceSavedTextColKey, nil, OBJC_ASSOCIATION_RETAIN_NONATOMIC);
            }
            UIColor *savedTint = objc_getAssociatedObject(btn, DramaSurfaceSavedTintColKey);
            if (savedTint) {
                btn.tintColor = savedTint;
                objc_setAssociatedObject(btn, DramaSurfaceSavedTintColKey, nil, OBJC_ASSOCIATION_RETAIN_NONATOMIC);
            }
        }
    } else if ([view isKindOfClass:UIImageView.class]) {
        UIImageView *iv = (UIImageView *)view;
        CGRect vb = iv.bounds;
        BOOL smallGlyph = (CGRectGetWidth(vb) >= 8.0 && CGRectGetWidth(vb) <= 44.0 &&
                           CGRectGetHeight(vb) >= 8.0 && CGRectGetHeight(vb) <= 44.0);
        UIImage *savedImg = objc_getAssociatedObject(iv, DramaSurfaceSavedImgKey);
        if (active && smallGlyph) {
            if (!savedImg && iv.image) {
                objc_setAssociatedObject(iv, DramaSurfaceSavedImgKey, iv.image, OBJC_ASSOCIATION_RETAIN_NONATOMIC);
                if (iv.tintColor) {
                    objc_setAssociatedObject(iv, DramaSurfaceSavedTintColKey, iv.tintColor, OBJC_ASSOCIATION_RETAIN_NONATOMIC);
                }
                iv.image = [iv.image imageWithRenderingMode:UIImageRenderingModeAlwaysTemplate];
            }
            if (iv.image) iv.tintColor = darkInk;
        } else if (!active && savedImg) {
            iv.image = savedImg;
            UIColor *savedTint = objc_getAssociatedObject(iv, DramaSurfaceSavedTintColKey);
            if (savedTint) iv.tintColor = savedTint;
            objc_setAssociatedObject(iv, DramaSurfaceSavedImgKey, nil, OBJC_ASSOCIATION_RETAIN_NONATOMIC);
            objc_setAssociatedObject(iv, DramaSurfaceSavedTintColKey, nil, OBJC_ASSOCIATION_RETAIN_NONATOMIC);
        }
    }
    for (UIView *sub in view.subviews) {
        FQXApplyDramaButtonVideoInkTree(sub, glass, active, depth + 1);
    }
}

static const char FQXK_DramaSurfaceRoseGlassViewKey = 0;
#define DramaSurfaceRoseGlassViewKey ((const void *)&FQXK_DramaSurfaceRoseGlassViewKey)
static const char FQXK_DramaActionRoseGlassViewKey = 0;
#define DramaActionRoseGlassViewKey ((const void *)&FQXK_DramaActionRoseGlassViewKey)

static void FQXApplyDramaGlassButtonSurface(UIView *glass, UIView *owner) {
    if (![glass isKindOfClass:UIButton.class] || ![owner isKindOfClass:UIView.class]) return;
    UIButton *btn = (UIButton *)glass;
    NSInteger surfMode = FQXDramaButtonSurfaceStyleMode();
    BOOL lightBase = (surfMode != FQXDramaButtonSurfaceDefaultGlass);
    NSNumber *applied = objc_getAssociatedObject(btn, DramaSurfaceAppliedVideoBaseKey);
    NSInteger prevMode = applied ? applied.integerValue : 0;
    BOOL reduce = UIAccessibilityIsReduceTransparencyEnabled();
    UIVisualEffectView *roseGlass = objc_getAssociatedObject(btn, DramaSurfaceRoseGlassViewKey);

    if (surfMode == FQXDramaButtonSurfaceVideoBase) {
        if (roseGlass) {
            [roseGlass removeFromSuperview];
            objc_setAssociatedObject(btn, DramaSurfaceRoseGlassViewKey, nil, OBJC_ASSOCIATION_RETAIN_NONATOMIC);
        }
        if (!applied || prevMode != FQXDramaButtonSurfaceVideoBase) {
            btn.configuration = [UIButtonConfiguration plainButtonConfiguration];
            btn.overrideUserInterfaceStyle = UIUserInterfaceStyleLight;
            btn.backgroundColor = FQXVideoBaseFillUIColor();
            btn.clipsToBounds = YES;
            btn.layer.cornerCurve = kCACornerCurveContinuous;
            btn.layer.borderWidth = 0.5;
            btn.layer.borderColor = FQXVideoBaseBorderUIColor().CGColor;
            objc_setAssociatedObject(btn, DramaSurfaceAppliedVideoBaseKey, @(FQXDramaButtonSurfaceVideoBase), OBJC_ASSOCIATION_RETAIN_NONATOMIC);
        }
        CGFloat r = MIN(CGRectGetWidth(btn.bounds), CGRectGetHeight(btn.bounds)) * 0.5;
        if (r > 0.5 && fabs(btn.layer.cornerRadius - r) > 0.25) btn.layer.cornerRadius = r;
    } else if (surfMode == FQXDramaButtonSurfaceRoseMistGlass) {
        if (!applied || prevMode != FQXDramaButtonSurfaceRoseMistGlass) {
            btn.configuration = [UIButtonConfiguration plainButtonConfiguration];
            btn.overrideUserInterfaceStyle = UIUserInterfaceStyleLight;
            btn.backgroundColor = UIColor.clearColor;
            btn.clipsToBounds = NO;
            btn.layer.borderWidth = 0.0;
            btn.layer.borderColor = NULL;
            btn.layer.cornerRadius = 0.0;
            objc_setAssociatedObject(btn, DramaSurfaceAppliedVideoBaseKey, @(FQXDramaButtonSurfaceRoseMistGlass), OBJC_ASSOCIATION_RETAIN_NONATOMIC);
        }
        if (!roseGlass) {
            roseGlass = [[UIVisualEffectView alloc] initWithEffect:nil];
            roseGlass.userInteractionEnabled = NO;
            roseGlass.isAccessibilityElement = NO;
            roseGlass.accessibilityElementsHidden = YES;
            roseGlass.autoresizingMask = UIViewAutoresizingFlexibleWidth | UIViewAutoresizingFlexibleHeight;
            roseGlass.backgroundColor = UIColor.clearColor;
            roseGlass.contentView.backgroundColor = UIColor.clearColor;
            roseGlass.contentView.layer.cornerCurve = kCACornerCurveContinuous;
            roseGlass.contentView.layer.borderWidth = 0.5;
            roseGlass.contentView.layer.borderColor = FQXRoseMistGlassBaseBorderUIColor().CGColor;
            roseGlass.contentView.clipsToBounds = YES;
            objc_setAssociatedObject(roseGlass, FQXOwnedGlassElementKey, @YES, OBJC_ASSOCIATION_RETAIN_NONATOMIC);
            objc_setAssociatedObject(btn, DramaSurfaceRoseGlassViewKey, roseGlass, OBJC_ASSOCIATION_RETAIN_NONATOMIC);
        }
        if (roseGlass.overrideUserInterfaceStyle != UIUserInterfaceStyleLight) {
            roseGlass.overrideUserInterfaceStyle = UIUserInterfaceStyleLight;
        }
        if (!roseGlass.effect || [roseGlass.effect isKindOfClass:UIBlurEffect.class]) {
            roseGlass.effect = FQXMakeGlassEffect(reduce ? 0 : 1, YES, FQXRoseMistGlassBaseTintUIColor());
        }
        if (roseGlass.superview != btn) {
            [btn insertSubview:roseGlass atIndex:0];
        }
        if (!CGRectEqualToRect(roseGlass.frame, btn.bounds)) {
            roseGlass.frame = btn.bounds;
        }
        FQXApplyCornerConfiguration(roseGlass, 0.0, NO);
        CGFloat r = MIN(CGRectGetWidth(btn.bounds), CGRectGetHeight(btn.bounds)) * 0.5;
        if (r > 0.5 && fabs(roseGlass.contentView.layer.cornerRadius - r) > 0.25) {
            roseGlass.contentView.layer.cornerRadius = r;
        }
    } else if (prevMode != FQXDramaButtonSurfaceDefaultGlass) {
        if (roseGlass) {
            [roseGlass removeFromSuperview];
            objc_setAssociatedObject(btn, DramaSurfaceRoseGlassViewKey, nil, OBJC_ASSOCIATION_RETAIN_NONATOMIC);
        }
        SEL glassCfgSel = sel_registerName("glassButtonConfiguration");
        if ([UIButtonConfiguration respondsToSelector:glassCfgSel]) {
            btn.configuration = ((id (*)(Class, SEL))objc_msgSend)(UIButtonConfiguration.class, glassCfgSel);
        }
        FQXApplyCornerConfiguration(btn, 0.0, NO);
        btn.overrideUserInterfaceStyle = UIUserInterfaceStyleDark;
        btn.backgroundColor = UIColor.clearColor;
        btn.clipsToBounds = NO;
        btn.layer.borderWidth = 0.0;
        btn.layer.borderColor = NULL;
        btn.layer.cornerRadius = 0.0;
        objc_setAssociatedObject(btn, DramaSurfaceAppliedVideoBaseKey, @(FQXDramaButtonSurfaceDefaultGlass), OBJC_ASSOCIATION_RETAIN_NONATOMIC);
    }
    FQXApplyDramaButtonVideoInkTree(owner, glass, lightBase, 0);
}

static void FQXApplyDramaActionSurface(UIView *owner, UIImageView *glyph, UIImageView *outline, NSInteger role) {
    if (![owner isKindOfClass:UIView.class]) return;
    NSInteger surfMode = FQXDramaButtonSurfaceStyleMode();
    BOOL lightBase = (surfMode != FQXDramaButtonSurfaceDefaultGlass);
    UIView *disk = objc_getAssociatedObject(owner, DramaActionMatteDiskViewKey);
    UIVisualEffectView *roseGlass = objc_getAssociatedObject(owner, DramaActionRoseGlassViewKey);
    UIView *parent = [glyph isKindOfClass:UIView.class] ? glyph.superview : nil;
    CGRect gf = glyph ? glyph.frame : CGRectZero;
    BOOL validGeom = (parent != nil && CGRectGetWidth(gf) > 4.0 && CGRectGetHeight(gf) > 4.0 &&
                      !owner.hidden && !glyph.hidden);
    BOOL showMatte = (surfMode == FQXDramaButtonSurfaceVideoBase) && validGeom;
    BOOL showRoseGlass = (surfMode == FQXDramaButtonSurfaceRoseMistGlass) && validGeom;

    if (!showMatte && disk) {
        [disk removeFromSuperview];
        objc_setAssociatedObject(owner, DramaActionMatteDiskViewKey, nil, OBJC_ASSOCIATION_RETAIN_NONATOMIC);
        disk = nil;
    }
    if (!showRoseGlass && roseGlass) {
        [roseGlass removeFromSuperview];
        objc_setAssociatedObject(owner, DramaActionRoseGlassViewKey, nil, OBJC_ASSOCIATION_RETAIN_NONATOMIC);
        roseGlass = nil;
    }
    if (showMatte || showRoseGlass) {
        id storedDia = [NSUserDefaults.standardUserDefaults objectForKey:@"FanqieX.DramaActionDiameter.1"];
        CGFloat prefDia = [storedDia respondsToSelector:@selector(doubleValue)] ? (CGFloat)[storedDia doubleValue] : 50.0;
        CGFloat d = MAX(40.0, MIN(48.0, isfinite(prefDia) ? prefDia : 44.0));
        CGRect target = CGRectMake(round(CGRectGetMidX(gf) - d * 0.5), round(CGRectGetMidY(gf) - d * 0.5), d, d);
        if (showMatte) {
            if (!disk) {
                disk = [[UIView alloc] initWithFrame:target];
                disk.userInteractionEnabled = NO;
                disk.isAccessibilityElement = NO;
                disk.accessibilityElementsHidden = YES;
                disk.backgroundColor = FQXVideoBaseFillUIColor();
                disk.layer.cornerCurve = kCACornerCurveContinuous;
                disk.layer.borderWidth = 0.5;
                disk.layer.borderColor = FQXVideoBaseBorderUIColor().CGColor;
                objc_setAssociatedObject(owner, DramaActionMatteDiskViewKey, disk, OBJC_ASSOCIATION_RETAIN_NONATOMIC);
            }
            disk.layer.cornerRadius = d * 0.5;
            if (!CGRectEqualToRect(disk.frame, target)) disk.frame = target;
            if (disk.superview != parent) {
                [parent insertSubview:disk belowSubview:glyph];
            }
            disk.hidden = NO;
        } else if (showRoseGlass) {
            BOOL reduce = UIAccessibilityIsReduceTransparencyEnabled();
            if (!roseGlass) {
                roseGlass = [[UIVisualEffectView alloc] initWithEffect:nil];
                roseGlass.userInteractionEnabled = NO;
                roseGlass.isAccessibilityElement = NO;
                roseGlass.accessibilityElementsHidden = YES;
                roseGlass.backgroundColor = UIColor.clearColor;
                roseGlass.contentView.backgroundColor = UIColor.clearColor;
                roseGlass.contentView.layer.cornerCurve = kCACornerCurveContinuous;
                roseGlass.contentView.layer.borderWidth = 0.5;
                roseGlass.contentView.layer.borderColor = FQXRoseMistGlassBaseBorderUIColor().CGColor;
                roseGlass.contentView.clipsToBounds = YES;
                objc_setAssociatedObject(roseGlass, FQXOwnedGlassElementKey, @YES, OBJC_ASSOCIATION_RETAIN_NONATOMIC);
                objc_setAssociatedObject(owner, DramaActionRoseGlassViewKey, roseGlass, OBJC_ASSOCIATION_RETAIN_NONATOMIC);
            }
            if (roseGlass.overrideUserInterfaceStyle != UIUserInterfaceStyleLight) {
                roseGlass.overrideUserInterfaceStyle = UIUserInterfaceStyleLight;
            }
            if (!roseGlass.effect || [roseGlass.effect isKindOfClass:UIBlurEffect.class]) {
                roseGlass.effect = FQXMakeGlassEffect(reduce ? 0 : 1, YES, FQXRoseMistGlassBaseTintUIColor());
            }
            if (!CGRectEqualToRect(roseGlass.frame, target)) roseGlass.frame = target;
            FQXApplyCornerConfiguration(roseGlass, 0.0, NO);
            roseGlass.contentView.layer.cornerRadius = d * 0.5;
            if (roseGlass.superview != parent) {
                [parent insertSubview:roseGlass belowSubview:glyph];
            }
            roseGlass.hidden = NO;
        }
    }

    // Preserve colored liked heart (role == 2) & collected star (role == 0); darken white unselected icons.
    id model = FQXObjGet(owner, "model");
    BOOL isSelectedColored = (role == 0 && FQXBoolGet(model, "isCollected", FQXBoolGet(owner, "isCollected", NO))) ||
                             (role == 2 && FQXBoolGet(model, "isLiked", NO));
    if ([outline isKindOfClass:UIImageView.class] && outline.superview) {
        if (lightBase && !isSelectedColored) {
            outline.tintColor = FQXVideoInkUIColor(1.0);
        } else if (!lightBase && !isSelectedColored) {
            outline.tintColor = UIColor.whiteColor;
        }
    }
    if ([glyph isKindOfClass:UIImageView.class] && glyph.image) {
        BOOL hadMode = [objc_getAssociatedObject(glyph, DramaActionSavedGlyphModeKey) boolValue];
        if (lightBase && !isSelectedColored) {
            if (!hadMode) {
                objc_setAssociatedObject(glyph, DramaActionSavedGlyphModeKey, @YES, OBJC_ASSOCIATION_RETAIN_NONATOMIC);
            }
            if (glyph.image.renderingMode != UIImageRenderingModeAlwaysTemplate) {
                glyph.image = [glyph.image imageWithRenderingMode:UIImageRenderingModeAlwaysTemplate];
            }
            glyph.tintColor = FQXVideoInkUIColor(1.0);
        } else if (hadMode) {
            if (glyph.image.renderingMode == UIImageRenderingModeAlwaysTemplate) {
                glyph.image = [glyph.image imageWithRenderingMode:UIImageRenderingModeAlwaysOriginal];
            }
            objc_setAssociatedObject(glyph, DramaActionSavedGlyphModeKey, nil, OBJC_ASSOCIATION_RETAIN_NONATOMIC);
        }
    }
}

static void FQXSetWeakAssocView(id owner, const void *key, UIView *target);
static UIView *FQXGetWeakAssocView(id owner, const void *key);

static BOOL FQXIsAlignedDramaGlassButton(UIButton *btn) {
    if (![btn isKindOfClass:UIButton.class]) return NO;
    if (btn.userInteractionEnabled || btn.isAccessibilityElement || !btn.accessibilityElementsHidden) return NO;
    if (objc_getAssociatedObject(btn, DramaSurfaceAppliedVideoBaseKey) != nil) return YES;
    if (!btn.configuration) return NO;
    if (btn.configuration.title.length > 0 || btn.configuration.image != nil) return NO;
    if (btn.currentTitle.length > 0 || btn.currentImage != nil) return NO;
    return btn.overrideUserInterfaceStyle == UIUserInterfaceStyleDark;
}

static UIView *FQXOwnerForDramaGlassButton(UIButton *glass) {
    UIView *parent = glass.superview;
    if (!parent) return nil;
    NSUInteger idx = [parent.subviews indexOfObjectIdenticalTo:glass];
    if (idx != NSNotFound && idx + 1 < parent.subviews.count) {
        UIView *above = parent.subviews[idx + 1];
        if (([above isKindOfClass:UIButton.class] || [above isKindOfClass:UIImageView.class]) &&
            !above.hidden && CGRectIntersectsRect(glass.frame, above.frame) &&
            CGRectGetWidth(parent.bounds) > CGRectGetWidth(glass.bounds) * 1.6) {
            return above;
        }
    }
    return parent;
}

static void FQXSyncDramaGlassSubtree(UIView *root, NSInteger depth) {
    if (![root isKindOfClass:UIView.class] || depth > 4) return;
    if ([root isKindOfClass:UIButton.class] && FQXIsAlignedDramaGlassButton((UIButton *)root)) {
        UIView *owner = FQXOwnerForDramaGlassButton((UIButton *)root);
        if (owner) {
            [FQXTrackedDramaSurfaceOwners() addObject:owner];
            FQXSetWeakAssocView(owner, DramaSurfaceGlassRefKey, root);
            FQXApplyDramaGlassButtonSurface(root, owner);
        }
        return;
    }
    for (UIView *sub in root.subviews) {
        FQXSyncDramaGlassSubtree(sub, depth + 1);
    }
}

static void FQXSyncDramaActionControl(UIView *owner, const char *glyphProp, NSInteger role) {
    if (![owner isKindOfClass:UIView.class]) return;
    id rawGlyph = glyphProp ? FQXObjGet(owner, glyphProp) : nil;
    UIImageView *glyph = [rawGlyph isKindOfClass:UIImageView.class] ? (UIImageView *)rawGlyph : nil;
    UIImageView *outline = nil;
    UIView *gParent = glyph ? glyph.superview : nil;
    if (gParent) {
        for (UIView *sub in gParent.subviews) {
            if (sub != glyph && [sub isKindOfClass:UIImageView.class] &&
                !sub.userInteractionEnabled && !sub.isAccessibilityElement && sub.accessibilityElementsHidden &&
                CGRectIntersectsRect(sub.frame, glyph.frame)) {
                outline = (UIImageView *)sub;
                break;
            }
        }
    }
    [FQXTrackedDramaActionSurfaceOwners() addObject:owner];
    if (glyph) FQXSetWeakAssocView(owner, DramaActionGlyphRefKey, glyph);
    if (outline) FQXSetWeakAssocView(owner, DramaActionOutlineRefKey, outline);
    objc_setAssociatedObject(owner, DramaActionRoleNumKey, @(role), OBJC_ASSOCIATION_RETAIN_NONATOMIC);
    FQXApplyDramaActionSurface(owner, glyph, outline, role);
}

static void FQXScanWindowForDramaButtonSurfaces(UIView *view, NSInteger depth) {
    if (![view isKindOfClass:UIView.class] || depth > 10) return;
    const char *cn = class_getName(object_getClass(view));
    if (cn) {
        if (strcmp(cn, "SSShortVideoRightInteractionCollectView") == 0) {
            FQXSyncDramaActionControl(view, "starIcon", 0);
            return;
        }
        if (strcmp(cn, "SSShortVideoRightInteractionCommentView") == 0 ||
            strcmp(cn, "SSShortVideoHostRightInteractionCommentView") == 0) {
            FQXSyncDramaActionControl(view, "commentIcon", 1);
            return;
        }
        if (strcmp(cn, "SSShortVideoRightInteractionLikeView") == 0) {
            FQXSyncDramaActionControl(view, "likeIcon", 2);
            return;
        }
        if (strcmp(cn, "SSShortVideoRightInteractionShareView") == 0) {
            FQXSyncDramaActionControl(view, "shareIcon", 3);
            return;
        }
        if (strncmp(cn, "SSShortVideo", 12) == 0 || strncmp(cn, "FQVShortVideo", 13) == 0 ||
            strncmp(cn, "FQCShortVideo", 13) == 0 || strncmp(cn, "FQVLandscapeAdjust", 18) == 0) {
            FQXSyncDramaGlassSubtree(view, 0);
        }
    }
    for (UIView *sub in view.subviews) {
        FQXScanWindowForDramaButtonSurfaces(sub, depth + 1);
    }
}

static void FQXRefreshAllDramaButtonSurfaces(void) {
    for (UIView *owner in FQXTrackedDramaSurfaceOwners().allObjects) {
        UIView *glass = FQXGetWeakAssocView(owner, DramaSurfaceGlassRefKey);
        if (glass && glass.superview) {
            FQXApplyDramaGlassButtonSurface(glass, owner);
        } else {
            FQXApplyDramaButtonVideoInkTree(owner, glass, NO, 0);
        }
    }
    for (UIView *owner in FQXTrackedDramaActionSurfaceOwners().allObjects) {
        UIImageView *glyph = (UIImageView *)FQXGetWeakAssocView(owner, DramaActionGlyphRefKey);
        UIImageView *outline = (UIImageView *)FQXGetWeakAssocView(owner, DramaActionOutlineRefKey);
        NSNumber *roleNum = objc_getAssociatedObject(owner, DramaActionRoleNumKey);
        FQXApplyDramaActionSurface(owner, glyph, outline, roleNum ? roleNum.integerValue : -1);
    }
    for (UIScene *scene in UIApplication.sharedApplication.connectedScenes) {
        if (![scene isKindOfClass:UIWindowScene.class]) continue;
        for (UIWindow *win in ((UIWindowScene *)scene).windows) {
            if (!win.hidden && win.alpha > 0.01) {
                FQXScanWindowForDramaButtonSurfaces(win, 0);
            }
        }
    }
}

static void FQXInstallDramaGlassVoidPostHook(const char *clsName, const char *selName) {
    Class cls = objc_lookUpClass(clsName);
    if (!cls) return;
    SEL sel = sel_registerName(selName);
    __block IMP orig = NULL;
    IMP hook = imp_implementationWithBlock(^(id self) {
        if (orig) ((void (*)(id, SEL))orig)(self, sel);
        if ([self isKindOfClass:UIView.class]) {
            FQXSyncDramaGlassSubtree((UIView *)self, 0);
        } else {
            id navBar = FQXObjGet(self, "navBar");
            if ([navBar isKindOfClass:UIView.class]) FQXSyncDramaGlassSubtree((UIView *)navBar, 0);
            id itemView = FQXObjGet(self, "view");
            if ([itemView isKindOfClass:UIView.class]) FQXSyncDramaGlassSubtree((UIView *)itemView, 0);
        }
    });
    if (!FQXInstallOwnedHook(cls, sel, NO, "v16@0:8", hook, &orig)) {
        imp_removeBlock(hook);
    }
}

static void FQXInstallDramaGlassObjPostHook(const char *clsName, const char *selName) {
    Class cls = objc_lookUpClass(clsName);
    if (!cls) return;
    SEL sel = sel_registerName(selName);
    __block IMP orig = NULL;
    IMP hook = imp_implementationWithBlock(^(id self, id arg) {
        if (orig) ((void (*)(id, SEL, id))orig)(self, sel, arg);
        if ([self isKindOfClass:UIView.class]) {
            FQXSyncDramaGlassSubtree((UIView *)self, 0);
        } else {
            id navBar = FQXObjGet(self, "navBar");
            if ([navBar isKindOfClass:UIView.class]) FQXSyncDramaGlassSubtree((UIView *)navBar, 0);
        }
    });
    if (!FQXInstallOwnedHook(cls, sel, NO, "v24@0:8@16", hook, &orig)) {
        imp_removeBlock(hook);
    }
}

static void FQXInstallDramaButtonSurfaceHooks(void) {
    static const struct { const char *cls; const char *sel; } kVoidGlassHooks[] = {
        {"SSShortVideoBottomDistributionView", "layoutSubviews"},
        {"SSShortVideoAlbumSeriesBottomInsertView", "layoutSubviews"},
        {"SSShortVideoAlbumSeriesBottomInsertView", "updateAdaptiveSubViews"},
        {"SSShortVideoOriginalNovelEntranceView", "layoutSubviews"},
        {"SSShortVideoSingleBottomInsertView", "layoutSubviews"},
        {"SSShortVideoTagListBottomInsertView", "layoutSubviews"},
        {"FQVShortVideoPlayerBottomView", "layoutSubviews"},
        {"FQCShortVideoDanmakuEntranceView", "layoutSubviews"},
        {"FQCShortVideoDanmakuEntranceView", "refreshIcon"},
        {"FQVShortVideoPlayerLandscapeBaseInfoView", "layoutSubviews"},
        {"FQVShortVideoPlayerLandscapeBaseControlView", "layoutSubviews"},
        {"FQVShortVideoLandscapeNavBar", "layoutSubviews"},
        {"FQVShortVideoLandscapeNavBar", "refreshLayout"},
        {"FQVShortVideoLandscapeBottomRightView", "layoutSubviews"},
        {"SSShortVideoLandscapeBizInteractionView", "layoutSubviews"},
        {"SSShortVideoLandscapeBizInteractionView", "refreshUI"},
        {"SSShortVideoLandscapeAutoInflowTipView", "layoutSubviews"},
        {"FQVLandscapeAdjustButtonBase", "layoutSubviews"},
        {"FQVShortVideoListVCNavBarComponent", "updateNavgationBarLeftView"},
        {"FQVShortVideoMoreBtnNavBarItem", "setUp"},
    };
    for (size_t i = 0; i < sizeof(kVoidGlassHooks) / sizeof(kVoidGlassHooks[0]); ++i) {
        FQXInstallDramaGlassVoidPostHook(kVoidGlassHooks[i].cls, kVoidGlassHooks[i].sel);
    }
    FQXInstallDramaGlassObjPostHook("SSShortVideoBottomDistributionView", "renderWithModel:");
    FQXInstallDramaGlassObjPostHook("FQVShortVideoListVCNavBarComponent", "setupLayout:");
    FQXInstallDramaGlassObjPostHook("FQVShortVideoListVCNavBarComponent", "updateNavgationBarRightViewWithRightItems:");

    Class bizCls = objc_lookUpClass("SSShortVideoLandscapeBizInteractionView");
    if (bizCls) {
        SEL sel = sel_registerName("danmakuSwitchDidChange:");
        __block IMP orig = NULL;
        IMP hook = imp_implementationWithBlock(^(id self, BOOL enabled) {
            if (orig) ((void (*)(id, SEL, BOOL))orig)(self, sel, enabled);
            if ([self isKindOfClass:UIView.class]) FQXSyncDramaGlassSubtree((UIView *)self, 0);
        });
        if (!FQXInstallOwnedHook(bizCls, sel, NO, "v20@0:8B16", hook, &orig)) imp_removeBlock(hook);
    }
    Class navCompCls = objc_lookUpClass("FQVShortVideoListVCNavBarComponent");
    if (navCompCls) {
        SEL sel = sel_registerName("updateNavgationBarRightView:showItemValue:");
        __block IMP orig = NULL;
        IMP hook = imp_implementationWithBlock(^(id self, id ctx, NSUInteger val) {
            if (orig) ((void (*)(id, SEL, id, NSUInteger))orig)(self, sel, ctx, val);
            id navBar = FQXObjGet(self, "navBar");
            if ([navBar isKindOfClass:UIView.class]) FQXSyncDramaGlassSubtree((UIView *)navBar, 0);
        });
        if (!FQXInstallOwnedHook(navCompCls, sel, NO, "v32@0:8@16Q24", hook, &orig)) imp_removeBlock(hook);
    }

    // Right-rail interaction buttons: collect, like, share (comment is wired in HookDramaCommentLayout / HookHostDramaCommentLayout)
    Class collectCls = objc_lookUpClass("SSShortVideoRightInteractionCollectView");
    if (collectCls) {
        SEL s1 = @selector(layoutSubviews);
        __block IMP o1 = NULL;
        IMP h1 = imp_implementationWithBlock(^(id self) {
            if (o1) ((void (*)(id, SEL))o1)(self, s1);
            FQXSyncDramaActionControl(self, "starIcon", 0);
        });
        if (!FQXInstallOwnedHook(collectCls, s1, NO, "v16@0:8", h1, &o1)) imp_removeBlock(h1);

        SEL s2 = sel_registerName("refreshUIWithModel:animated:");
        __block IMP o2 = NULL;
        IMP h2 = imp_implementationWithBlock(^(id self, id model, BOOL animated) {
            if (o2) ((void (*)(id, SEL, id, BOOL))o2)(self, s2, model, animated);
            FQXSyncDramaActionControl(self, "starIcon", 0);
        });
        if (!FQXInstallOwnedHook(collectCls, s2, NO, "v28@0:8@16B24", h2, &o2)) imp_removeBlock(h2);
    }
    Class likeCls = objc_lookUpClass("SSShortVideoRightInteractionLikeView");
    if (likeCls) {
        SEL s1 = @selector(layoutSubviews);
        __block IMP o1 = NULL;
        IMP h1 = imp_implementationWithBlock(^(id self) {
            if (o1) ((void (*)(id, SEL))o1)(self, s1);
            FQXSyncDramaActionControl(self, "likeIcon", 2);
        });
        if (!FQXInstallOwnedHook(likeCls, s1, NO, "v16@0:8", h1, &o1)) imp_removeBlock(h1);

        SEL s2 = sel_registerName("refreshUIWithModel:");
        __block IMP o2 = NULL;
        IMP h2 = imp_implementationWithBlock(^(id self, id model) {
            if (o2) ((void (*)(id, SEL, id))o2)(self, s2, model);
            FQXSyncDramaActionControl(self, "likeIcon", 2);
        });
        if (!FQXInstallOwnedHook(likeCls, s2, NO, "v24@0:8@16", h2, &o2)) imp_removeBlock(h2);

        SEL s3 = sel_registerName("updateLikeIconHidden:");
        __block IMP o3 = NULL;
        IMP h3 = imp_implementationWithBlock(^(id self, BOOL hidden) {
            if (o3) ((void (*)(id, SEL, BOOL))o3)(self, s3, hidden);
            FQXSyncDramaActionControl(self, "likeIcon", 2);
        });
        if (!FQXInstallOwnedHook(likeCls, s3, NO, "v20@0:8B16", h3, &o3)) imp_removeBlock(h3);
    }
    Class shareCls = objc_lookUpClass("SSShortVideoRightInteractionShareView");
    if (shareCls) {
        SEL s1 = @selector(layoutSubviews);
        __block IMP o1 = NULL;
        IMP h1 = imp_implementationWithBlock(^(id self) {
            if (o1) ((void (*)(id, SEL))o1)(self, s1);
            FQXSyncDramaActionControl(self, "shareIcon", 3);
        });
        if (!FQXInstallOwnedHook(shareCls, s1, NO, "v16@0:8", h1, &o1)) imp_removeBlock(h1);
    }
    Class actionStyleCls = objc_lookUpClass("FQXDramaActionStyle");
    if (actionStyleCls) {
        SEL s1 = sel_registerName("refresh");
        __block IMP o1 = NULL;
        IMP h1 = imp_implementationWithBlock(^(id self) {
            if (o1) ((void (*)(id, SEL))o1)(self, s1);
            FQXRefreshAllDramaButtonSurfaces();
        });
        if (!FQXInstallOwnedHook(actionStyleCls, s1, YES, "v16@0:8", h1, &o1)) imp_removeBlock(h1);

        SEL s2 = sel_registerName("refreshOwner:");
        __block IMP o2 = NULL;
        IMP h2 = imp_implementationWithBlock(^(id self, id owner) {
            if (o2) ((void (*)(id, SEL, id))o2)(self, s2, owner);
            if ([owner isKindOfClass:UIView.class]) {
                const char *cn = class_getName(object_getClass(owner));
                if (cn && strcmp(cn, "SSShortVideoRightInteractionCollectView") == 0) FQXSyncDramaActionControl(owner, "starIcon", 0);
                else if (cn && strcmp(cn, "SSShortVideoRightInteractionLikeView") == 0) FQXSyncDramaActionControl(owner, "likeIcon", 2);
                else if (cn && strcmp(cn, "SSShortVideoRightInteractionShareView") == 0) FQXSyncDramaActionControl(owner, "shareIcon", 3);
                else FQXSyncDramaActionControl(owner, "commentIcon", 1);
            }
        });
        if (!FQXInstallOwnedHook(actionStyleCls, s2, YES, "v24@0:8@16", h2, &o2)) imp_removeBlock(h2);

        SEL s3 = sel_registerName("syncActionModel:");
        __block IMP o3 = NULL;
        IMP h3 = imp_implementationWithBlock(^(id self, id model) {
            if (o3) ((void (*)(id, SEL, id))o3)(self, s3, model);
            FQXRefreshAllDramaButtonSurfaces();
        });
        if (!FQXInstallOwnedHook(actionStyleCls, s3, YES, "v24@0:8@16", h3, &o3)) imp_removeBlock(h3);
    }
}

