static Class FQXRealHookClass(id obj) {
    if (!obj) return Nil;
    Class cls = [obj class];
    if (!cls) cls = object_getClass(obj);
    while (cls && strncmp(class_getName(cls), "NSKVONotifying_", 15) == 0) {
        cls = class_getSuperclass(cls);
    }
    return cls;
}

