static void FQXInstallMineLayoutHooks(UICollectionViewLayout *layout) {
    if (!layout) return;
    static NSMutableSet<NSString *> *installedSize;
    static NSMutableSet<NSString *> *installedItem;
    static NSMutableSet<NSString *> *installedRect;
    static NSMutableSet<NSString *> *installedBounds;
    static NSMutableSet<NSString *> *installedTargetOffset;
    static dispatch_once_t once;
    dispatch_once(&once, ^{
        installedSize = [NSMutableSet set];
        installedItem = [NSMutableSet set];
        installedRect = [NSMutableSet set];
        installedBounds = [NSMutableSet set];
        installedTargetOffset = [NSMutableSet set];
        gFQXMineLayoutOrigItemMap = [NSMutableDictionary dictionary];
    });
    Class cls = FQXRealHookClass(layout);
    if (!cls || cls == UIView.class || cls == NSObject.class) return;
    NSString *name = NSStringFromClass(cls);
    if (!name.length) return;

    if (![installedSize containsObject:name]) {
        SEL sel = @selector(collectionViewContentSize);
        __block IMP origSize = NULL;
        IMP sizeHook = imp_implementationWithBlock(^CGSize(UICollectionViewLayout *owner) {
            UICollectionView *cv = owner.collectionView;
            FQXMineShortcutFlowState *state = cv ? objc_getAssociatedObject(cv, FQXMineFlowStateKey) : nil;
            if (state && state->_active && state->_layout == owner &&
                state->_pages > 0 && state->_viewportSize.width > 0.0 && state->_viewportHeight > 0.0) {
                return CGSizeMake(state->_viewportSize.width * (CGFloat)state->_pages, state->_viewportHeight);
            }
            return ((CGSize (*)(id, SEL))origSize)(owner, sel);
        });
        if (FQXInstallMineValidatedHook(cls, sel, 2, "{CGSize", NULL, sizeHook, &origSize)) {
            [installedSize addObject:name];
        } else {
            imp_removeBlock(sizeHook);
        }
    }

    if (![installedItem containsObject:name]) {
        SEL sel = @selector(layoutAttributesForItemAtIndexPath:);
        __block IMP origItem = NULL;
        IMP itemHook = imp_implementationWithBlock(^UICollectionViewLayoutAttributes *(
            UICollectionViewLayout *owner, NSIndexPath *indexPath) {
            UICollectionViewLayoutAttributes *native =
                ((UICollectionViewLayoutAttributes *(*)(id, SEL, id))origItem)(owner, sel, indexPath);
            UICollectionView *cv = owner.collectionView;
            FQXMineShortcutFlowState *state = cv ? objc_getAssociatedObject(cv, FQXMineFlowStateKey) : nil;
            if (!state || !state->_active || state->_layout != owner ||
                !state->_columns || state->_slotWidth < 44.0) {
                return native;
            }
            NSUInteger flatIdx = FQXMineFlatIndexForIndexPath(cv, indexPath);
            if (flatIdx == NSNotFound) return native;
            UICollectionViewLayoutAttributes *attrs = native
                ? [native copy]
                : [UICollectionViewLayoutAttributes layoutAttributesForCellWithIndexPath:indexPath];
            attrs.frame = FQXMineFrameForFlatIndex(state, flatIdx);
            attrs.hidden = NO;
            attrs.alpha = 1.0;
            return attrs;
        });
        if (FQXInstallMineValidatedHook(cls, sel, 3, "@", NULL, itemHook, &origItem)) {
            [installedItem addObject:name];
            if (origItem) gFQXMineLayoutOrigItemMap[name] = [NSValue valueWithPointer:origItem];
        } else {
            imp_removeBlock(itemHook);
        }
    }

    if (![installedRect containsObject:name]) {
        SEL sel = @selector(layoutAttributesForElementsInRect:);
        __block IMP origRect = NULL;
        IMP rectHook = imp_implementationWithBlock(^NSArray<UICollectionViewLayoutAttributes *> *(
            UICollectionViewLayout *owner, CGRect rect) {
            NSArray<UICollectionViewLayoutAttributes *> *native =
                ((NSArray *(*)(id, SEL, CGRect))origRect)(owner, sel, rect);
            UICollectionView *cv = owner.collectionView;
            FQXMineShortcutFlowState *state = cv ? objc_getAssociatedObject(cv, FQXMineFlowStateKey) : nil;
            if (!state || !state->_active || state->_layout != owner ||
                !state->_columns || state->_slotWidth < 44.0) {
                return native;
            }
            NSMutableArray<UICollectionViewLayoutAttributes *> *result = [NSMutableArray array];
            for (UICollectionViewLayoutAttributes *attr in native) {
                if (attr.representedElementCategory != UICollectionElementCategoryCell) {
                    [result addObject:[attr copy]];
                }
            }
            NSInteger sections = [cv numberOfSections];
            NSUInteger flatIdx = 0;
            for (NSInteger s = 0; s < sections; ++s) {
                NSInteger countInSec = [cv numberOfItemsInSection:s];
                for (NSInteger item = 0; item < countInSec; ++item) {
                    CGRect frame = FQXMineFrameForFlatIndex(state, flatIdx);
                    if (CGRectIntersectsRect(frame, rect)) {
                        NSIndexPath *ip = [NSIndexPath indexPathForItem:item inSection:s];
                        UICollectionViewLayoutAttributes *cellAttr = [owner layoutAttributesForItemAtIndexPath:ip];
                        if (cellAttr) [result addObject:cellAttr];
                    }
                    flatIdx++;
                }
            }
            return result;
        });
        if (FQXInstallMineValidatedHook(cls, sel, 3, "@", NULL, rectHook, &origRect)) {
            [installedRect addObject:name];
        } else {
            imp_removeBlock(rectHook);
        }
    }

    if (![installedBounds containsObject:name]) {
        SEL sel = @selector(shouldInvalidateLayoutForBoundsChange:);
        __block IMP origBounds = NULL;
        IMP boundsHook = imp_implementationWithBlock(^BOOL(UICollectionViewLayout *owner, CGRect newBounds) {
            UICollectionView *cv = owner.collectionView;
            FQXMineShortcutFlowState *state = cv ? objc_getAssociatedObject(cv, FQXMineFlowStateKey) : nil;
            if (state && state->_active && state->_layout == owner) return YES;
            return ((BOOL (*)(id, SEL, CGRect))origBounds)(owner, sel, newBounds);
        });
        if (FQXInstallMineValidatedHook(cls, sel, 3, "B", "c", boundsHook, &origBounds)) {
            [installedBounds addObject:name];
        } else {
            imp_removeBlock(boundsHook);
        }
    }

    if (![installedTargetOffset containsObject:name]) {
        SEL sel = @selector(targetContentOffsetForProposedContentOffset:withScrollingVelocity:);
        __block IMP origOffset = NULL;
        IMP offsetHook = imp_implementationWithBlock(^CGPoint(UICollectionViewLayout *owner,
                                                              CGPoint proposed, CGPoint velocity) {
            CGPoint native = ((CGPoint (*)(id, SEL, CGPoint, CGPoint))origOffset)(owner, sel, proposed, velocity);
            UICollectionView *cv = owner.collectionView;
            FQXMineShortcutFlowState *state = cv ? objc_getAssociatedObject(cv, FQXMineFlowStateKey) : nil;
            if (state && state->_active && state->_layout == owner && state->_pages > 0 && state->_viewportSize.width > 1.0) {
                CGFloat vw = state->_viewportSize.width;
                NSInteger page = (NSInteger)llround(proposed.x / vw);
                if (page < 0) page = 0;
                if (page >= (NSInteger)state->_pages) page = (NSInteger)state->_pages - 1;
                return CGPointMake((CGFloat)page * vw, native.y);
            }
            return native;
        });
        if (FQXInstallMineValidatedHook(cls, sel, 4, "{CGPoint", NULL, offsetHook, &origOffset)) {
            [installedTargetOffset addObject:name];
        } else {
            imp_removeBlock(offsetHook);
        }
    }
}

static void FQXEnforceMineVisibleCellFrames(UICollectionView *collection) {
    FQXMineShortcutFlowState *state = objc_getAssociatedObject(collection, FQXMineFlowStateKey);
    if (!state || !state->_active || state->_layout != collection.collectionViewLayout ||
        state->_columns != 4 || state->_slotWidth < 44.0) return;
    NSMutableSet<UICollectionViewCell *> *visited = [NSMutableSet set];
    for (NSIndexPath *ip in [collection indexPathsForVisibleItems]) {
        UICollectionViewCell *cell = [collection cellForItemAtIndexPath:ip];
        if (!cell) continue;
        [visited addObject:cell];
        NSUInteger flatIdx = FQXMineFlatIndexForIndexPath(collection, ip);
        if (flatIdx == NSNotFound) continue;
        CGRect expected = FQXMineFrameForFlatIndex(state, flatIdx);
        CGRect cur = cell.frame;
        if (fabs(cur.origin.x - expected.origin.x) > 0.5 ||
            fabs(cur.origin.y - expected.origin.y) > 0.5 ||
            fabs(CGRectGetWidth(cur) - CGRectGetWidth(expected)) > 0.5 ||
            fabs(CGRectGetHeight(cur) - CGRectGetHeight(expected)) > 0.5) {
            BOOL prevInFlight = FQXMineCellRelayoutInFlight;
            FQXMineCellRelayoutInFlight = YES;
            cell.frame = expected;
            FQXMineCellRelayoutInFlight = prevInFlight;
            FQXRelayoutMineTileAfterFrameChange(cell);
        }
    }
    for (UICollectionViewCell *cell in [collection visibleCells]) {
        if ([visited containsObject:cell]) continue;
        [visited addObject:cell];
        NSIndexPath *ip = [collection indexPathForCell:cell] ?: objc_getAssociatedObject(cell, FQXMineCellLastIndexPathKey);
        NSUInteger flatIdx = FQXMineFlatIndexForIndexPath(collection, ip);
        if (flatIdx == NSNotFound) continue;
        CGRect expected = FQXMineFrameForFlatIndex(state, flatIdx);
        CGRect cur = cell.frame;
        if (fabs(cur.origin.x - expected.origin.x) > 0.5 ||
            fabs(cur.origin.y - expected.origin.y) > 0.5 ||
            fabs(CGRectGetWidth(cur) - CGRectGetWidth(expected)) > 0.5 ||
            fabs(CGRectGetHeight(cur) - CGRectGetHeight(expected)) > 0.5) {
            BOOL prevInFlight = FQXMineCellRelayoutInFlight;
            FQXMineCellRelayoutInFlight = YES;
            cell.frame = expected;
            FQXMineCellRelayoutInFlight = prevInFlight;
            FQXRelayoutMineTileAfterFrameChange(cell);
        }
    }
    for (UIView *sub in [collection.subviews copy]) {
        if (!FQXIsMineShortcutItemCell(sub) || ![sub isKindOfClass:UICollectionViewCell.class]) continue;
        UICollectionViewCell *cell = (UICollectionViewCell *)sub;
        if ([visited containsObject:cell]) continue;
        NSIndexPath *ip = [collection indexPathForCell:cell] ?: objc_getAssociatedObject(cell, FQXMineCellLastIndexPathKey);
        NSUInteger flatIdx = FQXMineFlatIndexForIndexPath(collection, ip);
        if (flatIdx == NSNotFound) continue;
        CGRect expected = FQXMineFrameForFlatIndex(state, flatIdx);
        CGRect cur = cell.frame;
        if (fabs(cur.origin.x - expected.origin.x) > 0.5 ||
            fabs(cur.origin.y - expected.origin.y) > 0.5 ||
            fabs(CGRectGetWidth(cur) - CGRectGetWidth(expected)) > 0.5 ||
            fabs(CGRectGetHeight(cur) - CGRectGetHeight(expected)) > 0.5) {
            BOOL prevInFlight = FQXMineCellRelayoutInFlight;
            FQXMineCellRelayoutInFlight = YES;
            cell.frame = expected;
            FQXMineCellRelayoutInFlight = prevInFlight;
            FQXRelayoutMineTileAfterFrameChange(cell);
        }
    }
}

static void FQXRestoreMineFlow(UICollectionView *collection) {
    FQXMineShortcutFlowState *state = objc_getAssociatedObject(collection, FQXMineFlowStateKey);
    if (!state) return;
    state->_active = NO;
    objc_setAssociatedObject(collection, FQXMineDeferredSyncKey, nil, OBJC_ASSOCIATION_RETAIN_NONATOMIC);
    if (state->_layout == collection.collectionViewLayout) {
        if (state->_hasSavedFlowProps && [state->_layout isKindOfClass:UICollectionViewFlowLayout.class]) {
            UICollectionViewFlowLayout *flow = (UICollectionViewFlowLayout *)state->_layout;
            if (CGSizeEqualToSize(flow.itemSize, state->_appliedItemSize)) {
                flow.itemSize = state->_savedItemSize;
            }
            flow.estimatedItemSize = state->_savedEstimatedItemSize;
            flow.sectionInset = state->_savedSectionInset;
            flow.minimumLineSpacing = state->_savedLineSpacing;
            flow.minimumInteritemSpacing = state->_savedInteritemSpacing;
        }
        [state->_layout invalidateLayout];
    }
    if (state->_hasSavedContentInset) {
        UIEdgeInsets ins = collection.contentInset;
        ins.left = state->_savedContentInset.left;
        ins.right = state->_savedContentInset.right;
        collection.contentInset = ins;
    }
    collection.pagingEnabled = state->_savedPaging;
    FQXUpdateMinePageControl(state->_pageControl, state->_savedPageCount, 0);
    objc_setAssociatedObject(collection, FQXMineFlowStateKey, nil, OBJC_ASSOCIATION_RETAIN_NONATOMIC);
}

static void FQXCompleteMineFlowPage(UICollectionView *collection) {
    FQXMineShortcutFlowState *state = objc_getAssociatedObject(collection, FQXMineFlowStateKey);
    if (!state || !state->_active || state->_layout != collection.collectionViewLayout) return;
    NSUInteger count = FQXMineTotalItemCount(collection);
    if (!count || !state->_columns) return;
    NSUInteger pages = FQXComputeMineTotalPages(state, count);
    state->_totalCount = count;
    state->_pages = pages;
    CGFloat width = state->_viewportSize.width > 0.0 ? state->_viewportSize.width : CGRectGetWidth(collection.bounds);
    CGFloat vh = state->_viewportHeight > 0.0 ? state->_viewportHeight : CGRectGetHeight(collection.bounds);
    CGSize contentSize = CGSizeMake(width * pages, vh);
    if (!CGSizeEqualToSize(collection.contentSize, contentSize)) collection.contentSize = contentSize;
    if (state->_pageControl) {
        NSInteger cur = MAX(0, MIN((NSInteger)pages - 1,
            (NSInteger)llround(collection.contentOffset.x / MAX(1.0, width))));
        FQXUpdateMinePageControl(state->_pageControl, (NSInteger)pages, cur);
    }
}

static void FQXInstallMineScrollHook(UICollectionView *collection);
static void FQXSyncMineFlow(UICollectionView *collection);

static void FQXScheduleDeferredMineCollectionPass(UICollectionView *collection) {
    if (!collection || [objc_getAssociatedObject(collection, FQXMineDeferredSyncKey) boolValue]) return;
    objc_setAssociatedObject(collection, FQXMineDeferredSyncKey, @YES, OBJC_ASSOCIATION_RETAIN_NONATOMIC);
    __weak UICollectionView *weakCV = collection;
    dispatch_async(dispatch_get_main_queue(), ^{
        UICollectionView *strongCV = weakCV;
        if (!strongCV) return;
        objc_setAssociatedObject(strongCV, FQXMineDeferredSyncKey, nil, OBJC_ASSOCIATION_RETAIN_NONATOMIC);
        if (!strongCV.window || !FQXMineShortcutCardForView(strongCV)) return;
        FQXMineShortcutFlowState *st = objc_getAssociatedObject(strongCV, FQXMineFlowStateKey);
        if ((!st || !st->_active || st->_layout != strongCV.collectionViewLayout) &&
            !FQXMineViewportSyncInFlight && CGRectGetWidth(strongCV.bounds) >= 176.0) {
            FQXMineViewportSyncInFlight = YES;
            FQXInstallMineScrollHook(strongCV);
            FQXSyncMineFlow(strongCV);
            FQXMineViewportSyncInFlight = NO;
            st = objc_getAssociatedObject(strongCV, FQXMineFlowStateKey);
        }
        if (!st || !st->_active || st->_layout != strongCV.collectionViewLayout) return;
        [st->_layout invalidateLayout];
        [strongCV setNeedsLayout];
        [strongCV layoutIfNeeded];
        FQXEnforceMineVisibleCellFrames(strongCV);
        FQXCompleteMineFlowPage(strongCV);
    });
}

static IMP FQXLookupMineOrigItemIMP(UICollectionViewLayout *layout) {
    if (!layout || !gFQXMineLayoutOrigItemMap) return NULL;
    for (Class c = FQXRealHookClass(layout); c && c != NSObject.class; c = class_getSuperclass(c)) {
        NSString *cn = NSStringFromClass(c);
        if (!cn.length) continue;
        NSValue *v = gFQXMineLayoutOrigItemMap[cn];
        if (v) return (IMP)v.pointerValue;
    }
    return NULL;
}

static const char FQXMineFoldFirstPageBandKey = 0;

static UICollectionViewLayoutAttributes *FQXCenterMineFoldItem(
    UICollectionViewLayoutAttributes *attributes, CGRect band, NSInteger columns) {
    if (!attributes || CGRectIsNull(band) || attributes.indexPath.section != 0 ||
        attributes.indexPath.item >= columns) return attributes;
    CGRect frame = attributes.frame;
    CGFloat slotWidth = CGRectGetWidth(band) / columns;
    if (slotWidth < CGRectGetWidth(frame)) return attributes;
    CGFloat centerX = CGRectGetMinX(band) + (attributes.indexPath.item + 0.5) * slotWidth;
    frame.origin.x = centerX - CGRectGetWidth(frame) * 0.5;
    if (CGRectGetHeight(band) >= CGRectGetHeight(frame)) {
        frame.origin.y = CGRectGetMidY(band) - CGRectGetHeight(frame) * 0.5;
    }
    if (CGRectEqualToRect(frame, attributes.frame)) return attributes;
    UICollectionViewLayoutAttributes *effective = [attributes copy];
    effective.frame = frame;
    return effective;
}

static UICollectionViewLayoutAttributes *(*OrigMineFoldItemAttributes)(id, SEL, NSIndexPath *);
static UICollectionViewLayoutAttributes *HookMineFoldItemAttributes(
    UICollectionViewLayout *layout, SEL cmd, NSIndexPath *indexPath) {
    UICollectionViewLayoutAttributes *native = OrigMineFoldItemAttributes(layout, cmd, indexPath);
    UICollectionView *collection = layout.collectionView;
    NSValue *band = objc_getAssociatedObject(collection, &FQXMineFoldFirstPageBandKey);
    if (!native || !band || indexPath.section != 0) return native;
    return FQXCenterMineFoldItem(native, band.CGRectValue, MIN(4, [collection numberOfItemsInSection:0]));
}

static NSArray<UICollectionViewLayoutAttributes *> *(*OrigMineFoldRectAttributes)(id, SEL, CGRect);
static NSArray<UICollectionViewLayoutAttributes *> *HookMineFoldRectAttributes(
    UICollectionViewLayout *layout, SEL cmd, CGRect rect) {
    NSArray<UICollectionViewLayoutAttributes *> *native = OrigMineFoldRectAttributes(layout, cmd, rect);
    UICollectionView *collection = layout.collectionView;
    NSValue *bandValue = objc_getAssociatedObject(collection, &FQXMineFoldFirstPageBandKey);
    if (!bandValue || collection.numberOfSections == 0) return native;
    CGRect band = bandValue.CGRectValue;
    NSInteger columns = MIN(4, [collection numberOfItemsInSection:0]);
    NSMutableArray<UICollectionViewLayoutAttributes *> *attributes = [NSMutableArray arrayWithCapacity:native.count];
    for (UICollectionViewLayoutAttributes *item in native) {
        if (item.representedElementCategory != UICollectionElementCategoryCell ||
            item.indexPath.section != 0 || item.indexPath.item >= columns) [attributes addObject:item];
    }
    for (NSInteger column = 0; column < columns; ++column) {
        NSIndexPath *index = [NSIndexPath indexPathForItem:column inSection:0];
        UICollectionViewLayoutAttributes *item = [layout layoutAttributesForItemAtIndexPath:index];
        item = FQXCenterMineFoldItem(item, band, columns);
        if (item && CGRectIntersectsRect(item.frame, rect)) [attributes addObject:item];
    }
    return attributes;
}

static double FQXSafeLayoutDoubleProp(id obj, const char *selName) {
    if (!obj || !selName) return 0.0;
    SEL sel = sel_registerName(selName);
    Method m = class_getInstanceMethod(object_getClass(obj), sel);
    if (!m || strcmp(method_getTypeEncoding(m), "d16@0:8") != 0) return 0.0;
    double v = ((double (*)(id, SEL))objc_msgSend)(obj, sel);
    return isfinite(v) ? v : 0.0;
}

static CGSize FQXSafeLayoutSizeProp(id obj, const char *selName) {
    if (!obj || !selName) return CGSizeZero;
    SEL sel = sel_registerName(selName);
    Method m = class_getInstanceMethod(object_getClass(obj), sel);
    const char *enc = m ? method_getTypeEncoding(m) : NULL;
    if (!enc || strncmp(enc, "{CGSize=dd}16@0:8", 17) != 0) return CGSizeZero;
    return ((CGSize (*)(id, SEL))objc_msgSend)(obj, sel);
}

static BOOL FQXUpdateMineFoldFirstPageBand(UICollectionView *collection, UIView *fold) {
    NSValue *previous = objc_getAssociatedObject(collection, &FQXMineFoldFirstPageBandKey);
    CGRect oldBand = previous ? previous.CGRectValue : CGRectNull;
    CGRect band = CGRectNull;
    if (FQXGlassEnabled()) {
        // The fold has its native size before the card's material is mounted.
        CGPoint offset = collection.bounds.origin;
        CGRect card = CGRectOffset([fold convertRect:fold.bounds toView:collection], -offset.x, -offset.y);
        CGFloat radius = 27.0;
        UIView *indicator = FQXMinePageControl(fold, fold);
        BOOL hasDots = (indicator && !indicator.hidden && indicator.alpha > 0.05);
        double dotsMinY = 0.0;
        if (hasDots) {
            CGRect dots = [indicator convertRect:indicator.bounds toView:collection];
            dotsMinY = CGRectGetMinY(dots) - offset.y;
        }
        id rawAttach = FQXObjGet(fold, "attachView");
        UIView *attachView = [rawAttach isKindOfClass:UIView.class] ? (UIView *)rawAttach : nil;
        BOOL attachVisible = (attachView != nil && !attachView.hidden && attachView.alpha > 0.01);
        double attachmentHeight = FQXSafeLayoutDoubleProp(collection.collectionViewLayout, "attachmentHeight");
        if (attachmentHeight <= 0.5 && attachVisible && CGRectGetHeight(attachView.bounds) > 4.0) {
            attachmentHeight = CGRectGetHeight(attachView.bounds);
        }
        BOOL hasAttachment = (attachVisible || attachmentHeight > 0.5);
        BOOL hasAttachRect = NO;
        double attachMinY = 0.0;
        if (attachVisible && attachView.superview && CGRectGetHeight(attachView.bounds) > 4.0 &&
            [attachView isDescendantOfView:fold]) {
            CGRect attRect = CGRectOffset([attachView convertRect:attachView.bounds toView:collection],
                                          -offset.x, -offset.y);
            if (CGRectGetHeight(attRect) > 4.0) {
                hasAttachRect = YES;
                attachMinY = CGRectGetMinY(attRect);
            }
        }
        CGSize layoutItemSize = FQXSafeLayoutSizeProp(collection.collectionViewLayout, "itemSize");
        if (CGRectGetWidth(card) > 0.0) {
            double bandY = CGRectGetMinY(card);
            double bandH = 0.0;
            FQXComputeMineFoldFirstPageBandY(
                CGRectGetMinY(card),
                CGRectGetMaxY(card),
                hasDots ? 1 : 0,
                dotsMinY,
                hasAttachment ? 1 : 0,
                hasAttachRect ? 1 : 0,
                attachMinY,
                attachmentHeight,
                layoutItemSize.height,
                radius,
                &bandY,
                &bandH);
            band = CGRectMake(CGRectGetMinX(card), bandY, CGRectGetWidth(card), bandH);
            // The fold grows on the second page; keep the first row at its folded height while swiping.
            if (previous && offset.x > 0.5 && fabs(oldBand.size.width - band.size.width) < 0.25) {
                band.origin.y = oldBand.origin.y;
                band.size.height = oldBand.size.height;
            }
        }
    }
    if (CGRectIsNull(band)) {
        if (!previous) return NO;
        objc_setAssociatedObject(collection, &FQXMineFoldFirstPageBandKey, nil, OBJC_ASSOCIATION_RETAIN_NONATOMIC);
    } else {
        if (previous && fabs(oldBand.origin.x - band.origin.x) < 0.25 &&
            fabs(oldBand.origin.y - band.origin.y) < 0.25 && fabs(oldBand.size.width - band.size.width) < 0.25 &&
            fabs(oldBand.size.height - band.size.height) < 0.25) return NO;
        objc_setAssociatedObject(collection, &FQXMineFoldFirstPageBandKey, [NSValue valueWithCGRect:band],
                                 OBJC_ASSOCIATION_RETAIN_NONATOMIC);
    }
    return YES;
}

static void FQXSyncMineFlow(UICollectionView *collection) {
    if (!FQXIsInnerMineShortcutScroll(collection)) return;
    FQXMineShortcutFlowState *state = objc_getAssociatedObject(collection, FQXMineFlowStateKey);
    UICollectionViewLayout *layout = collection.collectionViewLayout;
    UIView *fold = FQXMineShortcutFold(collection);
    Class foldLayoutClass = objc_lookUpClass("SSFuncLayout");
    if ([layout isKindOfClass:foldLayoutClass]) {
        if (!fold) return;
        // Its content-size pass sets the page rectangles used to open and size the second page.
        FQXRestoreMineFlow(collection);
        FQXSafeSetUIntProp(fold, "colCountInFirstPage", "setColCountInFirstPage:", 4);
        static dispatch_once_t nativeAttributesHookOnce;
        dispatch_once(&nativeAttributesHookOnce, ^{
            FQXInstallOwnedHook(foldLayoutClass, @selector(layoutAttributesForItemAtIndexPath:), NO, "@24@0:8@16",
                (IMP)HookMineFoldItemAttributes, (IMP *)&OrigMineFoldItemAttributes);
            FQXInstallOwnedHook(foldLayoutClass, @selector(layoutAttributesForElementsInRect:), NO,
                "@48@0:8{CGRect={CGPoint=dd}{CGSize=dd}}16", (IMP)HookMineFoldRectAttributes,
                (IMP *)&OrigMineFoldRectAttributes);
        });
        BOOL needsLayoutInvalidation = FQXUpdateMineFoldFirstPageBand(collection, fold);
        SEL gapSelector = sel_registerName("externShowGap");
        Method gapMethod = class_getInstanceMethod(object_getClass(layout), gapSelector);
        if (gapMethod && strcmp(method_getTypeEncoding(gapMethod), "d16@0:8") == 0 &&
            ((double (*)(id, SEL))objc_msgSend)(layout, gapSelector) != 0.0) {
            FQXSafeSetDoubleProp(layout, NULL, "setExternShowGap:", 0.0);
            needsLayoutInvalidation = YES;
        }
        if (needsLayoutInvalidation) [layout invalidateLayout];
        return;
    }
    UIView *card = FQXMineShortcutCardForView(collection);
    NSUInteger count = FQXMineTotalItemCount(collection);
    CGFloat width = CGRectGetWidth(collection.bounds);
    UIView *outerRow = FQXMineOuterRowForView(collection);
    if (outerRow) {
        CGFloat cardW = CGRectGetWidth(outerRow.bounds);
        for (UIView *sub in outerRow.subviews) {
            if ([sub isKindOfClass:UIVisualEffectView.class] && CGRectGetWidth(sub.bounds) >= 160.0 &&
                CGRectGetWidth(sub.bounds) < cardW) {
                cardW = CGRectGetWidth(sub.bounds);
                break;
            }
        }
        UIView *content = FQXObjGet(outerRow, "contentView");
        if ([content isKindOfClass:UIView.class]) {
            for (UIView *sub in content.subviews) {
                if ([sub isKindOfClass:UIVisualEffectView.class] && CGRectGetWidth(sub.bounds) >= 160.0 &&
                    CGRectGetWidth(sub.bounds) < cardW) {
                    cardW = CGRectGetWidth(sub.bounds);
                    break;
                }
            }
        }
        if (cardW >= 160.0 && width > cardW + 4.0) {
            width = cardW;
        } else if (fold && cardW >= 160.0 && width < cardW - 6.0 && collection.superview == fold) {
            BOOL hasRightSiblingPage = NO;
            for (UIView *sib in fold.subviews) {
                if (sib != collection && !sib.hidden && sib.alpha > 0.01 &&
                    ![sib isKindOfClass:UIVisualEffectView.class] && !FQXViewIsPageControlLike(sib) &&
                    CGRectGetWidth(sib.bounds) >= 120.0 && CGRectGetMinX(sib.frame) >= 120.0) {
                    hasRightSiblingPage = YES;
                    break;
                }
            }
            if (!hasRightSiblingPage) {
                CGRect cf = collection.frame;
                cf.size.width = cardW;
                collection.frame = cf;
                width = cardW;
            }
        }
    }
    CGFloat boundsHeight = CGRectGetHeight(collection.bounds);
    BOOL supported = card != nil && layout != nil &&
        count > 0 && count <= 40 && width >= 160.0 && boundsHeight >= 32.0 && boundsHeight <= 520.0;
    if (!supported || (state && state->_layout != layout)) {
        FQXRestoreMineFlow(collection);
        if (!supported) return;
        state = nil;
    }

    UICollectionViewFlowLayout *flow = [layout isKindOfClass:UICollectionViewFlowLayout.class]
        ? (UICollectionViewFlowLayout *)layout : nil;
    id<UICollectionViewDelegateFlowLayout> delegate = (id)collection.delegate;
    FQXInstallMineScrollSnapDelegateHook(delegate);
    UIEdgeInsets inset = flow ? flow.sectionInset : UIEdgeInsetsZero;
    if (flow && [delegate respondsToSelector:@selector(collectionView:layout:insetForSectionAtIndex:)]) {
        inset = [delegate collectionView:collection layout:flow insetForSectionAtIndex:0];
    }
    CGFloat topInset = MAX(0.0, inset.top);
    CGFloat bottomInset = MAX(0.0, inset.bottom);
    CGFloat contentHeight = boundsHeight - collection.adjustedContentInset.top - collection.adjustedContentInset.bottom;
    if (contentHeight < 32.0) contentHeight = boundsHeight;
    if (contentHeight - topInset - bottomInset < 32.0) {
        topInset = 0.0;
        bottomInset = 0.0;
    }
    CGFloat planHeight = MAX(44.0, contentHeight);
    CGFloat planTop = (planHeight - topInset - bottomInset >= 44.0) ? topInset : 0.0;
    CGFloat planBottom = (planHeight - planTop - bottomInset >= 44.0) ? bottomInset : 0.0;
    FQXMineShortcutPlan plan = FQXPlanMineShortcuts(width, planHeight, width / 5.0,
                                                    0.0, planTop, planBottom, count);
    if (!plan.valid || plan.columns != 4) {
        FQXRestoreMineFlow(collection);
        return;
    }
    CGFloat actualItemHeight = MAX(32.0, contentHeight - topInset - bottomInset);

    // Class-wide layout hooks can run before this collection has associated flow state.
    FQXInstallMineLayoutHooks(layout);
    if (flow) {
        FQXInstallMineItemSizeHook(delegate);
        FQXInstallMineSectionInsetHook(delegate);
    }

    // Probe unhooked native item frames to detect SSScrollFoldFuncView's multi-row Page 2 layout
    // (1 row of 4 shortcuts on Page 1 + 2..4 rows of 4 shortcuts starting on Page 2) or a dedicated
    // multi-row Page 2 collection view so we preserve multi-row unfolding while eliminating Page 1 peek.
    NSInteger detectedFoldKind = 0;
    BOOL detectedColMajor = NO;
    NSUInteger detectedRows = 1;
    CGFloat detectedRowPitch = 68.0;
    CGFloat detectedRowItemH = actualItemHeight;
    IMP origItemImp = FQXLookupMineOrigItemIMP(layout);
    if (origItemImp && count > 4 && !flow) {
        BOOL wasActive = state ? state->_active : NO;
        if (state) state->_active = NO;
        SEL itemSel = @selector(layoutAttributesForItemAtIndexPath:);
        NSUInteger probeCount = MIN(count, (NSUInteger)16);
        CGRect nativeFrames[16];
        BOOL validFrames[16] = {NO};
        for (NSUInteger k = 0; k < probeCount; ++k) {
            NSIndexPath *ip = FQXMineIndexPathForFlatIndex(collection, k);
            UICollectionViewLayoutAttributes *na = ip
                ? ((UICollectionViewLayoutAttributes *(*)(id, SEL, id))origItemImp)(layout, itemSel, ip)
                : nil;
            if (na && CGRectGetWidth(na.frame) >= 24.0 && CGRectGetHeight(na.frame) >= 24.0) {
                nativeFrames[k] = na.frame;
                validFrames[k] = YES;
            }
        }
        if (state) state->_active = wasActive;
        if (validFrames[0]) {
            CGFloat row0Y = CGRectGetMinY(nativeFrames[0]);
            CGFloat minNextRowY = CGFLOAT_MAX;
            CGFloat maxRowY = row0Y;
            BOOL multiRowAtPage0 = NO;
            BOOL multiRowAtPage1 = NO;
            for (NSUInteger k = 1; k < probeCount; ++k) {
                if (!validFrames[k]) continue;
                CGFloat ny = CGRectGetMinY(nativeFrames[k]);
                CGFloat nx = CGRectGetMinX(nativeFrames[k]);
                if (ny >= row0Y + 26.0) {
                    if (ny < minNextRowY) minNextRowY = ny;
                    if (ny > maxRowY) maxRowY = ny;
                    if (nx < width * 0.48) multiRowAtPage0 = YES;
                    else multiRowAtPage1 = YES;
                }
            }
            if (multiRowAtPage0 || multiRowAtPage1) {
                detectedFoldKind = multiRowAtPage0 ? 2 : 1;
                detectedRowPitch = (minNextRowY < CGFLOAT_MAX) ? MAX(46.0, minNextRowY - row0Y) : 66.0;
                detectedRows = MAX((NSUInteger)2, (NSUInteger)llround((maxRowY - row0Y) / detectedRowPitch) + 1);
                if (detectedRows > 4) detectedRows = 4;
                topInset = MAX(0.0, row0Y);
                detectedRowItemH = MAX(36.0, MIN(actualItemHeight, CGRectGetHeight(nativeFrames[0])));
                NSUInteger baseIdx = (detectedFoldKind == 1) ? 4 : 0;
                if (baseIdx + 1 < probeCount && validFrames[baseIdx] && validFrames[baseIdx + 1]) {
                    if (fabs(CGRectGetMinY(nativeFrames[baseIdx + 1]) - CGRectGetMinY(nativeFrames[baseIdx])) >= 26.0) {
                        detectedColMajor = YES;
                    }
                }
            }
        }
    }

    if (!state) {
        state = [FQXMineShortcutFlowState new];
        state->_layout = layout;
        if (flow) {
            state->_savedItemSize = flow.itemSize;
            state->_savedEstimatedItemSize = flow.estimatedItemSize;
            state->_savedSectionInset = flow.sectionInset;
            state->_savedLineSpacing = flow.minimumLineSpacing;
            state->_savedInteritemSpacing = flow.minimumInteritemSpacing;
            state->_hasSavedFlowProps = YES;
        }
        state->_savedContentInset = collection.contentInset;
        state->_hasSavedContentInset = YES;
        state->_nativeItemSize = flow ? flow.itemSize : CGSizeZero;
        state->_savedPaging = collection.pagingEnabled;
        state->_pageControl = FQXMinePageControl(fold, card);
        state->_savedPageCount = FQXReadMinePageControlCount(state->_pageControl);
        objc_setAssociatedObject(collection, FQXMineFlowStateKey, state, OBJC_ASSOCIATION_RETAIN_NONATOMIC);
    } else if (!state->_pageControl) {
        state->_pageControl = FQXMinePageControl(fold, card);
        if (state->_pageControl) state->_savedPageCount = FQXReadMinePageControlCount(state->_pageControl);
    }

    state->_foldLayoutKind = detectedFoldKind;
    state->_page2ColumnMajor = detectedColMajor;
    state->_page2Rows = detectedRows;
    state->_rowPitchY = detectedRowPitch;
    state->_rowItemHeight = detectedRowItemH;
    state->_columns = plan.columns;
    NSUInteger resolvedPages = FQXComputeMineTotalPages(state, count);
    if (detectedFoldKind != 0) {
        CGFloat neededH = topInset + (CGFloat)(detectedRows - 1) * detectedRowPitch + detectedRowItemH;
        if (neededH > contentHeight) contentHeight = neededH;
    }

    CGSize itemSize = CGSizeMake(plan.itemWidth, (detectedFoldKind != 0) ? detectedRowItemH : actualItemHeight);
    UIEdgeInsets activeInset = UIEdgeInsetsMake(topInset, 0.0, bottomInset, 0.0);
    CGSize targetViewportSize = CGSizeMake(width, boundsHeight);
    BOOL flowChanged = flow && (
        !UIEdgeInsetsEqualToEdgeInsets(flow.sectionInset, activeInset) ||
        !CGSizeEqualToSize(flow.itemSize, itemSize) ||
        !CGSizeEqualToSize(flow.estimatedItemSize, CGSizeZero) ||
        fabs(flow.minimumLineSpacing) > 0.25 ||
        fabs(flow.minimumInteritemSpacing) > 0.25);
    BOOL changed = !state->_active || flowChanged ||
                   state->_pages != resolvedPages ||
                   state->_totalCount != count ||
                   fabs(state->_slotWidth - plan.itemWidth) > 0.25 ||
                   fabs(state->_itemHeight - actualItemHeight) > 0.25 ||
                   fabs(state->_topInset - topInset) > 0.25 ||
                   !CGSizeEqualToSize(state->_viewportSize, targetViewportSize);
    CGFloat oldWidth = state->_viewportSize.width;
    state->_pages = resolvedPages;
    state->_totalCount = count;
    state->_slotWidth = plan.itemWidth;
    state->_itemHeight = actualItemHeight;
    state->_topInset = topInset;
    state->_appliedItemSize = itemSize;
    state->_viewportSize = targetViewportSize;
    state->_viewportHeight = contentHeight;
    state->_active = YES;
    if (!collection.pagingEnabled) collection.pagingEnabled = YES;
    UIEdgeInsets cInset = collection.contentInset;
    if (fabs(cInset.left) > 0.5 || fabs(cInset.right) > 0.5) {
        cInset.left = 0.0;
        cInset.right = 0.0;
        collection.contentInset = cInset;
    }
    if (flow) {
        if (!CGSizeEqualToSize(flow.estimatedItemSize, CGSizeZero)) flow.estimatedItemSize = CGSizeZero;
        if (!CGSizeEqualToSize(flow.itemSize, itemSize)) flow.itemSize = itemSize;
        if (!UIEdgeInsetsEqualToEdgeInsets(flow.sectionInset, activeInset)) flow.sectionInset = activeInset;
        if (fabs(flow.minimumLineSpacing) > 0.25) flow.minimumLineSpacing = 0.0;
        if (fabs(flow.minimumInteritemSpacing) > 0.25) flow.minimumInteritemSpacing = 0.0;
    }
    if (changed) {
        // Preserve the page on rotation, not its obsolete absolute point offset.
        if (oldWidth > 0.0 && oldWidth != state->_viewportSize.width &&
            !collection.dragging && !collection.decelerating) {
            NSInteger page = llround(collection.contentOffset.x / oldWidth);
            collection.contentOffset = CGPointMake(MAX(0, MIN((NSInteger)resolvedPages - 1, page)) *
                                                     state->_viewportSize.width, collection.contentOffset.y);
        }
        [layout invalidateLayout];
        [collection setNeedsLayout];
        FQXScheduleDeferredMineCollectionPass(collection);
    }
    FQXCompleteMineFlowPage(collection);
}

static void FQXInstallMineScrollHook(UICollectionView *collection) {
    objc_setAssociatedObject(collection, FQXMineScrollTrackedKey, @YES, OBJC_ASSOCIATION_RETAIN_NONATOMIC);
    static NSMutableSet<NSString *> *installed;
    static NSMutableSet<NSString *> *installedCS;
    static dispatch_once_t once;
    dispatch_once(&once, ^{
        installed = [NSMutableSet set];
        installedCS = [NSMutableSet set];
    });
    Class cls = FQXRealHookClass(collection);
    if (!cls || cls == UIView.class || cls == NSObject.class) return;
    NSString *name = NSStringFromClass(cls);
    if (!name.length) return;
    if (![installed containsObject:name]) {
        __block IMP original = NULL;
        IMP hook = imp_implementationWithBlock(^(UICollectionView *view) {
            BOOL tracked = [objc_getAssociatedObject(view, FQXMineScrollTrackedKey) boolValue];
            UIView *card = tracked ? FQXMineShortcutCardForView(view) : nil;
            if (tracked && card && CGRectGetWidth(view.bounds) >= 176.0) {
                FQXSyncMineFlow(view);
            }
            ((void (*)(id, SEL))original)(view, @selector(layoutSubviews));
            if (!tracked) return;
            UIView *curCard = FQXMineShortcutCardForView(view);
            BOOL prevInFlight = FQXMineViewportSyncInFlight;
            FQXMineViewportSyncInFlight = YES;
            [FQXMineShortcutViewport applyToView:view enabled:(FQXGlassEnabled() && curCard != nil)];
            FQXMineViewportSyncInFlight = prevInFlight;
            if (curCard) {
                FQXEnforceMineVisibleCellFrames(view);
                FQXCompleteMineFlowPage(view);
            } else {
                FQXRestoreMineFlow(view);
            }
        });
        if (FQXInstallOwnedHook(cls, @selector(layoutSubviews), NO, "v16@0:8", hook, &original))
            [installed addObject:name];
        else imp_removeBlock(hook);
    }
    if (![name hasPrefix:@"UI"] && ![installedCS containsObject:name]) {
        SEL csSel = @selector(setContentSize:);
        __block IMP origCS = NULL;
        IMP csHook = imp_implementationWithBlock(^(UICollectionView *view, CGSize cs) {
            FQXMineShortcutFlowState *state = objc_getAssociatedObject(view, FQXMineFlowStateKey);
            if (state && state->_active && state->_layout == view.collectionViewLayout &&
                state->_pages > 0 && state->_viewportSize.width > 0.0 && state->_viewportHeight > 0.0) {
                CGSize targetCS = CGSizeMake(state->_viewportSize.width * (CGFloat)state->_pages, state->_viewportHeight);
                if (fabs(cs.width - targetCS.width) > 1.0 || fabs(cs.height - targetCS.height) > 1.0) {
                    cs = targetCS;
                }
            }
            ((void (*)(id, SEL, CGSize))origCS)(view, csSel, cs);
        });
        if (FQXInstallMineValidatedHook(cls, csSel, 3, "v", NULL, csHook, &origCS))
            [installedCS addObject:name];
        else imp_removeBlock(csHook);
    }
}

static void FQXSyncMineContainerUniversal(UIView *container) {
    if (![container isKindOfClass:UIView.class] || FQXIsInsideMineSidebar(container)) return;
    UIView *outerRow = FQXMineOuterRowForView(container);
    if (outerRow && [outerRow respondsToSelector:@selector(lynxVipView)]) return;
    UIView *card = outerRow ?: FQXMineShortcutCardForView(container) ?: container;

    // Check dual-page outer UIScrollView first (SSScrollFoldFuncView hosting Page 1 + 2-row Page 2)
    // so we don't prematurely return on only one nested inner UICollectionView.
    UIScrollView *plainSV = ([container isKindOfClass:UIScrollView.class] &&
                             ![container isKindOfClass:UICollectionView.class] &&
                             FQXIsInnerMineShortcutScroll(container))
        ? (UIScrollView *)container
        : FQXFindMinePlainScrollView(container, 6);
    if (plainSV && FQXSyncScrollFoldDualContainerSV(card, plainSV)) {
        [FQXMineShortcutViewport applyToView:plainSV enabled:(FQXGlassEnabled() && FQXMineShortcutCardForView(plainSV) != nil)];
        return;
    }

    UICollectionView *collection = nil;
    if ([container isKindOfClass:UICollectionView.class] && FQXIsInnerMineShortcutScroll(container)) {
        collection = (UICollectionView *)container;
    } else {
        id propCV = FQXObjGet(container, "collectionView");
        if ([propCV isKindOfClass:UICollectionView.class] &&
            [(UIView *)propCV isDescendantOfView:container] &&
            FQXIsInnerMineShortcutScroll((UIView *)propCV)) {
            collection = (UICollectionView *)propCV;
        }
        if (!collection) {
            collection = FQXFindMineCollectionView(container, 8);
        }
    }
    if (collection) {
        if (!FQXIsInnerMineShortcutScroll(collection)) return;
        FQXInstallMineScrollHook(collection);
        FQXSyncMineFlow(collection);
        FQXEnforceMineVisibleCellFrames(collection);
        [FQXMineShortcutViewport applyToView:collection enabled:(FQXGlassEnabled() && FQXMineShortcutCardForView(collection) != nil)];
        return;
    }
    if (plainSV && FQXSyncMinePlainScrollView(card, plainSV)) return;
    FQXSyncMineDirectTileHost(card);
}

static void (*OrigScrollFoldLayout)(id, SEL);
static void HookScrollFoldLayout(UIView *self, SEL _cmd) {
    if (OrigScrollFoldLayout) OrigScrollFoldLayout(self, _cmd);
    if (FQXIsInsideMineSidebar(self)) return;
    BOOL clipEnabled = FQXGlassEnabled() && FQXMineShortcutFold(self) == self;
    if (!FQXMineViewportSyncInFlight) {
        FQXMineViewportSyncInFlight = YES;
        FQXSyncMineContainerUniversal(self);
        [FQXMineShortcutViewport applyToView:self enabled:clipEnabled];
        FQXMineViewportSyncInFlight = NO;
    }
}

static void (*OrigScrollFoldAttachView)(id, SEL, id, NSInteger);
static void HookScrollFoldAttachView(UIView *self, SEL _cmd, id attachView, NSInteger attachType) {
    if (OrigScrollFoldAttachView) OrigScrollFoldAttachView(self, _cmd, attachView, attachType);
    if (FQXIsInsideMineSidebar(self)) return;
    id rawCV = FQXObjGet(self, "collectionView");
    if ([rawCV isKindOfClass:UICollectionView.class]) {
        UICollectionView *cv = (UICollectionView *)rawCV;
        Class foldLayoutClass = objc_lookUpClass("SSFuncLayout");
        if (foldLayoutClass && [cv.collectionViewLayout isKindOfClass:foldLayoutClass]) {
            if (FQXUpdateMineFoldFirstPageBand(cv, self)) {
                [cv.collectionViewLayout invalidateLayout];
            }
        }
    }
}

static void (*OrigMineShortcutCardLayout)(id, SEL);
static void HookMineShortcutCardLayout(UIView *self, SEL _cmd) {
    if (OrigMineShortcutCardLayout) OrigMineShortcutCardLayout(self, _cmd);
    if (!FQXMineShortcutCardForView(self)) return;
    if (!FQXMineViewportSyncInFlight) {
        FQXMineViewportSyncInFlight = YES;
        FQXSyncMineContainerUniversal(self);
        FQXMineViewportSyncInFlight = NO;
    }
}

static void (*OrigMineCard1Layout)(id, SEL);
static void HookMineCard1Layout(UIView *self, SEL _cmd) {
    if (OrigMineCard1Layout) OrigMineCard1Layout(self, _cmd);
    if ([self respondsToSelector:@selector(lynxVipView)] || FQXIsInsideMineSidebar(self)) return;
    if (!FQXMineViewportSyncInFlight) {
        FQXMineViewportSyncInFlight = YES;
        FQXSyncMineContainerUniversal(self);
        FQXMineViewportSyncInFlight = NO;
    }
}

static void FQXSyncOwnerCollectionFromShortcutCell(UICollectionViewCell *self) {
    if (FQXMineCellRelayoutInFlight || FQXIsInsideMineSidebar(self)) return;
    UIView *outerRow = FQXMineOuterRowForView(self);
    UIView *card = outerRow ?: FQXMineShortcutCardForView(self);
    if (!card) return;
    UICollectionView *ownerCV = nil;
    UIScrollView *outerPlainSV = nil;
    for (UIView *cur = self.superview; cur; cur = cur.superview) {
        if (!ownerCV && [cur isKindOfClass:UICollectionView.class] && FQXIsInnerMineShortcutScroll(cur)) {
            ownerCV = (UICollectionView *)cur;
        } else if (!outerPlainSV && [cur isKindOfClass:UIScrollView.class] &&
                   ![cur isKindOfClass:UICollectionView.class] && FQXIsInnerMineShortcutScroll(cur)) {
            outerPlainSV = (UIScrollView *)cur;
        }
        if (cur == outerRow) break;
    }
    if (outerPlainSV) {
        BOOL prevInFlight = FQXMineViewportSyncInFlight;
        FQXMineViewportSyncInFlight = YES;
        BOOL dualHandled = FQXSyncScrollFoldDualContainerSV(card, outerPlainSV);
        if (!dualHandled && !ownerCV) {
            FQXSyncMinePlainScrollView(card, outerPlainSV);
        }
        [FQXMineShortcutViewport applyToView:outerPlainSV enabled:FQXGlassEnabled()];
        FQXMineViewportSyncInFlight = prevInFlight;
        if (dualHandled && !ownerCV) return;
    }
    if (ownerCV) {
        FQXInstallMineScrollHook(ownerCV);
        FQXMineShortcutFlowState *state = objc_getAssociatedObject(ownerCV, FQXMineFlowStateKey);
        if (!state || !state->_active ||
            state->_totalCount != FQXMineTotalItemCount(ownerCV) ||
            CGRectGetWidth(ownerCV.bounds) < 160.0) {
            BOOL prevInFlight = FQXMineViewportSyncInFlight;
            FQXMineViewportSyncInFlight = YES;
            FQXSyncMineFlow(ownerCV);
            [FQXMineShortcutViewport applyToView:ownerCV enabled:FQXGlassEnabled()];
            FQXMineViewportSyncInFlight = prevInFlight;
            state = objc_getAssociatedObject(ownerCV, FQXMineFlowStateKey);
        }
        if (state && state->_active && state->_columns == 4 && state->_slotWidth >= 44.0) {
            NSIndexPath *ip = [ownerCV indexPathForCell:self] ?: objc_getAssociatedObject(self, FQXMineCellLastIndexPathKey);
            NSUInteger flatIdx = FQXMineFlatIndexForIndexPath(ownerCV, ip);
            if (flatIdx != NSNotFound) {
                CGRect expected = FQXMineFrameForFlatIndex(state, flatIdx);
                CGRect cur = self.frame;
                if (fabs(cur.origin.x - expected.origin.x) > 0.5 ||
                    fabs(cur.origin.y - expected.origin.y) > 0.5 ||
                    fabs(CGRectGetWidth(cur) - CGRectGetWidth(expected)) > 0.5 ||
                    fabs(CGRectGetHeight(cur) - CGRectGetHeight(expected)) > 0.5) {
                    BOOL prevCell = FQXMineCellRelayoutInFlight;
                    FQXMineCellRelayoutInFlight = YES;
                    self.frame = expected;
                    FQXMineCellRelayoutInFlight = prevCell;
                }
            }
        }
        FQXEnforceMineVisibleCellFrames(ownerCV);
    } else if (!outerPlainSV) {
        FQXSyncMineDirectTileHost(card);
    }
}

static UICollectionViewLayoutAttributes *FQXApplyMineCellLayoutAttributes(UICollectionViewCell *self,
                                                                          UICollectionViewLayoutAttributes *attrs) {
    if (!attrs || !attrs.indexPath || FQXIsInsideMineSidebar(self)) return attrs;
    objc_setAssociatedObject(self, FQXMineCellLastIndexPathKey, attrs.indexPath, OBJC_ASSOCIATION_RETAIN_NONATOMIC);
    UIView *outerRow = FQXMineOuterRowForView(self);
    UICollectionView *ownerCV = nil;
    for (UIView *cur = self.superview; cur; cur = cur.superview) {
        if ([cur isKindOfClass:UICollectionView.class] && FQXIsInnerMineShortcutScroll(cur)) {
            ownerCV = (UICollectionView *)cur;
            break;
        }
        if (cur == outerRow) break;
    }
    if (ownerCV && (outerRow || FQXMineShortcutCardForView(ownerCV))) {
        FQXMineShortcutFlowState *state = objc_getAssociatedObject(ownerCV, FQXMineFlowStateKey);
        if ((!state || !state->_active) && CGRectGetWidth(ownerCV.bounds) >= 160.0) {
            FQXScheduleDeferredMineCollectionPass(ownerCV);
        }
        if (state && state->_active && state->_columns == 4 && state->_slotWidth >= 44.0) {
            NSUInteger flatIdx = FQXMineFlatIndexForIndexPath(ownerCV, attrs.indexPath);
            if (flatIdx != NSNotFound) {
                CGRect target = FQXMineFrameForFlatIndex(state, flatIdx);
                if (!CGRectEqualToRect(attrs.frame, target)) {
                    UICollectionViewLayoutAttributes *effective = [attrs copy];
                    effective.frame = target;
                    return effective;
                }
            }
        }
    }
    return attrs;
}

static CGRect FQXRewriteMineCellFrame(UICollectionViewCell *cell, CGRect incoming) {
    if (FQXMineCellRelayoutInFlight || FQXIsInsideMineSidebar(cell)) return incoming;
    UIView *outerRow = FQXMineOuterRowForView(cell);
    UICollectionView *ownerCV = nil;
    for (UIView *cur = cell.superview; cur; cur = cur.superview) {
        if ([cur isKindOfClass:UICollectionView.class] && FQXIsInnerMineShortcutScroll(cur)) {
            ownerCV = (UICollectionView *)cur;
            break;
        }
        if (cur == outerRow) break;
    }
    if (!ownerCV) return incoming;
    FQXMineShortcutFlowState *state = objc_getAssociatedObject(ownerCV, FQXMineFlowStateKey);
    if ((!state || !state->_active) && CGRectGetWidth(ownerCV.bounds) >= 160.0) {
        FQXScheduleDeferredMineCollectionPass(ownerCV);
    }
    if (state && state->_active && state->_columns == 4 && state->_slotWidth >= 44.0) {
        NSIndexPath *ip = [ownerCV indexPathForCell:cell] ?: objc_getAssociatedObject(cell, FQXMineCellLastIndexPathKey);
        if (ip) {
            NSUInteger flatIdx = FQXMineFlatIndexForIndexPath(ownerCV, ip);
            if (flatIdx != NSNotFound) {
                return FQXMineFrameForFlatIndex(state, flatIdx);
            }
        } else {
            FQXScheduleDeferredMineCollectionPass(ownerCV);
        }
    }
    return incoming;
}

