static void FQXShelfApplyControlHidden(UIView *view, const void *key, BOOL hide) {
    if (![view isKindOfClass:UIView.class]) return;
    if (hide) {
        if (!view.hidden || view.alpha > 0.001 || view.userInteractionEnabled) {
            objc_setAssociatedObject(view, key, @YES, OBJC_ASSOCIATION_RETAIN_NONATOMIC);
            view.hidden = YES;
            view.alpha = 0.0;
            view.userInteractionEnabled = NO;
        }
    } else if ([objc_getAssociatedObject(view, key) boolValue]) {
        objc_setAssociatedObject(view, key, nil, OBJC_ASSOCIATION_RETAIN_NONATOMIC);
        view.hidden = NO;
        view.alpha = 1.0;
        view.userInteractionEnabled = YES;
    }
}

static NSString *FQXShelfFirstLabelText(UIView *view, NSInteger depth) {
    if (![view isKindOfClass:UIView.class] || depth > 3) return nil;
    if ([view isKindOfClass:UILabel.class]) {
        UILabel *lbl = (UILabel *)view;
        NSString *t = lbl.text.length ? lbl.text : lbl.attributedText.string;
        if (t.length) return t;
    }
    for (UIView *sub in view.subviews) {
        NSString *found = FQXShelfFirstLabelText(sub, depth + 1);
        if (found.length) return found;
    }
    return nil;
}

static NSString *FQXShelfTabKeyForTitle(NSString *title) {
    if (![title isKindOfClass:NSString.class]) return nil;
    if ([title containsString:@"书架"]) return @"FanqieX.ShelfTabBookshelf.1";
    if ([title containsString:@"历史"]) return @"FanqieX.ShelfTabHistory.1";
    if ([title containsString:@"收藏"]) return @"FanqieX.ShelfTabCollect.1";
    if ([title containsString:@"圈子"]) return @"FanqieX.ShelfTabCircle.1";
    return nil;
}

static NSString *FQXShelfTabKeyForCell(UIView *cell) {
    id model = FQXObjGet(cell, "cellModel") ?: FQXObjGet(cell, "model");
    NSString *title = nil;
    id titleObj = FQXObjGet(model, "title") ?: FQXObjGet(model, "name");
    if ([titleObj isKindOfClass:NSString.class]) title = titleObj;
    if (!title.length) {
        UILabel *lbl = FQXObjGet(cell, "titleLabel") ?: FQXObjGet(cell, "label");
        if ([lbl isKindOfClass:UILabel.class]) title = lbl.text;
    }
    if (!title.length) title = FQXShelfFirstLabelText(cell, 0);
    return FQXShelfTabKeyForTitle(title);
}

static NSArray *FQXShelfVisibleRootTabModels(NSArray *models) {
    if (![models isKindOfClass:NSArray.class] || models.count < 2) return models;
    NSMutableArray *visible = [NSMutableArray arrayWithCapacity:models.count];
    for (id model in models) {
        NSString *key = FQXShelfTabKeyForTitle(FQXObjGet(model, "title"));
        if (!key || FQXShelfOptionEnabled(key)) [visible addObject:model];
    }
    if (visible.count == models.count) return models;
    // The host's selected index assumes at least one controller.
    return visible.count ? [visible copy] : @[models.firstObject];
}

static NSArray *(*OrigShelfRootTabModels)(id, SEL);
static NSArray *HookShelfRootTabModels(id manager, SEL cmd) {
    return FQXShelfVisibleRootTabModels(OrigShelfRootTabModels(manager, cmd));
}

static NSUInteger FQXShelfRootSourceIndex(id manager, NSUInteger visibleIndex) {
    if (!OrigShelfRootTabModels) return visibleIndex;
    SEL getter = sel_registerName("getBookshelfTabModelArray");
    NSArray *source = OrigShelfRootTabModels(manager, getter);
    NSArray *visible = FQXShelfVisibleRootTabModels(source);
    if (source == visible) return visibleIndex;
    if (visibleIndex >= visible.count) return NSNotFound;
    return [source indexOfObjectIdenticalTo:visible[visibleIndex]];
}

static BOOL (*OrigShelfRootHasAdornment)(id, SEL, NSUInteger);
static BOOL HookShelfRootHasAdornment(id manager, SEL cmd, NSUInteger index) {
    NSUInteger sourceIndex = FQXShelfRootSourceIndex(manager, index);
    return sourceIndex != NSNotFound && OrigShelfRootHasAdornment(manager, cmd, sourceIndex);
}

static id (*OrigShelfRootAdornment)(id, SEL, NSUInteger);
static id HookShelfRootAdornment(id manager, SEL cmd, NSUInteger index) {
    NSUInteger sourceIndex = FQXShelfRootSourceIndex(manager, index);
    return sourceIndex == NSNotFound ? nil : OrigShelfRootAdornment(manager, cmd, sourceIndex);
}

static CGSize (*OrigShelfRootAdornmentSize)(id, SEL, NSUInteger);
static CGSize HookShelfRootAdornmentSize(id manager, SEL cmd, NSUInteger index) {
    NSUInteger sourceIndex = FQXShelfRootSourceIndex(manager, index);
    return sourceIndex == NSNotFound ? CGSizeZero : OrigShelfRootAdornmentSize(manager, cmd, sourceIndex);
}

static void (*OrigShelfRootManagerDidClick)(id, SEL, NSUInteger);
static void HookShelfRootManagerDidClick(id manager, SEL cmd, NSUInteger index) {
    NSUInteger sourceIndex = FQXShelfRootSourceIndex(manager, index);
    if (sourceIndex != NSNotFound) OrigShelfRootManagerDidClick(manager, cmd, sourceIndex);
}

static NSString *FQXHistoryFilterKeyForTitle(NSString *title);
static NSString *FQXHistoryFilterKeyForCell(UIView *cell);

static NSString *FQXShelfFilterKeyForTitle(NSString *title) {
    if (![title isKindOfClass:NSString.class] || !title.length) return nil;
    if ([title containsString:@"全部"]) return @"FanqieX.ShelfFilterAll.1";
    if ([title containsString:@"阅读"]) return @"FanqieX.ShelfFilterRead.1";
    if ([title containsString:@"听书"]) return @"FanqieX.ShelfFilterListen.1";
    if ([title containsString:@"漫剧"]) return @"FanqieX.ShelfFilterComic.1";
    if ([title containsString:@"星标"]) return @"FanqieX.ShelfFilterStar.1";
    return nil;
}

static NSString *FQXShelfFilterKeyForCell(UIView *cell) {
    NSString *title = nil;
    UILabel *lbl = FQXObjGet(cell, "textLabel") ?: FQXObjGet(cell, "titleLabel") ?: FQXObjGet(cell, "label");
    if ([lbl isKindOfClass:UILabel.class]) title = lbl.text;
    if (!title.length) {
        id model = FQXObjGet(cell, "model") ?: FQXObjGet(cell, "cellModel");
        id mTitle = FQXObjGet(model, "title") ?: FQXObjGet(model, "name");
        if ([mTitle isKindOfClass:NSString.class]) title = mTitle;
    }
    if (!title.length) title = FQXShelfFirstLabelText(cell, 0);
    return FQXShelfFilterKeyForTitle(title);
}

typedef NS_ENUM(NSInteger, FQXShelfStripKind) {
    FQXShelfStripKindHistoryFilter = 1,
    FQXShelfStripKindBookshelfFilter = 2,
    FQXShelfStripKindBookshelfRootTab = 3,
};

static FQXShelfStripKind FQXShelfStripKindForCallback(NSString *(*keyForCell)(UIView *)) {
    if (keyForCell == FQXHistoryFilterKeyForCell) return FQXShelfStripKindHistoryFilter;
    if (keyForCell == FQXShelfTabKeyForCell) return FQXShelfStripKindBookshelfRootTab;
    return FQXShelfStripKindBookshelfFilter;
}

static NSString *FQXShelfStripKeyForTitle(NSString *title, FQXShelfStripKind kind) {
    switch (kind) {
        case FQXShelfStripKindHistoryFilter:
            return FQXHistoryFilterKeyForTitle(title);
        case FQXShelfStripKindBookshelfRootTab:
            return FQXShelfTabKeyForTitle(title);
        case FQXShelfStripKindBookshelfFilter:
        default:
            return FQXShelfFilterKeyForTitle(title);
    }
}

static NSString *FQXShelfExtractItemTitleFromOwner(id owner, NSInteger index) {
    if (!owner || index < 0) return nil;
    NSArray *titles = FQXObjGet(owner, "titles");
    if ([titles isKindOfClass:NSArray.class] && (NSUInteger)index < titles.count) {
        id t = titles[(NSUInteger)index];
        if ([t isKindOfClass:NSString.class] && [t length]) return t;
    }
    const char *arrayNames[] = { "dataSource", "filterModels", "optionModels", "models", "dataArray", "itemModels" };
    for (size_t k = 0; k < sizeof(arrayNames) / sizeof(arrayNames[0]); ++k) {
        NSArray *arr = FQXObjGet(owner, arrayNames[k]);
        if (![arr isKindOfClass:NSArray.class] || (NSUInteger)index >= arr.count) continue;
        id item = arr[(NSUInteger)index];
        if ([item isKindOfClass:NSString.class] && [item length]) return item;
        id t = FQXObjGet(item, "title") ?: FQXObjGet(item, "name") ?: FQXObjGet(item, "filterName");
        if ([t isKindOfClass:NSString.class] && [t length]) return t;
    }
    return nil;
}

static NSString *FQXShelfResolveStripItemKey(UICollectionView *cv, NSInteger index, FQXShelfStripKind kind) {
    if (!cv || index < 0) return nil;
    id candidates[] = { cv.superview, cv.delegate, cv.dataSource, cv.superview ? cv.superview.superview : nil };
    for (size_t i = 0; i < sizeof(candidates) / sizeof(candidates[0]); ++i) {
        NSString *title = FQXShelfExtractItemTitleFromOwner(candidates[i], index);
        if (title.length) {
            NSString *k = FQXShelfStripKeyForTitle(title, kind);
            if (k) return k;
        }
    }
    NSDictionary<NSNumber *, NSString *> *cached = objc_getAssociatedObject(cv, FQXShelfCachedItemKeysKey);
    NSString *hit = cached[@(index)];
    return [hit isKindOfClass:NSString.class] && hit.length ? hit : nil;
}

static BOOL FQXBuildShelfCompactStripPlan(UICollectionView *cv,
                                          UICollectionViewLayout *layout,
                                          FQXShelfStripKind kind,
                                          CGFloat fallbackGap,
                                          FQXCompactStripPlan *outPlan,
                                          CGSize *outOrigSize) {
    if (!cv || !layout || [cv numberOfSections] < 1) return NO;
    NSInteger count = [cv numberOfItemsInSection:0];
    if (count < 1 || count > FQXMaxCompactStripItems) return NO;

    Class cls = object_getClass(layout);
    IMP itemImp = FQXLookupDramaCompactOrig(gFQXDramaCompactOrigItem, cls);
    IMP sizeImp = FQXLookupDramaCompactOrig(gFQXDramaCompactOrigSize, cls);

    FQXCompactStripItem rawItems[FQXMaxCompactStripItems];
    int visibleFlags[FQXMaxCompactStripItems];
    BOOL prevGuard = gFQXDramaCompactComputing;
    gFQXDramaCompactComputing = YES;
    for (NSInteger i = 0; i < count; ++i) {
        NSIndexPath *ip = [NSIndexPath indexPathForItem:i inSection:0];
        UICollectionViewLayoutAttributes *a = itemImp
            ? ((UICollectionViewLayoutAttributes *(*)(id, SEL, id))itemImp)(layout, @selector(layoutAttributesForItemAtIndexPath:), ip)
            : [layout layoutAttributesForItemAtIndexPath:ip];
        CGRect rf = a ? a.frame : CGRectZero;
        rawItems[i].x = rf.origin.x;
        rawItems[i].y = rf.origin.y;
        rawItems[i].width = rf.size.width;
        rawItems[i].height = rf.size.height;
        rawItems[i].hidden = 0;
        NSString *prefKey = FQXShelfResolveStripItemKey(cv, i, kind);
        visibleFlags[i] = (!prefKey || FQXShelfOptionEnabled(prefKey)) ? 1 : 0;
    }
    CGSize origSize = sizeImp
        ? ((CGSize (*)(id, SEL))sizeImp)(layout, @selector(collectionViewContentSize))
        : cv.contentSize;
    gFQXDramaCompactComputing = prevGuard;

    if (outOrigSize) *outOrigSize = origSize;
    FQXCompactStripPlan plan = FQXPlanCompactHorizontalStrip(rawItems,
                                                             visibleFlags,
                                                             (size_t)count,
                                                             fallbackGap,
                                                             CGRectGetWidth(cv.bounds),
                                                             cv.contentOffset.x);
    if (!plan.valid) return NO;
    if (outPlan) *outPlan = plan;
    return YES;
}

static BOOL FQXComputeShelfCompactedRects(UICollectionViewLayout *layout,
                                          CGRect outCompacted[24],
                                          BOOL outHidden[24],
                                          NSInteger *outCount,
                                          CGSize *outContentSize) {
    if (!layout || gFQXDramaCompactComputing) return NO;
    NSNumber *kindNum = objc_getAssociatedObject(layout, FQXShelfCompactLayoutKindKey);
    if (!kindNum) return NO;
    UICollectionView *cv = layout.collectionView;
    if (!cv) return NO;
    NSNumber *gapNum = objc_getAssociatedObject(layout, FQXShelfCompactFallbackGapKey);
    CGFloat gap = gapNum ? gapNum.doubleValue : 8.0;
    FQXCompactStripPlan plan;
    CGSize origSize = CGSizeZero;
    if (!FQXBuildShelfCompactStripPlan(cv, layout, (FQXShelfStripKind)kindNum.integerValue, gap, &plan, &origSize)) {
        return NO;
    }
    if (plan.hiddenCount == 0) return NO;
    for (size_t i = 0; i < plan.count; ++i) {
        outCompacted[i] = CGRectMake(plan.items[i].x, plan.items[i].y, plan.items[i].width, plan.items[i].height);
        outHidden[i] = (plan.items[i].hidden != 0);
    }
    if (outCount) *outCount = (NSInteger)plan.count;
    if (outContentSize) {
        *outContentSize = CGSizeMake(MAX(1.0, plan.contentWidth), MAX(1.0, origSize.height));
    }
    return YES;
}

static const char FQXK_FQXShelfReflowInFlightKey = 0;
#define FQXShelfReflowInFlightKey ((const void *)&FQXK_FQXShelfReflowInFlightKey)
static const char FQXK_FQXShelfRelayoutPendingKey = 0;
#define FQXShelfRelayoutPendingKey ((const void *)&FQXK_FQXShelfRelayoutPendingKey)

static void FQXScheduleShelfLayoutInvalidation(UICollectionView *cv, UICollectionViewLayout *layout) {
    if (!cv || !layout) return;
    if ([objc_getAssociatedObject(layout, FQXShelfRelayoutPendingKey) boolValue]) return;
    objc_setAssociatedObject(layout, FQXShelfRelayoutPendingKey, @YES, OBJC_ASSOCIATION_RETAIN_NONATOMIC);
    __weak UICollectionView *weakCV = cv;
    __weak UICollectionViewLayout *weakLayout = layout;
    dispatch_async(dispatch_get_main_queue(), ^{
        UICollectionViewLayout *strongLayout = weakLayout;
        UICollectionView *strongCV = weakCV;
        if (strongLayout) {
            objc_setAssociatedObject(strongLayout, FQXShelfRelayoutPendingKey, nil, OBJC_ASSOCIATION_RETAIN_NONATOMIC);
            [strongLayout invalidateLayout];
        }
        if (strongCV) {
            [strongCV setNeedsLayout];
        }
    });
}

static void FQXReflowShelfCollectionCellsLocked(UICollectionView *cv,
                                                NSString *(*keyForCell)(UIView *),
                                                CGFloat gap) {
    UICollectionViewLayout *layout = cv.collectionViewLayout;
    if (!layout || [cv numberOfSections] < 1) return;
    NSInteger count = [cv numberOfItemsInSection:0];
    if (count < 1 || count > FQXMaxCompactStripItems) return;

    FQXShelfStripKind kind = FQXShelfStripKindForCallback(keyForCell);
    FQXInstallCompactLayoutHooksOnClass(object_getClass(layout));
    objc_setAssociatedObject(layout, FQXShelfCompactLayoutKindKey, @(kind), OBJC_ASSOCIATION_RETAIN_NONATOMIC);
    objc_setAssociatedObject(layout, FQXShelfCompactFallbackGapKey, @(gap), OBJC_ASSOCIATION_RETAIN_NONATOMIC);

    NSMutableDictionary<NSNumber *, NSString *> *cachedKeys = objc_getAssociatedObject(cv, FQXShelfCachedItemKeysKey);
    if (!cachedKeys) {
        cachedKeys = [NSMutableDictionary dictionaryWithCapacity:(NSUInteger)count];
        objc_setAssociatedObject(cv, FQXShelfCachedItemKeysKey, cachedKeys, OBJC_ASSOCIATION_RETAIN_NONATOMIC);
    }
    for (NSIndexPath *ip in [cv indexPathsForVisibleItems]) {
        if (ip.section != 0 || ip.item < 0 || ip.item >= count) continue;
        UICollectionViewCell *cell = [cv cellForItemAtIndexPath:ip];
        if (!cell) continue;
        NSString *k = keyForCell ? keyForCell(cell) : nil;
        if (k.length) cachedKeys[@(ip.item)] = k;
    }

    NSUInteger visMask = ((NSUInteger)count << 24);
    for (NSInteger i = 0; i < count; ++i) {
        NSString *prefKey = FQXShelfResolveStripItemKey(cv, i, kind);
        if (!prefKey || FQXShelfOptionEnabled(prefKey)) {
            visMask |= (1UL << (NSUInteger)i);
        }
    }
    NSNumber *prevMask = objc_getAssociatedObject(layout, FQXShelfAppliedVisMaskKey);
    if (!prevMask || prevMask.unsignedIntegerValue != visMask) {
        objc_setAssociatedObject(layout, FQXShelfAppliedVisMaskKey, @(visMask), OBJC_ASSOCIATION_RETAIN_NONATOMIC);
        FQXScheduleShelfLayoutInvalidation(cv, layout);
    }

    FQXCompactStripPlan plan;
    CGSize origSize = CGSizeZero;
    if (!FQXBuildShelfCompactStripPlan(cv, layout, kind, gap, &plan, &origSize)) return;

    BOOL allowScroll = (plan.allowStripScroll != 0);
    if (cv.scrollEnabled != allowScroll) cv.scrollEnabled = allowScroll;
    if (cv.alwaysBounceHorizontal != allowScroll) cv.alwaysBounceHorizontal = allowScroll;
    if (plan.resetContentOffset) {
        double maxOff = allowScroll ? fmax(0.0, plan.contentWidth - CGRectGetWidth(cv.bounds)) : 0.0;
        CGFloat clampedX = (CGFloat)fmin(fmax(0.0, cv.contentOffset.x), maxOff);
        if (!allowScroll) clampedX = 0.0;
        if (fabs(cv.contentOffset.x - clampedX) > 0.5) {
            [cv setContentOffset:CGPointMake(clampedX, cv.contentOffset.y) animated:NO];
        }
    }

    BOOL wasReflowed = [objc_getAssociatedObject(cv, FQXShelfReflowAppliedKey) boolValue];
    if (plan.hiddenCount == 0) {
        for (NSInteger i = 0; i < count; ++i) {
            UICollectionViewCell *cell = [cv cellForItemAtIndexPath:[NSIndexPath indexPathForItem:i inSection:0]];
            if (cell) FQXShelfApplyControlHidden(cell, FQXShelfHiddenByUsKey, NO);
        }
        if (wasReflowed) {
            objc_setAssociatedObject(cv, FQXShelfReflowAppliedKey, nil, OBJC_ASSOCIATION_RETAIN_NONATOMIC);
            FQXScheduleShelfLayoutInvalidation(cv, layout);
        }
        return;
    }

    objc_setAssociatedObject(cv, FQXShelfReflowAppliedKey, @YES, OBJC_ASSOCIATION_RETAIN_NONATOMIC);
    if (fabs(cv.contentSize.width - plan.contentWidth) > 1.0 && cv.contentSize.height > 1.0) {
        cv.contentSize = CGSizeMake(plan.contentWidth, cv.contentSize.height);
    }
    for (NSInteger i = 0; i < count; ++i) {
        UICollectionViewCell *cell = [cv cellForItemAtIndexPath:[NSIndexPath indexPathForItem:i inSection:0]];
        if (!cell) continue;
        BOOL hideItem = (plan.items[i].hidden != 0);
        FQXShelfApplyControlHidden(cell, FQXShelfHiddenByUsKey, hideItem);
        if (!hideItem) {
            CGRect f = cell.frame;
            if (fabs(f.origin.x - plan.items[i].x) > 0.5 || fabs(f.size.width - plan.items[i].width) > 0.5) {
                f.origin.x = plan.items[i].x;
                f.size.width = plan.items[i].width;
                cell.frame = f;
            }
        }
    }
}

static void FQXReflowShelfCollectionCells(UICollectionView *cv,
                                          NSString *(*keyForCell)(UIView *),
                                          CGFloat gap,
                                          CGFloat fallbackStartX) {
    (void)fallbackStartX;
    if (![cv isKindOfClass:UICollectionView.class] || CGRectGetWidth(cv.bounds) < 44.0) return;
    if ([objc_getAssociatedObject(cv, FQXShelfReflowInFlightKey) boolValue]) return;
    objc_setAssociatedObject(cv, FQXShelfReflowInFlightKey, @YES, OBJC_ASSOCIATION_RETAIN_NONATOMIC);
    FQXReflowShelfCollectionCellsLocked(cv, keyForCell, gap);
    objc_setAssociatedObject(cv, FQXShelfReflowInFlightKey, nil, OBJC_ASSOCIATION_RETAIN_NONATOMIC);
}

static const char FQXK_FQXShelfTabTapBridgeKey = 0;
#define FQXShelfTabTapBridgeKey ((const void *)&FQXK_FQXShelfTabTapBridgeKey)
@interface FQXShelfTabTapBridge : NSObject <UIGestureRecognizerDelegate>
@property(nonatomic, weak) UIView *tabSelectView;
@property(nonatomic, strong) UITapGestureRecognizer *tapGesture;
@end

@implementation FQXShelfTabTapBridge

- (instancetype)initWithTabSelectView:(UIView *)tabView {
    self = [super init];
    if (self) {
        _tabSelectView = tabView;
        UITapGestureRecognizer *tap = [[UITapGestureRecognizer alloc] initWithTarget:self action:@selector(handleTabTap:)];
        tap.cancelsTouchesInView = NO;
        tap.delaysTouchesBegan = NO;
        tap.delaysTouchesEnded = NO;
        tap.delegate = self;
        _tapGesture = tap;
        [tabView addGestureRecognizer:tap];
    }
    return self;
}

- (BOOL)gestureRecognizer:(UIGestureRecognizer *)gr shouldRecognizeSimultaneouslyWithGestureRecognizer:(UIGestureRecognizer *)other {
    (void)gr; (void)other;
    return YES;
}

- (void)handleTabTap:(UITapGestureRecognizer *)gr {
    if (gr.state != UIGestureRecognizerStateEnded) return;
    UIView *tabView = self.tabSelectView;
    if (!tabView || !tabView.window || tabView.hidden) return;
    UICollectionView *cv = FQXObjGet(tabView, "collectionView") ?: FQXFindMineCollectionView(tabView, 3);
    if (![cv isKindOfClass:UICollectionView.class] || !cv.window) return;

    CGPoint ptInCV = [gr locationInView:cv];
    NSArray<NSIndexPath *> *ips = [cv indexPathsForVisibleItems];
    NSIndexPath *hitIP = nil;
    UIView *hitCell = nil;
    CGFloat bestDist = CGFLOAT_MAX;
    for (NSIndexPath *ip in ips) {
        UICollectionViewCell *cell = [cv cellForItemAtIndexPath:ip];
        if (!cell || cell.hidden || cell.alpha <= 0.05 || CGRectGetWidth(cell.frame) < 8.0) continue;
        CGRect hitRect = CGRectInset(cell.frame, -6.0, -8.0);
        if (CGRectContainsPoint(hitRect, ptInCV)) {
            CGFloat dist = fabs(ptInCV.x - CGRectGetMidX(cell.frame));
            if (dist < bestDist) {
                bestDist = dist;
                hitIP = ip;
                hitCell = cell;
            }
        }
    }
    if (!hitIP || !hitCell) return;

    NSInteger tappedIdx = hitIP.item;
    NSString *tappedTitle = FQXShelfFirstLabelText(hitCell, 0) ?: @"";
    id owner = FQXObjGet(tabView, "delegate");
    NSInteger prevTabIdx = FQXIntGet(tabView, "selectedIndex", -1);
    NSInteger prevOwnerIdx = owner ? FQXIntGet(owner, "currentTabIndex", -1) : -1;
    CGRect cellFrame = hitCell.frame;
    UICollectionViewLayoutAttributes *attr = [cv layoutAttributesForItemAtIndexPath:hitIP];
    CGRect layoutFrame = attr ? attr.frame : CGRectZero;
    BOOL reflowApplied = [objc_getAssociatedObject(cv, FQXShelfReflowAppliedKey) boolValue];
    if (!FQXShouldRunShelfTabTapRecovery(reflowApplied ? 1 : 0,
                                         CGRectGetMinX(cellFrame), CGRectGetMinX(layoutFrame),
                                         CGRectGetWidth(cellFrame), CGRectGetWidth(layoutFrame))) {
        return;
    }

    __weak UIView *weakTabView = tabView;
    __weak UICollectionView *weakCV = cv;
    dispatch_async(dispatch_get_main_queue(), ^{
        UIView *sTab = weakTabView;
        UICollectionView *sCV = weakCV;
        if (!sTab || !sCV || !sTab.window) return;
        id sOwner = FQXObjGet(sTab, "delegate");
        UIView *container = FQXObjGet(sOwner, "containerView");
        UIScrollView *pagerScroll = FQXObjGet(container, "scrollView");
        NSInteger nowTabIdx = FQXIntGet(sTab, "selectedIndex", -1);
        NSInteger nowOwnerIdx = FQXIntGet(sOwner, "currentTabIndex", -1);
        NSInteger nowPagerIdx = FQXIntGet(container, "currentIndex", -1);
        BOOL alreadySelected = nowTabIdx == tappedIdx && (nowOwnerIdx < 0 || nowOwnerIdx == tappedIdx) &&
            (nowPagerIdx < 0 || nowPagerIdx == tappedIdx);
        if (alreadySelected) return;

        BOOL attempted = NO;
        if (nowTabIdx != tappedIdx) {
            // The host's programmatic selection commits the title, pager and owner together.
            SEL selectSel = sel_registerName("selectItemAtIndex:needAnimation:");
            Method sm = class_getInstanceMethod(object_getClass(sTab), selectSel);
            if (sm && strcmp(method_getTypeEncoding(sm), "B28@0:8q16B24") == 0) {
                BOOL animated = !UIAccessibilityIsReduceMotionEnabled();
                ((BOOL (*)(id, SEL, NSInteger, BOOL))objc_msgSend)(sTab, selectSel, tappedIdx, animated);
                attempted = YES;
            }
        }
        NSInteger afterTabIdx = FQXIntGet(sTab, "selectedIndex", -1);
        if (afterTabIdx == tappedIdx && !FQXBoolGet(pagerScroll, "isScrollAnimating", NO)) {
            NSInteger pagerIndex = FQXIntGet(container, "currentIndex", -1);
            if (pagerIndex >= 0 && pagerIndex != tappedIdx) {
                SEL clickSel = sel_registerName("didClickSelectedItemAtIndex:");
                Method cm = class_getInstanceMethod(object_getClass(container), clickSel);
                if (cm && strcmp(method_getTypeEncoding(cm), "v24@0:8q16") == 0) {
                    ((void (*)(id, SEL, NSInteger))objc_msgSend)(container, clickSel, tappedIdx);
                    pagerIndex = FQXIntGet(container, "currentIndex", -1);
                    attempted = YES;
                }
            }
            NSInteger ownerIndex = FQXIntGet(sOwner, "currentTabIndex", -1);
            if (pagerIndex == tappedIdx && ownerIndex >= 0 && ownerIndex != tappedIdx) {
                SEL ownerSel = sel_registerName("categoryView:didSelectedItemAtIndex:");
                Method om = class_getInstanceMethod(object_getClass(sOwner), ownerSel);
                if (om && strcmp(method_getTypeEncoding(om), "v32@0:8@16q24") == 0) {
                    ((void (*)(id, SEL, id, NSInteger))objc_msgSend)(sOwner, ownerSel, sTab, tappedIdx);
                    attempted = YES;
                }
            }
        }
        if (attempted) {
            FQXDiagRecordEvent(FQXDiagCategoryUI, @"shelf_tab_tap_recovery", @{
                @"tappedTitle": tappedTitle,
                @"tappedIndex": @(tappedIdx),
                @"prevTabIdx": @(prevTabIdx),
                @"prevOwnerIdx": @(prevOwnerIdx),
                @"nowTabIdx": @(nowTabIdx),
                @"nowOwnerIdx": @(nowOwnerIdx),
                @"nowPagerIdx": @(nowPagerIdx),
                @"afterTabIdx": @(FQXIntGet(sTab, "selectedIndex", -1)),
                @"afterOwnerIdx": @(FQXIntGet(sOwner, "currentTabIndex", -1)),
                @"afterPagerIdx": @(FQXIntGet(container, "currentIndex", -1)),
                @"cellFrame": FQXDockRectArray(cellFrame),
                @"layoutFrame": FQXDockRectArray(layoutFrame),
            }, NO);
        }
    });
}

@end

static void FQXReflowShelfTabSelectView(UIView *tabSelectView) {
    if (![tabSelectView isKindOfClass:UIView.class]) return;
    [FQXTrackedShelfTabViews() addObject:tabSelectView];
    UICollectionView *cv = FQXObjGet(tabSelectView, "collectionView") ?: FQXFindMineCollectionView(tabSelectView, 3);
    FQXReflowShelfCollectionCells(cv, FQXShelfTabKeyForCell, 16.0, 0.0);
    FQXShelfTabTapBridge *bridge = objc_getAssociatedObject(tabSelectView, FQXShelfTabTapBridgeKey);
    if (!bridge) {
        bridge = [[FQXShelfTabTapBridge alloc] initWithTabSelectView:tabSelectView];
        objc_setAssociatedObject(tabSelectView, FQXShelfTabTapBridgeKey, bridge, OBJC_ASSOCIATION_RETAIN_NONATOMIC);
    } else if (bridge.tapGesture.view != tabSelectView) {
        [bridge.tapGesture.view removeGestureRecognizer:bridge.tapGesture];
        [tabSelectView addGestureRecognizer:bridge.tapGesture];
    }
}

static void FQXSyncShelfHeaderRightButtons(UIViewController *controller) {
    if (!controller) return;
    Class shelf525Cls = objc_lookUpClass("SSBookShelf525ViewController");
    Class shelfSubCls = objc_lookUpClass("SSBookShelfSubViewController");
    if (shelf525Cls && [controller isKindOfClass:shelf525Cls]) {
        [FQXTrackedShelf525VCs() addObject:controller];
        UIViewController *curTab = FQXObjGet(controller, "currentTabVC");
        if (curTab && curTab != controller) {
            FQXSyncShelfHeaderRightButtons(curTab);
            return;
        }
    }
    if (shelfSubCls && [controller isKindOfClass:shelfSubCls]) {
        [FQXTrackedShelfSubVCs() addObject:controller];
    }

    UIView *holder = FQXObjGet(controller, "searchAndMoreView");
    UIView *searchBtn = FQXObjGet(controller, "searchButton");
    UIView *moreBtn = FQXObjGet(controller, "moreButton");
    BOOL showSearch = FQXShelfOptionEnabled(@"FanqieX.ShelfSearchButton.1");
    BOOL showMore = FQXShelfOptionEnabled(@"FanqieX.ShelfMoreButton.1");
    BOOL showEdit = FQXShelfEditButtonEnabled();

    if ([searchBtn isKindOfClass:UIView.class]) {
        FQXShelfApplyControlHidden(searchBtn, FQXShelfHiddenByUsKey, !showSearch);
    }
    if ([moreBtn isKindOfClass:UIView.class]) {
        FQXShelfApplyControlHidden(moreBtn, FQXShelfHiddenByUsKey, !showMore);
    }
    if (![holder isKindOfClass:UIView.class]) return;

    UIView *relocatedEdit = nil;
    for (UIView *sub in holder.subviews) {
        if (sub == searchBtn || sub == moreBtn || [sub isKindOfClass:UIVisualEffectView.class]) continue;
        if ([sub isKindOfClass:UIControl.class] || CGRectGetWidth(sub.bounds) >= 24.0) {
            NSString *txt = FQXShelfFirstLabelText(sub, 0);
            if ([sub isKindOfClass:UIButton.class] || [txt containsString:@"编辑"]) {
                relocatedEdit = sub;
                break;
            }
        }
    }
    if (relocatedEdit) {
        FQXShelfApplyControlHidden(relocatedEdit, FQXShelfEditHiddenByUsKey, !showEdit);
    }

    NSMutableArray<UIView *> *rightToLeft = [NSMutableArray arrayWithCapacity:3];
    for (UIView *candidate in @[moreBtn ?: NSNull.null, searchBtn ?: NSNull.null, relocatedEdit ?: NSNull.null]) {
        if (![candidate isKindOfClass:UIView.class]) continue;
        UIView *btn = candidate;
        if (![btn isDescendantOfView:holder] || btn.hidden || btn.alpha <= 0.01 ||
            CGRectGetWidth(btn.bounds) < 12.0) {
            continue;
        }
        [rightToLeft addObject:btn];
    }

    FQXShelfApplyControlHidden(holder, FQXShelfHiddenByUsKey, rightToLeft.count == 0);
    if (!rightToLeft.count) return;

    CGFloat rightEdge = CGRectGetWidth(holder.bounds);
    for (UIView *btn in rightToLeft) {
        CGFloat w = CGRectGetWidth(btn.bounds);
        CGFloat targetX = rightEdge - w;
        CGRect f = btn.frame;
        if (fabs(f.origin.x - targetX) > 0.5) {
            f.origin.x = targetX;
            btn.frame = f;
        }
        rightEdge = targetX - 8.0;
    }
}

