static void FQXApplyShelfFunctionCellLayout(UIView *cell) {
    if (![cell isKindOfClass:UIView.class]) return;
    [FQXTrackedShelfFunctionCells() addObject:cell];
    UIView *header = FQXObjGet(cell, "headerView");
