static NSString *FQXHistoryDirectTextOfView(UIView *view) {
    if (!view) return nil;
    if ([view isKindOfClass:UILabel.class]) {
        UILabel *lbl = (UILabel *)view;
        return lbl.text.length ? lbl.text : lbl.attributedText.string;
    }
    if ([view isKindOfClass:UIButton.class]) {
        UIButton *btn = (UIButton *)view;
        NSString *t = btn.currentTitle.length ? btn.currentTitle : btn.currentAttributedTitle.string;
        if (t.length) return t;
        if (btn.titleLabel) {
            return btn.titleLabel.text.length ? btn.titleLabel.text : btn.titleLabel.attributedText.string;
        }
    }
    return nil;
}

static NSString *FQXHistoryFilterKeyForTitle(NSString *title) {
    if (![title isKindOfClass:NSString.class] || !title.length || title.length > 8) return nil;
    if ([title containsString:@"全部"]) return @"FanqieX.ShelfHistoryFilterAll.1";
    if ([title containsString:@"短篇"]) return @"FanqieX.ShelfHistoryFilterShortStory.1";
    if ([title containsString:@"漫画"]) return @"FanqieX.ShelfHistoryFilterComic.1";
    if ([title containsString:@"话题"]) return @"FanqieX.ShelfHistoryFilterTopic.1";
    if ([title containsString:@"阅读"] || [title containsString:@"小说"]) return @"FanqieX.ShelfHistoryFilterRead.1";
    if ([title containsString:@"听书"]) return @"FanqieX.ShelfHistoryFilterListen.1";
    if ([title containsString:@"短剧"] || [title containsString:@"漫剧"]) return @"FanqieX.ShelfHistoryFilterDrama.1";
    return nil;
}

static BOOL FQXHistoryCategoryVisible(NSString *title) {
    NSString *key = FQXHistoryFilterKeyForTitle(title);
    return !key || FQXShelfOptionEnabled(key);
}

static void (*OrigShelfHistoryLoadCategory)(id, SEL, double);
static void HookShelfHistoryLoadCategory(UIViewController *self, SEL cmd, double height) {
    FQXMigrateLegacyHistoryFilterBarPrefIfNeeded();
    NSArray *tabs = FQXObjGet(self, "tabVCs");
    NSInteger current = FQXIntGet(self, "currentVCIndex", -1);
    if ([tabs isKindOfClass:NSArray.class] && tabs.count <= FQXMaxCompactStripItems &&
        current >= 0 && (NSUInteger)current < tabs.count &&
        !FQXHistoryCategoryVisible(FQXObjGet(tabs[(NSUInteger)current], "tabName"))) {
        unsigned int visibleMask = 0;
        for (NSUInteger i = 0; i < tabs.count; i++) {
            if (FQXHistoryCategoryVisible(FQXObjGet(tabs[i], "tabName"))) visibleMask |= 1u << i;
        }
        int redirect = FQXEvaluateVisiblePagerPolicy(tabs.count, visibleMask, 1, (int)current).redirectIndex;
        SEL setter = sel_registerName("setCurrentVCIndex:");
        Method method = class_getInstanceMethod(object_getClass(self), setter);
        if (redirect >= 0 && method && strcmp(method_getTypeEncoding(method), "v24@0:8q16") == 0) {
            // The host copies this index into the category and its lazy list container during setup.
            ((void (*)(id, SEL, NSInteger))objc_msgSend)(self, setter, redirect);
        }
    }
    OrigShelfHistoryLoadCategory(self, cmd, height);
}

static NSString *FQXHistoryFilterKeyForCell(UIView *cell) {
    if (![cell isKindOfClass:UIView.class]) return nil;
    NSString *title = FQXHistoryDirectTextOfView(cell);
    if (!title.length) {
        UILabel *lbl = FQXObjGet(cell, "textLabel") ?: FQXObjGet(cell, "titleLabel") ?: FQXObjGet(cell, "label");
        if ([lbl isKindOfClass:UILabel.class]) {
            title = lbl.text.length ? lbl.text : lbl.attributedText.string;
        }
    }
    if (!title.length) {
        id model = FQXObjGet(cell, "model") ?: FQXObjGet(cell, "cellModel");
        id mTitle = FQXObjGet(model, "title") ?: FQXObjGet(model, "name");
        if ([mTitle isKindOfClass:NSString.class]) title = mTitle;
    }
    if (!title.length) title = FQXShelfFirstLabelText(cell, 0);
    return FQXHistoryFilterKeyForTitle(title);
}

