static void FQXSelectShelfCategoryIndex(UIViewController *ownerVC,
                                        id categoryView,
                                        id listContainer,
                                        UIScrollView *pagerScroll,
                                        NSInteger target,
                                        BOOL isRootShelf) {
    if (target < 0) return;
    if (categoryView) {
        SEL selNeedAnim = sel_registerName("selectItemAtIndex:needAnimation:");
        Method mAnim = class_getInstanceMethod(object_getClass(categoryView), selNeedAnim);
        if (mAnim && strcmp(method_getTypeEncoding(mAnim), "B28@0:8q16B24") == 0) {
            ((BOOL (*)(id, SEL, NSInteger, BOOL))objc_msgSend)(categoryView, selNeedAnim, target, NO);
        } else {
            SEL selPlain = sel_registerName("selectItemAtIndex:");
            Method mPlain = class_getInstanceMethod(object_getClass(categoryView), selPlain);
            if (mPlain && strcmp(method_getTypeEncoding(mPlain), "v24@0:8q16") == 0) {
                ((void (*)(id, SEL, NSInteger))objc_msgSend)(categoryView, selPlain, target);
            }
        }
    }
    if (listContainer) {
        NSInteger lcCur = FQXIntGet(listContainer, "currentIndex", target);
        if (lcCur != target) {
            SEL clickSel = sel_registerName("didClickSelectedItemAtIndex:");
            Method cm = class_getInstanceMethod(object_getClass(listContainer), clickSel);
            if (cm && strcmp(method_getTypeEncoding(cm), "v24@0:8q16") == 0) {
                ((void (*)(id, SEL, NSInteger))objc_msgSend)(listContainer, clickSel, target);
            }
        }
    }
    if ([pagerScroll isKindOfClass:UIScrollView.class]) {
        CGFloat pageW = CGRectGetWidth(pagerScroll.bounds);
        if (pageW > 100.0 && !FQXBoolGet(pagerScroll, "isScrollAnimating", NO)) {
            CGFloat targetX = pageW * (CGFloat)target;
            CGFloat maxContentX = pagerScroll.contentSize.width - pageW;
            if ((isRootShelf || targetX <= maxContentX + 1.0) &&
                fabs(pagerScroll.contentOffset.x - targetX) > 1.0) {
                [pagerScroll setContentOffset:CGPointMake(targetX, pagerScroll.contentOffset.y) animated:NO];
            }
        }
    }
    if (ownerVC && categoryView) {
        NSInteger ownerCur = isRootShelf
            ? FQXIntGet(ownerVC, "currentTabIndex", target)
            : FQXIntGet(ownerVC, "currentVCIndex", target);
        if (ownerCur != target) {
            SEL didSel = sel_registerName("categoryView:didSelectedItemAtIndex:");
            Method om = class_getInstanceMethod(object_getClass(ownerVC), didSel);
            if (om && strcmp(method_getTypeEncoding(om), "v32@0:8@16q24") == 0) {
                ((void (*)(id, SEL, id, NSInteger))objc_msgSend)(ownerVC, didSel, categoryView, target);
            }
        }
    }
    if ([categoryView isKindOfClass:UIView.class]) {
        [(UIView *)categoryView setNeedsLayout];
    }
}

static unsigned int FQXShelfPagerMaskAndCount(UIViewController *ownerVC,
                                              id categoryView,
                                              BOOL isRootShelf,
                                              size_t *outCount) {
    if (outCount) *outCount = 0;
    if (isRootShelf) {
        NSArray *models = FQXObjGet(ownerVC, "bookshelfTabModelArray");
        if (![models isKindOfClass:NSArray.class] || !models.count || models.count > FQXMaxCompactStripItems) {
            return 0;
        }
        unsigned int mask = 0;
        for (NSUInteger i = 0; i < models.count; ++i) {
            NSString *key = FQXShelfTabKeyForTitle(FQXObjGet(models[i], "title"));
            if (!key || FQXShelfOptionEnabled(key)) mask |= (1u << i);
        }
        if (outCount) *outCount = models.count;
        return mask;
    }

    NSArray *titles = FQXObjGet(categoryView, "titles");
    NSArray *ds = FQXObjGet(categoryView, "dataSource");
    NSUInteger count = [titles isKindOfClass:NSArray.class] ? titles.count : 0;
    if (count == 0 && [ds isKindOfClass:NSArray.class]) count = ds.count;
    if (count == 0 || count > FQXMaxCompactStripItems) return 0;
    unsigned int mask = 0;
    for (NSUInteger i = 0; i < count; ++i) {
        NSString *title = nil;
        if ([titles isKindOfClass:NSArray.class] && i < titles.count && [titles[i] isKindOfClass:NSString.class]) {
            title = titles[i];
        } else if ([ds isKindOfClass:NSArray.class] && i < ds.count) {
            id t = FQXObjGet(ds[i], "title") ?: FQXObjGet(ds[i], "name");
            if ([t isKindOfClass:NSString.class]) title = t;
        }
        if (FQXHistoryCategoryVisible(title)) mask |= (1u << i);
    }
    if (outCount) *outCount = count;
    return mask;
}

static NSInteger FQXShelfCurrentPagerIndex(UIViewController *ownerVC,
                                           id categoryView,
                                           id listContainer,
                                           UIScrollView *pagerScroll,
                                           BOOL isRootShelf) {
    NSInteger sel = FQXIntGet(categoryView, "selectedIndex", -1);
    if (sel >= 0) return sel;
    if (listContainer) {
        NSInteger lc = FQXIntGet(listContainer, "currentIndex", -1);
        if (lc >= 0) return lc;
    }
    NSInteger vcIdx = isRootShelf
        ? FQXIntGet(ownerVC, "currentTabIndex", -1)
        : FQXIntGet(ownerVC, "currentVCIndex", -1);
    if (vcIdx >= 0) return vcIdx;
    if ([pagerScroll isKindOfClass:UIScrollView.class] && CGRectGetWidth(pagerScroll.bounds) > 100.0) {
        return (NSInteger)llround(pagerScroll.contentOffset.x / CGRectGetWidth(pagerScroll.bounds));
    }
    return -1;
}

@interface FQXShelfVisiblePagerPanController : NSObject <UIGestureRecognizerDelegate> {
@public
    __weak UIViewController *_ownerVC;
    __weak id _categoryView;
    __weak id _listContainer;
    __weak UIView *_gestureHost;
    __weak UIScrollView *_pagerScroll;
    UIPanGestureRecognizer *_panGesture;
    BOOL _visibleStepSwipeActive;
    BOOL _isRootShelf;
}
@end

@implementation FQXShelfVisiblePagerPanController

- (instancetype)initWithHost:(UIView *)host scrollView:(UIScrollView *)scroll {
    self = [super init];
    if (self) {
        _gestureHost = host;
        _pagerScroll = scroll;
        UIPanGestureRecognizer *pan = [[UIPanGestureRecognizer alloc] initWithTarget:self action:@selector(handlePan:)];
        pan.maximumNumberOfTouches = 1;
        pan.cancelsTouchesInView = YES;
        pan.delaysTouchesBegan = NO;
        pan.delaysTouchesEnded = YES;
        pan.delegate = self;
        pan.enabled = NO;
        _panGesture = pan;
        [host addGestureRecognizer:pan];
    }
    return self;
}

- (BOOL)gestureRecognizer:(UIGestureRecognizer *)gestureRecognizer shouldReceiveTouch:(UITouch *)touch {
    if (gestureRecognizer != self->_panGesture) return YES;
    if (!self->_visibleStepSwipeActive) return NO;
    UIView *host = self->_gestureHost;
    UIScrollView *pager = self->_pagerScroll;
    if (!host || !host.window || host.hidden || !pager || !pager.window || pager.hidden) return NO;

    CGPoint locInPager = [touch locationInView:pager];
    if (!CGRectContainsPoint(pager.bounds, locInPager)) return NO;

    if ([self->_categoryView isKindOfClass:UIView.class]) {
        UIView *catV = (UIView *)self->_categoryView;
        if (!catV.hidden && catV.window == host.window) {
            CGPoint locInCat = [touch locationInView:catV];
            if (CGRectContainsPoint(CGRectInset(catV.bounds, -8.0, -8.0), locInCat)) return NO;
        }
    }

    for (UIView *view = touch.view; view && view != host; view = view.superview) {
        if ([view isKindOfClass:UIScrollView.class] && view != pager) {
            UIScrollView *nested = (UIScrollView *)view;
            if (nested.scrollEnabled && nested.userInteractionEnabled &&
                nested.contentSize.width > CGRectGetWidth(nested.bounds) + 2.0) {
                return NO;
            }
        }
    }
    return YES;
}

- (BOOL)gestureRecognizerShouldBegin:(UIGestureRecognizer *)gestureRecognizer {
    if (gestureRecognizer != self->_panGesture) return YES;
    if (!self->_visibleStepSwipeActive) return NO;
    UIView *host = self->_gestureHost;
    if (!host || !host.window || host.hidden || !self->_ownerVC) return NO;
    CGPoint direction = [self->_panGesture translationInView:host];
    if (fmax(fabs(direction.x), fabs(direction.y)) < 4.0) {
        direction = [self->_panGesture velocityInView:host];
    }
    return fabs(direction.x) > fabs(direction.y) * 1.45;
}

- (BOOL)gestureRecognizer:(UIGestureRecognizer *)gr
    shouldRecognizeSimultaneouslyWithGestureRecognizer:(UIGestureRecognizer *)other {
    (void)gr; (void)other;
    return NO;
}

- (BOOL)gestureRecognizer:(UIGestureRecognizer *)gestureRecognizer
    shouldBeRequiredToFailByGestureRecognizer:(UIGestureRecognizer *)other {
    UIView *host = self->_gestureHost;
    return gestureRecognizer == self->_panGesture && self->_visibleStepSwipeActive && host &&
           [other isKindOfClass:UITapGestureRecognizer.class] && [other.view isDescendantOfView:host];
}

- (void)handlePan:(UIPanGestureRecognizer *)pan {
    if (pan.state != UIGestureRecognizerStateEnded || !self->_visibleStepSwipeActive) return;
    UIView *host = self->_gestureHost;
    UIViewController *owner = self->_ownerVC;
    if (!host || !owner) return;

    CGPoint trans = [pan translationInView:host];
    CGPoint vel = [pan velocityInView:host];
    if (fabs(trans.y) > fabs(trans.x) * 0.9 && fabs(vel.x) < 340.0) return;

    int step = 0;
    if (trans.x <= -46.0 || vel.x <= -340.0) step = 1;
    else if (trans.x >= 46.0 || vel.x >= 340.0) step = -1;
    if (step == 0) return;

    size_t count = 0;
    unsigned int mask = FQXShelfPagerMaskAndCount(owner, self->_categoryView, self->_isRootShelf, &count);
    if (count < 2 || mask == 0) return;
    NSInteger cur = FQXShelfCurrentPagerIndex(owner, self->_categoryView, self->_listContainer, self->_pagerScroll, self->_isRootShelf);
    int target = FQXStepVisiblePagerIndex(count, mask, (int)cur, step);
    if (target < 0 || target == (int)cur) return;

    UISelectionFeedbackGenerator *gen = [[UISelectionFeedbackGenerator alloc] init];
    [gen selectionChanged];
    FQXSelectShelfCategoryIndex(owner, self->_categoryView, self->_listContainer, self->_pagerScroll, target, self->_isRootShelf);
    FQXDiagRecordEvent(FQXDiagCategoryUI, @"shelf_pager_visible_swipe", @{
        @"isRootShelf": @(self->_isRootShelf),
        @"fromIndex": @(cur),
        @"toIndex": @(target),
        @"direction": (step > 0) ? @"left_next" : @"right_prev",
        @"visibleMask": @(mask),
    }, NO);
}

@end

static UIScrollView *FQXFindHorizontalHistoryPagerScroll(UIView *root, UIView *excludedStrip, NSInteger depth) {
    if (!root || depth > 4 || root == excludedStrip || (excludedStrip && [root isDescendantOfView:excludedStrip])) {
        return nil;
    }
    if ([root isKindOfClass:UIScrollView.class] &&
        ![root isKindOfClass:UITableView.class] &&
        ![root isKindOfClass:UICollectionView.class]) {
        UIScrollView *sv = (UIScrollView *)root;
        CGFloat w = CGRectGetWidth(sv.bounds);
        CGFloat h = CGRectGetHeight(sv.bounds);
        if (w >= 180.0 && h >= 160.0 && (sv.isPagingEnabled || sv.contentSize.width > w * 1.4)) {
            return sv;
        }
    }
    for (UIView *sub in root.subviews) {
        UIScrollView *hit = FQXFindHorizontalHistoryPagerScroll(sub, excludedStrip, depth + 1);
        if (hit) return hit;
    }
    return nil;
}

static void FQXApplyShelfPagerPolicy(UIViewController *ownerVC,
                                     id categoryView,
                                     id listContainer,
                                     UIScrollView *scroll,
                                     size_t totalCount,
                                     unsigned int visibleMask,
                                     BOOL masterVisible,
                                     BOOL isRootShelf) {
    if (!ownerVC || ![scroll isKindOfClass:UIScrollView.class] || totalCount == 0) return;

    NSInteger currentIndex = FQXShelfCurrentPagerIndex(ownerVC, categoryView, listContainer, scroll, isRootShelf);
    FQXVisiblePagerPolicy policy = FQXEvaluateVisiblePagerPolicy(totalCount,
                                                                 visibleMask,
                                                                 masterVisible ? 1 : 0,
                                                                 (int)currentIndex);
    BOOL allowNative = (policy.allowNativeScroll != 0);
    BOOL allowStepPan = (policy.allowVisibleStepPan != 0);

    UIPanGestureRecognizer *nativePan = scroll.panGestureRecognizer;
    BOOL disabledByPlugin = objc_getAssociatedObject(scroll, &FQXHistoryPanDisabledByPlugin) != nil;
    if (!allowNative) {
        objc_setAssociatedObject(scroll, &FQXHistoryPanDisabledByPlugin, @YES, OBJC_ASSOCIATION_RETAIN_NONATOMIC);
        if (scroll.scrollEnabled) scroll.scrollEnabled = NO;
        if (nativePan && nativePan.enabled) nativePan.enabled = NO;
    } else if (disabledByPlugin) {
        objc_setAssociatedObject(scroll, &FQXHistoryPanDisabledByPlugin, nil, OBJC_ASSOCIATION_RETAIN_NONATOMIC);
        if (!scroll.scrollEnabled) scroll.scrollEnabled = YES;
        if (nativePan && !nativePan.enabled) nativePan.enabled = YES;
    }

    UIView *gestureHost = ([listContainer isKindOfClass:UIView.class] ? (UIView *)listContainer : nil)
        ?: scroll.superview
        ?: ownerVC.view;
    FQXShelfVisiblePagerPanController *panCtl = gestureHost
        ? objc_getAssociatedObject(gestureHost, &FQXShelfPagerControllerKey)
        : nil;
    if (!panCtl && allowStepPan && gestureHost) {
        panCtl = [[FQXShelfVisiblePagerPanController alloc] initWithHost:gestureHost scrollView:scroll];
        objc_setAssociatedObject(gestureHost, &FQXShelfPagerControllerKey, panCtl, OBJC_ASSOCIATION_RETAIN_NONATOMIC);
    }
    if (panCtl) {
        panCtl->_ownerVC = ownerVC;
        panCtl->_categoryView = categoryView;
        panCtl->_listContainer = listContainer;
        panCtl->_gestureHost = gestureHost;
        panCtl->_pagerScroll = scroll;
        panCtl->_isRootShelf = isRootShelf;
        panCtl->_visibleStepSwipeActive = allowStepPan;
        if (gestureHost && panCtl->_panGesture.view != gestureHost) {
            [panCtl->_panGesture.view removeGestureRecognizer:panCtl->_panGesture];
            [gestureHost addGestureRecognizer:panCtl->_panGesture];
        }
        if (panCtl->_panGesture.enabled != allowStepPan) {
            panCtl->_panGesture.enabled = allowStepPan;
        }
    }

    if (policy.redirectIndex >= 0) {
        NSNumber *lastTs = objc_getAssociatedObject(scroll, &FQXShelfPagerRedirectTsKey);
        CFTimeInterval now = CACurrentMediaTime();
        if (!lastTs || (now - lastTs.doubleValue) > 0.20) {
            objc_setAssociatedObject(scroll, &FQXShelfPagerRedirectTsKey, @(now), OBJC_ASSOCIATION_RETAIN_NONATOMIC);
            FQXSelectShelfCategoryIndex(ownerVC, categoryView, listContainer, scroll, policy.redirectIndex, isRootShelf);
        }
    } else if (!allowNative && currentIndex >= 0 && (size_t)currentIndex < totalCount &&
               ((visibleMask >> (unsigned int)currentIndex) & 1u)) {
        CGFloat pageW = CGRectGetWidth(scroll.bounds);
        if (pageW > 100.0 && !FQXBoolGet(scroll, "isScrollAnimating", NO)) {
            CGFloat expectedX = pageW * (CGFloat)currentIndex;
            if (fabs(scroll.contentOffset.x - expectedX) > 1.0 &&
                (isRootShelf || expectedX <= scroll.contentSize.width - pageW + 1.0)) {
                [scroll setContentOffset:CGPointMake(expectedX, scroll.contentOffset.y) animated:NO];
            }
        }
    }
}

static void FQXSyncShelfHistoryPager(UIViewController *historyVC, id category, UIView *leftCV, BOOL anyLeft) {
    size_t count = 0;
    unsigned int visibleMask = FQXShelfPagerMaskAndCount(historyVC, category, NO, &count);
    if (count == 0) return;

    id listContainer = FQXObjGet(category, "listContainer")
        ?: FQXObjGet(historyVC, "listContainerView")
        ?: FQXObjGet(historyVC, "containerView")
        ?: FQXObjGet(historyVC, "listContainer");
    UIScrollView *scroll = nil;
    id candScrolls[] = {
        FQXObjGet(category, "contentScrollView"),
        FQXObjGet(listContainer, "scrollView"),
        FQXObjGet(historyVC, "contentScrollView"),
        FQXObjGet(historyVC, "scrollView"),
    };
    for (size_t i = 0; i < sizeof(candScrolls) / sizeof(candScrolls[0]); ++i) {
        if ([candScrolls[i] isKindOfClass:UIScrollView.class] && candScrolls[i] != leftCV) {
            scroll = candScrolls[i];
            break;
        }
    }
    if (!scroll && historyVC.isViewLoaded) {
        scroll = FQXFindHorizontalHistoryPagerScroll(historyVC.view, leftCV, 0);
    }
    if (!scroll) return;

    FQXApplyShelfPagerPolicy(historyVC, category, listContainer, scroll, count, visibleMask, anyLeft, NO);
}

static BOOL (*OrigShelfHistoryCanSelect)(id, SEL, id, NSInteger);
static BOOL HookShelfHistoryCanSelect(id historyVC, SEL cmd, id category, NSInteger index) {
    size_t count = 0;
    unsigned int mask = FQXShelfPagerMaskAndCount(historyVC, category, NO, &count);
    if (count > 0 && index >= 0 && (size_t)index < count) {
        if (((mask >> (unsigned int)index) & 1u) == 0) return NO;
    }
    return OrigShelfHistoryCanSelect ? OrigShelfHistoryCanSelect(historyVC, cmd, category, index) : YES;
}

static void FQXCollectHistoryBarMarkers(UIView *view, NSMutableSet<NSString *> *hits, NSInteger depth) {
    if (!view || depth > 5 || hits.count >= 6) return;
    NSString *t = FQXHistoryDirectTextOfView(view);
    if (t.length > 0 && t.length <= 8) {
        static NSArray<NSString *> *tokens = nil;
        static dispatch_once_t once;
        dispatch_once(&once, ^{ tokens = @[@"全部", @"阅读", @"小说", @"听书", @"短剧", @"漫剧", @"短篇", @"漫画", @"话题", @"筛选", @"编辑"]; });
        for (NSString *tok in tokens) {
            if ([t containsString:tok]) {
                [hits addObject:tok];
                break;
            }
        }
    }
    for (UIView *sub in view.subviews) {
        FQXCollectHistoryBarMarkers(sub, hits, depth + 1);
    }
}

static UIScrollView *FQXFindMainHistoryContentScroll(UIView *root, NSArray<UIView *> *excludedBars, NSInteger depth) {
    if (!root || depth > 5) return nil;
    for (UIView *bar in excludedBars) {
        if (root == bar || [root isDescendantOfView:bar]) return nil;
    }
    UIScrollView *best = nil;
    CGFloat bestArea = 0.0;
    if ([root isKindOfClass:UICollectionView.class] || [root isKindOfClass:UITableView.class] ||
        [root isKindOfClass:UIScrollView.class]) {
        CGFloat h = CGRectGetHeight(root.bounds);
        CGFloat w = CGRectGetWidth(root.bounds);
        if (h >= 150.0 && w >= 200.0) {
            best = (UIScrollView *)root;
            bestArea = w * h;
        }
    }
    for (UIView *sub in root.subviews) {
        UIScrollView *cand = FQXFindMainHistoryContentScroll(sub, excludedBars, depth + 1);
        if (cand) {
            CGFloat area = CGRectGetWidth(cand.bounds) * CGRectGetHeight(cand.bounds);
            if (area > bestArea) {
                best = cand;
                bestArea = area;
            }
        }
    }
    return best;
}

@interface FQXHistoryPillTapBridge : NSObject <UIGestureRecognizerDelegate>
@property(nonatomic, weak) UICollectionView *collectionView;
@property(nonatomic, strong) UITapGestureRecognizer *tapGesture;
@end

@implementation FQXHistoryPillTapBridge
- (instancetype)initWithCollectionView:(UICollectionView *)cv {
    self = [super init];
    if (self) {
        _collectionView = cv;
        UITapGestureRecognizer *tap = [[UITapGestureRecognizer alloc] initWithTarget:self action:@selector(handleTap:)];
        tap.cancelsTouchesInView = NO;
        tap.delaysTouchesBegan = NO;
        tap.delaysTouchesEnded = NO;
        tap.delegate = self;
        _tapGesture = tap;
        [cv addGestureRecognizer:tap];
    }
    return self;
}
- (BOOL)gestureRecognizer:(UIGestureRecognizer *)gr shouldRecognizeSimultaneouslyWithGestureRecognizer:(UIGestureRecognizer *)other {
    (void)gr; (void)other;
    return YES;
}
- (void)handleTap:(UITapGestureRecognizer *)gr {
    if (gr.state != UIGestureRecognizerStateEnded) return;
    UICollectionView *cv = self.collectionView;
    if (!cv || !cv.window || cv.hidden) return;
    if (![objc_getAssociatedObject(cv, FQXShelfReflowAppliedKey) boolValue]) return;
    CGPoint pt = [gr locationInView:cv];
    NSIndexPath *nativeIP = [cv indexPathForItemAtPoint:pt];
    NSIndexPath *visualIP = nil;
    CGFloat bestDist = CGFLOAT_MAX;
    for (NSIndexPath *ip in [cv indexPathsForVisibleItems]) {
        UICollectionViewCell *cell = [cv cellForItemAtIndexPath:ip];
        if (!cell || cell.hidden || cell.alpha <= 0.05) continue;
        if (CGRectContainsPoint(CGRectInset(cell.frame, -4.0, -6.0), pt)) {
            CGFloat d = fabs(pt.x - CGRectGetMidX(cell.frame));
            if (d < bestDist) {
                bestDist = d;
                visualIP = ip;
            }
        }
    }
    if (!visualIP || (nativeIP && [nativeIP isEqual:visualIP])) return;
    id<UICollectionViewDelegate> del = cv.delegate;
    if (del && [del respondsToSelector:@selector(collectionView:didSelectItemAtIndexPath:)]) {
        dispatch_async(dispatch_get_main_queue(), ^{
            if (cv.window && cv.delegate == del) {
                [del collectionView:cv didSelectItemAtIndexPath:visualIP];
            }
        });
    }
}
@end

static void FQXInstallHistoryLeftCVHookIfNeeded(UICollectionView *cv) {
    if (![cv isKindOfClass:UICollectionView.class]) return;
    objc_setAssociatedObject(cv, FQXHistoryLeftCVTrackedKey, @YES, OBJC_ASSOCIATION_RETAIN_NONATOMIC);
    if (!objc_getAssociatedObject(cv, FQXHistoryLeftCVTapBridgeKey)) {
        FQXHistoryPillTapBridge *bridge = [[FQXHistoryPillTapBridge alloc] initWithCollectionView:cv];
        objc_setAssociatedObject(cv, FQXHistoryLeftCVTapBridgeKey, bridge, OBJC_ASSOCIATION_RETAIN_NONATOMIC);
    }
    static NSMutableSet<NSString *> *hooked;
    static dispatch_once_t once;
    dispatch_once(&once, ^{ hooked = [NSMutableSet set]; });
    Class cls = FQXRealHookClass(cv);
    if (!cls || cls == UICollectionView.class) return;
    NSString *name = NSStringFromClass(cls);
    if (!name.length || [hooked containsObject:name]) return;
    __block IMP orig = NULL;
    IMP hook = imp_implementationWithBlock(^(UICollectionView *selfCV) {
        if (orig) ((void (*)(id, SEL))orig)(selfCV, @selector(layoutSubviews));
        if (![objc_getAssociatedObject(selfCV, FQXHistoryLeftCVTrackedKey) boolValue]) return;
        if (FQXHistoryAnyLeftPillEnabled()) {
            FQXReflowShelfCollectionCells(selfCV, FQXHistoryFilterKeyForCell, 8.0, 0.0);
        }
    });
    if (FQXInstallOwnedHook(cls, @selector(layoutSubviews), NO, "v16@0:8", hook, &orig)) {
        [hooked addObject:name];
    } else {
        imp_removeBlock(hook);
    }
}

static BOOL FQXViewSubtreeContainsAnyToken(UIView *view, NSArray<NSString *> *tokens, NSInteger depth) {
    if (!view || depth > 4) return NO;
    NSString *t = FQXHistoryDirectTextOfView(view);
    if (t.length > 0 && t.length <= 12) {
        for (NSString *tok in tokens) {
            if ([t containsString:tok]) return YES;
        }
    }
    for (UIView *sub in view.subviews) {
        if (FQXViewSubtreeContainsAnyToken(sub, tokens, depth + 1)) return YES;
    }
    return NO;
}

static UIView *FQXClimbTightHistoryButton(UIView *leaf, UIView *vcView, NSArray<NSString *> *forbiddenTokens) {
    if (!leaf || !vcView) return nil;
    UIView *best = leaf;
    for (UIView *cur = leaf; cur && cur != vcView; cur = cur.superview) {
        if ([cur isKindOfClass:UIScrollView.class]) break;
        CGRect cb = cur.bounds;
        CGFloat w = CGRectGetWidth(cb);
        CGFloat h = CGRectGetHeight(cb);
        if (w < 16.0 || w > 116.0 || h < 12.0 || h > 56.0) break;
        if (FQXViewSubtreeContainsAnyToken(cur, forbiddenTokens, 0)) break;
        best = cur;
        if ([cur isKindOfClass:UIControl.class]) break;
    }
    return best;
}

typedef struct {
    __unsafe_unretained UICollectionView *leftCV;
    __unsafe_unretained UIView *filterBtn;
    __unsafe_unretained UIView *editBtn;
} FQXHistoryTopBarScan;

static void FQXScanHistoryTopBarDepth(UIView *node,
                                      UIView *vcView,
                                      UIScrollView *mainScroll,
                                      CGFloat vcW,
                                      FQXHistoryTopBarScan *scan,
                                      NSMutableArray<UIView *> *leftPills,
                                      NSInteger depth) {
    if (!node || !vcView || depth > 7) return;
    if (mainScroll && (node == mainScroll || [node isDescendantOfView:mainScroll])) return;

    CGRect inVC = [node convertRect:node.bounds toView:vcView];
    if (depth > 0 && CGRectGetMinY(inVC) > 200.0) return;

    if (depth > 0 && [node isKindOfClass:UICollectionView.class] &&
        CGRectGetHeight(inVC) >= 18.0 && CGRectGetHeight(inVC) <= 76.0 &&
        CGRectGetWidth(inVC) >= 72.0) {
        UICollectionView *cv = (UICollectionView *)node;
        BOOL matched = [objc_getAssociatedObject(cv, FQXHistoryLeftCVTrackedKey) boolValue];
        if (!matched) {
            for (UICollectionViewCell *cell in cv.visibleCells) {
                if (FQXHistoryFilterKeyForCell(cell)) { matched = YES; break; }
            }
        }
        if (!matched) {
            NSMutableSet<NSString *> *hits = [NSMutableSet set];
            FQXCollectHistoryBarMarkers(cv, hits, 0);
            for (NSString *title in hits) {
                if (FQXHistoryFilterKeyForTitle(title)) {
                    matched = YES;
                    break;
                }
            }
        }
        if (matched && !scan->leftCV) {
            scan->leftCV = cv;
            return;
        }
    }

    if (depth > 0 && CGRectGetMinY(inVC) <= 190.0 && CGRectGetHeight(inVC) <= 64.0) {
        NSString *t = FQXHistoryDirectTextOfView(node);
        if (t.length > 0 && t.length <= 8) {
            if ([t containsString:@"筛选"] && ![t containsString:@"编辑"] && !scan->filterBtn) {
                scan->filterBtn = FQXClimbTightHistoryButton(node, vcView, @[@"编辑", @"全部", @"阅读", @"小说", @"听书", @"短剧", @"漫剧", @"短篇", @"漫画", @"话题"]);
                return;
            }
            if ([t containsString:@"编辑"] && ![t containsString:@"筛选"] &&
                ![t containsString:@"完成"] && ![t containsString:@"取消"] && !scan->editBtn) {
                scan->editBtn = FQXClimbTightHistoryButton(node, vcView, @[@"筛选", @"全部", @"阅读", @"小说", @"听书", @"短剧", @"漫剧", @"短篇", @"漫画", @"话题"]);
                return;
            }
            if (!scan->leftCV && FQXHistoryFilterKeyForTitle(t)) {
                UIView *pill = FQXClimbTightHistoryButton(node, vcView, @[@"筛选", @"编辑"]);
                if (pill && pill != vcView && CGRectGetWidth(pill.bounds) <= 120.0) {
                    NSMutableSet<NSString *> *subHits = [NSMutableSet set];
                    FQXCollectHistoryBarMarkers(pill, subHits, 0);
                    if (subHits.count <= 1) {
                        BOOL dup = NO;
                        for (UIView *existing in leftPills) {
                            if (existing == pill || [pill isDescendantOfView:existing] || [existing isDescendantOfView:pill]) {
                                dup = YES;
                                break;
                            }
                        }
                        if (!dup) [leftPills addObject:pill];
                        return;
                    }
                }
            }
        }
    }

    for (UIView *sub in node.subviews) {
        FQXScanHistoryTopBarDepth(sub, vcView, mainScroll, vcW, scan, leftPills, depth + 1);
    }
}

static const char FQXK_HistoryLayerHiddenByUsKey = 0;
#define FQXHistoryLayerHiddenByUsKey ((const void *)&FQXK_HistoryLayerHiddenByUsKey)

static void FQXApplyHistoryLayerHidden(CALayer *layer, BOOL hide) {
    if (![layer isKindOfClass:CALayer.class]) return;
    if (hide) {
        if (!layer.hidden) {
            objc_setAssociatedObject(layer, FQXHistoryLayerHiddenByUsKey, @YES, OBJC_ASSOCIATION_RETAIN_NONATOMIC);
            layer.hidden = YES;
        }
    } else if ([objc_getAssociatedObject(layer, FQXHistoryLayerHiddenByUsKey) boolValue]) {
        layer.hidden = NO;
        objc_setAssociatedObject(layer, FQXHistoryLayerHiddenByUsKey, nil, OBJC_ASSOCIATION_RETAIN_NONATOMIC);
    }
}

static BOOL FQXViewHasGradientLayer(UIView *view) {
    if (![view isKindOfClass:UIView.class]) return NO;
    if ([view.layer isKindOfClass:CAGradientLayer.class]) return YES;
    for (CALayer *sub in view.layer.sublayers) {
        if ([sub isKindOfClass:CAGradientLayer.class]) return YES;
    }
    return NO;
}

static void FQXCollectHistoryDividersDepth(UIView *node,
                                           UIView *vcView,
                                           UIScrollView *mainScroll,
                                           CGFloat vcW,
                                           CGFloat rowMidY,
                                           NSMutableArray<UIView *> *outDividers,
                                           NSMutableArray<UIView *> *outRightMasks,
                                           NSInteger depth) {
    if (!node || !vcView || depth > 6) return;
    if (mainScroll && (node == mainScroll || [node isDescendantOfView:mainScroll])) return;
    CGRect inVC = [node convertRect:node.bounds toView:vcView];
    if (depth > 0 && CGRectGetMinY(inVC) > 200.0) return;
    if (depth > 0 && ![node isKindOfClass:UILabel.class] && ![node isKindOfClass:UIControl.class] &&
        ![node isKindOfClass:UICollectionView.class] && ![node isKindOfClass:UICollectionViewCell.class]) {
        CGFloat w = CGRectGetWidth(inVC);
        CGFloat h = CGRectGetHeight(inVC);
        NSString *clsName = NSStringFromClass(node.class) ?: @"";
        if (![clsName containsString:@"ScrollIndicator"] && fabs(CGRectGetMidY(inVC) - rowMidY) <= 18.0) {
            if (w >= 0.3 && w <= 4.0 && h >= 6.0 && h <= 36.0 && CGRectGetMinX(inVC) >= vcW * 0.45) {
                if (![outDividers containsObject:node]) [outDividers addObject:node];
                return;
            }
            if (outRightMasks && w > 4.0 && w <= 36.0 && h >= 14.0 && h <= 56.0 &&
                CGRectGetMinX(inVC) >= vcW * 0.40 && node.subviews.count == 0 &&
                ([node isKindOfClass:UIImageView.class] || FQXViewHasGradientLayer(node))) {
                if (![outRightMasks containsObject:node]) [outRightMasks addObject:node];
                return;
            }
        }
    }
    for (UIView *sub in node.subviews) {
        FQXCollectHistoryDividersDepth(sub, vcView, mainScroll, vcW, rowMidY, outDividers, outRightMasks, depth + 1);
    }
}

static UIView *FQXCommonCompactAncestor(UIView *a, UIView *b, UIView *vcView, UIScrollView *mainScroll) {
    if (!a || !b || !vcView) return nil;
    for (UIView *pa = a.superview; pa && pa != vcView; pa = pa.superview) {
        if ([b isDescendantOfView:pa]) {
            if (mainScroll && (pa == mainScroll || [mainScroll isDescendantOfView:pa])) return nil;
            CGRect inVC = [pa convertRect:pa.bounds toView:vcView];
            if (CGRectGetHeight(inVC) <= 82.0 && CGRectGetMinY(inVC) <= 190.0) {
                return pa;
            }
            return nil;
        }
    }
    return nil;
}

static void FQXRestoreHistoryScrollGeometry(UIScrollView *scroll) {
    if (![scroll isKindOfClass:UIScrollView.class]) return;
    NSValue *savedFrameVal = objc_getAssociatedObject(scroll, FQXHistoryScrollSavedFrameKey);
    NSValue *appliedFrameVal = objc_getAssociatedObject(scroll, FQXHistoryScrollAppliedFrameKey);
    if (savedFrameVal) {
        if (!appliedFrameVal || CGRectEqualToRect(scroll.frame, appliedFrameVal.CGRectValue)) {
            scroll.frame = savedFrameVal.CGRectValue;
        }
        objc_setAssociatedObject(scroll, FQXHistoryScrollSavedFrameKey, nil, OBJC_ASSOCIATION_RETAIN_NONATOMIC);
        objc_setAssociatedObject(scroll, FQXHistoryScrollAppliedFrameKey, nil, OBJC_ASSOCIATION_RETAIN_NONATOMIC);
    }
    NSNumber *savedInset = objc_getAssociatedObject(scroll, FQXHistoryScrollSavedInsetTopKey);
    if (savedInset) {
        UIEdgeInsets ins = scroll.contentInset;
        ins.top = savedInset.doubleValue;
        scroll.contentInset = ins;
        objc_setAssociatedObject(scroll, FQXHistoryScrollSavedInsetTopKey, nil, OBJC_ASSOCIATION_RETAIN_NONATOMIC);
        objc_setAssociatedObject(scroll, FQXHistoryScrollAppliedInsetKey, nil, OBJC_ASSOCIATION_RETAIN_NONATOMIC);
    }
}

static const char FQXK_FQXHistorySyncInFlightKey = 0;
#define FQXHistorySyncInFlightKey ((const void *)&FQXK_FQXHistorySyncInFlightKey)

// Lightweight O(1) mask/divider pass safe to run inside categoryLayout / loadMaskView: /
// layoutCategoryRightButtons. Reads ONLY already-allocated ivars (never lazy view getters)
// and NEVER mutates frames, layout invalidation, or pager selection.
static void FQXApplyHistoryEdgeMasksOnly(UIViewController *historyVC) {
    if (![historyVC isKindOfClass:UIViewController.class] || !historyVC.isViewLoaded) return;
    FQXMigrateLegacyHistoryFilterBarPrefIfNeeded();
    BOOL anyHidden = FQXHistoryAnyButtonHidden();
    UIView *ivarFilterLine = FQXRawIvarObj(historyVC, "_filterLineView");
    UIView *ivarModeLine = FQXRawIvarObj(historyVC, "_modeLineView");
    UIView *ivarRightMask = FQXRawIvarObj(historyVC, "_rightMaskView");
    UIView *ivarRightGrad = FQXRawIvarObj(historyVC, "_rightGradientView");
    UIView *ivarLeftMask = FQXRawIvarObj(historyVC, "_leftMaskView");
    UIView *ivarLeftGrad = FQXRawIvarObj(historyVC, "_leftGradientView");
    CALayer *ivarRightLayer = FQXRawIvarObj(historyVC, "_rightMaskLayer");
    CALayer *ivarLeftLayer = FQXRawIvarObj(historyVC, "_leftMaskLayer");

    if (!anyHidden) {
        if ([ivarFilterLine isKindOfClass:UIView.class]) FQXShelfApplyControlHidden(ivarFilterLine, FQXHistoryBarHiddenByUsKey, NO);
        if ([ivarModeLine isKindOfClass:UIView.class]) FQXShelfApplyControlHidden(ivarModeLine, FQXHistoryBarHiddenByUsKey, NO);
        if ([ivarRightMask isKindOfClass:UIView.class]) FQXShelfApplyControlHidden(ivarRightMask, FQXHistoryBarHiddenByUsKey, NO);
        if ([ivarRightGrad isKindOfClass:UIView.class]) FQXShelfApplyControlHidden(ivarRightGrad, FQXHistoryBarHiddenByUsKey, NO);
        if ([ivarLeftMask isKindOfClass:UIView.class]) FQXShelfApplyControlHidden(ivarLeftMask, FQXHistoryBarHiddenByUsKey, NO);
        if ([ivarLeftGrad isKindOfClass:UIView.class]) FQXShelfApplyControlHidden(ivarLeftGrad, FQXHistoryBarHiddenByUsKey, NO);
        FQXApplyHistoryLayerHidden(ivarRightLayer, NO);
        FQXApplyHistoryLayerHidden(ivarLeftLayer, NO);
        return;
    }

    BOOL showFilter = FQXHistoryFilterBtnEnabled();
    BOOL showEdit = FQXHistoryEditBtnEnabled();
    BOOL anyLeft = FQXHistoryAnyLeftPillEnabled();
    id category = FQXRawIvarObj(historyVC, "_categoryView");
    if (category) {
        size_t catCount = 0;
        unsigned int catMask = FQXShelfPagerMaskAndCount(historyVC, category, NO, &catCount);
        if (catCount > 0) anyLeft = (catMask != 0);
    }
    id categoryCV = category ? FQXObjGet(category, "collectionView") : nil;
    BOOL allowStripScroll = [categoryCV isKindOfClass:UICollectionView.class] ? ((UICollectionView *)categoryCV).scrollEnabled : NO;
    BOOL hideRightMasks = FQXShouldHideHistoryEdgeMask(
        1, showFilter ? 1 : 0, showEdit ? 1 : 0, allowStripScroll ? 1 : 0, anyLeft ? 1 : 0) != 0;
    BOOL hideLeftMasks = FQXShouldHideHistoryEdgeMask(
        0, showFilter ? 1 : 0, showEdit ? 1 : 0, allowStripScroll ? 1 : 0, anyLeft ? 1 : 0) != 0;
    BOOL hideDividers = (!showFilter || !showEdit);

    if ([ivarFilterLine isKindOfClass:UIView.class]) {
        [FQXTrackedHistoryBarViews() addObject:ivarFilterLine];
        FQXShelfApplyControlHidden(ivarFilterLine, FQXHistoryBarHiddenByUsKey, hideDividers);
    }
    if ([ivarModeLine isKindOfClass:UIView.class]) {
        [FQXTrackedHistoryBarViews() addObject:ivarModeLine];
        FQXShelfApplyControlHidden(ivarModeLine, FQXHistoryBarHiddenByUsKey, hideDividers);
    }
    if ([ivarRightMask isKindOfClass:UIView.class]) {
        [FQXTrackedHistoryBarViews() addObject:ivarRightMask];
        FQXShelfApplyControlHidden(ivarRightMask, FQXHistoryBarHiddenByUsKey, hideRightMasks);
    }
    if ([ivarRightGrad isKindOfClass:UIView.class]) {
        [FQXTrackedHistoryBarViews() addObject:ivarRightGrad];
        FQXShelfApplyControlHidden(ivarRightGrad, FQXHistoryBarHiddenByUsKey, hideRightMasks);
    }
    if ([ivarLeftMask isKindOfClass:UIView.class]) {
        [FQXTrackedHistoryBarViews() addObject:ivarLeftMask];
        FQXShelfApplyControlHidden(ivarLeftMask, FQXHistoryBarHiddenByUsKey, hideLeftMasks);
    }
    if ([ivarLeftGrad isKindOfClass:UIView.class]) {
        [FQXTrackedHistoryBarViews() addObject:ivarLeftGrad];
        FQXShelfApplyControlHidden(ivarLeftGrad, FQXHistoryBarHiddenByUsKey, hideLeftMasks);
    }
    FQXApplyHistoryLayerHidden(ivarRightLayer, hideRightMasks);
    FQXApplyHistoryLayerHidden(ivarLeftLayer, hideLeftMasks);
}

static void FQXSyncShelfHistoryFilterBarBody(UIViewController *historyVC) {
    UIView *vcView = historyVC.view;
    [FQXTrackedShelfHistoryVCs() addObject:historyVC];
    FQXMigrateLegacyHistoryFilterBarPrefIfNeeded();

    BOOL showAll = FQXHistoryAllEnabled();
    BOOL showRead = FQXHistoryReadEnabled();
    BOOL showListen = FQXHistoryListenEnabled();
    BOOL showDrama = FQXHistoryDramaEnabled();
    BOOL showFilter = FQXHistoryFilterBtnEnabled();
    BOOL showEdit = FQXHistoryEditBtnEnabled();
    BOOL anyLeft = FQXHistoryAnyLeftPillEnabled();
    BOOL anyHidden = FQXHistoryAnyButtonHidden();
    id category = FQXObjGet(historyVC, "categoryView");
    size_t catCount = 0;
    unsigned int catMask = FQXShelfPagerMaskAndCount(historyVC, category, NO, &catCount);
    if (catCount > 0) {
        anyLeft = (catMask != 0);
    }
    BOOL allHidden = !anyLeft && !showFilter && !showEdit;

    UIScrollView *mainScroll = FQXFindMainHistoryContentScroll(vcView, nil, 0);
    if (!anyHidden) {
        FQXSyncShelfHistoryPager(historyVC, category, FQXObjGet(category, "collectionView"), anyLeft);
        FQXApplyHistoryEdgeMasksOnly(historyVC);
        for (UIView *bar in FQXTrackedHistoryBarViews().allObjects) {
            if (!bar.superview || ![bar isDescendantOfView:vcView]) continue;
            FQXShelfApplyControlHidden(bar, FQXHistoryBarHiddenByUsKey, NO);
            NSValue *savedLeftF = objc_getAssociatedObject(bar, &FQXHistoryLeftSavedFrameKey);
            if (savedLeftF) {
                if (!CGRectEqualToRect(bar.frame, savedLeftF.CGRectValue)) {
                    bar.frame = savedLeftF.CGRectValue;
                }
                objc_setAssociatedObject(bar, &FQXHistoryLeftSavedFrameKey, nil, OBJC_ASSOCIATION_RETAIN_NONATOMIC);
            }
            if ([objc_getAssociatedObject(bar, FQXHistoryFilterShiftedKey) boolValue]) {
                NSValue *savedF = objc_getAssociatedObject(bar, FQXHistoryFilterSavedFrameKey);
                if (savedF && !CGRectEqualToRect(bar.frame, savedF.CGRectValue)) bar.frame = savedF.CGRectValue;
                objc_setAssociatedObject(bar, FQXHistoryFilterShiftedKey, nil, OBJC_ASSOCIATION_RETAIN_NONATOMIC);
                objc_setAssociatedObject(bar, FQXHistoryFilterSavedFrameKey, nil, OBJC_ASSOCIATION_RETAIN_NONATOMIC);
            }
            NSValue *savedPillF = objc_getAssociatedObject(bar, FQXHistoryPillSavedFrameKey);
            if (savedPillF) {
                if (!CGRectEqualToRect(bar.frame, savedPillF.CGRectValue)) bar.frame = savedPillF.CGRectValue;
                objc_setAssociatedObject(bar, FQXHistoryPillSavedFrameKey, nil, OBJC_ASSOCIATION_RETAIN_NONATOMIC);
            }
            if ([bar isKindOfClass:UICollectionView.class] &&
                [objc_getAssociatedObject(bar, FQXHistoryLeftCVTrackedKey) boolValue]) {
                FQXReflowShelfCollectionCells((UICollectionView *)bar, FQXHistoryFilterKeyForCell, 8.0, 0.0);
            }
        }
        FQXRestoreHistoryScrollGeometry(mainScroll);
        objc_setAssociatedObject(historyVC, FQXHistoryBarDiagKey, nil, OBJC_ASSOCIATION_RETAIN_NONATOMIC);
        return;
    }

    CGFloat vcW = CGRectGetWidth(vcView.bounds);
    FQXHistoryTopBarScan scan = { nil, nil, nil };
    NSMutableArray<UIView *> *leftPills = [NSMutableArray array];
    FQXScanHistoryTopBarDepth(vcView, vcView, mainScroll, vcW, &scan, leftPills, 0);

    id categoryCollection = FQXObjGet(category, "collectionView");
    UICollectionView *leftCV = [categoryCollection isKindOfClass:UICollectionView.class] &&
                               [categoryCollection isDescendantOfView:vcView] ? categoryCollection : scan.leftCV;
    FQXSyncShelfHistoryPager(historyVC, category, leftCV, anyLeft);
    UIView *filterBtn = scan.filterBtn;
    UIView *editBtn = scan.editBtn;

    if (!leftCV && !leftPills.count && !filterBtn && !editBtn) return;

    UIView *leftAnchor = leftCV ?: leftPills.firstObject;
    UIView *rightAnchor = filterBtn ?: editBtn;
    CGFloat rowMidY = -1.0;
    if (rightAnchor) {
        rowMidY = CGRectGetMidY([rightAnchor convertRect:rightAnchor.bounds toView:vcView]);
    } else if (leftAnchor) {
        rowMidY = CGRectGetMidY([leftAnchor convertRect:leftAnchor.bounds toView:vcView]);
    }
    NSMutableArray<UIView *> *dividers = [NSMutableArray array];
    NSMutableArray<UIView *> *rightEdgeMasks = [NSMutableArray array];
    if (rowMidY >= 0.0) {
        FQXCollectHistoryDividersDepth(vcView, vcView, mainScroll, vcW, rowMidY, dividers, rightEdgeMasks, 0);
    }
    UIView *ivarFilterLine = FQXRawIvarObj(historyVC, "_filterLineView");
    UIView *ivarModeLine = FQXRawIvarObj(historyVC, "_modeLineView");
    if ([ivarFilterLine isKindOfClass:UIView.class] && ![dividers containsObject:ivarFilterLine]) {
        [dividers addObject:ivarFilterLine];
    }
    if ([ivarModeLine isKindOfClass:UIView.class] && ![dividers containsObject:ivarModeLine]) {
        [dividers addObject:ivarModeLine];
    }
    UIView *ivarRightMask = FQXRawIvarObj(historyVC, "_rightMaskView");
    UIView *ivarRightGrad = FQXRawIvarObj(historyVC, "_rightGradientView");
    UIView *ivarLeftMask = FQXRawIvarObj(historyVC, "_leftMaskView");
    UIView *ivarLeftGrad = FQXRawIvarObj(historyVC, "_leftGradientView");
    if ([ivarRightMask isKindOfClass:UIView.class] && ![rightEdgeMasks containsObject:ivarRightMask]) {
        [rightEdgeMasks addObject:ivarRightMask];
    }
    if ([ivarRightGrad isKindOfClass:UIView.class] && ![rightEdgeMasks containsObject:ivarRightGrad]) {
        [rightEdgeMasks addObject:ivarRightGrad];
    }

    UIView *fullRowWrapper = (leftAnchor && rightAnchor)
        ? FQXCommonCompactAncestor(leftAnchor, rightAnchor, vcView, mainScroll)
        : nil;
    UIView *leftContainer = nil;
    if (leftCV) {
        leftContainer = leftCV;
        UIView *p = leftCV.superview;
        if (p && p != vcView && p != fullRowWrapper &&
            (!filterBtn || ![filterBtn isDescendantOfView:p]) &&
            (!editBtn || ![editBtn isDescendantOfView:p]) &&
            (!mainScroll || ![mainScroll isDescendantOfView:p]) &&
            CGRectGetHeight(p.bounds) <= 76.0) {
            leftContainer = p;
        }
    } else if (leftPills.count > 0) {
        UIView *p = leftPills.firstObject.superview;
        if (p && p != vcView && p != fullRowWrapper &&
            (!filterBtn || ![filterBtn isDescendantOfView:p]) &&
            (!editBtn || ![editBtn isDescendantOfView:p]) &&
            (!mainScroll || ![mainScroll isDescendantOfView:p]) &&
            CGRectGetHeight(p.bounds) <= 76.0) {
            leftContainer = p;
        }
    }
    UIView *rightContainer = nil;
    if (filterBtn && editBtn) {
        UIView *rc = FQXCommonCompactAncestor(filterBtn, editBtn, vcView, mainScroll);
        if (rc && rc != fullRowWrapper &&
            (!leftAnchor || ![leftAnchor isDescendantOfView:rc]) &&
            CGRectGetWidth(rc.bounds) <= vcW * 0.50) {
            rightContainer = rc;
        }
    }

    // 1. Left category pills (全部 / 阅读 / 听书 / 短剧)
    if (leftCV) {
        [FQXTrackedHistoryBarViews() addObject:leftCV];
        FQXInstallHistoryLeftCVHookIfNeeded(leftCV);
        if (leftContainer && leftContainer != leftCV) [FQXTrackedHistoryBarViews() addObject:leftContainer];
        FQXShelfApplyControlHidden(leftCV, FQXHistoryBarHiddenByUsKey, !anyLeft);
        if (leftContainer && leftContainer != leftCV) {
            FQXShelfApplyControlHidden(leftContainer, FQXHistoryBarHiddenByUsKey, !anyLeft);
        }
        if (anyLeft) {
            FQXReflowShelfCollectionCells(leftCV, FQXHistoryFilterKeyForCell, 8.0, 0.0);
        }
    } else if (leftPills.count > 0) {
        if (leftContainer) [FQXTrackedHistoryBarViews() addObject:leftContainer];
        for (UIView *pill in leftPills) {
            [FQXTrackedHistoryBarViews() addObject:pill];
            if (!objc_getAssociatedObject(pill, FQXHistoryPillSavedFrameKey)) {
                objc_setAssociatedObject(pill, FQXHistoryPillSavedFrameKey, [NSValue valueWithCGRect:pill.frame], OBJC_ASSOCIATION_RETAIN_NONATOMIC);
            }
        }
        [leftPills sortUsingComparator:^NSComparisonResult(UIView *a, UIView *b) {
            NSValue *fa = objc_getAssociatedObject(a, FQXHistoryPillSavedFrameKey);
            NSValue *fb = objc_getAssociatedObject(b, FQXHistoryPillSavedFrameKey);
            CGFloat ax = fa ? CGRectGetMinX(fa.CGRectValue) : CGRectGetMinX(a.frame);
            CGFloat bx = fb ? CGRectGetMinX(fb.CGRectValue) : CGRectGetMinX(b.frame);
            return ax < bx ? NSOrderedAscending : (ax > bx ? NSOrderedDescending : NSOrderedSame);
        }];
        CGFloat startX = CGFLOAT_MAX;
        CGFloat nativeGap = 8.0;
        BOOL hasGap = NO;
        CGRect prevStock = CGRectZero;
        BOOL hasPrev = NO;
        BOOL anyPillHidden = NO;
        BOOL hiddenBeforeVisible = NO;
        NSMutableArray<UIView *> *visPills = [NSMutableArray array];
        for (UIView *pill in leftPills) {
            NSValue *sv = objc_getAssociatedObject(pill, FQXHistoryPillSavedFrameKey);
            CGRect sf = sv ? sv.CGRectValue : pill.frame;
            if (CGRectGetMinX(sf) < startX) startX = CGRectGetMinX(sf);
            if (hasPrev && !hasGap) {
                CGFloat g = CGRectGetMinX(sf) - CGRectGetMaxX(prevStock);
                if (g >= 4.0 && g <= 24.0) { nativeGap = g; hasGap = YES; }
            }
            prevStock = sf;
            hasPrev = YES;
            NSString *k = FQXHistoryFilterKeyForCell(pill);
            BOOL show = k ? FQXShelfOptionEnabled(k) : YES;
            FQXShelfApplyControlHidden(pill, FQXHistoryBarHiddenByUsKey, !show);
            if (show) {
                if (anyPillHidden) hiddenBeforeVisible = YES;
                [visPills addObject:pill];
            } else {
                anyPillHidden = YES;
            }
        }
        if (leftContainer) FQXShelfApplyControlHidden(leftContainer, FQXHistoryBarHiddenByUsKey, !anyLeft);
        if (anyLeft && hiddenBeforeVisible && startX < CGFLOAT_MAX) {
            CGFloat curX = startX;
            for (UIView *pill in visPills) {
                CGRect f = pill.frame;
                if (fabs(f.origin.x - curX) > 0.5) {
                    f.origin.x = curX;
                    pill.frame = f;
                }
                curX += CGRectGetWidth(f) + nativeGap;
            }
        } else if (anyLeft && !hiddenBeforeVisible) {
            for (UIView *pill in visPills) {
                NSValue *sv = objc_getAssociatedObject(pill, FQXHistoryPillSavedFrameKey);
                if (sv && !CGRectEqualToRect(pill.frame, sv.CGRectValue)) {
                    pill.frame = sv.CGRectValue;
                }
            }
        }
    }

    // 2. Right buttons (筛选 / 编辑) + vertical divider
    if (filterBtn) {
        [FQXTrackedHistoryBarViews() addObject:filterBtn];
        if (![objc_getAssociatedObject(filterBtn, FQXHistoryFilterShiftedKey) boolValue]) {
            objc_setAssociatedObject(filterBtn, FQXHistoryFilterSavedFrameKey, [NSValue valueWithCGRect:filterBtn.frame], OBJC_ASSOCIATION_RETAIN_NONATOMIC);
        }
        FQXShelfApplyControlHidden(filterBtn, FQXHistoryBarHiddenByUsKey, !showFilter);
    }
    if (editBtn) {
        [FQXTrackedHistoryBarViews() addObject:editBtn];
        FQXShelfApplyControlHidden(editBtn, FQXHistoryBarHiddenByUsKey, !showEdit);
    }
    for (UIView *div in dividers) {
        [FQXTrackedHistoryBarViews() addObject:div];
        FQXShelfApplyControlHidden(div, FQXHistoryBarHiddenByUsKey, (!showFilter || !showEdit));
    }
    if (rightContainer) {
        [FQXTrackedHistoryBarViews() addObject:rightContainer];
        FQXShelfApplyControlHidden(rightContainer, FQXHistoryBarHiddenByUsKey, (!showFilter && !showEdit));
    }
    if (filterBtn && showFilter && !showEdit && editBtn && filterBtn.superview == editBtn.superview) {
        NSValue *savedVal = objc_getAssociatedObject(filterBtn, FQXHistoryFilterSavedFrameKey);
        CGRect baseF = savedVal ? savedVal.CGRectValue : filterBtn.frame;
        CGFloat targetX = CGRectGetMaxX(editBtn.frame) - CGRectGetWidth(baseF);
        if (targetX > CGRectGetMinX(baseF) + 2.0) {
            CGRect shifted = baseF;
            shifted.origin.x = targetX;
            if (!CGRectEqualToRect(filterBtn.frame, shifted)) {
                filterBtn.frame = shifted;
            }
            objc_setAssociatedObject(filterBtn, FQXHistoryFilterShiftedKey, @YES, OBJC_ASSOCIATION_RETAIN_NONATOMIC);
        }
    } else if (filterBtn && [objc_getAssociatedObject(filterBtn, FQXHistoryFilterShiftedKey) boolValue]) {
        NSValue *savedVal = objc_getAssociatedObject(filterBtn, FQXHistoryFilterSavedFrameKey);
        if (savedVal && !CGRectEqualToRect(filterBtn.frame, savedVal.CGRectValue)) filterBtn.frame = savedVal.CGRectValue;
        objc_setAssociatedObject(filterBtn, FQXHistoryFilterShiftedKey, nil, OBJC_ASSOCIATION_RETAIN_NONATOMIC);
    }

    // Expand leftCV / leftContainer into freed right-button space when 筛选 and/or 编辑 are hidden
    // so visible pills never clip against the former ~240pt right boundary.
    if (leftCV && anyLeft) {
        UIView *outerLeft = (leftContainer && leftContainer != leftCV) ? leftContainer : leftCV;
        if (!objc_getAssociatedObject(outerLeft, &FQXHistoryLeftSavedFrameKey) &&
            FQXShouldCaptureHistorySavedFrame(CGRectGetWidth(outerLeft.frame), CGRectGetHeight(outerLeft.frame))) {
            objc_setAssociatedObject(outerLeft, &FQXHistoryLeftSavedFrameKey,
                                     [NSValue valueWithCGRect:outerLeft.frame], OBJC_ASSOCIATION_RETAIN_NONATOMIC);
        }
        if (outerLeft != leftCV && !objc_getAssociatedObject(leftCV, &FQXHistoryLeftSavedFrameKey) &&
            FQXShouldCaptureHistorySavedFrame(CGRectGetWidth(leftCV.frame), CGRectGetHeight(leftCV.frame))) {
            objc_setAssociatedObject(leftCV, &FQXHistoryLeftSavedFrameKey,
                                     [NSValue valueWithCGRect:leftCV.frame], OBJC_ASSOCIATION_RETAIN_NONATOMIC);
        }
        NSValue *savedOuterVal = objc_getAssociatedObject(outerLeft, &FQXHistoryLeftSavedFrameKey);
        NSValue *savedCVVal = objc_getAssociatedObject(leftCV, &FQXHistoryLeftSavedFrameKey);
        if (showFilter && showEdit) {
            if (savedOuterVal && !CGRectEqualToRect(outerLeft.frame, savedOuterVal.CGRectValue)) {
                outerLeft.frame = savedOuterVal.CGRectValue;
            }
            if (outerLeft != leftCV && savedCVVal && !CGRectEqualToRect(leftCV.frame, savedCVVal.CGRectValue)) {
                leftCV.frame = savedCVVal.CGRectValue;
            }
        } else if (outerLeft.superview) {
            CGFloat rightLimitInVC = vcW - 12.0;
            if (showFilter && filterBtn && !filterBtn.hidden) {
                rightLimitInVC = MIN(rightLimitInVC, CGRectGetMinX([filterBtn convertRect:filterBtn.bounds toView:vcView]) - 8.0);
            }
            if (showEdit && editBtn && !editBtn.hidden) {
                rightLimitInVC = MIN(rightLimitInVC, CGRectGetMinX([editBtn convertRect:editBtn.bounds toView:vcView]) - 8.0);
            }
            CGRect baseOuter = savedOuterVal ? savedOuterVal.CGRectValue : outerLeft.frame;
            CGRect outerInVC = [outerLeft.superview convertRect:baseOuter toView:vcView];
            CGFloat desiredW = rightLimitInVC - CGRectGetMinX(outerInVC);
            CGFloat targetOuterW = (CGFloat)FQXResolveHistoryExpandedWidth(
                CGRectGetWidth(baseOuter), CGRectGetWidth(outerLeft.frame), desiredW);
            BOOL widthChanged = NO;
            if (targetOuterW > 0.0) {
                CGRect expandedOuter = baseOuter;
                expandedOuter.size.width = targetOuterW;
                if (!CGRectEqualToRect(outerLeft.frame, expandedOuter)) {
                    outerLeft.frame = expandedOuter;
                    widthChanged = YES;
                }
            }
            if (outerLeft != leftCV && CGRectGetWidth(outerLeft.bounds) >= 40.0) {
                CGRect targetCVFrame;
                if (outerLeft == category) {
                    // Keep FQRJXCategoryBaseView.collectionView.frame strictly equal to self.bounds so
                    // FQRJXCategoryBaseView::layoutSubviews never triggers reloadData/invalidateLayout loops.
                    targetCVFrame = outerLeft.bounds;
                } else {
                    CGRect baseCV = savedCVVal ? savedCVVal.CGRectValue : leftCV.frame;
                    targetCVFrame = baseCV;
                    CGFloat availCVW = round(CGRectGetWidth(outerLeft.bounds) - CGRectGetMinX(baseCV));
                    if (availCVW > CGRectGetWidth(baseCV)) targetCVFrame.size.width = availCVW;
                }
                if (!CGRectEqualToRect(leftCV.frame, targetCVFrame)) {
                    leftCV.frame = targetCVFrame;
                    widthChanged = YES;
                }
            }
            if (widthChanged) {
                FQXReflowShelfCollectionCells(leftCV, FQXHistoryFilterKeyForCell, 8.0, 0.0);
            }
        }
    }

    // 2b. Sync History scroll-edge fade masks (rightMaskView / rightGradientView / leftMaskView / leftGradientView)
    //     so hiding 筛选 & 编辑 never leaves the 18pt dark vertical gradient stripe stranded in mid-row.
    BOOL allowHistoryStripScroll = leftCV ? leftCV.scrollEnabled : NO;
    BOOL hideRightMasks = FQXShouldHideHistoryEdgeMask(
        1, showFilter ? 1 : 0, showEdit ? 1 : 0, allowHistoryStripScroll ? 1 : 0, anyLeft ? 1 : 0) != 0;
    BOOL hideLeftMasks = FQXShouldHideHistoryEdgeMask(
        0, showFilter ? 1 : 0, showEdit ? 1 : 0, allowHistoryStripScroll ? 1 : 0, anyLeft ? 1 : 0) != 0;
    for (UIView *rm in rightEdgeMasks) {
        [FQXTrackedHistoryBarViews() addObject:rm];
        FQXShelfApplyControlHidden(rm, FQXHistoryBarHiddenByUsKey, hideRightMasks);
    }
    if ([ivarLeftMask isKindOfClass:UIView.class]) {
        [FQXTrackedHistoryBarViews() addObject:ivarLeftMask];
        FQXShelfApplyControlHidden(ivarLeftMask, FQXHistoryBarHiddenByUsKey, hideLeftMasks);
    }
    if ([ivarLeftGrad isKindOfClass:UIView.class]) {
        [FQXTrackedHistoryBarViews() addObject:ivarLeftGrad];
        FQXShelfApplyControlHidden(ivarLeftGrad, FQXHistoryBarHiddenByUsKey, hideLeftMasks);
    }
    FQXApplyHistoryLayerHidden(FQXRawIvarObj(historyVC, "_rightMaskLayer"), hideRightMasks);
    FQXApplyHistoryLayerHidden(FQXRawIvarObj(historyVC, "_leftMaskLayer"), hideLeftMasks);

    // 3. Full-row collapse & book-grid upward shift ONLY when all 6 controls are hidden
    if (fullRowWrapper) {
        [FQXTrackedHistoryBarViews() addObject:fullRowWrapper];
        FQXShelfApplyControlHidden(fullRowWrapper, FQXHistoryBarHiddenByUsKey, allHidden);
    }
    CGFloat minY = CGFLOAT_MAX, maxY = -CGFLOAT_MAX;
    NSMutableArray<UIView *> *rowBoundsViews = [NSMutableArray array];
    if (fullRowWrapper) [rowBoundsViews addObject:fullRowWrapper];
    if (leftContainer) [rowBoundsViews addObject:leftContainer];
    else if (leftCV) [rowBoundsViews addObject:leftCV];
    else [rowBoundsViews addObjectsFromArray:leftPills];
    if (filterBtn) [rowBoundsViews addObject:filterBtn];
    if (editBtn) [rowBoundsViews addObject:editBtn];
    for (UIView *v in rowBoundsViews) {
        CGRect inVC = [v convertRect:v.bounds toView:vcView];
        if (CGRectGetMinY(inVC) < minY) minY = CGRectGetMinY(inVC);
        if (CGRectGetMaxY(inVC) > maxY) maxY = CGRectGetMaxY(inVC);
    }
    CGFloat barH = (maxY > minY) ? (maxY - minY) : 0.0;

    NSString *layoutMode = @"partial_visible";
    if (!allHidden) {
        FQXRestoreHistoryScrollGeometry(mainScroll);
    } else if (mainScroll && barH >= 16.0 && barH <= 84.0) {
        layoutMode = @"hide_only";
        CGRect curFrame = mainScroll.frame;
        NSValue *appliedVal = objc_getAssociatedObject(mainScroll, FQXHistoryScrollAppliedFrameKey);
        BOOL alreadyShiftedFrame = (appliedVal && fabs(curFrame.origin.y - appliedVal.CGRectValue.origin.y) < 1.0 &&
                                    fabs(curFrame.size.height - appliedVal.CGRectValue.size.height) < 1.0);
        CGRect scrollInVC = [mainScroll.superview convertRect:curFrame toView:vcView];
        if (alreadyShiftedFrame) {
            layoutMode = @"above_scroll";
        } else if (CGRectGetMinY(scrollInVC) >= maxY - 12.0 && CGRectGetMinY(scrollInVC) <= maxY + 24.0) {
            CGFloat shift = CGRectGetMinY(scrollInVC) - minY;
            if (shift >= 16.0 && shift <= 88.0) {
                objc_setAssociatedObject(mainScroll, FQXHistoryScrollSavedFrameKey, [NSValue valueWithCGRect:curFrame], OBJC_ASSOCIATION_RETAIN_NONATOMIC);
                CGRect shifted = curFrame;
                shifted.origin.y -= shift;
                shifted.size.height += shift;
                mainScroll.frame = shifted;
                objc_setAssociatedObject(mainScroll, FQXHistoryScrollAppliedFrameKey, [NSValue valueWithCGRect:shifted], OBJC_ASSOCIATION_RETAIN_NONATOMIC);
                layoutMode = @"above_scroll";
            }
        } else if (mainScroll.contentInset.top >= barH - 4.0) {
            NSNumber *appliedIns = objc_getAssociatedObject(mainScroll, FQXHistoryScrollAppliedInsetKey);
            if (!appliedIns || fabs(mainScroll.contentInset.top - appliedIns.doubleValue) > 1.0) {
                if (!objc_getAssociatedObject(mainScroll, FQXHistoryScrollSavedInsetTopKey)) {
                    objc_setAssociatedObject(mainScroll, FQXHistoryScrollSavedInsetTopKey, @(mainScroll.contentInset.top), OBJC_ASSOCIATION_RETAIN_NONATOMIC);
                }
                UIEdgeInsets ins = mainScroll.contentInset;
                ins.top = MAX(0.0, ins.top - barH);
                mainScroll.contentInset = ins;
                objc_setAssociatedObject(mainScroll, FQXHistoryScrollAppliedInsetKey, @(ins.top), OBJC_ASSOCIATION_RETAIN_NONATOMIC);
            }
            layoutMode = @"inset_overlay";
        }
    }

    if (FQXDiagnosticsHubIsEnabled()) {
        NSInteger visibleMask = (showAll ? 1 : 0) | (showRead ? 2 : 0) | (showListen ? 4 : 0) |
                                (showDrama ? 8 : 0) | (showFilter ? 16 : 0) | (showEdit ? 32 : 0) |
                                (FQXHistoryShortStoryEnabled() ? 64 : 0) |
                                (FQXHistoryComicEnabled() ? 128 : 0) | (FQXHistoryTopicEnabled() ? 256 : 0);
        NSString *diagSig = [NSString stringWithFormat:@"%ld|%d|%@|%@|%@|%lu",
                             (long)visibleMask, allHidden ? 1 : 0, layoutMode,
                             filterBtn ? NSStringFromClass(filterBtn.class) : @"nil",
                             editBtn ? NSStringFromClass(editBtn.class) : @"nil",
                             (unsigned long)dividers.count];
        if (![diagSig isEqualToString:objc_getAssociatedObject(historyVC, FQXHistoryBarDiagKey)]) {
            objc_setAssociatedObject(historyVC, FQXHistoryBarDiagKey, diagSig, OBJC_ASSOCIATION_COPY_NONATOMIC);
            FQXDiagRecordEvent(FQXDiagCategoryUI, @"shelf_history_bar_visibility", @{
                @"leftClass": leftCV ? (NSStringFromClass(leftCV.class) ?: @"") : (leftContainer ? (NSStringFromClass(leftContainer.class) ?: @"") : @""),
                @"leftPillCount": @(leftPills.count),
                @"filterBtnClass": filterBtn ? (NSStringFromClass(filterBtn.class) ?: @"") : @"",
                @"editBtnClass": editBtn ? (NSStringFromClass(editBtn.class) ?: @"") : @"",
                @"dividerCount": @(dividers.count),
                @"fullRowClass": fullRowWrapper ? (NSStringFromClass(fullRowWrapper.class) ?: @"") : @"",
                @"barHeight": @(round(barH * 10.0) / 10.0),
                @"scrollClass": mainScroll ? (NSStringFromClass(mainScroll.class) ?: @"") : @"",
                @"layoutMode": layoutMode,
                @"allSixHidden": @(allHidden),
                @"visibleMask": @(visibleMask),
            }, NO);
        }
    }
}

static void FQXSyncShelfHistoryFilterBar(UIViewController *historyVC) {
    if (![historyVC isKindOfClass:UIViewController.class]) return;
    int inFlight = [objc_getAssociatedObject(historyVC, FQXHistorySyncInFlightKey) boolValue] ? 1 : 0;
    UIView *vcView = historyVC.isViewLoaded ? historyVC.view : nil;
    if (!FQXShouldRunHistoryFullSync(inFlight,
                                     (historyVC.isViewLoaded && vcView != nil) ? 1 : 0,
                                     vcView ? CGRectGetWidth(vcView.bounds) : 0.0,
                                     vcView ? CGRectGetHeight(vcView.bounds) : 0.0,
                                     0)) {
        return;
    }
    objc_setAssociatedObject(historyVC, FQXHistorySyncInFlightKey, @YES, OBJC_ASSOCIATION_RETAIN_NONATOMIC);
    FQXSyncShelfHistoryFilterBarBody(historyVC);
    objc_setAssociatedObject(historyVC, FQXHistorySyncInFlightKey, nil, OBJC_ASSOCIATION_RETAIN_NONATOMIC);
}

