    id controller = OrigShelfBuildFavoritesController(shelf, cmd, model);
    if ([controller isKindOfClass:objc_lookUpClass("SSVideoCollectViewController")]) {
        FQXTrackShelfFavoritesController(controller);
    }
    return controller;
