static void (*OrigShelfFavoritesWillAppear)(id, SEL, BOOL);
static void HookShelfFavoritesWillAppear(UIViewController *controller, SEL cmd, BOOL animated) {
    if (OrigShelfFavoritesWillAppear) OrigShelfFavoritesWillAppear(controller, cmd, animated);
    if (!FQXIsShelfFavoritesController(controller)) return;
    NSUInteger policy = FQXShelfFavoritesRowsPolicy();
    if (FQXShelfFavoritesAppliedRowsPolicy(controller) != policy) {
        objc_setAssociatedObject(controller, &ShelfFavoritesRowsPolicyKey, @(policy), OBJC_ASSOCIATION_RETAIN_NONATOMIC);
        UICollectionView *collection = FQXObjGet(controller, "collectionView");
        if ([collection isKindOfClass:UICollectionView.class]) {
            [collection reloadData];
        }
    }
}

static NSInteger (*OrigShelfFavoritesDisplayCount)(id, SEL, BOOL);
static NSInteger HookShelfFavoritesDisplayCount(UIViewController *controller, SEL cmd, BOOL includeExtra) {
    if (includeExtra && FQXIsShelfFavoritesController(controller) && (FQXShelfFavoritesAppliedRowsPolicy(controller) & 2u)) {
        id model = FQXObjGet(controller, "viewModel");
        // Verified against SSVideoCollectEmptyCell (-updateWithCellStyle:uiConfigParams:) and
        // SSVideoCollectViewModel (-addCellStyleString): style 0 is "bookshelf_more_history"
        // ("查看短剧浏览历史"); style 1 is "video_goto_bookstore" ("前往首页").
        NSInteger style = FQXIntGet(model, "videoCollectAddCellStyle", -1);
        if (FQXShouldHideShelfFavoritesExtraCell(0, (long long)style)) includeExtra = NO;
    }
    return OrigShelfFavoritesDisplayCount(controller, cmd, includeExtra);
}

static NSInteger (*OrigShelfFavoritesNumberOfItems)(id, SEL, UICollectionView *, NSInteger);
static NSInteger HookShelfFavoritesNumberOfItems(UIViewController *controller, SEL cmd, UICollectionView *collection, NSInteger section) {
    if (section == 0 && FQXIsShelfFavoritesController(controller) && (FQXShelfFavoritesAppliedRowsPolicy(controller) & 1u) &&
        FQXBoolGet(controller, "isFilterEnabled", NO) && FQXIntGet(controller, "videoContentSection", 0) > 0) {
        NSArray *models = FQXObjGet(controller, "filterModels");
        if ([models isKindOfClass:NSArray.class]) {
            for (id model in models) {
                if (!FQXShelfFavoritesFilterKey(model)) return OrigShelfFavoritesNumberOfItems(controller, cmd, collection, section);
            }
            return 0;
        }
    }
    return OrigShelfFavoritesNumberOfItems(controller, cmd, collection, section);
}

static UICollectionViewCell *(*OrigShelfFavoritesCell)(id, SEL, UICollectionView *, NSIndexPath *);
static UICollectionViewCell *HookShelfFavoritesCell(UIViewController *controller, SEL cmd, UICollectionView *collection, NSIndexPath *index) {
    UICollectionViewCell *cell = OrigShelfFavoritesCell(controller, cmd, collection, index);
    if ([cell isKindOfClass:objc_lookUpClass("SSVideoCollectHeaderCell")] && FQXIsShelfFavoritesController(controller)) {
        FQXSyncShelfFavoritesEdit(cell);
        FQXSyncShelfFavoritesFilters(cell, controller);
    }
    return cell;
}

static void (*OrigShelfFavoritesWillDisplay)(id, SEL, UICollectionView *, UICollectionViewCell *, NSIndexPath *);
static void HookShelfFavoritesWillDisplay(UIViewController *controller, SEL cmd, UICollectionView *collection,
                                         UICollectionViewCell *cell, NSIndexPath *index) {
    OrigShelfFavoritesWillDisplay(controller, cmd, collection, cell, index);
    if ([cell isKindOfClass:objc_lookUpClass("SSVideoCollectHeaderCell")] && FQXIsShelfFavoritesController(controller)) {
        FQXSyncShelfFavoritesEdit(cell);
        FQXSyncShelfFavoritesFilters(cell, controller);
    }
}

static void FQXRefreshShelfFavoritesItems(void) {
    NSUInteger policy = FQXShelfFavoritesRowsPolicy();
    for (UIViewController *controller in FQXTrackedShelfFavoritesControllers().allObjects) {
        BOOL reload = FQXShelfFavoritesAppliedRowsPolicy(controller) != policy;
        if (reload) objc_setAssociatedObject(controller, &ShelfFavoritesRowsPolicyKey, @(policy), OBJC_ASSOCIATION_RETAIN_NONATOMIC);
        if (!controller.isViewLoaded) continue;
        UICollectionView *collection = FQXObjGet(controller, "collectionView");
        if (![collection isKindOfClass:UICollectionView.class]) continue;
        if (reload) [collection reloadData];
        for (UICollectionViewCell *cell in collection.visibleCells) FQXSyncShelfFavoritesEdit(cell);
    }
}

static void FQXRefreshAllShelfHeaderControls(void) {
    if (!NSThread.isMainThread) {
        dispatch_async(dispatch_get_main_queue(), ^{ FQXRefreshAllShelfHeaderControls(); });
        return;
    }
    for (UIView *tabView in FQXTrackedShelfTabViews().allObjects) {
        FQXReflowShelfTabSelectView(tabView);
        [tabView setNeedsLayout];
    }
    for (UIViewController *vc in FQXTrackedShelf525VCs().allObjects) {
        FQXSyncShelfHeaderRightButtons(vc);
        UIViewController *curTab = FQXObjGet(vc, "currentTabVC");
        Class histCls = objc_lookUpClass("SSBookHistorySubViewController");
        if (histCls && [curTab isKindOfClass:histCls]) {
            FQXSyncShelfHistoryFilterBar(curTab);
        }
        if (vc.isViewLoaded) [vc.view setNeedsLayout];
    }
    for (UIViewController *histVC in FQXTrackedShelfHistoryVCs().allObjects) {
        FQXSyncShelfHistoryFilterBar(histVC);
        if (histVC.isViewLoaded) [histVC.view setNeedsLayout];
    }
    for (UIViewController *vc in FQXTrackedShelfSubVCs().allObjects) {
        FQXSyncShelfHeaderRightButtons(vc);
        UICollectionView *cv = FQXObjGet(vc, "collectionView");
        if ([cv isKindOfClass:UICollectionView.class]) {
            [cv.collectionViewLayout invalidateLayout];
            [cv setNeedsLayout];
        }
    }
    for (UIView *cell in FQXTrackedShelfFunctionCells().allObjects) {
        FQXApplyShelfFunctionCellLayout(cell);
        [cell setNeedsLayout];
        for (UIView *p = cell.superview; p; p = p.superview) {
            if ([p isKindOfClass:UICollectionView.class]) {
                [((UICollectionView *)p).collectionViewLayout invalidateLayout];
                break;
            }
        }
    }
    for (UIView *header in FQXTrackedShelfFilterHeaders().allObjects) {
        FQXSyncShelfFilterHeaderView(header);
        [header setNeedsLayout];
    }
    for (UICollectionView *cv in FQXTrackedShelfFilterCollections().allObjects) {
        FQXReflowShelfFilterCollectionView(cv, nil);
        [cv setNeedsLayout];
    }
    FQXRefreshShelfFavoritesItems();
    FQXRefreshShelfFavoritesFilters();
    FQXRefreshAllShelfEditButtons();
}

static void FQXSyncShelfRootPager(UIViewController *shelfVC) {
    if (![shelfVC isKindOfClass:UIViewController.class] || !shelfVC.isViewLoaded) return;
    id category = FQXObjGet(shelfVC, "categoryTitleView") ?: FQXObjGet(shelfVC, "tabSelectView");
    id container = FQXObjGet(shelfVC, "containerView") ?: FQXObjGet(category, "listContainer");
    UIScrollView *scroll = FQXObjGet(container, "scrollView") ?: FQXObjGet(category, "contentScrollView");
    if (![scroll isKindOfClass:UIScrollView.class]) return;
    size_t count = 0;
    unsigned int visibleMask = FQXShelfPagerMaskAndCount(shelfVC, category, YES, &count);
    if (count == 0) return;
    FQXApplyShelfPagerPolicy(shelfVC, category, container, scroll, count, visibleMask, visibleMask != 0, YES);
}

static BOOL (*OrigShelfRootCanSelect)(id, SEL, id, NSInteger);
static BOOL HookShelfRootCanSelect(id shelfVC, SEL cmd, id category, NSInteger index) {
    size_t count = 0;
    unsigned int mask = FQXShelfPagerMaskAndCount(shelfVC, category, YES, &count);
    if (count > 0 && index >= 0 && (size_t)index < count) {
        if (((mask >> (unsigned int)index) & 1u) == 0) return NO;
    }
    return OrigShelfRootCanSelect ? OrigShelfRootCanSelect(shelfVC, cmd, category, index) : YES;
}

static void FQXUpdateShelfRootControllerTabs(UIViewController *controller) {
    if (!OrigShelfRootTabModels || !controller.isViewLoaded) return;
    SEL update = sel_registerName("updateTabDataIfInit:withDefaultSelectTabType:");
    Method method = class_getInstanceMethod(object_getClass(controller), update);
    if (!method || method_getNumberOfArguments(method) != 4) {
        FQXSyncShelfRootPager(controller);
        return;
    }
    NSInteger type = FQXIntGet(controller, "currentBookShelfTabType", -1);
    id manager = FQXObjGet(controller, "tabManager") ?: FQXObjGet(controller, "bookshelfTabManager");
    NSArray *source = manager ? OrigShelfRootTabModels(manager, sel_registerName("getBookshelfTabModelArray")) : nil;
    if (![source isKindOfClass:NSArray.class]) source = FQXObjGet(controller, "bookshelfTabModelArray");
    NSArray *visible = FQXShelfVisibleRootTabModels(source);
    if ([visible isKindOfClass:NSArray.class] && visible.count > 0) {
        BOOL currentVisible = NO;
        NSInteger fallbackType = -1;
        for (id model in visible) {
            NSInteger mType = FQXIntGet(model, "tabType", FQXIntGet(model, "type", -1));
            if (fallbackType < 0 && mType >= 0) fallbackType = mType;
            if (mType == type && type >= 0) {
                currentVisible = YES;
                break;
            }
        }
        if (!currentVisible && fallbackType >= 0) type = fallbackType;
    }
    if (type >= 0) {
        char argType[8] = {0};
        method_getArgumentType(method, 3, argType, sizeof(argType));
        if (argType[0] == 'i' || argType[0] == 'I') {
            ((void (*)(id, SEL, BOOL, int))objc_msgSend)(controller, update, NO, (int)type);
        } else if (argType[0] == 'q' || argType[0] == 'Q') {
            ((void (*)(id, SEL, BOOL, NSInteger))objc_msgSend)(controller, update, NO, type);
        }
    }
    FQXSyncShelfRootPager(controller);
}

static void FQXRefreshShelfRootTabModels(void) {
    if (!NSThread.isMainThread) {
        dispatch_async(dispatch_get_main_queue(), ^{ FQXRefreshShelfRootTabModels(); });
        return;
    }
    for (UIViewController *controller in FQXTrackedShelf525VCs().allObjects) {
        FQXUpdateShelfRootControllerTabs(controller);
    }
}

