    if (FQXAudioDedupInFlight) return;
    if (alpha > 0.01 && self.window && !self.hidden) {
        FQXDeduplicateAudioIndicators(self);
    } else if (alpha <= 0.01) {
        FQXRestoreSuppressedAudioIndicatorIfNeeded(self);
    }
}

