        }
    }
    return nil;
}

static BOOL FQXViewSubtreeHasAudioMoreMarker(UIView *view, NSInteger *budget, NSInteger depth) {
    if (!view || view.hidden || view.alpha <= 0.01 || depth > 14 || *budget <= 0) return NO;
    (*budget)--;
    NSString *text = nil;
    if ([view isKindOfClass:UILabel.class]) {
        UILabel *lbl = (UILabel *)view;
        text = lbl.text.length ? lbl.text : lbl.attributedText.string;
    } else if ([view isKindOfClass:UIButton.class]) {
        UIButton *btn = (UIButton *)view;
        text = btn.currentTitle.length ? btn.currentTitle : btn.currentAttributedTitle.string;
    }
    if (text.length > 0 && text.length <= 24) {
        if ([text isEqualToString:@"有声详情"] ||
            [text isEqualToString:@"听书记录"] ||
            [text isEqualToString:@"播放器样式"] ||
            [text isEqualToString:@"真人讲书支持边听边读"] ||
            [text isEqualToString:@"听书进度自动跟随左右翻页"] ||
            [text isEqualToString:@"书末自动推荐下一本"]) {
            return YES;
        }
    }
    for (UIView *sub in view.subviews) {
        if (FQXViewSubtreeHasAudioMoreMarker(sub, budget, depth + 1)) return YES;
    }
    return NO;
}

static UIColor *FQXSampleCenterPixelColor(UIImage *image) {
    CGImageRef cg = image.CGImage;
    if (!cg) return nil;
    size_t w = CGImageGetWidth(cg);
    size_t h = CGImageGetHeight(cg);
    if (w < 8 || h < 8) return nil;
    CGRect crop = CGRectMake((CGFloat)(w / 2), (CGFloat)(h / 2), 1.0, 1.0);
    CGImageRef pixelImg = CGImageCreateWithImageInRect(cg, crop);
    if (!pixelImg) return nil;
    uint8_t rgba[4] = {0, 0, 0, 0};
    CGColorSpaceRef cs = CGColorSpaceCreateDeviceRGB();
    CGContextRef ctx = CGBitmapContextCreate(rgba, 1, 1, 8, 4, cs,
                                             (CGBitmapInfo)(kCGImageAlphaPremultipliedLast | kCGBitmapByteOrder32Big));
    CGColorSpaceRelease(cs);
    if (!ctx) {
        CGImageRelease(pixelImg);
        return nil;
    }
    CGContextDrawImage(ctx, CGRectMake(0.0, 0.0, 1.0, 1.0), pixelImg);
    CGContextRelease(ctx);
    CGImageRelease(pixelImg);
    if (rgba[3] < 200) return nil;
    CGFloat a = (CGFloat)rgba[3] / 255.0;
    CGFloat r = MIN(1.0, ((CGFloat)rgba[0] / 255.0) / a);
    CGFloat g = MIN(1.0, ((CGFloat)rgba[1] / 255.0) / a);
    CGFloat b = MIN(1.0, ((CGFloat)rgba[2] / 255.0) / a);
    return [UIColor colorWithRed:r green:g blue:b alpha:1.0];
}

static UIColor *FQXExtractOpaqueCanvasColor(UIView *view,
                                            CGFloat minW,
                                            CGFloat minH,
                                            UIView *excludingSubtree,
                                            NSInteger depth) {
    if (!view || view.hidden || view.alpha < 0.85 || depth > 4) return nil;
    if (excludingSubtree && (view == excludingSubtree || [view isDescendantOfView:excludingSubtree])) return nil;
    if ([view isKindOfClass:UIVisualEffectView.class]) return nil;

    // Prefer deeper full-screen reader page canvas (e.g. page background view) over root wrapper.
    for (UIView *sub in view.subviews) {
        CGRect sb = sub.bounds;
        if (CGRectGetWidth(sb) >= minW && CGRectGetHeight(sb) >= minH) {
            UIColor *deeper = FQXExtractOpaqueCanvasColor(sub, minW, minH, excludingSubtree, depth + 1);
            if (deeper) return deeper;
        }
    }

    if ([view isKindOfClass:UIImageView.class]) {
        UIImage *img = ((UIImageView *)view).image;
        if (img) {
            UIColor *sampled = FQXSampleCenterPixelColor(img);
            if (sampled) return sampled;
        }
    }

    UIColor *bg = view.backgroundColor;
    if (bg) {
        UIColor *resolved = [bg resolvedColorWithTraitCollection:view.traitCollection];
        CGFloat r = 0, g = 0, b = 0, a = 0, w = 0;
        if ([resolved getRed:&r green:&g blue:&b alpha:&a] && a >= 0.85) {
            return [UIColor colorWithRed:r green:g blue:b alpha:1.0];
        }
        if ([resolved getWhite:&w alpha:&a] && a >= 0.85) {
            return [UIColor colorWithWhite:w alpha:1.0];
        }
    }
    if (view.layer.backgroundColor) {
        UIColor *lbg = [UIColor colorWithCGColor:view.layer.backgroundColor];
        CGFloat r = 0, g = 0, b = 0, a = 0, w = 0;
        if ([lbg getRed:&r green:&g blue:&b alpha:&a] && a >= 0.85) {
            return [UIColor colorWithRed:r green:g blue:b alpha:1.0];
        }
        if ([lbg getWhite:&w alpha:&a] && a >= 0.85) {
            return [UIColor colorWithWhite:w alpha:1.0];
        }
    }
    return nil;
}

static UIColor *FQXSampleActiveReaderPaperColor(UIWindow *window,
                                                UIView *excludingSheet,
                                                BOOL *outFromReader) {
    if (outFromReader) *outFromReader = NO;
    UIViewController *readerVC = FQXFindVisibleReaderVCInWindow(window);
    if (readerVC && readerVC.isViewLoaded && readerVC.view) {
        CGRect rb = readerVC.view.bounds;
        CGFloat minW = MAX(200.0, CGRectGetWidth(rb) - 24.0);
        CGFloat minH = MAX(320.0, CGRectGetHeight(rb) - 180.0);
        UIColor *paper = FQXExtractOpaqueCanvasColor(readerVC.view, minW, minH, excludingSheet, 0);
        if (paper) {
            if (outFromReader) *outFromReader = YES;
            return paper;
        }
        UIColor *rootBg = readerVC.view.backgroundColor;
        if (rootBg) {
            UIColor *resolved = [rootBg resolvedColorWithTraitCollection:readerVC.view.traitCollection];
            CGFloat r = 0, g = 0, b = 0, a = 0, w = 0;
            if ([resolved getRed:&r green:&g blue:&b alpha:&a] && a >= 0.5) {
                if (outFromReader) *outFromReader = YES;
                return [UIColor colorWithRed:r green:g blue:b alpha:1.0];
            }
            if ([resolved getWhite:&w alpha:&a] && a >= 0.5) {
                if (outFromReader) *outFromReader = YES;
                return [UIColor colorWithWhite:w alpha:1.0];
            }
        }
    }
    return nil;
}

static BOOL FQXColorIsNeutralSurface(UIColor *color, UITraitCollection *traits) {
    if (![color isKindOfClass:UIColor.class]) return NO;
    UIColor *resolved = traits ? [color resolvedColorWithTraitCollection:traits] : color;
    CGFloat r = 0, g = 0, b = 0, a = 0, w = 0;
    if ([resolved getRed:&r green:&g blue:&b alpha:&a]) {
        if (a < 0.01) return NO;
        CGFloat mx = MAX(r, MAX(g, b));
        CGFloat mn = MIN(r, MIN(g, b));
        return (mx - mn) < 0.14;
    }
    if ([resolved getWhite:&w alpha:&a]) {
        return a >= 0.01;
    }
    return NO;
}

// Convert colored/dark circular share icons (e.g. WeChat, Moments, Douyin, Link, Weibo, QQ)
// or standalone transparent glyphs into unified crisp pure-black (light mode) or pure-white
// (dark/night mode) monochrome logos while preserving anti-aliased inner glyph detail.
static UIImage *FQXMakeMonochromeShareLogoImage(UIImage *orig, BOOL isDark) {
    if (![orig isKindOfClass:UIImage.class]) return nil;
    NSString *cacheKey = [NSString stringWithFormat:@"%p_%d", (const void *)orig, isDark ? 1 : 0];
    UIImage *cached = [FQXMonochromeShareIconCache() objectForKey:cacheKey];
    if (cached) return cached;

    UIColor *monoColor = isDark ? UIColor.whiteColor : UIColor.blackColor;
    CGImageRef cg = orig.CGImage;
    if (!cg || orig.isSymbolImage) {
        UIImage *tinted = [orig imageWithTintColor:monoColor renderingMode:UIImageRenderingModeAlwaysOriginal];
        if (tinted) [FQXMonochromeShareIconCache() setObject:tinted forKey:cacheKey];
        return tinted ?: orig;
    }

    size_t srcW = CGImageGetWidth(cg);
    size_t srcH = CGImageGetHeight(cg);
    if (srcW < 12 || srcH < 12) {
        UIImage *tinted = [orig imageWithTintColor:monoColor renderingMode:UIImageRenderingModeAlwaysOriginal];
        if (tinted) [FQXMonochromeShareIconCache() setObject:tinted forKey:cacheKey];
        return tinted ?: orig;
    }

    size_t w = srcW;
    size_t h = srcH;
    if (w > 144 || h > 144) {
        double ratio = 144.0 / (double)MAX(w, h);
        w = MAX((size_t)16, (size_t)llround((double)w * ratio));
        h = MAX((size_t)16, (size_t)llround((double)h * ratio));
    }

    size_t byteCount = w * h * 4;
    uint8_t *rgba = (uint8_t *)calloc(byteCount, 1);
    if (!rgba) return [orig imageWithTintColor:monoColor renderingMode:UIImageRenderingModeAlwaysOriginal];

    CGColorSpaceRef cs = CGColorSpaceCreateDeviceRGB();
    CGContextRef ctx = CGBitmapContextCreate(rgba, w, h, 8, w * 4, cs,
                                             (CGBitmapInfo)(kCGImageAlphaPremultipliedLast | kCGBitmapByteOrder32Big));
    if (!ctx) {
        CGColorSpaceRelease(cs);
        free(rgba);
        return [orig imageWithTintColor:monoColor renderingMode:UIImageRenderingModeAlwaysOriginal];
    }
    CGContextSetInterpolationQuality(ctx, kCGInterpolationHigh);
    CGContextDrawImage(ctx, CGRectMake(0.0, 0.0, (CGFloat)w, (CGFloat)h), cg);
    CGContextRelease(ctx);

    double cx = (double)w * 0.5;
    double cy = (double)h * 0.5;
    double rad = (double)MIN(w, h) * 0.5;
    double r92Sq = (rad * 0.92) * (rad * 0.92);
    double r94Sq = (rad * 0.94) * (rad * 0.94);
    double r72Sq = (rad * 0.72) * (rad * 0.72);
    double r90Sq = (rad * 0.90) * (rad * 0.90);

    NSUInteger totalInCircle = 0;
    NSUInteger opaqueInCircle = 0;
    NSUInteger whiteGlyphCount = 0;
    NSUInteger coloredOrDarkBgCount = 0;
    double bgSumR = 0.0, bgSumG = 0.0, bgSumB = 0.0;
    NSUInteger bgCnt = 0;
    double allRingR = 0.0, allRingG = 0.0, allRingB = 0.0;
    NSUInteger allRingCnt = 0;

    for (size_t y = 0; y < h; ++y) {
        double dy = ((double)y + 0.5) - cy;
        for (size_t x = 0; x < w; ++x) {
            double dx = ((double)x + 0.5) - cx;
            double d2 = dx * dx + dy * dy;
            if (d2 > r92Sq) continue;
            totalInCircle++;
            size_t idx = (y * w + x) * 4;
            uint8_t a8 = rgba[idx + 3];
            if (a8 < 128) continue;
            opaqueInCircle++;
            double a = (double)a8 / 255.0;
            double r = MIN(1.0, ((double)rgba[idx + 0] / 255.0) / a);
            double g = MIN(1.0, ((double)rgba[idx + 1] / 255.0) / a);
            double b = MIN(1.0, ((double)rgba[idx + 2] / 255.0) / a);
            double mx = MAX(r, MAX(g, b));
            double mn = MIN(r, MIN(g, b));
            double sat = mx - mn;
            double luma = 0.299 * r + 0.587 * g + 0.114 * b;
            if (luma > 0.78 && sat < 0.18) whiteGlyphCount++;
            if (sat >= 0.14 || luma < 0.65) coloredOrDarkBgCount++;
            if (d2 >= r72Sq && d2 <= r90Sq && a8 > 215) {
                allRingR += r; allRingG += g; allRingB += b; allRingCnt++;
                if (!(luma > 0.82 && sat < 0.12)) {
                    bgSumR += r; bgSumG += g; bgSumB += b; bgCnt++;
                }
            }
        }
    }

    BOOL isSolidDisk = (totalInCircle > 0 && opaqueInCircle >= (NSUInteger)((double)totalInCircle * 0.60));
    BOOL isColoredOrDarkDiskWithWhiteGlyph = (isSolidDisk &&
                                              bgCnt > 0 &&
                                              whiteGlyphCount >= MAX((NSUInteger)6, (NSUInteger)((double)opaqueInCircle * 0.025)) &&
                                              coloredOrDarkBgCount >= (NSUInteger)((double)opaqueInCircle * 0.25));
    double ringR = allRingCnt > 0 ? (allRingR / (double)allRingCnt) : 0.0;
    double ringG = allRingCnt > 0 ? (allRingG / (double)allRingCnt) : 0.0;
    double ringB = allRingCnt > 0 ? (allRingB / (double)allRingCnt) : 0.0;
    double ringLuma = 0.299 * ringR + 0.587 * ringG + 0.114 * ringB;
    double ringSat = MAX(ringR, MAX(ringG, ringB)) - MIN(ringR, MIN(ringG, ringB));
    BOOL isWhiteDiskWithDarkOrColoredGlyph = (isSolidDisk && !isColoredOrDarkDiskWithWhiteGlyph &&
                                              allRingCnt > 0 && ringLuma > 0.85 && ringSat < 0.12 &&
                                              coloredOrDarkBgCount >= MAX((NSUInteger)6, (NSUInteger)((double)opaqueInCircle * 0.025)));

    if (!isColoredOrDarkDiskWithWhiteGlyph && !isWhiteDiskWithDarkOrColoredGlyph) {
        CGColorSpaceRelease(cs);
        free(rgba);
        UIImage *tinted = [orig imageWithTintColor:monoColor renderingMode:UIImageRenderingModeAlwaysOriginal];
        if (tinted) [FQXMonochromeShareIconCache() setObject:tinted forKey:cacheKey];
        return tinted ?: orig;
    }

    uint8_t *outBuf = (uint8_t *)calloc(byteCount, 1);
    if (!outBuf) {
        CGColorSpaceRelease(cs);
        free(rgba);
        return [orig imageWithTintColor:monoColor renderingMode:UIImageRenderingModeAlwaysOriginal];
    }

    double bR = bgCnt > 0 ? (bgSumR / (double)bgCnt) : ringR;
    double bG = bgCnt > 0 ? (bgSumG / (double)bgCnt) : ringG;
    double bB = bgCnt > 0 ? (bgSumB / (double)bgCnt) : ringB;
    double vR = 1.0 - bR;
    double vG = 1.0 - bG;
    double vB = 1.0 - bB;
    double vLen2 = MAX(0.08, vR * vR + vG * vG + vB * vB);
    uint8_t inkVal = isDark ? 255 : 0;

    size_t minX = w, maxX = 0, minY = h, maxY = 0;
    NSUInteger extractedPixels = 0;

    for (size_t y = 0; y < h; ++y) {
        double dy = ((double)y + 0.5) - cy;
        for (size_t x = 0; x < w; ++x) {
            double dx = ((double)x + 0.5) - cx;
            if (dx * dx + dy * dy > r94Sq) continue;
            size_t idx = (y * w + x) * 4;
            uint8_t a8 = rgba[idx + 3];
            if (a8 < 12) continue;
            double a = (double)a8 / 255.0;
            double r = MIN(1.0, ((double)rgba[idx + 0] / 255.0) / a);
            double g = MIN(1.0, ((double)rgba[idx + 1] / 255.0) / a);
            double b = MIN(1.0, ((double)rgba[idx + 2] / 255.0) / a);

            double glyphA = 0.0;
            if (isColoredOrDarkDiskWithWhiteGlyph) {
                double proj = ((r - bR) * vR + (g - bG) * vG + (b - bB) * vB) / vLen2;
                if (proj > 0.14) {
                    glyphA = MIN(1.0, (proj - 0.14) / 0.78) * a;
                }
            } else {
                double dr = 1.0 - r, dg = 1.0 - g, db = 1.0 - b;
                double distW = sqrt(dr * dr + dg * dg + db * db);
                if (distW > 0.14) {
                    glyphA = MIN(1.0, (distW - 0.14) / 0.50) * a;
                }
            }
            if (glyphA <= 0.01) continue;
            uint8_t oa = (uint8_t)llround(MAX(0.0, MIN(1.0, glyphA)) * 255.0);
            uint8_t premul = (inkVal == 255) ? oa : 0;
            outBuf[idx + 0] = premul;
            outBuf[idx + 1] = premul;
            outBuf[idx + 2] = premul;
            outBuf[idx + 3] = oa;
            if (oa > 64) {
                extractedPixels++;
                if (x < minX) minX = x;
                if (x > maxX) maxX = x;
                if (y < minY) minY = y;
                if (y > maxY) maxY = y;
            }
        }
    }

    free(rgba);

    if (extractedPixels < 8 || maxX <= minX || maxY <= minY) {
        CGColorSpaceRelease(cs);
        free(outBuf);
        UIImage *tinted = [orig imageWithTintColor:monoColor renderingMode:UIImageRenderingModeAlwaysOriginal];
        if (tinted) [FQXMonochromeShareIconCache() setObject:tinted forKey:cacheKey];
        return tinted ?: orig;
    }

    CGContextRef outCtx = CGBitmapContextCreate(outBuf, w, h, 8, w * 4, cs,
                                                (CGBitmapInfo)(kCGImageAlphaPremultipliedLast | kCGBitmapByteOrder32Big));
    CGImageRef rawGlyphCG = outCtx ? CGBitmapContextCreateImage(outCtx) : NULL;
    if (outCtx) CGContextRelease(outCtx);
    CGColorSpaceRelease(cs);
    free(outBuf);

    if (!rawGlyphCG) {
        return [orig imageWithTintColor:monoColor renderingMode:UIImageRenderingModeAlwaysOriginal];
    }

    // Re-center and gently optically boost the extracted logo to ~68% of the icon canvas
    // (capped at 1.32x) so removing the colored disk leaves a balanced, unified monochrome mark.
    CGSize ptSize = orig.size;
    if (ptSize.width < 12.0 || ptSize.height < 12.0) {
        CGFloat sc = orig.scale > 0.5 ? orig.scale : UIScreen.mainScreen.scale;
        ptSize = CGSizeMake((CGFloat)w / sc, (CGFloat)h / sc);
    }
    CGRect cropPx = CGRectMake((CGFloat)minX, (CGFloat)minY,
                               (CGFloat)(maxX - minX + 1), (CGFloat)(maxY - minY + 1));
    CGImageRef croppedCG = CGImageCreateWithImageInRect(rawGlyphCG, cropPx);
    CGImageRelease(rawGlyphCG);

    UIImage *result = nil;
    if (croppedCG) {
        UIGraphicsImageRendererFormat *fmt = [UIGraphicsImageRendererFormat defaultFormat];
        fmt.opaque = NO;
        fmt.scale = orig.scale > 0.5 ? orig.scale : UIScreen.mainScreen.scale;
        UIGraphicsImageRenderer *renderer = [[UIGraphicsImageRenderer alloc] initWithSize:ptSize format:fmt];
        CGFloat cropW = CGRectGetWidth(cropPx);
        CGFloat cropH = CGRectGetHeight(cropPx);
        CGFloat basePtW = cropW * (ptSize.width / (CGFloat)w);
        CGFloat basePtH = cropH * (ptSize.height / (CGFloat)h);
        CGFloat maxDim = MAX(basePtW, basePtH);
        CGFloat desiredDim = MIN(ptSize.width, ptSize.height) * 0.68;
        CGFloat boost = (maxDim > 1.0) ? MIN(1.32, MAX(1.0, desiredDim / maxDim)) : 1.0;
        CGFloat drawW = basePtW * boost;
        CGFloat drawH = basePtH * boost;
        CGRect drawRect = CGRectMake((ptSize.width - drawW) * 0.5,
                                     (ptSize.height - drawH) * 0.5,
                                     drawW, drawH);
        UIImage *glyphUI = [UIImage imageWithCGImage:croppedCG scale:fmt.scale orientation:UIImageOrientationUp];
        result = [renderer imageWithActions:^(__unused UIGraphicsImageRendererContext *rctx) {
            [glyphUI drawInRect:drawRect];
        }];
        CGImageRelease(croppedCG);
        result = [result imageWithRenderingMode:UIImageRenderingModeAlwaysOriginal];
    }

    if (!result) {
        result = [orig imageWithTintColor:monoColor renderingMode:UIImageRenderingModeAlwaysOriginal];
    }
    if (result) [FQXMonochromeShareIconCache() setObject:result forKey:cacheKey];
    return result;
}

static void FQXSetShareSheetHostClipping(UIView *view, BOOL unclip) {
    if (!view) return;
    if (unclip) {
        if (!objc_getAssociatedObject(view, FQXShareSavedClipsKey)) {
            objc_setAssociatedObject(view, FQXShareSavedClipsKey, @(view.clipsToBounds), OBJC_ASSOCIATION_RETAIN_NONATOMIC);
        }
        if (view.clipsToBounds) view.clipsToBounds = NO;
        if (view.layer.mask) {
            if (!objc_getAssociatedObject(view, FQXShareSavedMaskKey)) {
                objc_setAssociatedObject(view, FQXShareSavedMaskKey, view.layer.mask, OBJC_ASSOCIATION_RETAIN_NONATOMIC);
            }
            view.layer.mask = nil;
        }
        if (view.layer.cornerRadius > 0.5) {
            if (!objc_getAssociatedObject(view, FQXShareSavedCornerRKey)) {
                objc_setAssociatedObject(view, FQXShareSavedCornerRKey, @(view.layer.cornerRadius), OBJC_ASSOCIATION_RETAIN_NONATOMIC);
                objc_setAssociatedObject(view, FQXShareSavedCornerMaskKey, @(view.layer.maskedCorners), OBJC_ASSOCIATION_RETAIN_NONATOMIC);
            }
            view.layer.cornerRadius = 0.0;
        }
        // Hide any opaque/tinted full-bleed host CALayer backdrops directly on sheet.layer.
        CGRect sb = view.bounds;
        for (CALayer *sub in view.layer.sublayers) {
            if (sub.delegate != nil) continue; // belongs to a UIView subview
            if (CGRectGetWidth(sub.frame) >= CGRectGetWidth(sb) * 0.75 &&
                CGRectGetHeight(sub.frame) >= CGRectGetHeight(sb) * 0.50 &&
                !sub.hidden) {
                objc_setAssociatedObject(sub, FQXShareHiddenSublayerKey, @YES, OBJC_ASSOCIATION_RETAIN_NONATOMIC);
                sub.hidden = YES;
            }
        }
    } else {
        NSNumber *savedClips = objc_getAssociatedObject(view, FQXShareSavedClipsKey);
        if (savedClips) {
            view.clipsToBounds = savedClips.boolValue;
            objc_setAssociatedObject(view, FQXShareSavedClipsKey, nil, OBJC_ASSOCIATION_RETAIN_NONATOMIC);
        }
        CALayer *savedMask = objc_getAssociatedObject(view, FQXShareSavedMaskKey);
        if (savedMask) {
            view.layer.mask = savedMask;
            objc_setAssociatedObject(view, FQXShareSavedMaskKey, nil, OBJC_ASSOCIATION_RETAIN_NONATOMIC);
        }
        NSNumber *savedCornerR = objc_getAssociatedObject(view, FQXShareSavedCornerRKey);
        if (savedCornerR) {
            view.layer.cornerRadius = savedCornerR.doubleValue;
            NSNumber *savedCornerMask = objc_getAssociatedObject(view, FQXShareSavedCornerMaskKey);
            if (savedCornerMask) view.layer.maskedCorners = (CACornerMask)savedCornerMask.unsignedIntegerValue;
            objc_setAssociatedObject(view, FQXShareSavedCornerRKey, nil, OBJC_ASSOCIATION_RETAIN_NONATOMIC);
            objc_setAssociatedObject(view, FQXShareSavedCornerMaskKey, nil, OBJC_ASSOCIATION_RETAIN_NONATOMIC);
        }
        for (CALayer *sub in view.layer.sublayers) {
            if ([objc_getAssociatedObject(sub, FQXShareHiddenSublayerKey) boolValue]) {
                sub.hidden = NO;
                objc_setAssociatedObject(sub, FQXShareHiddenSublayerKey, nil, OBJC_ASSOCIATION_RETAIN_NONATOMIC);
            }
        }
    }
}

static BOOL FQXStyleShareSheet(UIView *sheet, UIView *root, BOOL forceDarkDrama);

static void HookDynamicShareCellLayout(UIView *cell, SEL cmd) {
    IMP orig = NULL;
    if (gFQXDynamicShareCellOrigLayouts) {
        for (Class c = object_getClass(cell); c && c != UICollectionViewCell.class && c != UIView.class; c = class_getSuperclass(c)) {
            NSValue *v = gFQXDynamicShareCellOrigLayouts[NSStringFromClass(c) ?: @""];
            if (v) { orig = (IMP)v.pointerValue; break; }
        }
    }
    if (orig) ((void (*)(id, SEL))orig)(cell, cmd);
    if (!cell.window) return;
    // Walk up to find an enclosing marked share sheet and re-apply lightweight cleanup/monochrome styling.
    for (UIView *cur = cell.superview; cur; cur = cur.superview) {
        if (objc_getAssociatedObject(cur, FQXShareMarkedSheetKey)) {
            BOOL forceDark = [objc_getAssociatedObject(cur, FQXShareForceDarkKey) boolValue];
            UIView *root = FQXGetWeakAssocView(cur, FQXShareAssociatedRootKey) ?: cur.superview;
            FQXStyleShareSheet(cur, root, forceDark);
            break;
        }
    }
}

static void FQXEnsureShareCellClassHooked(UIView *cell) {
    if (![cell isKindOfClass:UICollectionViewCell.class]) return;
    Class cls = object_getClass(cell);
    if (!cls || cls == UICollectionViewCell.class) return;
    NSString *name = NSStringFromClass(cls);
    if (!name.length || [name hasPrefix:@"UI"] || [name hasPrefix:@"_UI"]) return;
    static dispatch_once_t once;
    dispatch_once(&once, ^{ gFQXDynamicShareCellOrigLayouts = [NSMutableDictionary dictionary]; });
    if (gFQXDynamicShareCellOrigLayouts[name]) return;
    IMP orig = NULL;
    if (FQXInstallOwnedHook(cls, @selector(layoutSubviews), NO, "v16@0:8",
                            (IMP)HookDynamicShareCellLayout, &orig) && orig) {
        gFQXDynamicShareCellOrigLayouts[name] = [NSValue valueWithPointer:(const void *)orig];
    }
}

typedef struct {
    NSInteger neutralizedEffects;
    NSInteger monochromeIcons;
} FQXShareCleanupStats;

static void FQXApplyShareSubtreeCleanup(UIView *view,
                                        UIView *rootSheet,
                                        BOOL clear,
                                        BOOL adaptInk,
                                        BOOL monochromeIcons,
                                        BOOL isDark,
                                        NSInteger depth,
                                        FQXShareCleanupStats *stats) {
    if (!view || depth > 16) return;
    if ([view isKindOfClass:FQXCommentGlassSurfaceView.class] ||
        [view isKindOfClass:FQXBackdropBlurView.class]) {
        return;
    }

    // Neutralize any host UIVisualEffectView (e.g. native UIBlurEffect) inside the share sheet
    // so it never double-blurs on top of our Clear Liquid Glass surface.
    if ([view isKindOfClass:UIVisualEffectView.class]) {
        FQXNeutralizeHostEffectView((UIVisualEffectView *)view, clear);
        if (clear && stats) stats->neutralizedEffects++;
        return;
    }

    if (clear && [view isKindOfClass:UICollectionViewCell.class]) {
        FQXEnsureShareCellClassHooked(view);
    }

    CGRect b = view.bounds;
    CGFloat w = CGRectGetWidth(b);
    CGFloat h = CGRectGetHeight(b);
    CGRect sb = rootSheet.bounds;
    CGFloat sheetW = CGRectGetWidth(sb);
    CGFloat sheetH = CGRectGetHeight(sb);

    BOOL isHairline = (h > 0.0 && h <= 1.5 && w >= 60.0);
    BOOL isGrabberPill = (w >= 20.0 && w <= 68.0 && h >= 2.0 && h <= 8.0 &&
                          CGRectGetMinY([view convertRect:b toView:rootSheet]) <= 26.0 &&
                          ![view isKindOfClass:UILabel.class] &&
                          ![view isKindOfClass:UIImageView.class] &&
                          ![view isKindOfClass:UIButton.class]);
    BOOL isSmallIconBadge = (w > 16.0 && w <= 72.0 && h > 16.0 && h <= 72.0 &&
                             ![view isKindOfClass:UILabel.class] &&
                             (view.layer.cornerRadius >= 10.0 ||
                              view.layer.mask != nil ||
                              [view isKindOfClass:UIImageView.class] ||
                              (fabs(w - h) <= 4.0 && w >= 28.0)));
    BOOL isFullBleedWrapper = (view != rootSheet &&
                               ![view isKindOfClass:UIScrollView.class] &&
                               ![view isKindOfClass:UIImageView.class] &&
                               w >= sheetW - 12.0 && h >= sheetH - 12.0);
    BOOL isFullBleedBgImage = ([view isKindOfClass:UIImageView.class] &&
                               w >= sheetW * 0.72 && h >= sheetH * 0.45);

    if (clear) {
        if (isFullBleedWrapper) {
            FQXSetShareSheetHostClipping(view, YES);
        }
        if (isFullBleedBgImage) {
            FQXAudioSetHiddenTracked(view, YES);
        }
        if (isGrabberPill) {
            if (view.backgroundColor && !objc_getAssociatedObject(view, FQXShareSavedGrabberBgKey)) {
                objc_setAssociatedObject(view, FQXShareSavedGrabberBgKey, view.backgroundColor, OBJC_ASSOCIATION_RETAIN_NONATOMIC);
            }
            view.backgroundColor = [UIColor colorWithWhite:(isDark ? 1.0 : 0.0) alpha:0.32];
        } else if (!isHairline) {
            BOOL isCellContent = ([view.superview isKindOfClass:UICollectionViewCell.class] &&
                                  view == ((UICollectionViewCell *)view.superview).contentView);
            BOOL isContainerClass = ([view isKindOfClass:UICollectionView.class] ||
                                     [view isKindOfClass:UIScrollView.class] ||
                                     [view isKindOfClass:UICollectionViewCell.class] ||
                                     [view isKindOfClass:UITableView.class] ||
                                     [view isKindOfClass:UITableViewCell.class] ||
                                     view == rootSheet ||
                                     isFullBleedWrapper ||
                                     isCellContent);
            BOOL isNeutralBg = FQXColorIsNeutralSurface(view.backgroundColor, view.traitCollection);
            BOOL isWideNeutral = (!isSmallIconBadge && (w >= 76.0 || h >= 72.0) && isNeutralBg);
            BOOL isCancelOrHeaderBtn = ([view isKindOfClass:UIButton.class] && w >= 120.0 && h >= 32.0 && isNeutralBg);
            // When monochrome icon mode is active, also clear colored circular badge containers
            // behind transparent white-glyph UIImageViews so no stray colored disk remains.
            BOOL clearBadgeContainer = (monochromeIcons && isSmallIconBadge &&
                                        ![view isKindOfClass:UIImageView.class] &&
                                        ![view isKindOfClass:UIButton.class]);
            if ((isContainerClass || isWideNeutral || isCancelOrHeaderBtn || clearBadgeContainer) &&
                ![view isKindOfClass:UIImageView.class] && ![view isKindOfClass:UILabel.class]) {
                FQXAudioClearBackground(view, YES);
                if (view.layer.backgroundColor && CGColorGetAlpha(view.layer.backgroundColor) > 0.001) {
                    UIColor *lbg = [UIColor colorWithCGColor:view.layer.backgroundColor];
                    if (clearBadgeContainer || FQXColorIsNeutralSurface(lbg, view.traitCollection)) {
                        if (!objc_getAssociatedObject(view, FQXCommentSavedLayerBgKey)) {
                            objc_setAssociatedObject(view, FQXCommentSavedLayerBgKey, lbg, OBJC_ASSOCIATION_RETAIN_NONATOMIC);
                        }
                        view.layer.backgroundColor = NULL;
                    }
                }
            }
        }

        if (monochromeIcons) {
            if ([view isKindOfClass:UIImageView.class] && !isFullBleedBgImage &&
                w >= 14.0 && w <= 76.0 && h >= 14.0 && h <= 76.0) {
                UIImageView *iv = (UIImageView *)view;
                UIImage *curImg = iv.image;
                if (curImg) {
                    UIImage *appliedMono = objc_getAssociatedObject(iv, FQXShareAppliedMonoImageKey);
                    UIImage *origImg = objc_getAssociatedObject(iv, FQXShareSavedOrigImageKey);
                    if (!origImg || (curImg != appliedMono && curImg != origImg)) {
                        origImg = curImg;
                        objc_setAssociatedObject(iv, FQXShareSavedOrigImageKey, origImg, OBJC_ASSOCIATION_RETAIN_NONATOMIC);
                    }
                    UIImage *mono = FQXMakeMonochromeShareLogoImage(origImg, isDark);
                    if (mono) {
                        if (iv.image != mono) iv.image = mono;
                        objc_setAssociatedObject(iv, FQXShareAppliedMonoImageKey, mono, OBJC_ASSOCIATION_RETAIN_NONATOMIC);
                        if (stats) stats->monochromeIcons++;
                    }
                }
                FQXAudioClearBackground(iv, YES);
            } else if ([view isKindOfClass:UIButton.class] && w <= 96.0 && h <= 96.0) {
                UIButton *btn = (UIButton *)view;
                UIImage *curBtnImg = [btn imageForState:UIControlStateNormal];
                if (curBtnImg && curBtnImg.size.width >= 14.0 && curBtnImg.size.width <= 76.0) {
                    UIImage *appliedMono = objc_getAssociatedObject(btn, FQXShareAppliedBtnMonoImageKey);
                    UIImage *origImg = objc_getAssociatedObject(btn, FQXShareSavedBtnOrigImageKey);
                    if (!origImg || (curBtnImg != appliedMono && curBtnImg != origImg)) {
                        origImg = curBtnImg;
                        objc_setAssociatedObject(btn, FQXShareSavedBtnOrigImageKey, origImg, OBJC_ASSOCIATION_RETAIN_NONATOMIC);
                    }
                    UIImage *mono = FQXMakeMonochromeShareLogoImage(origImg, isDark);
                    if (mono) {
                        if (curBtnImg != mono) [btn setImage:mono forState:UIControlStateNormal];
                        objc_setAssociatedObject(btn, FQXShareAppliedBtnMonoImageKey, mono, OBJC_ASSOCIATION_RETAIN_NONATOMIC);
                        if (stats) stats->monochromeIcons++;
                    }
                }
            }
        }

        if (adaptInk) {
            UIColor *targetInk = isDark
                ? [UIColor colorWithWhite:1.0 alpha:0.95]
                : [UIColor colorWithWhite:0.0 alpha:0.94];
            if ([view isKindOfClass:UILabel.class]) {
                UILabel *lbl = (UILabel *)view;
                if (lbl.attributedText.length > 0) {
                    if (!objc_getAssociatedObject(lbl, FQXShareSavedAttrTextKey)) {
                        objc_setAssociatedObject(lbl, FQXShareSavedAttrTextKey, lbl.attributedText, OBJC_ASSOCIATION_COPY_NONATOMIC);
                    }
                    NSMutableAttributedString *mut = [lbl.attributedText mutableCopy];
                    [mut addAttribute:NSForegroundColorAttributeName value:targetInk range:NSMakeRange(0, mut.length)];
                    lbl.attributedText = mut;
                    lbl.textColor = targetInk;
                } else if (lbl.text.length > 0 && lbl.textColor &&
                           FQXColorIsNeutralSurface(lbl.textColor, lbl.traitCollection)) {
                    if (!objc_getAssociatedObject(lbl, FQXShareSavedTextColorKey)) {
                        objc_setAssociatedObject(lbl, FQXShareSavedTextColorKey, lbl.textColor, OBJC_ASSOCIATION_RETAIN_NONATOMIC);
                    }
                    lbl.textColor = targetInk;
                }
            } else if ([view isKindOfClass:UIButton.class]) {
                UIButton *btn = (UIButton *)view;
                UIColor *curTitleCol = [btn titleColorForState:UIControlStateNormal];
                if ((btn.currentTitle.length > 0 || btn.currentAttributedTitle.length > 0) && curTitleCol &&
                    FQXColorIsNeutralSurface(curTitleCol, btn.traitCollection)) {
                    if (!objc_getAssociatedObject(btn, FQXShareSavedBtnTitleColorKey)) {
                        objc_setAssociatedObject(btn, FQXShareSavedBtnTitleColorKey, curTitleCol, OBJC_ASSOCIATION_RETAIN_NONATOMIC);
                    }
                    [btn setTitleColor:targetInk forState:UIControlStateNormal];
                }
            }
        }
    } else {
        FQXSetShareSheetHostClipping(view, NO);
        FQXAudioSetHiddenTracked(view, NO);
        UIColor *savedGrabber = objc_getAssociatedObject(view, FQXShareSavedGrabberBgKey);
        if ([savedGrabber isKindOfClass:UIColor.class]) {
            view.backgroundColor = savedGrabber;
            objc_setAssociatedObject(view, FQXShareSavedGrabberBgKey, nil, OBJC_ASSOCIATION_RETAIN_NONATOMIC);
        }
        FQXAudioClearBackground(view, NO);
        UIColor *savedLayerBg = objc_getAssociatedObject(view, FQXCommentSavedLayerBgKey);
        if ([savedLayerBg isKindOfClass:UIColor.class]) {
            view.layer.backgroundColor = savedLayerBg.CGColor;
            objc_setAssociatedObject(view, FQXCommentSavedLayerBgKey, nil, OBJC_ASSOCIATION_RETAIN_NONATOMIC);
        }
        if ([view isKindOfClass:UIImageView.class]) {
            UIImage *origImg = objc_getAssociatedObject(view, FQXShareSavedOrigImageKey);
            if ([origImg isKindOfClass:UIImage.class]) {
                ((UIImageView *)view).image = origImg;
                objc_setAssociatedObject(view, FQXShareSavedOrigImageKey, nil, OBJC_ASSOCIATION_RETAIN_NONATOMIC);
                objc_setAssociatedObject(view, FQXShareAppliedMonoImageKey, nil, OBJC_ASSOCIATION_RETAIN_NONATOMIC);
            }
        } else if ([view isKindOfClass:UIButton.class]) {
            UIImage *origBtnImg = objc_getAssociatedObject(view, FQXShareSavedBtnOrigImageKey);
            if ([origBtnImg isKindOfClass:UIImage.class]) {
                [(UIButton *)view setImage:origBtnImg forState:UIControlStateNormal];
                objc_setAssociatedObject(view, FQXShareSavedBtnOrigImageKey, nil, OBJC_ASSOCIATION_RETAIN_NONATOMIC);
                objc_setAssociatedObject(view, FQXShareAppliedBtnMonoImageKey, nil, OBJC_ASSOCIATION_RETAIN_NONATOMIC);
            }
            UIColor *savedBtn = objc_getAssociatedObject(view, FQXShareSavedBtnTitleColorKey);
            if ([savedBtn isKindOfClass:UIColor.class]) {
                [(UIButton *)view setTitleColor:savedBtn forState:UIControlStateNormal];
                objc_setAssociatedObject(view, FQXShareSavedBtnTitleColorKey, nil, OBJC_ASSOCIATION_RETAIN_NONATOMIC);
            }
        } else if ([view isKindOfClass:UILabel.class]) {
            NSAttributedString *savedAttr = objc_getAssociatedObject(view, FQXShareSavedAttrTextKey);
            if ([savedAttr isKindOfClass:NSAttributedString.class]) {
                ((UILabel *)view).attributedText = savedAttr;
                objc_setAssociatedObject(view, FQXShareSavedAttrTextKey, nil, OBJC_ASSOCIATION_RETAIN_NONATOMIC);
            }
            UIColor *savedText = objc_getAssociatedObject(view, FQXShareSavedTextColorKey);
            if ([savedText isKindOfClass:UIColor.class]) {
                ((UILabel *)view).textColor = savedText;
                objc_setAssociatedObject(view, FQXShareSavedTextColorKey, nil, OBJC_ASSOCIATION_RETAIN_NONATOMIC);
            }
        }
    }

    for (UIView *sub in view.subviews) {
        FQXApplyShareSubtreeCleanup(sub, rootSheet, clear, adaptInk, monochromeIcons, isDark, depth + 1, stats);
    }
}

static void FQXClearOneShareDimmerView(UIView *view, BOOL clear, NSInteger depth) {
    if (!view || depth > 2) return;
    if (clear) {
        [FQXTrackedShareDimmers() addObject:view];
        FQXAudioClearBackground(view, YES);
        if (view.layer.backgroundColor && CGColorGetAlpha(view.layer.backgroundColor) > 0.001) {
            UIColor *lbg = [UIColor colorWithCGColor:view.layer.backgroundColor];
            if (FQXColorIsDarkDimmingScrim(lbg, view.traitCollection, view.alpha)) {
                if (!objc_getAssociatedObject(view, FQXCommentSavedLayerBgKey)) {
                    objc_setAssociatedObject(view, FQXCommentSavedLayerBgKey, lbg, OBJC_ASSOCIATION_RETAIN_NONATOMIC);
                }
                view.layer.backgroundColor = NULL;
            }
        }
        CGFloat vw = CGRectGetWidth(view.bounds);
        CGFloat vh = CGRectGetHeight(view.bounds);
        for (CALayer *sub in view.layer.sublayers) {
            if (sub.delegate != nil || sub.hidden) continue;
            if (CGRectGetWidth(sub.bounds) >= vw * 0.70 && CGRectGetHeight(sub.bounds) >= vh * 0.40) {
                objc_setAssociatedObject(sub, FQXShareHiddenSublayerKey, @YES, OBJC_ASSOCIATION_RETAIN_NONATOMIC);
                sub.hidden = YES;
            }
        }
        if (depth < 2) {
            for (UIView *child in view.subviews) {
                if (child.hidden || child.alpha < 0.01) continue;
                if ([child isKindOfClass:FQXCommentGlassSurfaceView.class] ||
                    [child isKindOfClass:FQXBackdropBlurView.class]) continue;
                if (CGRectGetWidth(child.bounds) >= vw * 0.70 && CGRectGetHeight(child.bounds) >= vh * 0.40 &&
                    !FQXSubtreeHasVisibleContent(child, 0) && FQXViewHasDarkDimmingFill(child)) {
                    FQXClearOneShareDimmerView(child, YES, depth + 1);
                }
            }
        }
    } else {
        FQXAudioClearBackground(view, NO);
        UIColor *savedLayerBg = objc_getAssociatedObject(view, FQXCommentSavedLayerBgKey);
        if ([savedLayerBg isKindOfClass:UIColor.class]) {
            view.layer.backgroundColor = savedLayerBg.CGColor;
            objc_setAssociatedObject(view, FQXCommentSavedLayerBgKey, nil, OBJC_ASSOCIATION_RETAIN_NONATOMIC);
        }
        for (CALayer *sub in view.layer.sublayers) {
            if ([objc_getAssociatedObject(sub, FQXShareHiddenSublayerKey) boolValue]) {
                sub.hidden = NO;
                objc_setAssociatedObject(sub, FQXShareHiddenSublayerKey, nil, OBJC_ASSOCIATION_RETAIN_NONATOMIC);
            }
        }
    }
}

// Clear dark translucent dimming overlays behind the Share Sheet (e.g. SSReadingSharePanel's
// full-screen dark scrim) while keeping userInteractionEnabled & hit-testing intact so tapping
// outside still dismisses the sheet and Novel Share matches Short Drama Share's clean bright backdrop.
static NSInteger FQXSyncShareBackdropDimmer(UIView *sheet, BOOL clearDimmer) {
    if (!sheet) return 0;
    if (!clearDimmer) {
        for (UIView *d in FQXTrackedShareDimmers().allObjects) {
            if (!d.window || d.window == sheet.window) {
                FQXClearOneShareDimmerView(d, NO, 0);
            }
        }
        return 0;
    }
    UIWindow *win = sheet.window;
    if (!win) return 0;
    CGFloat winW = CGRectGetWidth(win.bounds);
    CGFloat winH = CGRectGetHeight(win.bounds);
    if (winW < 200.0 || winH < 300.0) return 0;

    NSInteger cleared = 0;
    UIView *branch = sheet;
    UIView *cur = sheet.superview;
    NSInteger steps = 0;
    while (cur && steps < 6) {
        steps++;
        BOOL isWin = (cur == win);
        BOOL isProtectedHostVCView = isWin;
        if (!isProtectedHostVCView && [cur.nextResponder isKindOfClass:UIViewController.class]) {
            NSString *vcName = NSStringFromClass(cur.nextResponder.class) ?: @"";
            if ([vcName hasPrefix:@"BDReader"] || [vcName hasPrefix:@"SSTabBar"] ||
                [vcName hasPrefix:@"SSVideoSeriesFeed"] || [vcName hasPrefix:@"FQVShortVideoList"] ||
                [vcName hasPrefix:@"SSBookShelf"] || [vcName hasPrefix:@"SSBookStore"]) {
                isProtectedHostVCView = YES;
            }
        }

        if (!isProtectedHostVCView && FQXViewHasDarkDimmingFill(cur)) {
            FQXClearOneShareDimmerView(cur, YES, 0);
            cleared++;
        }

        NSArray<UIView *> *siblings = cur.subviews;
        NSUInteger branchIdx = [siblings indexOfObjectIdenticalTo:branch];
        for (NSUInteger i = 0; i < siblings.count; ++i) {
            UIView *sib = siblings[i];
            if (sib == branch || sib == sheet || [sheet isDescendantOfView:sib] || sib.hidden || sib.alpha < 0.01) continue;
            if (isProtectedHostVCView && branchIdx != NSNotFound && i > branchIdx) continue;
            if ([sib isKindOfClass:FQXCommentGlassSurfaceView.class] ||
                [sib isKindOfClass:FQXBackdropBlurView.class]) continue;
            CGRect sibInWin = [sib convertRect:sib.bounds toView:win];
            if (CGRectGetWidth(sibInWin) < winW * 0.72 || CGRectGetHeight(sibInWin) < winH * 0.40) continue;
            if (FQXSubtreeHasVisibleContent(sib, 0)) continue;
            if (FQXViewHasDarkDimmingFill(sib)) {
                FQXClearOneShareDimmerView(sib, YES, 0);
                cleared++;
            }
        }
        if (isWin || isProtectedHostVCView) break;
        branch = cur;
        cur = cur.superview;
    }
    return cleared;
}

static void FQXRemoveShareSheetStyling(UIView *sheet) {
    if (!sheet) return;
    UIVisualEffectView *oldLegacy = objc_getAssociatedObject(sheet, SheetGlassKey);
    if (oldLegacy) FQXRemoveGlassSheet(sheet);
    UIVisualEffectView *surface = objc_getAssociatedObject(sheet, FQXShareGlassSurfaceKey);
    if (surface) {
        FQXReleaseCommentSurface(surface);
        objc_setAssociatedObject(sheet, FQXShareGlassSurfaceKey, nil, OBJC_ASSOCIATION_RETAIN_NONATOMIC);
    }
    objc_setAssociatedObject(sheet, FQXShareStyledStampKey, nil, OBJC_ASSOCIATION_RETAIN_NONATOMIC);
    if (sheet.overrideUserInterfaceStyle != UIUserInterfaceStyleUnspecified) {
        sheet.overrideUserInterfaceStyle = UIUserInterfaceStyleUnspecified;
    }
    FQXSetShareSheetHostClipping(sheet, NO);
    FQXSyncShareBackdropDimmer(sheet, NO);
    FQXApplyShareSubtreeCleanup(sheet, sheet, NO, NO, NO, NO, 0, NULL);
}

static BOOL FQXStyleShareSheet(UIView *sheet, UIView *root, BOOL forceDarkDrama) {
    if (![sheet isKindOfClass:UIView.class]) return NO;
    CGRect sb = sheet.bounds;
    if (CGRectGetWidth(sb) < 120.0 || CGRectGetHeight(sb) < 72.0) return NO;

    [FQXTrackedShareSheets() addObject:sheet];
    objc_setAssociatedObject(sheet, FQXShareForceDarkKey, @(forceDarkDrama), OBJC_ASSOCIATION_RETAIN_NONATOMIC);
    objc_setAssociatedObject(sheet, FQXShareMarkedSheetKey, @YES, OBJC_ASSOCIATION_RETAIN_NONATOMIC);
    if (root && root != sheet) {
        FQXSetWeakAssocView(sheet, FQXShareAssociatedRootKey, root);
    }

    if (FQXHotPrefsSnapshot().glassDisabled) {
        FQXRemoveShareSheetStyling(sheet);
        return NO;
    }

    BOOL isAudioMoreSheet = (FQXFindVisibleAudioPlayVCInWindow(sheet.window) != nil);
    if (!isAudioMoreSheet) {
        NSInteger markerBudget = 220;
        isAudioMoreSheet = FQXViewSubtreeHasAudioMoreMarker(sheet, &markerBudget, 0);
    }

    NSUserDefaults *ud = NSUserDefaults.standardUserDefaults;
    id audioSheetBlurObj = [ud objectForKey:AudioSheetBlurPrefKey];
    id audioMoreBlurObj = [ud objectForKey:AudioMoreBlurPrefKey];
    BOOL hasAudioSheetBlurPref = (audioSheetBlurObj && [audioSheetBlurObj respondsToSelector:@selector(doubleValue)]);
    BOOL hasAudioMoreBlurPref = (audioMoreBlurObj && [audioMoreBlurObj respondsToSelector:@selector(doubleValue)]);
    NSInteger rawAudioMoreBlur = FQXResolveAudioSheetBlur(
        hasAudioSheetBlurPref ? 1 : 0,
        hasAudioSheetBlurPref ? (int)llround([audioSheetBlurObj doubleValue]) : 0,
        hasAudioMoreBlurPref ? 1 : 0,
        hasAudioMoreBlurPref ? (int)llround([audioMoreBlurObj doubleValue]) : 0);
    NSInteger rawShareBlur = FQXBlurPercent([ud doubleForKey:ShareBlurPrefKey]);

    FQXShareMaterialStyle style = isAudioMoreSheet
        ? FQXCurrentAudioSheetMaterialStyle()
        : FQXCurrentShareMaterialStyle();
    if (!isAudioMoreSheet && FQXShouldPromoteAudioMoreSheetMaterial(0, (int)style, (int)rawAudioMoreBlur)) {
        style = FQXShareMaterialClearGlass;
    }
    if (style == FQXShareMaterialNative) {
        FQXRemoveShareSheetStyling(sheet);
        return NO;
    }

    if (objc_getAssociatedObject(sheet, SheetGlassKey)) {
        FQXRemoveGlassSheet(sheet);
    }

    // Resolve unified Light/Dark polarity across both Short Drama and Novel Share sheets:
    // Light mode => pure black logos + black text; Night/Dark mode => pure white logos + white text.
    BOOL fromReader = NO;
    UIColor *paperColor = FQXSampleActiveReaderPaperColor(sheet.window, root ?: sheet, &fromReader);
    BOOL isDark = FQXAppIsInNightMode();
    if (fromReader && paperColor) {
        CGFloat luma = 0.5;
        if (FQXColorLuminance(paperColor, sheet.traitCollection, &luma)) {
            isDark = (luma < 0.45);
        }
    }

    CGFloat hostCornerR = FQXReadHostSheetCornerRadius(sheet, root);
    CGFloat cornerR = (hostCornerR >= 10.0 && hostCornerR <= 22.0) ? hostCornerR : 18.0;
    BOOL reduceTrans = UIAccessibilityIsReduceTransparencyEnabled();
    BOOL darkTint = FQXGlassDarkTintEnabled();
    NSInteger blurPct = reduceTrans ? 0 : FQXResolveAudioMoreSheetBlur(isAudioMoreSheet ? 1 : 0,
                                                                       (hasAudioSheetBlurPref || hasAudioMoreBlurPref) ? 1 : 0,
                                                                       (int)rawAudioMoreBlur,
                                                                       (int)rawShareBlur);
    BOOL hadMask = (sheet.layer.mask != nil || objc_getAssociatedObject(sheet, FQXShareSavedMaskKey) != nil);
    BOOL hadClips = (sheet.clipsToBounds || [objc_getAssociatedObject(sheet, FQXShareSavedClipsKey) boolValue]);
    FQXShareCleanupStats stats = {0, 0};
    NSInteger clearedDimmers = FQXSyncShareBackdropDimmer(sheet, YES);

    // Fallback to Gaussian Blur on pre-iOS 26 if native UIGlassEffect is unavailable
    FQXShareMaterialStyle effStyle = style;
    if ((effStyle == FQXShareMaterialClearGlass || effStyle == FQXShareMaterialRegularGlass) && !FQXGlassEnabled()) {
        effStyle = FQXShareMaterialGaussianBlur;
    }

    BOOL wantsGaussian = (effStyle == FQXShareMaterialGaussianBlur);
    NSInteger minimumBlur = wantsGaussian ? 35 : 0;
    NSInteger effectiveBlur = reduceTrans ? (wantsGaussian ? 100 : 0) : FQXSheetBlurPercent(blurPct, (int)minimumBlur);
    CGFloat maxGlassTint = (effStyle == FQXShareMaterialRegularGlass)
        ? (isDark ? 0.34 : 0.30)
        : (isAudioMoreSheet ? (isDark ? 0.36 : 0.34) : (isDark ? 0.22 : 0.18));
    UIVisualEffectView *surface = objc_getAssociatedObject(sheet, FQXShareGlassSurfaceKey);
    BOOL isBlurView = [surface isKindOfClass:FQXBackdropBlurView.class];
    BOOL isGlassView = [surface isKindOfClass:FQXCommentGlassSurfaceView.class];
    if (surface && ((wantsGaussian && !isBlurView) || (!wantsGaussian && !isGlassView))) {
        FQXReleaseCommentSurface(surface);
        objc_setAssociatedObject(sheet, FQXShareGlassSurfaceKey, nil, OBJC_ASSOCIATION_RETAIN_NONATOMIC);
        surface = nil;
    }
    if (!surface) {
        if (wantsGaussian) {
            surface = FQXNewSheetBlur();
        } else {
            FQXCommentGlassSurfaceView *gv = [[FQXCommentGlassSurfaceView alloc] initWithEffect:nil];
            gv->_flexSourceView = sheet;
            gv->_isBarGlass = NO;
            surface = gv;
        }
        surface.userInteractionEnabled = NO;
        surface.accessibilityElementsHidden = YES;
        surface.isAccessibilityElement = NO;
        surface.alpha = 1.0;
        surface.autoresizingMask = UIViewAutoresizingFlexibleWidth | UIViewAutoresizingFlexibleHeight;
        objc_setAssociatedObject(sheet, FQXShareGlassSurfaceKey, surface, OBJC_ASSOCIATION_RETAIN_NONATOMIC);
    }

    // Match Comment Sheet's verified Clear Liquid Glass compositor policy:
    // Use UIUserInterfaceStyleUnspecified on Clear Glass so iOS 26/27 renders crisp
    // transparent glass with bright optical rim refraction (never milky/frosted Light haze).
    UIUserInterfaceStyle surfaceUIStyle = (effStyle == FQXShareMaterialClearGlass)
        ? UIUserInterfaceStyleUnspecified
        : (isDark ? UIUserInterfaceStyleDark : UIUserInterfaceStyleLight);
    UIUserInterfaceStyle hostUIStyle = isDark
        ? UIUserInterfaceStyleDark
        : ((effStyle == FQXShareMaterialClearGlass) ? UIUserInterfaceStyleUnspecified : UIUserInterfaceStyleLight);

    [CATransaction begin];
    [CATransaction setDisableActions:YES];
    // Remove host layer.mask / clipsToBounds so Core Animation never offscreen-rasterizes
    // UIGlassEffect or clips its specular top rim highlight.
    FQXSetShareSheetHostClipping(sheet, YES);
    if (sheet.overrideUserInterfaceStyle != hostUIStyle) sheet.overrideUserInterfaceStyle = hostUIStyle;
    if (surface.overrideUserInterfaceStyle != surfaceUIStyle) surface.overrideUserInterfaceStyle = surfaceUIStyle;
    FQXSyncSheetBlur(sheet, surface, wantsGaussian, effectiveBlur, isDark, maxGlassTint, cornerR);
    FQXApplyShareSubtreeCleanup(sheet, sheet, YES, YES, YES, isDark, 0, &stats);
    [CATransaction commit];

    if (!wantsGaussian) {
        FQXCommentGlassSurfaceView *gv = (FQXCommentGlassSurfaceView *)surface;
        gv->_flexSourceView = sheet;
        NSInteger desiredStamp = ((NSInteger)effStyle * 100) + (isDark ? 10 : 0) + (darkTint ? 2 : 0) + (reduceTrans ? 1 : 0);
        NSNumber *appliedStamp = objc_getAssociatedObject(gv, FQXShareStyledStampKey);
        if (!gv.effect || !appliedStamp || appliedStamp.integerValue != desiredStamp) {
            NSInteger glassStyle = (reduceTrans || effStyle == FQXShareMaterialRegularGlass) ? 0 : 1;
            UIColor *tint = (!reduceTrans && effStyle == FQXShareMaterialClearGlass && darkTint && isDark)
                ? [UIColor colorWithWhite:0.0 alpha:0.30] : nil;
            UIVisualEffect *glassEffect = FQXMakeGlassEffect(glassStyle, YES, tint);
            [UIView performWithoutAnimation:^{
                gv.overrideUserInterfaceStyle = surfaceUIStyle;
                gv.effect = glassEffect;
            }];
            objc_setAssociatedObject(gv, FQXShareStyledStampKey, @(desiredStamp), OBJC_ASSOCIATION_RETAIN_NONATOMIC);
        }
    }

    if (FQXDiagnosticsHubIsEnabled()) {
        NSString *diagSig = [NSString stringWithFormat:@"%ld|%d|%ld|%d|%d|%.0f|%ld|%ld|%ld",
                             (long)effStyle, isDark ? 1 : 0, (long)blurPct, darkTint ? 1 : 0,
                             isAudioMoreSheet ? 1 : 0,
                             CGRectGetHeight(sb), (long)stats.monochromeIcons, (long)stats.neutralizedEffects, (long)clearedDimmers];
        if (![diagSig isEqualToString:objc_getAssociatedObject(sheet, FQXShareDiagLoggedKey)]) {
            objc_setAssociatedObject(sheet, FQXShareDiagLoggedKey, diagSig, OBJC_ASSOCIATION_COPY_NONATOMIC);
            FQXDiagRecordEvent(FQXDiagCategoryUI, @"share_panel_styled", @{
                @"sheetClass": NSStringFromClass(sheet.class) ?: @"",
                @"rootClass": root ? (NSStringFromClass(root.class) ?: @"") : @"",
                @"materialStyle": @((NSInteger)effStyle),
                @"blurPercent": @(blurPct),
                @"effectiveBlurPercent": @(effectiveBlur),
                @"isAudioMoreSheet": @(isAudioMoreSheet),
                @"audioMoreBlurPercent": @(rawAudioMoreBlur),
                @"fromReader": @(fromReader),
                @"isDark": @(isDark),
                @"darkTint": @(darkTint),
                @"surfaceEffectClass": surface.effect ? (NSStringFromClass(surface.effect.class) ?: @"") : @"nil",
                @"surfaceOverrideStyle": @((NSInteger)surface.overrideUserInterfaceStyle),
                @"monochromeIcons": @(stats.monochromeIcons),
                @"neutralizedEffects": @(stats.neutralizedEffects),
                @"clearedDimmers": @(clearedDimmers),
                @"sheetHadMask": @(hadMask),
                @"sheetHadClips": @(hadClips),
                @"sheetFrame": FQXDockRectArray(sb),
            }, NO);
        }
    }
    return YES;
}

static void FQXRefreshAllShareSheets(void) {
    if (!NSThread.isMainThread) {
        dispatch_async(dispatch_get_main_queue(), ^{ FQXRefreshAllShareSheets(); });
        return;
    }
    for (UIView *sheet in FQXTrackedShareSheets().allObjects) {
        if (!sheet.superview) continue;
        BOOL forceDark = [objc_getAssociatedObject(sheet, FQXShareForceDarkKey) boolValue];
        UIView *root = FQXGetWeakAssocView(sheet, FQXShareAssociatedRootKey) ?: sheet.superview;
        FQXStyleShareSheet(sheet, root, forceDark);
    }
}

static NSSet<NSString *> *FQXShareChannelMarkers(void) {
    static NSSet<NSString *> *markers;
    static dispatch_once_t once;
    dispatch_once(&once, ^{
        markers = [NSSet setWithArray:@[
            @"微信", @"朋友圈", @"微信好友", @"抖音好友", @"发布到抖音",
            @"复制链接", @"生成分享图", @"微博", @"QQ", @"QQ空间",
            @"私信", @"分享给好友", @"分享到", @"分享至", @"保存图片", @"转发",
        ]];
    });
    return markers;
}

static NSInteger FQXCountShareChannelMarkersInView(UIView *root,
                                                   NSMutableSet<NSString *> *matched,
                                                   NSInteger *visitedBudget,
                                                   NSInteger depth) {
    if (!root || root.hidden || root.alpha <= 0.01 || depth > 16 || *visitedBudget <= 0) return (NSInteger)matched.count;
    (*visitedBudget)--;
    NSString *text = nil;
    if ([root isKindOfClass:UILabel.class]) {
        UILabel *lbl = (UILabel *)root;
        text = lbl.text.length ? lbl.text : lbl.attributedText.string;
    } else if ([root isKindOfClass:UIButton.class]) {
        UIButton *btn = (UIButton *)root;
        text = btn.currentTitle.length ? btn.currentTitle : btn.currentAttributedTitle.string;
    }
    if (!text.length && root.accessibilityLabel.length > 0 && root.accessibilityLabel.length <= 16) {
        text = root.accessibilityLabel;
    }
    if (text.length > 0 && text.length <= 16) {
        NSString *trimmed = [text stringByTrimmingCharactersInSet:NSCharacterSet.whitespaceAndNewlineCharacterSet];
        if ([FQXShareChannelMarkers() containsObject:trimmed]) {
            [matched addObject:trimmed];
            if (matched.count >= 2) return (NSInteger)matched.count;
        }
    }
    for (UIView *sub in root.subviews) {
        FQXCountShareChannelMarkersInView(sub, matched, visitedBudget, depth + 1);
        if (matched.count >= 2) return (NSInteger)matched.count;
    }
    return (NSInteger)matched.count;
}

static UIView *FQXFindShareSheetCardInRoot(UIView *root, UIWindow *window) {
    if (!root || !window) return nil;
    CGFloat winW = CGRectGetWidth(window.bounds);
    CGFloat winH = CGRectGetHeight(window.bounds);
    if (winW < 200.0 || winH < 300.0) return nil;

    // Breadth-first search for the highest full-width bottom-anchored card holding >= 2 share channels.
    NSMutableArray<UIView *> *queue = [NSMutableArray arrayWithObject:root];
    NSInteger inspected = 0;
    UIView *best = nil;
    while (queue.count > 0 && inspected < 140) {
        UIView *cur = queue.firstObject;
        [queue removeObjectAtIndex:0];
        if (!cur || cur.hidden || cur.alpha <= 0.01) continue;
        if ([cur isKindOfClass:UICollectionView.class] || [cur isKindOfClass:UITableView.class]) continue;
        inspected++;

        CGRect inWin = [cur convertRect:cur.bounds toView:window];
        CGFloat w = CGRectGetWidth(inWin);
        CGFloat h = CGRectGetHeight(inWin);
        BOOL isBottomCard = (w >= winW - 36.0) &&
                            (h >= 120.0 && h <= winH * 0.78) &&
                            (CGRectGetMaxY(inWin) >= winH - 64.0);
        if (isBottomCard) {
            NSMutableSet<NSString *> *hits = [NSMutableSet set];
            NSInteger budget = 240;
            if (FQXCountShareChannelMarkersInView(cur, hits, &budget, 0) >= 2) {
                best = cur;
                break;
            }
        }
        for (UIView *sub in cur.subviews) {
            if (!sub.hidden && sub.alpha > 0.01) [queue addObject:sub];
        }
    }
    return best;
}

static UIView *FQXFindFirstCustomViewInside(UIView *view, NSInteger depth) {
    if (!view || depth > 8) return nil;
    NSString *name = NSStringFromClass(view.class) ?: @"";
    if (name.length && ![name hasPrefix:@"UI"] && ![name hasPrefix:@"_UI"] &&
        ![name hasPrefix:@"FQX"] && ![name hasPrefix:@"FanqieX"] &&
        ![view isKindOfClass:UICollectionViewCell.class] &&
        ![view isKindOfClass:UILabel.class] &&
        ![view isKindOfClass:UIImageView.class]) {
        return view;
    }
    for (UIView *sub in view.subviews) {
        UIView *found = FQXFindFirstCustomViewInside(sub, depth + 1);
        if (found) return found;
    }
    return nil;
}

static void HookDynamicShareSheetLayout(UIView *view, SEL cmd) {
    IMP orig = NULL;
    if (gFQXDynamicShareOrigLayouts) {
        for (Class c = object_getClass(view); c && c != UIView.class; c = class_getSuperclass(c)) {
            NSValue *v = gFQXDynamicShareOrigLayouts[NSStringFromClass(c) ?: @""];
            if (v) { orig = (IMP)v.pointerValue; break; }
        }
    }
    if (orig) ((void (*)(id, SEL))orig)(view, cmd);
    if (!view.window) return;
    UIView *card = FQXGetWeakAssocView(view, FQXShareAssociatedCardKey);
    if (!card && objc_getAssociatedObject(view, FQXShareMarkedSheetKey)) {
        card = view;
    }
    if (card && card.window) {
        BOOL forceDark = [objc_getAssociatedObject(card, FQXShareForceDarkKey) boolValue];
        UIView *root = FQXGetWeakAssocView(card, FQXShareAssociatedRootKey) ?: card.superview;
        FQXStyleShareSheet(card, root, forceDark);
    }
}

static void FQXEnsureShareSheetClassHooked(UIView *target, UIView *card) {
    if (!target) return;
    if (card && target != card) {
        FQXSetWeakAssocView(target, FQXShareAssociatedCardKey, card);
    }
    Class cls = object_getClass(target);
    if (!cls || cls == UIView.class) return;
    NSString *name = NSStringFromClass(cls);
    if (!name.length || [name hasPrefix:@"UI"] || [name hasPrefix:@"_UI"] ||
        [name hasPrefix:@"FQX"] || [name hasPrefix:@"FanqieX"] ||
        [name isEqualToString:@"SSVideoSharePanelView"] ||
        [name isEqualToString:@"SSReadingSharePanel"]) return;
    static dispatch_once_t mapOnce;
    dispatch_once(&mapOnce, ^{ gFQXDynamicShareOrigLayouts = [NSMutableDictionary dictionary]; });
    if (gFQXDynamicShareOrigLayouts[name]) return;
    IMP orig = NULL;
    if (FQXInstallOwnedHook(cls, @selector(layoutSubviews), NO, "v16@0:8",
                            (IMP)HookDynamicShareSheetLayout, &orig) && orig) {
        gFQXDynamicShareOrigLayouts[name] = [NSValue valueWithPointer:(const void *)orig];
    }
}

static BOOL FQXShouldSkipShareCandidateClass(NSString *clsName) {
    if (!clsName.length) return YES;
    if ([clsName hasPrefix:@"FQX"] || [clsName hasPrefix:@"FanqieX"]) return YES;
    if ([clsName hasPrefix:@"_UI"]) {
        if ([clsName containsString:@"Sheet"] || [clsName containsString:@"Transition"] ||
            [clsName containsString:@"DropShadow"] || [clsName containsString:@"Presentation"]) {
            return NO;
        }
        return YES;
    }
    return NO;
}

static void FQXInspectCandidateShareContainer(UIView *root) {
    if (!root || !root.window || root.hidden || root.alpha <= 0.01) return;
    NSString *clsName = NSStringFromClass(root.class) ?: @"";
    if (FQXShouldSkipShareCandidateClass(clsName)) return;
    if ([root isKindOfClass:objc_lookUpClass("SSVideoSharePanelView")]) {
        FQXStyleShareSheet(root, root.superview, YES);
        return;
    }

    NSMutableSet<NSString *> *hits = [NSMutableSet set];
    NSInteger budget = 320;
    if (FQXCountShareChannelMarkersInView(root, hits, &budget, 0) < 2) return;

    UIView *card = FQXFindShareSheetCardInRoot(root, root.window);
    if (!card) return;
    FQXEnsureShareSheetClassHooked(card, card);
    if (root != card) FQXEnsureShareSheetClassHooked(root, card);
    UIView *innerCustom = FQXFindFirstCustomViewInside(card, 0);
    if (innerCustom && innerCustom != card && innerCustom != root) {
        FQXEnsureShareSheetClassHooked(innerCustom, card);
    }
    FQXStyleShareSheet(card, root, NO);
}

static NSHashTable<UIView *> *FQXTrackedAudioPlaySheets(void) {
    static NSHashTable<UIView *> *table;
    static dispatch_once_t once;
    dispatch_once(&once, ^{ table = [NSHashTable weakObjectsHashTable]; });
    return table;
}

static const char FQXK_FQXAudioSheetSurfaceKey = 0;
#define FQXAudioSheetSurfaceKey ((const void *)&FQXK_FQXAudioSheetSurfaceKey)
static const char FQXK_FQXAudioSheetStampKey = 0;
#define FQXAudioSheetStampKey ((const void *)&FQXK_FQXAudioSheetStampKey)
static const char FQXK_FQXAudioSheetMarkedKey = 0;
#define FQXAudioSheetMarkedKey ((const void *)&FQXK_FQXAudioSheetMarkedKey)
static const char FQXK_FQXAudioSheetRootKey = 0;
#define FQXAudioSheetRootKey ((const void *)&FQXK_FQXAudioSheetRootKey)
static const char FQXK_FQXAudioSheetCardKey = 0;
#define FQXAudioSheetCardKey ((const void *)&FQXK_FQXAudioSheetCardKey)
static const char FQXK_FQXAudioSheetSavedChipBgKey = 0;
#define FQXAudioSheetSavedChipBgKey ((const void *)&FQXK_FQXAudioSheetSavedChipBgKey)
static const char FQXK_FQXAudioSheetDiagKey = 0;
#define FQXAudioSheetDiagKey ((const void *)&FQXK_FQXAudioSheetDiagKey)
static const char FQXK_FQXAudioTouchObserverKey = 0;
#define FQXAudioTouchObserverKey ((const void *)&FQXK_FQXAudioTouchObserverKey)
static NSMutableDictionary<NSString *, NSValue *> *gFQXDynamicAudioSheetOrigLayouts = nil;
static NSMutableDictionary<NSString *, NSValue *> *gFQXDynamicAudioSheetCellOrigLayouts = nil;

static NSInteger FQXCurrentAudioSheetBlurPercent(void) {
    NSUserDefaults *ud = NSUserDefaults.standardUserDefaults;
    id sheetObj = [ud objectForKey:AudioSheetBlurPrefKey];
    id moreObj = [ud objectForKey:AudioMoreBlurPrefKey];
    BOOL hasSheet = (sheetObj && [sheetObj respondsToSelector:@selector(doubleValue)]);
    BOOL hasMore = (moreObj && [moreObj respondsToSelector:@selector(doubleValue)]);
    return FQXResolveAudioSheetBlur(
        hasSheet ? 1 : 0, hasSheet ? (int)llround([sheetObj doubleValue]) : 0,
        hasMore ? 1 : 0, hasMore ? (int)llround([moreObj doubleValue]) : 0);
}

static BOOL FQXStyleAudioPlaySheet(UIView *sheet, UIView *root);

static void HookDynamicAudioSheetLayout(UIView *view, SEL cmd) {
    IMP orig = NULL;
    if (gFQXDynamicAudioSheetOrigLayouts) {
        for (Class c = object_getClass(view); c && c != UIView.class; c = class_getSuperclass(c)) {
            NSValue *v = gFQXDynamicAudioSheetOrigLayouts[NSStringFromClass(c) ?: @""];
            if (v) { orig = (IMP)v.pointerValue; break; }
        }
    }
    if (orig) ((void (*)(id, SEL))orig)(view, cmd);
    if (!view.window) return;
    UIView *card = FQXGetWeakAssocView(view, FQXAudioSheetCardKey);
    if (!card && objc_getAssociatedObject(view, FQXAudioSheetMarkedKey)) {
        card = view;
    }
    if (card && card.window) {
        UIView *root = FQXGetWeakAssocView(card, FQXAudioSheetRootKey) ?: card.superview;
        FQXStyleAudioPlaySheet(card, root);
    }
}

static void FQXEnsureAudioSheetClassHooked(UIView *target, UIView *card) {
    if (!target) return;
    if (card && target != card) {
        FQXSetWeakAssocView(target, FQXAudioSheetCardKey, card);
    }
    Class cls = object_getClass(target);
    if (!cls || cls == UIView.class) return;
    NSString *name = NSStringFromClass(cls);
    if (!name.length || [name hasPrefix:@"UI"] || [name hasPrefix:@"_UI"] ||
        [name hasPrefix:@"FQX"] || [name hasPrefix:@"FanqieX"] ||
        [name isEqualToString:@"SSReadingSharePanel"] ||
        [name isEqualToString:@"SSVideoSharePanelView"]) return;
    static dispatch_once_t once;
    dispatch_once(&once, ^{ gFQXDynamicAudioSheetOrigLayouts = [NSMutableDictionary dictionary]; });
    if (gFQXDynamicAudioSheetOrigLayouts[name]) return;
    IMP orig = NULL;
    if (FQXInstallOwnedHook(cls, @selector(layoutSubviews), NO, "v16@0:8",
                            (IMP)HookDynamicAudioSheetLayout, &orig) && orig) {
        gFQXDynamicAudioSheetOrigLayouts[name] = [NSValue valueWithPointer:(const void *)orig];
    }
}

static void HookDynamicAudioSheetCellLayout(UIView *cell, SEL cmd) {
    IMP orig = NULL;
    if (gFQXDynamicAudioSheetCellOrigLayouts) {
        for (Class c = object_getClass(cell); c && c != UICollectionViewCell.class && c != UITableViewCell.class && c != UIView.class; c = class_getSuperclass(c)) {
            NSValue *v = gFQXDynamicAudioSheetCellOrigLayouts[NSStringFromClass(c) ?: @""];
            if (v) { orig = (IMP)v.pointerValue; break; }
        }
    }
    if (orig) ((void (*)(id, SEL))orig)(cell, cmd);
    if (!cell.window) return;
    for (UIView *cur = cell.superview; cur; cur = cur.superview) {
        if (objc_getAssociatedObject(cur, FQXAudioSheetMarkedKey)) {
            UIView *root = FQXGetWeakAssocView(cur, FQXAudioSheetRootKey) ?: cur.superview;
            FQXStyleAudioPlaySheet(cur, root);
            break;
        }
    }
}

static void FQXEnsureAudioSheetCellClassHooked(UIView *cell) {
    if (![cell isKindOfClass:UICollectionViewCell.class] && ![cell isKindOfClass:UITableViewCell.class]) return;
    Class cls = object_getClass(cell);
    if (!cls || cls == UICollectionViewCell.class || cls == UITableViewCell.class) return;
    NSString *name = NSStringFromClass(cls);
    if (!name.length || [name hasPrefix:@"UI"] || [name hasPrefix:@"_UI"] ||
        [name hasPrefix:@"FQX"] || [name hasPrefix:@"FanqieX"]) return;
    static dispatch_once_t once;
    dispatch_once(&once, ^{ gFQXDynamicAudioSheetCellOrigLayouts = [NSMutableDictionary dictionary]; });
    if (gFQXDynamicAudioSheetCellOrigLayouts[name]) return;
    IMP orig = NULL;
    if (FQXInstallOwnedHook(cls, @selector(layoutSubviews), NO, "v16@0:8",
                            (IMP)HookDynamicAudioSheetCellLayout, &orig) && orig) {
        gFQXDynamicAudioSheetCellOrigLayouts[name] = [NSValue valueWithPointer:(const void *)orig];
    }
}

static void FQXApplyAudioSheetSubtreeCleanup(UIView *view,
                                             UIView *rootSheet,
                                             BOOL clear,
                                             BOOL isDark,
                                             NSInteger depth) {
    if (!view || depth > 16) return;
    if ([view isKindOfClass:FQXCommentGlassSurfaceView.class] ||
        [view isKindOfClass:FQXBackdropBlurView.class] ||
        [view isKindOfClass:UISwitch.class] ||
        [view isKindOfClass:UISlider.class]) {
        return;
    }
    if ([view isKindOfClass:UIVisualEffectView.class]) {
        FQXNeutralizeHostEffectView((UIVisualEffectView *)view, clear);
        return;
    }
    if (clear && ([view isKindOfClass:UICollectionViewCell.class] ||
                  [view isKindOfClass:UITableViewCell.class])) {
        FQXEnsureAudioSheetCellClassHooked(view);
    }

    CGRect b = view.bounds;
    CGFloat w = CGRectGetWidth(b);
    CGFloat h = CGRectGetHeight(b);
    CGRect sb = rootSheet.bounds;
    CGFloat sheetW = CGRectGetWidth(sb);
    CGFloat sheetH = CGRectGetHeight(sb);

    BOOL isHairline = (h > 0.0 && h <= 1.5 && w >= 40.0);
    BOOL isGrabberPill = (w >= 20.0 && w <= 68.0 && h >= 2.0 && h <= 8.0 &&
                          CGRectGetMinY([view convertRect:b toView:rootSheet]) <= 26.0 &&
                          ![view isKindOfClass:UILabel.class] &&
                          ![view isKindOfClass:UIImageView.class] &&
                          ![view isKindOfClass:UIButton.class]);
    BOOL isSliderThumbOrTrack = (h >= 2.0 && h <= 30.0 && w <= 34.0 &&
                                 fabs(w - h) <= 4.0 && view.layer.cornerRadius >= MIN(w, h) * 0.40 &&
                                 view.layer.shadowOpacity > 0.01);
    BOOL isFullBleedWrapper = (view != rootSheet &&
                               ![view isKindOfClass:UIScrollView.class] &&
                               ![view isKindOfClass:UIImageView.class] &&
                               w >= sheetW - 12.0 && h >= sheetH - 12.0);
    BOOL isFullBleedBgImage = ([view isKindOfClass:UIImageView.class] &&
                               w >= sheetW * 0.72 && h >= sheetH * 0.45);

    if (clear) {
        if (isFullBleedWrapper) {
            FQXSetShareSheetHostClipping(view, YES);
        }
        if (isFullBleedBgImage) {
            FQXAudioSetHiddenTracked(view, YES);
        }
        if (isGrabberPill) {
            if (view.backgroundColor && !objc_getAssociatedObject(view, FQXShareSavedGrabberBgKey)) {
                objc_setAssociatedObject(view, FQXShareSavedGrabberBgKey, view.backgroundColor, OBJC_ASSOCIATION_RETAIN_NONATOMIC);
            }
            view.backgroundColor = [UIColor colorWithWhite:(isDark ? 1.0 : 0.0) alpha:0.32];
        } else if (!isHairline && !isSliderThumbOrTrack) {
            BOOL isCellContent = ([view.superview isKindOfClass:UICollectionViewCell.class] &&
                                  view == ((UICollectionViewCell *)view.superview).contentView) ||
                                 ([view.superview isKindOfClass:UITableViewCell.class] &&
                                  view == ((UITableViewCell *)view.superview).contentView);
            BOOL isContainerClass = ([view isKindOfClass:UICollectionView.class] ||
                                     [view isKindOfClass:UIScrollView.class] ||
                                     [view isKindOfClass:UICollectionViewCell.class] ||
                                     [view isKindOfClass:UITableView.class] ||
                                     [view isKindOfClass:UITableViewCell.class] ||
                                     view == rootSheet ||
                                     isFullBleedWrapper ||
                                     isCellContent);
            UIColor *bg = view.backgroundColor;
            BOOL isNeutralBg = FQXColorIsNeutralSurface(bg, view.traitCollection);
            CGFloat bgLuma = 0.5;
            BOOL hasLuma = isNeutralBg && FQXColorLuminance(bg, view.traitCollection, &bgLuma);
            BOOL isPureSheetSurface = isNeutralBg && (!hasLuma || bgLuma >= 0.965 || bgLuma <= 0.14);
            BOOL isRoundedSubCardOrChip = (!isContainerClass &&
                                           ![view isKindOfClass:UILabel.class] &&
                                           ![view isKindOfClass:UIImageView.class] &&
                                           isNeutralBg && !isPureSheetSurface &&
                                           w >= 44.0 && w <= sheetW - 12.0 &&
                                           h >= 24.0 && h <= 116.0 &&
                                           (view.layer.cornerRadius >= 5.0 || [view isKindOfClass:UIButton.class]));
            BOOL isWideNeutralBar = (!isRoundedSubCardOrChip && isNeutralBg &&
                                     (w >= sheetW * 0.72 || h >= 72.0));
            BOOL isFooterOrCancelBtn = ([view isKindOfClass:UIButton.class] && !isRoundedSubCardOrChip &&
                                        w >= 110.0 && h >= 32.0 && isNeutralBg);

            if (isRoundedSubCardOrChip) {
                if (bg && !objc_getAssociatedObject(view, FQXAudioSheetSavedChipBgKey)) {
                    objc_setAssociatedObject(view, FQXAudioSheetSavedChipBgKey, bg, OBJC_ASSOCIATION_RETAIN_NONATOMIC);
                }
                UIColor *chipFill = isDark
                    ? [UIColor colorWithWhite:1.0 alpha:0.14]
                    : [UIColor colorWithWhite:0.0 alpha:0.065];
                if (![view.backgroundColor isEqual:chipFill]) {
                    view.backgroundColor = chipFill;
                }
            } else if ((isContainerClass || isWideNeutralBar || isFooterOrCancelBtn) &&
                       ![view isKindOfClass:UIImageView.class] && ![view isKindOfClass:UILabel.class]) {
                FQXAudioClearBackground(view, YES);
                if (view.layer.backgroundColor && CGColorGetAlpha(view.layer.backgroundColor) > 0.001) {
                    UIColor *lbg = [UIColor colorWithCGColor:view.layer.backgroundColor];
                    if (FQXColorIsNeutralSurface(lbg, view.traitCollection)) {
                        if (!objc_getAssociatedObject(view, FQXCommentSavedLayerBgKey)) {
                            objc_setAssociatedObject(view, FQXCommentSavedLayerBgKey, lbg, OBJC_ASSOCIATION_RETAIN_NONATOMIC);
                        }
                        view.layer.backgroundColor = NULL;
                    }
                }
            }
        }

        // Adapt neutral text ink while preserving orange/colored highlights and secondary hierarchy.
        UIColor *primaryInk = isDark
            ? [UIColor colorWithWhite:1.0 alpha:0.95]
            : [UIColor colorWithWhite:0.0 alpha:0.93];
        UIColor *secondaryInk = isDark
            ? [UIColor colorWithWhite:1.0 alpha:0.68]
            : [UIColor colorWithWhite:0.0 alpha:0.62];
        if ([view isKindOfClass:UILabel.class]) {
            UILabel *lbl = (UILabel *)view;
            if (lbl.text.length > 0 && lbl.textColor &&
                FQXColorIsNeutralSurface(lbl.textColor, lbl.traitCollection)) {
                UIColor *orig = objc_getAssociatedObject(lbl, FQXShareSavedTextColorKey);
                if (!orig) {
                    orig = lbl.textColor;
                    objc_setAssociatedObject(lbl, FQXShareSavedTextColorKey, orig, OBJC_ASSOCIATION_RETAIN_NONATOMIC);
                }
                CGFloat luma = 0.0;
                BOOL muted = FQXColorLuminance(orig, lbl.traitCollection, &luma) && luma > 0.38 && luma < 0.85;
                UIColor *desired = muted ? secondaryInk : primaryInk;
                if (![lbl.textColor isEqual:desired]) lbl.textColor = desired;
            }
        } else if ([view isKindOfClass:UIButton.class]) {
            UIButton *btn = (UIButton *)view;
            UIColor *curTitleCol = [btn titleColorForState:UIControlStateNormal];
            if ((btn.currentTitle.length > 0 || btn.currentAttributedTitle.length > 0) && curTitleCol &&
                FQXColorIsNeutralSurface(curTitleCol, btn.traitCollection)) {
                UIColor *orig = objc_getAssociatedObject(btn, FQXShareSavedBtnTitleColorKey);
                if (!orig) {
                    orig = curTitleCol;
                    objc_setAssociatedObject(btn, FQXShareSavedBtnTitleColorKey, orig, OBJC_ASSOCIATION_RETAIN_NONATOMIC);
                }
                CGFloat luma = 0.0;
                BOOL muted = FQXColorLuminance(orig, btn.traitCollection, &luma) && luma > 0.38 && luma < 0.85;
                UIColor *desired = muted ? secondaryInk : primaryInk;
                if (![curTitleCol isEqual:desired]) [btn setTitleColor:desired forState:UIControlStateNormal];
            }
        }
    } else {
        FQXSetShareSheetHostClipping(view, NO);
        FQXAudioSetHiddenTracked(view, NO);
        UIColor *savedGrabber = objc_getAssociatedObject(view, FQXShareSavedGrabberBgKey);
        if ([savedGrabber isKindOfClass:UIColor.class]) {
            view.backgroundColor = savedGrabber;
            objc_setAssociatedObject(view, FQXShareSavedGrabberBgKey, nil, OBJC_ASSOCIATION_RETAIN_NONATOMIC);
        }
        UIColor *savedChip = objc_getAssociatedObject(view, FQXAudioSheetSavedChipBgKey);
        if ([savedChip isKindOfClass:UIColor.class]) {
            view.backgroundColor = savedChip;
            objc_setAssociatedObject(view, FQXAudioSheetSavedChipBgKey, nil, OBJC_ASSOCIATION_RETAIN_NONATOMIC);
        }
        FQXAudioClearBackground(view, NO);
        UIColor *savedLayerBg = objc_getAssociatedObject(view, FQXCommentSavedLayerBgKey);
        if ([savedLayerBg isKindOfClass:UIColor.class]) {
            view.layer.backgroundColor = savedLayerBg.CGColor;
            objc_setAssociatedObject(view, FQXCommentSavedLayerBgKey, nil, OBJC_ASSOCIATION_RETAIN_NONATOMIC);
        }
        if ([view isKindOfClass:UILabel.class]) {
            UIColor *savedText = objc_getAssociatedObject(view, FQXShareSavedTextColorKey);
            if ([savedText isKindOfClass:UIColor.class]) {
                ((UILabel *)view).textColor = savedText;
                objc_setAssociatedObject(view, FQXShareSavedTextColorKey, nil, OBJC_ASSOCIATION_RETAIN_NONATOMIC);
            }
        } else if ([view isKindOfClass:UIButton.class]) {
            UIColor *savedBtn = objc_getAssociatedObject(view, FQXShareSavedBtnTitleColorKey);
            if ([savedBtn isKindOfClass:UIColor.class]) {
                [(UIButton *)view setTitleColor:savedBtn forState:UIControlStateNormal];
                objc_setAssociatedObject(view, FQXShareSavedBtnTitleColorKey, nil, OBJC_ASSOCIATION_RETAIN_NONATOMIC);
            }
        }
    }

    for (UIView *sub in view.subviews) {
        FQXApplyAudioSheetSubtreeCleanup(sub, rootSheet, clear, isDark, depth + 1);
    }
}

static void FQXRemoveAudioPlaySheetStyling(UIView *sheet) {
    if (!sheet) return;
    UIVisualEffectView *surface = objc_getAssociatedObject(sheet, FQXAudioSheetSurfaceKey);
    if (surface) {
        FQXReleaseCommentSurface(surface);
        objc_setAssociatedObject(sheet, FQXAudioSheetSurfaceKey, nil, OBJC_ASSOCIATION_RETAIN_NONATOMIC);
    }
    objc_setAssociatedObject(sheet, FQXAudioSheetStampKey, nil, OBJC_ASSOCIATION_RETAIN_NONATOMIC);
    if (sheet.overrideUserInterfaceStyle != UIUserInterfaceStyleUnspecified) {
        sheet.overrideUserInterfaceStyle = UIUserInterfaceStyleUnspecified;
    }
    FQXSetShareSheetHostClipping(sheet, NO);
    FQXSyncShareBackdropDimmer(sheet, NO);
    FQXApplyAudioSheetSubtreeCleanup(sheet, sheet, NO, NO, 0);
}

static BOOL FQXViewIsInsideOrContainsMainAudioPlayer(UIView *view, UIView *audioRootView);

static BOOL FQXStyleAudioPlaySheet(UIView *sheet, UIView *root) {
    if (![sheet isKindOfClass:UIView.class]) return NO;
    CGRect sb = sheet.bounds;
    if (CGRectGetWidth(sb) < 120.0 || CGRectGetHeight(sb) < 100.0) return NO;
    UIViewController *audioVC = sheet.window ? FQXFindVisibleAudioPlayVCInWindow(sheet.window) : nil;
    UIView *audioRootView = (audioVC && audioVC.isViewLoaded) ? audioVC.view : nil;
    if (FQXViewIsInsideOrContainsMainAudioPlayer(sheet, audioRootView)) {
        return NO;
    }
    if (objc_getAssociatedObject(sheet, FQXShareMarkedSheetKey) ||
        objc_getAssociatedObject(sheet, SheetGlassKey)) {
        return NO;
    }

    [FQXTrackedAudioPlaySheets() addObject:sheet];
    objc_setAssociatedObject(sheet, FQXAudioSheetMarkedKey, @YES, OBJC_ASSOCIATION_RETAIN_NONATOMIC);
    if (root && root != sheet) {
        FQXSetWeakAssocView(sheet, FQXAudioSheetRootKey, root);
    }

    if (FQXHotPrefsSnapshot().glassDisabled) {
        FQXRemoveAudioPlaySheetStyling(sheet);
        return NO;
    }

    FQXShareMaterialStyle style = FQXCurrentAudioSheetMaterialStyle();
    if (style == FQXShareMaterialNative) {
        FQXRemoveAudioPlaySheetStyling(sheet);
        return NO;
    }

    BOOL isDark = FQXAppIsInNightMode();
    CGFloat hostCornerR = FQXReadHostSheetCornerRadius(sheet, root);
    CGFloat cornerR = (hostCornerR >= 10.0 && hostCornerR <= 24.0) ? hostCornerR : 18.0;
    BOOL reduceTrans = UIAccessibilityIsReduceTransparencyEnabled();
    BOOL darkTint = FQXGlassDarkTintEnabled();
    NSInteger blurPct = reduceTrans ? 0 : FQXCurrentAudioSheetBlurPercent();
    FQXSyncShareBackdropDimmer(sheet, YES);

    FQXShareMaterialStyle effStyle = style;
    if ((effStyle == FQXShareMaterialClearGlass || effStyle == FQXShareMaterialRegularGlass) && !FQXGlassEnabled()) {
        effStyle = FQXShareMaterialGaussianBlur;
    }

    BOOL wantsGaussian = (effStyle == FQXShareMaterialGaussianBlur);
    NSInteger minimumBlur = wantsGaussian ? 35 : 0;
    NSInteger effectiveBlur = reduceTrans ? (wantsGaussian ? 100 : 0) : FQXSheetBlurPercent((int)blurPct, (int)minimumBlur);
    CGFloat maxGlassTint = (effStyle == FQXShareMaterialRegularGlass)
        ? (isDark ? 0.34 : 0.30)
        : (isDark ? 0.36 : 0.34);

    UIVisualEffectView *surface = objc_getAssociatedObject(sheet, FQXAudioSheetSurfaceKey);
    BOOL isBlurView = [surface isKindOfClass:FQXBackdropBlurView.class];
    BOOL isGlassView = [surface isKindOfClass:FQXCommentGlassSurfaceView.class];
    if (surface && ((wantsGaussian && !isBlurView) || (!wantsGaussian && !isGlassView))) {
        FQXReleaseCommentSurface(surface);
        objc_setAssociatedObject(sheet, FQXAudioSheetSurfaceKey, nil, OBJC_ASSOCIATION_RETAIN_NONATOMIC);
        surface = nil;
    }
    if (!surface) {
        if (wantsGaussian) {
            surface = FQXNewSheetBlur();
        } else {
            FQXCommentGlassSurfaceView *gv = [[FQXCommentGlassSurfaceView alloc] initWithEffect:nil];
            gv->_flexSourceView = sheet;
            gv->_isBarGlass = NO;
            surface = gv;
        }
        surface.userInteractionEnabled = NO;
        surface.accessibilityElementsHidden = YES;
        surface.isAccessibilityElement = NO;
        surface.alpha = 1.0;
        surface.autoresizingMask = UIViewAutoresizingFlexibleWidth | UIViewAutoresizingFlexibleHeight;
        objc_setAssociatedObject(sheet, FQXAudioSheetSurfaceKey, surface, OBJC_ASSOCIATION_RETAIN_NONATOMIC);
    }

    UIUserInterfaceStyle surfaceUIStyle = (effStyle == FQXShareMaterialClearGlass)
        ? UIUserInterfaceStyleUnspecified
        : (isDark ? UIUserInterfaceStyleDark : UIUserInterfaceStyleLight);
    UIUserInterfaceStyle hostUIStyle = isDark
        ? UIUserInterfaceStyleDark
        : ((effStyle == FQXShareMaterialClearGlass) ? UIUserInterfaceStyleUnspecified : UIUserInterfaceStyleLight);

    [CATransaction begin];
    [CATransaction setDisableActions:YES];
    FQXSetShareSheetHostClipping(sheet, YES);
    if (sheet.overrideUserInterfaceStyle != hostUIStyle) sheet.overrideUserInterfaceStyle = hostUIStyle;
    if (surface.overrideUserInterfaceStyle != surfaceUIStyle) surface.overrideUserInterfaceStyle = surfaceUIStyle;
    FQXSyncSheetBlur(sheet, surface, wantsGaussian, effectiveBlur, isDark, maxGlassTint, cornerR);
    FQXApplyAudioSheetSubtreeCleanup(sheet, sheet, YES, isDark, 0);
    [CATransaction commit];

    if (!wantsGaussian) {
        FQXCommentGlassSurfaceView *gv = (FQXCommentGlassSurfaceView *)surface;
        gv->_flexSourceView = sheet;
        NSInteger desiredStamp = ((NSInteger)effStyle * 100) + (isDark ? 10 : 0) + (darkTint ? 2 : 0) + (reduceTrans ? 1 : 0);
        NSNumber *appliedStamp = objc_getAssociatedObject(gv, FQXAudioSheetStampKey);
        if (!gv.effect || !appliedStamp || appliedStamp.integerValue != desiredStamp) {
            NSInteger glassStyle = (reduceTrans || effStyle == FQXShareMaterialRegularGlass) ? 0 : 1;
            UIColor *tint = (!reduceTrans && effStyle == FQXShareMaterialClearGlass && darkTint && isDark)
                ? [UIColor colorWithWhite:0.0 alpha:0.30] : nil;
            UIVisualEffect *glassEffect = FQXMakeGlassEffect(glassStyle, YES, tint);
            [UIView performWithoutAnimation:^{
                gv.overrideUserInterfaceStyle = surfaceUIStyle;
                gv.effect = glassEffect;
            }];
            objc_setAssociatedObject(gv, FQXAudioSheetStampKey, @(desiredStamp), OBJC_ASSOCIATION_RETAIN_NONATOMIC);
        }
    }

    if (FQXDiagnosticsHubIsEnabled()) {
        NSString *diagSig = [NSString stringWithFormat:@"%ld|%d|%ld|%.0f",
                             (long)effStyle, isDark ? 1 : 0, (long)blurPct, CGRectGetHeight(sb)];
        if (![diagSig isEqualToString:objc_getAssociatedObject(sheet, FQXAudioSheetDiagKey)]) {
            objc_setAssociatedObject(sheet, FQXAudioSheetDiagKey, diagSig, OBJC_ASSOCIATION_COPY_NONATOMIC);
            FQXDiagRecordEvent(FQXDiagCategoryUI, @"audio_sheet_styled", @{
                @"sheetClass": NSStringFromClass(sheet.class) ?: @"",
                @"rootClass": root ? (NSStringFromClass(root.class) ?: @"") : @"",
                @"materialStyle": @((NSInteger)effStyle),
                @"blurPercent": @(blurPct),
                @"effectiveBlurPercent": @(effectiveBlur),
                @"isDark": @(isDark),
                @"surfaceEffectClass": surface.effect ? (NSStringFromClass(surface.effect.class) ?: @"") : @"nil",
                @"sheetFrame": FQXDockRectArray(sb),
            }, NO);
        }
    }
    return YES;
}

static void FQXRefreshAllAudioPlaySheets(void) {
    if (!NSThread.isMainThread) {
        dispatch_async(dispatch_get_main_queue(), ^{ FQXRefreshAllAudioPlaySheets(); });
        return;
    }
    for (UIView *sheet in FQXTrackedAudioPlaySheets().allObjects) {
        if (!sheet.superview) continue;
        UIView *root = FQXGetWeakAssocView(sheet, FQXAudioSheetRootKey) ?: sheet.superview;
        FQXStyleAudioPlaySheet(sheet, root);
    }
}

static BOOL FQXViewMatchesAudioSheetMarkers(UIView *root,
                                            NSMutableSet<NSString *> *secondaryHits,
                                            BOOL *vetoed,
                                            NSInteger *budget,
                                            NSInteger depth) {
    if (!root || root.hidden || root.alpha <= 0.01 || depth > 16 || *budget <= 0 || (vetoed && *vetoed)) return NO;
    (*budget)--;
    NSString *text = nil;
    if ([root isKindOfClass:UILabel.class]) {
        UILabel *lbl = (UILabel *)root;
        text = lbl.text.length ? lbl.text : lbl.attributedText.string;
    } else if ([root isKindOfClass:UIButton.class]) {
        UIButton *btn = (UIButton *)root;
        text = btn.currentTitle.length ? btn.currentTitle : btn.currentAttributedTitle.string;
    }
    if (!text.length && root.accessibilityLabel.length > 0 && root.accessibilityLabel.length <= 24) {
        text = root.accessibilityLabel;
    }
    if (text.length > 0 && text.length <= 36) {
        NSString *trimmed = [text stringByTrimmingCharactersInSet:NSCharacterSet.whitespaceAndNewlineCharacterSet];
        // Hard veto: "边听边读" belongs exclusively to the main audiobook player body, never to secondary sheets.
        if ([trimmed isEqualToString:@"边听边读"]) {
            if (vetoed) *vetoed = YES;
            return NO;
        }
        // Strong single-hit markers unique to the 7 audiobook secondary half-sheets:
        // 1. 章评  2. 选择章节  3. 已加书架  4. 语速  5. 定时关闭  6. 简介/播放目录  7. 音色设置
        // Note: "音色设置" and "真人讲书" also appear on the main player screen, so they are intentionally
        // excluded from single-hit markers and require unique sheet markers or 2+ secondary hits.
        if ([trimmed isEqualToString:@"全部章评"] ||
            [trimmed hasPrefix:@"发表本章看法"] ||
            [trimmed isEqualToString:@"期待你的第一条评论"] ||
            [trimmed isEqualToString:@"选择章节"] ||
            [trimmed isEqualToString:@"我的下载"] ||
            [trimmed hasPrefix:@"当前下载音色"] ||
            [trimmed isEqualToString:@"已加书架"] ||
            [trimmed isEqualToString:@"移动到分组"] ||
            [trimmed isEqualToString:@"移出书架"] ||
            [trimmed isEqualToString:@"仅对本书生效"] ||
            [trimmed hasPrefix:@"语速·"] ||
            [trimmed hasPrefix:@"语速 ·"] ||
            [trimmed isEqualToString:@"定时关闭"] ||
            [trimmed isEqualToString:@"播完本章"] ||
            [trimmed isEqualToString:@"播完3章"] ||
            [trimmed isEqualToString:@"播完5章"] ||
            [trimmed hasPrefix:@"自定义时长"] ||
            [trimmed isEqualToString:@"播放目录"] ||
            [trimmed isEqualToString:@"顺序播放"] ||
            [trimmed isEqualToString:@"离线朗读"] ||
            [trimmed isEqualToString:@"甜美少女音"] ||
            [trimmed isEqualToString:@"开朗青年音"] ||
            [trimmed isEqualToString:@"清亮青叔音"] ||
            [trimmed isEqualToString:@"温柔淑女音"] ||
            [trimmed isEqualToString:@"成熟大叔离线版"] ||
            [trimmed isEqualToString:@"甜美少女离线版"] ||
            [trimmed hasPrefix:@"主播："] ||
            [trimmed hasPrefix:@"主播:"]) {
            return YES;
        }
        static NSSet<NSString *> *secMarkers = nil;
        static dispatch_once_t secOnce;
        dispatch_once(&secOnce, ^{
            secMarkers = [NSSet setWithArray:@[
                @"章评", @"最热", @"最新", @"全选", @"语速", @"重置",
                @"按章节", @"按时间", @"10分钟", @"30分钟", @"60分钟", @"90分钟",
                @"播完整章", @"简介", @"倒序", @"取消",
                @"音色设置", @"真人讲书", @"智能朗读", @"超自然", @"自然流畅"
            ]];
        });
        if ([secMarkers containsObject:trimmed]) {
            [secondaryHits addObject:trimmed];
            if (secondaryHits.count >= 2) return YES;
        }
    }
    for (UIView *sub in root.subviews) {
        if (FQXViewMatchesAudioSheetMarkers(sub, secondaryHits, vetoed, budget, depth + 1)) {
            return (vetoed && *vetoed) ? NO : YES;
        }
        if (vetoed && *vetoed) return NO;
    }
    return NO;
}

static BOOL FQXIsCoreAudioPlayerOwnView(UIView *view, UIView *audioRootView) {
    if (!view) return YES;
    if (audioRootView && (view == audioRootView || [audioRootView isDescendantOfView:view])) return YES;
    NSString *cls = NSStringFromClass(view.class) ?: @"";
    return [cls hasPrefix:@"SSNewAudioPlay"] ||
           [cls hasPrefix:@"SSAudioPlayTTS"] ||
           [cls hasPrefix:@"SSAudioPlayTone"] ||
           [cls hasPrefix:@"SSAudioReadingGuide"] ||
           [cls hasPrefix:@"SSAudioV4ReadingGuide"] ||
           [cls isEqualToString:@"FQRJXCategoryListContainerView"] ||
           [cls hasPrefix:@"JXCategory"] ||
           [cls isEqualToString:@"SSNestedContainerScrollView"] ||
           [cls isEqualToString:@"SSAudioPageBackView"] ||
           [cls isEqualToString:@"SSReadingSharePanel"];
}

static BOOL FQXIsAudioSheetDisallowedCardClass(UIView *view) {
    if (!view) return YES;
    if ([view isKindOfClass:UIScrollView.class]) return YES;
    NSString *cls = NSStringFromClass(view.class) ?: @"";
    return [cls isEqualToString:@"FQRJXCategoryListContainerView"] ||
           [cls hasPrefix:@"JXCategory"] ||
           [cls isEqualToString:@"SSNestedContainerScrollView"] ||
           [cls isEqualToString:@"UILayoutContainerView"] ||
           [cls isEqualToString:@"UINavigationTransitionView"] ||
           [cls isEqualToString:@"UIViewControllerWrapperView"] ||
           [cls isEqualToString:@"UITransitionView"] ||
           [cls isEqualToString:@"UIDropShadowView"] ||
           [cls isEqualToString:@"UINavigationBar"];
}

static BOOL FQXSubtreeContainsMainAudioPlayer(UIView *view, UIView *audioRootView, NSInteger *budget, NSInteger depth) {
    if (!view || depth > 10 || *budget <= 0) return NO;
    (*budget)--;
    if (audioRootView && view == audioRootView) return YES;
    NSString *cls = NSStringFromClass(view.class) ?: @"";
    if ([cls isEqualToString:@"FQRJXCategoryListContainerView"] ||
        [cls isEqualToString:@"SSNestedContainerScrollView"] ||
        [cls hasPrefix:@"SSNewAudioPlay"] ||
        [cls hasPrefix:@"SSAudioPlayTTS"] ||
        [cls hasPrefix:@"SSAudioPlayTone"] ||
        [cls hasPrefix:@"SSAudioReadingGuide"] ||
        [cls hasPrefix:@"SSAudioV4ReadingGuide"]) {
        return YES;
    }
    if ([view isKindOfClass:UILabel.class] && !view.hidden && view.alpha > 0.01) {
        UILabel *lbl = (UILabel *)view;
        NSString *t = lbl.text.length ? lbl.text : lbl.attributedText.string;
        if (t.length > 0 && t.length <= 16) {
            NSString *trimmed = [t stringByTrimmingCharactersInSet:NSCharacterSet.whitespaceAndNewlineCharacterSet];
            if ([trimmed isEqualToString:@"边听边读"]) return YES;
        }
    }
    for (UIView *sub in view.subviews) {
        if (FQXSubtreeContainsMainAudioPlayer(sub, audioRootView, budget, depth + 1)) return YES;
    }
    return NO;
}

static BOOL FQXViewIsInsideOrContainsMainAudioPlayer(UIView *view, UIView *audioRootView) {
    if (!view) return YES;
    int isScroll = [view isKindOfClass:UIScrollView.class] ? 1 : 0;
    NSString *cls = NSStringFromClass(view.class) ?: @"";
    int isCat = ([cls isEqualToString:@"FQRJXCategoryListContainerView"] ||
                 [cls hasPrefix:@"JXCategory"] ||
                 [cls isEqualToString:@"SSNestedContainerScrollView"]) ? 1 : 0;
    if (FQXAudioSheetCandidateIsMainPlayer(isScroll, isCat, 0)) return YES;
    if (audioRootView && (view == audioRootView || [audioRootView isDescendantOfView:view])) return YES;

    // Walk up ancestors: reject anything inside the main player's category/scroll/TTS hierarchy.
    // Note: an overlay sheet directly added as a sibling subview on audioRootView is allowed.
    for (UIView *anc = view.superview; anc && anc != audioRootView; anc = anc.superview) {
        NSString *acls = NSStringFromClass(anc.class) ?: @"";
        if ([acls isEqualToString:@"FQRJXCategoryListContainerView"] ||
            [acls isEqualToString:@"SSNestedContainerScrollView"] ||
            [acls hasPrefix:@"SSNewAudioPlay"] ||
            [acls hasPrefix:@"SSAudioPlayTTS"] ||
            [acls hasPrefix:@"SSAudioPlayTone"] ||
            [acls hasPrefix:@"SSAudioReadingGuide"] ||
            [acls hasPrefix:@"SSAudioV4ReadingGuide"]) {
            return YES;
        }
    }

    // Walk down descendants: reject any container wrapping the main player body or "边听边读".
    NSInteger budget = 240;
    int containsMain = FQXSubtreeContainsMainAudioPlayer(view, audioRootView, &budget, 0) ? 1 : 0;
    return FQXAudioSheetCandidateIsMainPlayer(0, 0, containsMain) != 0;
}

static UIView *FQXFindAudioSheetCardInRoot(UIView *root, UIWindow *window, UIView *audioRootView) {
    if (!root || !window) return nil;
    CGFloat winW = CGRectGetWidth(window.bounds);
    CGFloat winH = CGRectGetHeight(window.bounds);
    if (winW < 200.0 || winH < 300.0) return nil;

    NSMutableArray<UIView *> *queue = [NSMutableArray arrayWithObject:root];
    NSInteger inspected = 0;
    while (queue.count > 0 && inspected < 360) {
        UIView *cur = queue.firstObject;
        [queue removeObjectAtIndex:0];
        if (!cur || cur.hidden || cur.alpha <= 0.01) continue;
        if ([cur isKindOfClass:UIScrollView.class]) continue;
        if (FQXIsCoreAudioPlayerOwnView(cur, audioRootView)) {
            if (cur == audioRootView) {
                for (UIView *sub in cur.subviews) {
                    if (!sub.hidden && sub.alpha > 0.01 && !FQXIsCoreAudioPlayerOwnView(sub, audioRootView)) {
                        [queue addObject:sub];
                    }
                }
            }
            continue;
        }
        inspected++;
        if (!FQXIsAudioSheetDisallowedCardClass(cur)) {
            CGRect inWin = [cur convertRect:cur.bounds toView:window];
            if (FQXAudioSheetCardGeometryValid(CGRectGetMinY(inWin), CGRectGetMaxY(inWin),
                                               CGRectGetWidth(inWin), CGRectGetHeight(inWin),
                                               winW, winH) &&
                !FQXViewIsInsideOrContainsMainAudioPlayer(cur, audioRootView)) {
                NSMutableSet<NSString *> *sec = [NSMutableSet set];
                BOOL vetoed = NO;
                NSInteger budget = 360;
                if (FQXViewMatchesAudioSheetMarkers(cur, sec, &vetoed, &budget, 0) && !vetoed) {
                    return cur;
                }
            }
        }
        for (UIView *sub in cur.subviews) {
            if (!sub.hidden && sub.alpha > 0.01) [queue addObject:sub];
        }
    }
    return nil;
}

static void FQXInspectCandidateAudioSheetContainer(UIView *root) {
    if (!root || !root.window || root.hidden || root.alpha <= 0.01) return;
    UIWindow *win = root.window;
    UIViewController *audioVC = FQXFindVisibleAudioPlayVCInWindow(win);
    if (!audioVC) return;
    NSString *clsName = NSStringFromClass(root.class) ?: @"";
    if (FQXShouldSkipShareCandidateClass(clsName)) return;
    if (objc_getAssociatedObject(root, FQXShareMarkedSheetKey) ||
        objc_getAssociatedObject(root, SheetGlassKey)) return;

    UIView *audioRootView = audioVC.isViewLoaded ? audioVC.view : nil;
    if (FQXIsCoreAudioPlayerOwnView(root, audioRootView) && root != audioRootView) return;
    UIView *card = FQXFindAudioSheetCardInRoot(root, win, audioRootView);
    if (!card) return;
    if (FQXViewIsInsideOrContainsMainAudioPlayer(card, audioRootView)) return;
    if (objc_getAssociatedObject(card, FQXShareMarkedSheetKey) ||
        objc_getAssociatedObject(card, SheetGlassKey)) return;

    FQXEnsureAudioSheetClassHooked(card, card);
    if (root != card && root != audioRootView && !FQXIsAudioSheetDisallowedCardClass(root)) {
        FQXEnsureAudioSheetClassHooked(root, card);
    }
    UIView *innerCustom = FQXFindFirstCustomViewInside(card, 0);
    if (innerCustom && innerCustom != card && innerCustom != root && innerCustom != audioRootView &&
        !FQXIsAudioSheetDisallowedCardClass(innerCustom)) {
        FQXEnsureAudioSheetClassHooked(innerCustom, card);
    }
    FQXStyleAudioPlaySheet(card, root);
}

static UIView *FQXEnclosingModalSheetRootForView(UIView *view);

static void FQXInspectPresentedChainForAudioSheets(UIViewController *start) {
    NSInteger guard = 0;
    for (UIViewController *cur = start; cur && guard < 8; cur = cur.presentedViewController, ++guard) {
        if (cur.isViewLoaded && cur.view.window) {
            UIView *modalRoot = FQXEnclosingModalSheetRootForView(cur.view);
            FQXInspectCandidateAudioSheetContainer(modalRoot ?: cur.view);
        }
    }
}

static void FQXScanWindowForAudioPlaySheets(UIWindow *window) {
    if (!window) return;
    UIViewController *audioVC = FQXFindVisibleAudioPlayVCInWindow(window);
    if (!audioVC) return;
    UIView *audioRootView = audioVC.isViewLoaded ? audioVC.view : nil;

    // 1. Scan all visible windows in connected scenes (covers both key window & dedicated overlay windows).
    for (UIScene *scene in UIApplication.sharedApplication.connectedScenes) {
        if (![scene isKindOfClass:UIWindowScene.class]) continue;
        for (UIWindow *win in ((UIWindowScene *)scene).windows) {
            if (win.hidden || win.alpha <= 0.01) continue;
            NSString *wcls = NSStringFromClass(win.class) ?: @"";
            if ([wcls containsString:@"Keyboard"] || [wcls containsString:@"Effects"]) continue;
            for (UIView *sub in win.subviews.reverseObjectEnumerator) {
                if (sub.hidden || sub.alpha <= 0.01) continue;
                FQXInspectCandidateAudioSheetContainer(sub);
            }
            if (win.rootViewController.presentedViewController) {
                FQXInspectPresentedChainForAudioSheets(win.rootViewController.presentedViewController);
            }
        }
    }

    // 2. Scan navigation controller overlay subviews (skipping main transition container & nav bar).
    if (audioVC.navigationController.isViewLoaded && audioVC.navigationController.view) {
        for (UIView *sub in audioVC.navigationController.view.subviews.reverseObjectEnumerator) {
            if (sub.hidden || sub.alpha <= 0.01) continue;
            NSString *sc = NSStringFromClass(sub.class) ?: @"";
            if ([sc isEqualToString:@"UINavigationTransitionView"] ||
                [sc isEqualToString:@"UINavigationBar"]) continue;
            FQXInspectCandidateAudioSheetContainer(sub);
        }
    }

    // 3. Scan sibling overlay subviews & child VCs on audioVC (strictly skipping main player body).
    if (audioRootView) {
        for (UIView *sub in audioRootView.subviews.reverseObjectEnumerator) {
            if (sub.hidden || sub.alpha <= 0.01) continue;
            if (FQXIsCoreAudioPlayerOwnView(sub, audioRootView)) continue;
            FQXInspectCandidateAudioSheetContainer(sub);
        }
    }
    for (UIViewController *child in audioVC.childViewControllers) {
        if (child.isViewLoaded && child.view.window &&
            !FQXViewIsInsideOrContainsMainAudioPlayer(child.view, audioRootView)) {
            FQXInspectCandidateAudioSheetContainer(child.view);
        }
    }
    FQXInspectPresentedChainForAudioSheets(audioVC.presentedViewController);
    FQXInspectPresentedChainForAudioSheets(audioVC.navigationController.presentedViewController);
}

static void FQXScheduleAudioSheetScanInWindow(UIWindow *window) {
    if (!window) return;
    __weak UIWindow *weakWin = window;
    static const double delays[] = {0.06, 0.22, 0.50};
    for (size_t i = 0; i < sizeof(delays) / sizeof(delays[0]); ++i) {
        double d = delays[i];
        dispatch_after(dispatch_time(DISPATCH_TIME_NOW, (int64_t)(d * NSEC_PER_SEC)), dispatch_get_main_queue(), ^{
            UIWindow *w = weakWin;
            if (w && !w.hidden) FQXScanWindowForAudioPlaySheets(w);
        });
    }
}

@interface FQXAudioTouchObserverGesture : UIGestureRecognizer
@end

@implementation FQXAudioTouchObserverGesture
- (instancetype)init {
    self = [super initWithTarget:nil action:NULL];
    if (self) {
        self.cancelsTouchesInView = NO;
        self.delaysTouchesBegan = NO;
        self.delaysTouchesEnded = NO;
    }
    return self;
}
- (void)touchesEnded:(NSSet<UITouch *> *)touches withEvent:(UIEvent *)event {
    [super touchesEnded:touches withEvent:event];
    if (self.view.window) {
        FQXScheduleAudioSheetScanInWindow(self.view.window);
    }
    self.state = UIGestureRecognizerStateFailed;
}
- (void)touchesCancelled:(NSSet<UITouch *> *)touches withEvent:(UIEvent *)event {
    [super touchesCancelled:touches withEvent:event];
    if (self.view.window) {
        FQXScheduleAudioSheetScanInWindow(self.view.window);
    }
    self.state = UIGestureRecognizerStateFailed;
}
- (BOOL)canPreventGestureRecognizer:(UIGestureRecognizer *)preventedGestureRecognizer {
    (void)preventedGestureRecognizer;
    return NO;
}
- (BOOL)canBePreventedByGestureRecognizer:(UIGestureRecognizer *)preventingGestureRecognizer {
    (void)preventingGestureRecognizer;
    return NO;
}
@end

static void FQXEnsureAudioSheetTouchObserverOnVC(UIViewController *vc) {
    if (![vc isKindOfClass:UIViewController.class] || !vc.isViewLoaded || !vc.view) return;
    FQXAudioTouchObserverGesture *obs = objc_getAssociatedObject(vc.view, FQXAudioTouchObserverKey);
    if (!obs || obs.view != vc.view) {
        obs = [[FQXAudioTouchObserverGesture alloc] init];
        [vc.view addGestureRecognizer:obs];
        objc_setAssociatedObject(vc.view, FQXAudioTouchObserverKey, obs, OBJC_ASSOCIATION_RETAIN_NONATOMIC);
    }
}

static void FQXScheduleCandidateShareInspection(UIView *candidate) {
    if (!candidate) return;
    NSString *clsName = NSStringFromClass(candidate.class) ?: @"";
    if (FQXShouldSkipShareCandidateClass(clsName) || [candidate isKindOfClass:UIVisualEffectView.class]) {
        return;
    }
    __weak UIView *weakView = candidate;
    static const double delays[] = {0.0, 0.14, 0.38, 0.72};
    for (size_t i = 0; i < sizeof(delays) / sizeof(delays[0]); ++i) {
        double d = delays[i];
        void (^task)(void) = ^{
            UIView *v = weakView;
            if (!v || !v.window) return;
            FQXInspectCandidateShareContainer(v);
            FQXInspectCandidateAudioSheetContainer(v);
        };
        if (d <= 0.0) {
            dispatch_async(dispatch_get_main_queue(), task);
        } else {
            dispatch_after(dispatch_time(DISPATCH_TIME_NOW, (int64_t)(d * NSEC_PER_SEC)), dispatch_get_main_queue(), task);
        }
    }
}

static UIView *FQXEnclosingModalSheetRootForView(UIView *view) {
    if (!view || !view.window) return view;
    UIView *best = view;
    for (UIView *cur = view.superview; cur && cur != view.window; cur = cur.superview) {
        NSString *cname = NSStringFromClass(cur.class) ?: @"";
        if ([cname containsString:@"Transition"] || [cname containsString:@"DropShadow"] ||
            [cname containsString:@"Sheet"] || [cname containsString:@"Share"] ||
            [cname containsString:@"Modal"] || [cname containsString:@"Pop"] ||
            [cname containsString:@"LayoutContainer"]) {
            best = cur;
        }
    }
    return best;
}

static void (*OrigWindowAddSubviewForShare)(id, SEL, id);
static void HookWindowAddSubviewForShare(UIWindow *window, SEL cmd, UIView *subview) {
    if (OrigWindowAddSubviewForShare) OrigWindowAddSubviewForShare(window, cmd, subview);
    if (!window || !subview) return;
    NSString *winName = NSStringFromClass(window.class) ?: @"";
    if ([winName containsString:@"Keyboard"] || [winName containsString:@"Effects"]) return;
    FQXScheduleCandidateShareInspection(subview);
}

static void (*OrigWindowMakeKeyForShare)(id, SEL);
static void HookWindowMakeKeyForShare(UIWindow *window, SEL cmd) {
    if (OrigWindowMakeKeyForShare) OrigWindowMakeKeyForShare(window, cmd);
    if (!window) return;
    NSString *winName = NSStringFromClass(window.class) ?: @"";
    if ([winName containsString:@"Keyboard"] || [winName containsString:@"Effects"]) return;
    if (window.rootViewController.viewIfLoaded) {
        FQXScheduleCandidateShareInspection(window.rootViewController.viewIfLoaded);
    }
    for (UIView *sub in window.subviews) {
        FQXScheduleCandidateShareInspection(sub);
    }
}

static void (*OrigVCPresentForShare)(id, SEL, id, BOOL, id);
static void HookVCPresentForShare(UIViewController *self, SEL cmd, UIViewController *vc, BOOL animated, void (^completion)(void)) {
    if (OrigVCPresentForShare) OrigVCPresentForShare(self, cmd, vc, animated, completion);
    if (!vc || [vc isKindOfClass:UIAlertController.class] ||
        [vc isKindOfClass:UIActivityViewController.class] ||
        [vc isKindOfClass:UISearchController.class]) {
        return;
    }
    NSString *vcName = NSStringFromClass(vc.class) ?: @"";
    if ([vcName hasPrefix:@"FQX"] || [vcName hasPrefix:@"FanqieX"]) return;
    __weak UIViewController *weakVC = vc;
    static const double delays[] = {0.0, 0.14, 0.38, 0.72};
    for (size_t i = 0; i < sizeof(delays) / sizeof(delays[0]); ++i) {
        double d = delays[i];
        void (^task)(void) = ^{
            UIViewController *s = weakVC;
            if (!s || !s.isViewLoaded || !s.view.window) return;
            UIView *modalRoot = FQXEnclosingModalSheetRootForView(s.view);
            FQXInspectCandidateShareContainer(modalRoot ?: s.view);
            FQXInspectCandidateAudioSheetContainer(modalRoot ?: s.view);
        };
        if (d <= 0.0) {
            dispatch_async(dispatch_get_main_queue(), task);
        } else {
            dispatch_after(dispatch_time(DISPATCH_TIME_NOW, (int64_t)(d * NSEC_PER_SEC)), dispatch_get_main_queue(), task);
        }
    }
}

static void (*OrigVCViewDidAppearForShare)(id, SEL, BOOL);
static void HookVCViewDidAppearForShare(UIViewController *self, SEL cmd, BOOL animated) {
    if (OrigVCViewDidAppearForShare) OrigVCViewDidAppearForShare(self, cmd, animated);
    if (!self || !self.isViewLoaded || !self.view.window) return;
    if ([self isKindOfClass:UINavigationController.class] ||
        [self isKindOfClass:UITabBarController.class] ||
        [self isKindOfClass:UIAlertController.class] ||
        [self isKindOfClass:UISearchController.class]) {
        return;
    }
    NSString *vcName = NSStringFromClass(self.class) ?: @"";
    if ([vcName hasPrefix:@"FQX"] || [vcName hasPrefix:@"FanqieX"] ||
        [vcName hasPrefix:@"BDReader"] || [vcName hasPrefix:@"SSBookShelf"] ||
        [vcName hasPrefix:@"SSBookStore"] || [vcName hasPrefix:@"SSVideoSeriesFeed"] ||
        [vcName hasPrefix:@"FQVShortVideoList"] || [vcName hasPrefix:@"SSNewAudioPlay"]) {
        return;
    }
    UIWindow *win = self.view.window;
    CGFloat winH = CGRectGetHeight(win.bounds);
    BOOL inAudioPlayer = (FQXFindVisibleAudioPlayVCInWindow(win) != nil);
    BOOL isModalOrSheet = (self.presentingViewController != nil) ||
                          (self.navigationController.presentingViewController != nil) ||
                          (winH > 300.0 && CGRectGetHeight(self.view.bounds) <= winH * 0.94) ||
                          inAudioPlayer ||
                          [vcName containsString:@"Share"] ||
                          [vcName containsString:@"Sheet"];
    if (!isModalOrSheet) return;
    UIView *modalRoot = FQXEnclosingModalSheetRootForView(self.navigationController.viewIfLoaded ?: self.view);
    FQXScheduleCandidateShareInspection(modalRoot ?: self.view);
}

static void (*OrigNavPushForShare)(id, SEL, id, BOOL);
static void HookNavPushForShare(UINavigationController *nav, SEL cmd, UIViewController *vc, BOOL animated) {
    if (OrigNavPushForShare) OrigNavPushForShare(nav, cmd, vc, animated);
    if (!nav || !vc) return;
    NSString *vcName = NSStringFromClass(vc.class) ?: @"";
    if ([vcName hasPrefix:@"FQX"] || [vcName hasPrefix:@"FanqieX"]) return;
    __weak UINavigationController *weakNav = nav;
    __weak UIViewController *weakVC = vc;
    dispatch_async(dispatch_get_main_queue(), ^{
        UINavigationController *sNav = weakNav;
        UIViewController *sVC = weakVC;
        if (!sNav || !sNav.isViewLoaded || !sNav.view.window) return;
        CGFloat winH = CGRectGetHeight(sNav.view.window.bounds);
        BOOL isModalOrSheet = (sNav.presentingViewController != nil) ||
                              (winH > 300.0 && CGRectGetHeight(sNav.view.bounds) <= winH * 0.82) ||
                              [vcName containsString:@"Share"] ||
                              [vcName containsString:@"Sheet"];
        if (!isModalOrSheet) return;
        UIView *modalRoot = FQXEnclosingModalSheetRootForView(sNav.view);
        FQXScheduleCandidateShareInspection(modalRoot ?: (sVC.viewIfLoaded ?: sNav.view));
    });
}

