static void (*OrigKMPShareLayout)(id, SEL);
static void HookKMPShareLayout(UIViewController *controller, SEL cmd) {
    OrigKMPShareLayout(controller, cmd);
    UIViewController *content = FQXObjGet(controller, "contentViewController");
    UIView *sheet = content.viewIfLoaded;
    UIView *root = controller.viewIfLoaded;
    if (!sheet || ![sheet isDescendantOfView:root]) return;
    // The wrapper can include a full-screen dismissal area. Use its actual
    // content frame in that arrangement, so the material starts at the sheet.
    BOOL fillsWrapper = fabs(CGRectGetHeight(root.bounds) - CGRectGetHeight(sheet.bounds)) < 2.0;
    UIView *previous = fillsWrapper ? sheet : root;
    if (objc_getAssociatedObject(previous, SheetGlassKey) ||
        objc_getAssociatedObject(previous, FQXShareGlassSurfaceKey)) {
        FQXRemoveShareSheetStyling(previous);
    }
    UIView *target = fillsWrapper ? root : sheet;
    BOOL styled = FQXStyleShareSheet(target, root, FQXFindVisibleReaderVCInWindow(root.window) == nil);
    if (fillsWrapper) FQXAudioClearBackground(sheet, styled);
}

static NSString *const DramaPlaybackOptionsMaterialPrefKey = @"FanqieX.DramaPlaybackOptionsMaterial.1";
static NSString *const DramaPlaybackOptionsBlurPrefKey = @"FanqieX.DramaPlaybackOptionsBlur.1";
static const CGFloat DramaPlaybackOptionsGroupAlpha = 0.48;
static const char DramaPlaybackOptionsSurfaceKey;
static const char DramaPlaybackOptionsMaterialStampKey;
static const char DramaPlaybackOptionsSavedColorKey;
static const char DramaPlaybackOptionsSavedEffectKey;
static const char DramaPlaybackOptionsReadabilityKey;
static const char DramaPlaybackOptionsCoveredControlsKey;
static const char DramaPlaybackOptionsLoggedMaterialKey;
static void (*OrigDramaPlaybackOptionsDisappeared)(id, SEL, BOOL);

static void FQXSetPlaybackOptionsBackground(UIView *view, BOOL active, CGFloat alpha) {
    if (!view) return;
    UIColor *current = view.backgroundColor;
    UIColor *original = objc_getAssociatedObject(view, &DramaPlaybackOptionsSavedColorKey);
    if (active) {
        if (current && CGColorGetAlpha([current resolvedColorWithTraitCollection:view.traitCollection].CGColor) > alpha + 0.001) {
            objc_setAssociatedObject(view, &DramaPlaybackOptionsSavedColorKey, current, OBJC_ASSOCIATION_RETAIN_NONATOMIC);
            view.backgroundColor = alpha == 0.0 ? UIColor.clearColor : [current colorWithAlphaComponent:alpha];
        }
    } else if (original) {
        UIColor *applied = alpha == 0.0 ? UIColor.clearColor : [original colorWithAlphaComponent:alpha];
        if ([current isEqual:applied]) view.backgroundColor = original;
        objc_setAssociatedObject(view, &DramaPlaybackOptionsSavedColorKey, nil, OBJC_ASSOCIATION_RETAIN_NONATOMIC);
    }
}

static void FQXSetPlaybackOptionsNativeBackdrop(UIVisualEffectView *backdrop, BOOL active) {
    UIVisualEffect *nativeEffect = backdrop.effect;
    if (active && nativeEffect) {
        objc_setAssociatedObject(backdrop, &DramaPlaybackOptionsSavedEffectKey, nativeEffect, OBJC_ASSOCIATION_RETAIN_NONATOMIC);
        backdrop.effect = nil;
    } else if (!active && backdrop) {
        UIVisualEffect *saved = objc_getAssociatedObject(backdrop, &DramaPlaybackOptionsSavedEffectKey);
        if (saved && !nativeEffect) backdrop.effect = saved;
        if (saved) objc_setAssociatedObject(backdrop, &DramaPlaybackOptionsSavedEffectKey, nil, OBJC_ASSOCIATION_RETAIN_NONATOMIC);
    }
}

static void FQXSyncPlaybackOptionsReadability(UIVisualEffectView *surface, BOOL dark, BOOL clearGlass, CGFloat radius) {
    UIView *fill = objc_getAssociatedObject(surface, &DramaPlaybackOptionsReadabilityKey);
    if (!fill) {
        fill = [[UIView alloc] initWithFrame:surface.contentView.bounds];
        fill.userInteractionEnabled = NO;
        fill.opaque = NO;
        fill.autoresizingMask = UIViewAutoresizingFlexibleWidth | UIViewAutoresizingFlexibleHeight;
        fill.layer.cornerCurve = kCACornerCurveContinuous;
        fill.layer.maskedCorners = kCALayerMinXMinYCorner | kCALayerMaxXMinYCorner;
        objc_setAssociatedObject(surface, &DramaPlaybackOptionsReadabilityKey, fill, OBJC_ASSOCIATION_RETAIN_NONATOMIC);
    }
    if (fill.superview != surface.contentView || surface.contentView.subviews.lastObject != fill) {
        fill.frame = surface.contentView.bounds;
        [surface.contentView addSubview:fill];
    } else if (!CGRectEqualToRect(fill.frame, surface.contentView.bounds)) {
        fill.frame = surface.contentView.bounds;
    }
    CGFloat fillAlpha = clearGlass ? (dark ? 0.20 : 0.14) : (dark ? 0.26 : 0.20);
    UIColor *color = [UIColor colorWithWhite:dark ? 0.0 : 1.0 alpha:fillAlpha];
    if (![fill.backgroundColor isEqual:color]) fill.backgroundColor = color;
    if (fabs(fill.layer.cornerRadius - radius) > 0.25) fill.layer.cornerRadius = radius;
}

static void FQXSyncPlaybackOptionsCoveredControls(UIViewController *controller, BOOL covered) {
    UIView *root = controller.viewIfLoaded;
    UIWindow *window = root.window;
    NSHashTable<UIView *> *hidden = objc_getAssociatedObject(root, &DramaPlaybackOptionsCoveredControlsKey);
    NSMutableSet<UIView *> *wanted = nil;
    if (covered && window) {
        id context = FQXObjGet(controller, "listVCContext");
        UIView *cell = FQXObjGet(FQXObjGet(context, "currentVideoDataModel"), "cellView");
        if ([cell isKindOfClass:UIView.class] && cell.window == window) {
            UIView *control = FQXObjGet(cell, "vPlayerControlView");
            UIView *decoration = FQXObjGet(cell, "decorationContentView");
            UIView *rail = [decoration isKindOfClass:UIView.class]
                ? FQXFindViewOfClassRecursive(decoration, objc_lookUpClass("SSShortVideoRightInteractionView")) : nil;
            UIView *candidates[] = { FQXObjGet(control, "baseInfoView"), FQXObjGet(control, "bottomView"),
                                     FQXObjGet(control, "progressContainer"), FQXObjGet(control, "insertAboveProgressView"), rail };
            CGRect sheet = [root convertRect:root.bounds toView:window];
            wanted = [NSMutableSet set];
            for (NSUInteger i = 0; i < sizeof(candidates) / sizeof(candidates[0]); ++i) {
                UIView *view = candidates[i];
                if ([view isKindOfClass:UIView.class] && view.window == window &&
                    [view isDescendantOfView:cell] && ![view isDescendantOfView:root] &&
                    CGRectIntersectsRect(sheet, [view convertRect:view.bounds toView:window])) {
                    [wanted addObject:view];
                }
            }
        }
    }
    for (UIView *view in hidden.allObjects) {
        if ([wanted containsObject:view]) continue;
        FQXSetBackdropContentHidden(view, NO);
        [hidden removeObject:view];
    }
    if (!wanted.count) {
        if (hidden) objc_setAssociatedObject(root, &DramaPlaybackOptionsCoveredControlsKey, nil, OBJC_ASSOCIATION_RETAIN_NONATOMIC);
        return;
    }
    if (!hidden) {
        hidden = [NSHashTable weakObjectsHashTable];
        objc_setAssociatedObject(root, &DramaPlaybackOptionsCoveredControlsKey, hidden, OBJC_ASSOCIATION_RETAIN_NONATOMIC);
    }
    for (UIView *view in wanted) {
        FQXSetBackdropContentHidden(view, YES);
        [hidden addObject:view];
    }
}

static NSHashTable<UIViewController *> *FQXTrackedDramaPlaybackOptionsVCs(void) {
    static NSHashTable<UIViewController *> *table = nil;
    static dispatch_once_t onceToken;
    dispatch_once(&onceToken, ^{
        table = [NSHashTable weakObjectsHashTable];
    });
    return table;
}

static void FQXStyleDramaPlaybackOptions(UIViewController *controller) {
    if ([controller isKindOfClass:UIViewController.class]) {
        [FQXTrackedDramaPlaybackOptionsVCs() addObject:controller];
    }
    UIView *root = controller.viewIfLoaded;
    if (!root || CGRectIsEmpty(root.bounds)) {
        FQXSyncPlaybackOptionsCoveredControls(controller, NO);
        return;
    }
    UIVisualEffectView *surface = objc_getAssociatedObject(root, &DramaPlaybackOptionsSurfaceKey);
    id config = FQXObjGet(controller, "config");
    NSUserDefaults *prefs = NSUserDefaults.standardUserDefaults;
    NSInteger material = [prefs integerForKey:DramaPlaybackOptionsMaterialPrefKey];
    BOOL active = !FQXHotPrefsSnapshot().glassDisabled && material != -1 &&
        !FQXBoolGet(config, "isLandscapeMode", NO);
    if (!active && !surface) return;
    UITableView *table = FQXObjGet(controller, "tableView");
    if (![table isKindOfClass:UITableView.class] || ![table isDescendantOfView:root]) {
        FQXSyncPlaybackOptionsCoveredControls(controller, NO);
        return;
    }
    UIVisualEffectView *nativeBackdrop = nil;
    UIView *nativeTint = nil;
    if (FQXBoolGet(controller, "useBlurBackground", NO)) {
        UIView *blur = FQXObjGet(controller, "blurView");
        if ([blur isKindOfClass:UIVisualEffectView.class] && [blur isDescendantOfView:root]) {
            nativeBackdrop = (UIVisualEffectView *)blur;
            nativeTint = FQXObjGet(controller, "effectViewContentView");
        }
    }

    if (!active) {
        FQXReleaseCommentSurface(surface);
        objc_setAssociatedObject(root, &DramaPlaybackOptionsSurfaceKey, nil, OBJC_ASSOCIATION_RETAIN_NONATOMIC);
        FQXSetShareSheetHostClipping(root, NO);
        FQXSyncPlaybackOptionsCoveredControls(controller, NO);
    } else {
        BOOL followDock = material != FQXCommentMaterialClearGlass && material != FQXCommentMaterialRegularGlass &&
                          material != FQXCommentMaterialGaussianBlur;
        FQXDockMaterialMode dockMode = FQXCurrentDockMaterialMode();
        if (dockMode == FQXDockMaterialVideoBase || dockMode == FQXDockMaterialRoseMistGlass) {
            dockMode = FQXDockMaterialNewGlass;
        }
        BOOL reduce = UIAccessibilityIsReduceTransparencyEnabled();
        BOOL gaussian = !reduce && (!FQXGlassEnabled() || (followDock && dockMode == FQXDockMaterialIOS18Gaussian) ||
                                     material == FQXCommentMaterialGaussianBlur);
        BOOL clearGlass = !gaussian && !reduce && (followDock ? dockMode != FQXDockMaterialFrostedGlass
                                                              : material == FQXCommentMaterialClearGlass);
        BOOL dark = FQXAppIsInNightMode();
        CGFloat luma;
        UIColor *panelColor = FQXObjGet(controller, "panelSolidBackgroundColor");
        if (FQXColorLuminance(panelColor, root.traitCollection, &luma)) dark = luma < 0.45;
        BOOL darkTint = FQXGlassDarkTintEnabled();
        BOOL nativeGlass = !gaussian && !reduce;
        if (!nativeGlass) FQXSetShareSheetHostClipping(root, NO);
        CGFloat savedRadius = [objc_getAssociatedObject(root, FQXShareSavedCornerRKey) doubleValue];
        CGFloat radius = FQXReadHostSheetCornerRadius(root, nil);
        if (savedRadius >= 8.0) radius = savedRadius <= 20.0 ? savedRadius : 16.0;
        if (nativeGlass) FQXSetShareSheetHostClipping(root, YES);

        if (surface && [surface isKindOfClass:FQXBackdropBlurView.class] != gaussian) {
            FQXReleaseCommentSurface(surface);
            surface = nil;
        }
        if (!surface) {
            if (gaussian) {
                surface = FQXNewSheetBlur();
            } else {
                FQXCommentGlassSurfaceView *glass = [[FQXCommentGlassSurfaceView alloc] initWithEffect:nil];
                glass->_isSheetBackdrop = YES;
                surface = glass;
            }
            surface.userInteractionEnabled = NO;
            surface.accessibilityElementsHidden = YES;
            surface.opaque = NO;
            surface.autoresizingMask = UIViewAutoresizingFlexibleWidth | UIViewAutoresizingFlexibleHeight;
            objc_setAssociatedObject(surface, FQXOwnedGlassElementKey, @YES, OBJC_ASSOCIATION_RETAIN_NONATOMIC);
            objc_setAssociatedObject(root, &DramaPlaybackOptionsSurfaceKey, surface, OBJC_ASSOCIATION_RETAIN_NONATOMIC);
        }
        int userBlur = FQXResolvePlaybackOptionsUserBlur(
            followDock ? 1 : 0,
            FQXBlurPercent([prefs doubleForKey:DramaPlaybackOptionsBlurPrefKey]),
            FQXBlurPercent([prefs doubleForKey:DockBlurPrefKey]));
        int minimumBlur = gaussian ? 35 : 0;
        NSInteger strength = reduce ? (gaussian ? 100 : 0) : FQXSheetBlurPercent(userBlur, minimumBlur);
        CGFloat maxGlassTint = clearGlass ? (dark ? 0.22 : 0.18) : (dark ? 0.34 : 0.30);
        FQXSyncSheetBlur(root, surface, gaussian, strength, dark, maxGlassTint, radius);
        if (!gaussian) {
            UIUserInterfaceStyle style = clearGlass ? UIUserInterfaceStyleUnspecified
                : (dark ? UIUserInterfaceStyleDark : UIUserInterfaceStyleLight);
            if (surface.overrideUserInterfaceStyle != style) surface.overrideUserInterfaceStyle = style;
            NSInteger stamp = ((followDock ? 10 + dockMode : material) << 3) | (dark << 2) | (darkTint << 1) | reduce;
            NSNumber *previous = objc_getAssociatedObject(surface, &DramaPlaybackOptionsMaterialStampKey);
            if (!previous || previous.integerValue != stamp) {
                UIVisualEffect *effect;
                if (reduce) {
                    effect = [UIBlurEffect effectWithStyle:dark ? UIBlurEffectStyleSystemMaterialDark : UIBlurEffectStyleSystemMaterialLight];
                } else if (followDock) {
                    effect = FQXMakeDockEffectForMode(dockMode, dark, NO, NO);
                } else {
                    effect = FQXBuildCommentGlassEffect((FQXCommentMaterialStyle)material, dark && darkTint, NO, NO);
                }
                surface.effect = effect;
                objc_setAssociatedObject(surface, &DramaPlaybackOptionsMaterialStampKey, @(stamp), OBJC_ASSOCIATION_RETAIN_NONATOMIC);
            }
        }
        if (nativeGlass) FQXSyncPlaybackOptionsReadability(surface, dark, clearGlass, radius);
        else [objc_getAssociatedObject(surface, &DramaPlaybackOptionsReadabilityKey) removeFromSuperview];
        if (OrigDramaPlaybackOptionsDisappeared) {
            FQXSyncPlaybackOptionsCoveredControls(controller, nativeGlass && !controller.isBeingDismissed);
        }
        if (FQXDiagnosticsHubIsEnabled()) {
            NSDictionary *materialState = @{@"material": @(material), @"dockMaterial": @(dockMode),
                @"gaussian": @(gaussian), @"userBlurPercent": @(userBlur),
                @"effectiveBlurPercent": @(strength), @"reduceTransparency": @(reduce)};
            if (![materialState isEqualToDictionary:objc_getAssociatedObject(surface, &DramaPlaybackOptionsLoggedMaterialKey)]) {
                objc_setAssociatedObject(surface, &DramaPlaybackOptionsLoggedMaterialKey, materialState, OBJC_ASSOCIATION_RETAIN_NONATOMIC);
                FQXDiagRecordEvent(FQXDiagCategoryUI, @"drama_playback_options_material", materialState, NO);
            }
        }
    }

    FQXSetPlaybackOptionsBackground(root, active, 0.0);
    FQXSetPlaybackOptionsBackground(table, active, 0.0);
    FQXSetPlaybackOptionsBackground(nativeTint, active, 0.0);
    FQXSetPlaybackOptionsNativeBackdrop(nativeBackdrop, active);
    for (UITableViewCell *cell in table.visibleCells) {
        FQXSetPlaybackOptionsBackground(cell, active, DramaPlaybackOptionsGroupAlpha);
    }
    UICollectionView *pinned = FQXObjGet(FQXObjGet(controller, "pinnedItemsView"), "collectionView");
    if ([pinned isKindOfClass:UICollectionView.class] && [pinned isDescendantOfView:root]) {
        for (UICollectionViewCell *cell in pinned.visibleCells) {
            FQXSetPlaybackOptionsBackground(cell.contentView, active, DramaPlaybackOptionsGroupAlpha);
        }
    }
}

static void FQXRefreshAllDramaPlaybackOptions(void) {
    if (!NSThread.isMainThread) {
        dispatch_async(dispatch_get_main_queue(), ^{ FQXRefreshAllDramaPlaybackOptions(); });
        return;
    }
    for (UIViewController *vc in FQXTrackedDramaPlaybackOptionsVCs().allObjects) {
        UIView *root = vc.viewIfLoaded;
        if (!root || !root.window) continue;
        UIVisualEffectView *surface = objc_getAssociatedObject(root, &DramaPlaybackOptionsSurfaceKey);
        if (surface) {
            objc_setAssociatedObject(surface, &DramaPlaybackOptionsMaterialStampKey, nil, OBJC_ASSOCIATION_RETAIN_NONATOMIC);
        }
        FQXStyleDramaPlaybackOptions(vc);
    }
}

